def deduction_step(mine_grid, clue_grid, rows, cols):
    changed = False
    for r in range(rows):
        for c in range(cols):
            if clue_grid[r][c] is not None:
                n = clue_grid[r][c]
                neigh = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neigh.append((nr, nc))
                mines = sum(1 for nr, nc in neigh if mine_grid[nr][nc] == 1)
                unk = [(nr, nc) for nr, nc in neigh if mine_grid[nr][nc] == -1]
                unk_count = len(unk)
                if mines > n or mines + unk_count < n:
                    return False, False
                if mines == n and unk_count > 0:
                    for nr, nc in unk:
                        mine_grid[nr][nc] = 0
                    changed = True
                if mines + unk_count == n and unk_count > 0:
                    for nr, nc in unk:
                        mine_grid[nr][nc] = 1
                    changed = True
    return True, changed

def propagate(mine_grid, clue_grid, rows, cols):
    while True:
        ok, changed = deduction_step(mine_grid, clue_grid, rows, cols)
        if not ok:
            return False
        if not changed:
            return True

def find_solution(mine_grid, clue_grid, rows, cols):
    if not propagate(mine_grid, clue_grid, rows, cols):
        return None
    solved = all(mine_grid[r][c] != -1 for r in range(rows) for c in range(cols))
    if solved:
        return [['F' if mine_grid[r][c] == 1 else None for c in range(cols)] for r in range(rows)]
    branch_r, branch_c = next((r, c) for r in range(rows) for c in range(cols) if mine_grid[r][c] == -1)
    # Try safe (0)
    new_grid = [[mine_grid[r][c] for c in range(cols)] for r in range(rows)]
    new_grid[branch_r][branch_c] = 0
    sol = find_solution(new_grid, clue_grid, rows, cols)
    if sol is not None:
        return sol
    # Try mine (1)
    new_grid = [[mine_grid[r][c] for c in range(cols)] for r in range(rows)]
    new_grid[branch_r][branch_c] = 1
    sol = find_solution(new_grid, clue_grid, rows, cols)
    if sol is not None:
        return sol
    return None

def solve(observation):
    clue_grid = observation['data']
    rows = len(clue_grid)
    cols = len(clue_grid[0])
    mine_grid = [[0 if clue_grid[r][c] is not None else -1 for c in range(cols)] for r in range(rows)]
    sol = find_solution(mine_grid, clue_grid, rows, cols)
    if sol is None:
        return "No Solution"
    return sol

