OBSERVATION = {'U': [1, 2, 4, 2, 3], 'D': [2, 2, 1, 4, 3], 'L': [1, 3, 3, 2, 2], 'R': [4, 2, 1, 3, 2]}

import itertools

def visibility(line, reverse=False):
    if reverse:
        line = line[::-1]
    count = 0
    max_h = 0
    for h in line:
        if h > max_h:
            count += 1
            max_h = h
    return count

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    # Precompute possible perms for rows
    row_possibles = []
    for i in range(N):
        perms = [p for p in itertools.permutations(range(1, N+1))
                 if visibility(p, False) == L[i] and visibility(p, True) == R[i]]
        row_possibles.append(perms)

    # Precompute possible perms for columns
    col_possibles = []
    for j in range(N):
        perms = [p for p in itertools.permutations(range(1, N+1))
                 if visibility(p, False) == U[j] and visibility(p, True) == D[j]]
        col_possibles.append(perms)

    chosen_perms = [None] * N
    col_used = [set() for _ in range(N)]

    def backtrack(row_index, current_col_poss):
        if row_index == N:
            return True
        for p in row_possibles[row_index]:
            # Check uniqueness
            can_place = True
            for j in range(N):
                if p[j] in col_used[j]:
                    can_place = False
                    break
            if not can_place:
                continue
            # Create new col_poss by copying current
            new_col_poss = [list(current_col_poss[j]) for j in range(N)]
            filter_ok = True
            for j in range(N):
                new_col_poss[j] = [q for q in new_col_poss[j] if q[row_index] == p[j]]
                if not new_col_poss[j]:
                    filter_ok = False
                    break
            if not filter_ok:
                continue
            # Add to used
            for j in range(N):
                col_used[j].add(p[j])
            # Recurse
            if backtrack(row_index + 1, new_col_poss):
                chosen_perms[row_index] = list(p)
                return True
            # Backtrack used
            for j in range(N):
                col_used[j].remove(p[j])
        return False

    if backtrack(0, col_possibles):
        return chosen_perms
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
