from collections import defaultdict, deque

def get_possible_masks(row_data, N):
    groups = defaultdict(list)
    for col, num in enumerate(row_data):
        groups[num].append(col)
    nums = sorted(groups.keys())
    masks = []
    def rec(i, current_white_cols):
        if i == len(nums):
            white = [False] * N
            for c in current_white_cols:
                white[c] = True
            valid = True
            for j in range(N - 1):
                if not white[j] and not white[j + 1]:
                    valid = False
                    break
            if valid:
                masks.append(white[:])
            return
        num = nums[i]
        poss = groups[num]
        rec(i + 1, current_white_cols)
        for c in poss:
            rec(i + 1, current_white_cols + [c])
    rec(0, [])
    return masks

def is_connected(white_masks, N):
    whites = []
    for i in range(N):
        for j in range(N):
            if white_masks[i][j]:
                whites.append((i, j))
    if not whites:
        return True
    visited = set()
    start = whites[0]
    q = deque([start])
    visited.add(start)
    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and white_masks[nx][ny] and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny))
    return len(visited) == len(whites)

def backtrack(r, used, prev_black, white_masks, possibles, data, N):
    if r == N:
        if is_connected(white_masks, N):
            return [[None if white_masks[i][j] else 'B' for j in range(N)] for i in range(N)]
        return None
    for mask in possibles[r]:
        new_black = [not mask[c] for c in range(N)]
        valid = True
        for c in range(N):
            if new_black[c] and prev_black[c]:
                valid = False
                break
        if not valid:
            continue
        new_used = [s.copy() for s in used]
        valid = True
        for c in range(N):
            if mask[c]:
                num = data[r][c]
                if num in new_used[c]:
                    valid = False
                    break
                new_used[c].add(num)
        if not valid:
            continue
        white_masks[r] = mask[:]
        res = backtrack(r + 1, new_used, new_black, white_masks, possibles, data, N)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    possibles = []
    for r in range(N):
        possibles.append(get_possible_masks(data[r], N))
    used = [set() for _ in range(N)]
    white_masks = [None] * N
    res = backtrack(0, used, [False] * N, white_masks, possibles, data, N)
    if res is not None:
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
