from collections import deque

def propagate(grid, forced, N):
    changed = True
    while changed:
        changed = False
        for i in range(N - 1):
            for j in range(N - 1):
                cells = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
                colors = [grid[x][y] for x, y in cells]
                known = [c for c in colors if c is not None]
                num_known = len(known)
                if num_known == 4:
                    if all(c == known[0] for c in known):
                        return False
                elif num_known == 3 and all(c == known[0] for c in known):
                    opp = 'W' if known[0] == 'B' else 'B'
                    for k in range(4):
                        if colors[k] is None:
                            x, y = cells[k]
                            grid[x][y] = opp
                            forced.append((x, y))
                            changed = True
                            break
    return True

def can_connect(grid, color, N):
    positions = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
    if not positions:
        return True
    opp = 'W' if color == 'B' else 'B'
    start = positions[0]
    visited = set()
    q = deque([start])
    visited.add(start)
    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and grid[nx][ny] != opp:
                visited.add((nx, ny))
                q.append((nx, ny))
    return all(p in visited for p in positions)

def backtrack(pos, empties, grid, N):
    if pos == len(empties):
        if can_connect(grid, 'B', N) and can_connect(grid, 'W', N):
            return [row[:] for row in grid]
        else:
            return None
    i, j = empties[pos]
    if grid[i][j] is not None:
        return backtrack(pos + 1, empties, grid, N)
    for color in ['B', 'W']:
        grid[i][j] = color
        forced = []
        if propagate(grid, forced, N) and can_connect(grid, 'B', N) and can_connect(grid, 'W', N):
            result = backtrack(pos + 1, empties, grid, N)
            if result is not None:
                return result
        grid[i][j] = None
        for x, y in reversed(forced):
            grid[x][y] = None
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    forced = []
    if not propagate(grid, forced, N):
        return "No Solution"
    if not can_connect(grid, 'B', N) or not can_connect(grid, 'W', N):
        return "No Solution"
    empties = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None]
    result = backtrack(0, empties, grid, N)
    return result if result is not None else "No Solution"

