                        stack = [(r, c)]
                        touches_w = False
                        while stack:
                            x, y = stack.pop()
                            if (x, y) in visited:
                                continue
                            visited.add((x, y))
                            if grid[x][y] == 'U':
                                component.append((x, y))
                                for dx, dy in directions:
                                    nx, ny = x + dx, y + dy
                                    if is_valid_pos(nx, ny):
                                        if grid[nx][ny] == 'U':
                                            stack.append((nx, ny))
                                        elif grid[nx][ny] == 'W':
                                            touches_w = True
                        if not touches_w:
                            for x, y in component:
                                grid[x][y] = 'B'
                                changed = True
                                if violates_2x2(grid, x, y):
                                    return False
        return True

    if not propagate(grid):
        return "No Solution"

    def backtrack(grid):
        pr, pc = -1, -1
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'U':
                    pr, pc = r, c
                    break
            if pr != -1:
                break
        if pr == -1:
            if check_final(grid):
                return grid
            else:
                return None
        # Try 'W'
        new_grid = [row[:] for row in grid]
        new_grid[pr][pc] = 'W'
        proceed = True
        if proceed and propagate(new_grid):
            res = backtrack(new_grid)
            if res is not None:
                return res
        # Try 'B'
        new_grid = [row[:] for row in grid]
        new_grid[pr][pc] = 'B'
        if not violates_2x2(new_grid, pr, pc):
            if propagate(new_grid):
                res = backtrack(new_grid)
                if res is not None:
                    return res
        return None

    def check_final(grid):
        # No 2x2 black
        for r in range(rows - 1):
            for c in range(cols - 1):
                if all(grid[x][y] == 'B' for x in [r, r + 1] for y in [c, c + 1]):
                    return False
        # White islands
        visited = set()
        for cr, cc, num in clues:
            if (cr, cc) in visited:
                return False
            size = 0
            stack = [(cr, cc)]
            while stack:
                x, y = stack.pop()
                if (x, y) in visited:
                    continue
                visited.add((x, y))
                if grid[x][y] == 'W':
                    size += 1
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if is_valid_pos(nx, ny) and grid[nx][ny] == 'W':
                            stack.append((nx, ny))
            if size != num:
                return False
        total_w = sum(1 for row in grid for cell in row if cell == 'W')
        if len(visited) != total_w:
            return False
        # Black connectivity
        b_cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 'B']
        if not b_cells:
            return True
        visited_b = set()
        stack = [b_cells[0]]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited_b:
                continue
            visited_b.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid_pos(nx, ny) and grid[nx][ny] == 'B':
                    stack.append((nx, ny))
        if len(visited_b) != len(b_cells):
            return False
        return True

    result = backtrack(grid)
    if result is None:
        return "No Solution"
    out_grid = [[None if cell == 'W' else cell if cell == 'B' else None for cell in row] for row in result]
    return out_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
