from collections import deque

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    to_fill = [(i, j) for i in range(n) for j in range(n) if grid[i][j] is None]

    def do_propagate(initial_queue, forced_list):
        q = deque(initial_queue)
        while q:
            r, c = q.popleft()
            for tr in [r-1, r]:
                for tc in [c-1, c]:
                    if tr < 0 or tr >= n-1 or tc < 0 or tc >= n-1:
                        continue
                    cells = [(tr, tc), (tr, tc+1), (tr+1, tc), (tr+1, tc+1)]
                    colors = [grid[a][b] for a, b in cells]
                    num_none = colors.count(None)
                    num_b = colors.count('B')
                    num_w = colors.count('W')
                    if num_none == 0:
                        if num_b == 4 or num_w == 4:
                            return False
                    if num_none == 1:
                        force_color = None
                        if num_b == 3 and num_w == 0:
                            force_color = 'W'
                        elif num_w == 3 and num_b == 0:
                            force_color = 'B'
                        if force_color is not None:
                            for ii, colr in enumerate(colors):
                                if colr is None:
                                    ar, ac = cells[ii]
                                    grid[ar][ac] = force_color
                                    forced_list.append((ar, ac))
                                    q.append((ar, ac))
                                    break
        return True

    def check_connect_possible():
        def is_connectable(pos_list, can_traverse):
            if not pos_list:
                return True
            start = pos_list[0]
            visited = set()
            q = deque([start])
            visited.add(start)
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            while q:
                x, y = q.popleft()
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and can_traverse(grid[nx][ny]):
                        visited.add((nx, ny))
                        q.append((nx, ny))
            return all(p in visited for p in pos_list)

        fixed_b = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == 'B']
        if fixed_b and not is_connectable(fixed_b, lambda c: c != 'W'):
            return False
        fixed_w = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == 'W']
        if fixed_w and not is_connectable(fixed_w, lambda c: c != 'B'):
            return False
        return True

    # Initial propagation
    initial_queue = [(i, j) for i in range(n) for j in range(n) if grid[i][j] is not None]
    initial_forced = []
    if not do_propagate(initial_queue, initial_forced):
        return "No Solution"

    def backtrack(index):
        if index == len(to_fill):
            if check_connect_possible():
                return [row[:] for row in grid]
            return None
        r, c = to_fill[index]
        if grid[r][c] is not None:
            return backtrack(index + 1)
        # Try 'B'
        grid[r][c] = 'B'
        forced = []
        if do_propagate([(r, c)], forced) and check_connect_possible():
            res = backtrack(index + 1)
            if res is not None:
                return res
        for fr, fc in forced:
            grid[fr][fc] = None
        grid[r][c] = None
        # Try 'W'
        grid[r][c] = 'W'
        forced = []
        if do_propagate([(r, c)], forced) and check_connect_possible():
            res = backtrack(index + 1)
            if res is not None:
                return res
        for fr, fc in forced:
            grid[fr][fc] = None
        grid[r][c] = None
        return None

    result = backtrack(0)
    return result if result is not None else "No Solution"

