from collections import defaultdict, deque

def solve(observation):
    data = observation['data']
    N = len(data)
    row_counts = [defaultdict(int) for _ in range(N)]
    col_counts = [defaultdict(int) for _ in range(N)]
    for r in range(N):
        for c in range(N):
            num = data[r][c]
            row_counts[r][num] += 1
            col_counts[c][num] += 1

    positions = []
    for r in range(N):
        for c in range(N):
            positions.append((r, c))
    positions.sort(key=lambda p: -((row_counts[p[0]][data[p[0]][p[1]]] - 1) + (col_counts[p[1]][data[p[0]][p[1]]] - 1)))

    state = [[None for _ in range(N)] for _ in range(N)]
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]

    def backtrack(idx):
        if idx == len(positions):
            return is_connected(state, N)
        r, c = positions[idx]
        num = data[r][c]
        conflict = (row_counts[r][num] - 1) + (col_counts[c][num] - 1)
        attempts = ['B', 'W'] if conflict > 0 else ['W', 'B']
        for choice in attempts:
            if choice == 'W':
                if num not in row_used[r] and num not in col_used[c]:
                    state[r][c] = 'W'
                    row_used[r].add(num)
                    col_used[c].add(num)
                    if backtrack(idx + 1):
                        return True
                    row_used[r].remove(num)
                    col_used[c].remove(num)
                    state[r][c] = None
            else:  # 'B'
                can = True
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 'B':
                        can = False
                        break
                if can:
                    state[r][c] = 'B'
                    if backtrack(idx + 1):
                        return True
                    state[r][c] = None
        return False

    def is_connected(state, N):
        whites = [(i, j) for i in range(N) for j in range(N) if state[i][j] == 'W']
        if not whites:
            return False
        visited = set()
        q = deque([whites[0]])
        visited.add(whites[0])
        count = 1
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 'W' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
                    count += 1
        return count == len(whites)

    if backtrack(0):
        output = [['B' if state[i][j] == 'B' else None for j in range(N)] for i in range(N)]
        return output
    return "No Solution"

