import copy

def solve(observation):
    grid = observation['data']
    N = len(grid)
    regions = defaultdict(list)
    for r in range(N):
        for c in range(N):
            regions[grid[r][c]].append((r, c))
    max_rid = max(regions.keys())
    def get_possible_for_row(rr, col_used, region_used, forbidden):
        possible_cells = []
        for c in range(N):
            if forbidden[rr][c]:
                continue
            rid = grid[rr][c]
            if region_used[rid] >= 2:
                continue
            if col_used[c] >= 2:
                continue
            possible_cells.append(c)
        possible_pairs = []
        for i in range(len(possible_cells)):
            for j in range(i + 1, len(possible_cells)):
                c1 = possible_cells[i]
                c2 = possible_cells[j]
                if abs(c1 - c2) < 2:
                    continue
                rid1 = grid[rr][c1]
                rid2 = grid[rr][c2]
                add = defaultdict(int)
                add[rid1] += 1
                add[rid2] += 1
                ok = all(region_used[rid] + add[rid] <= 2 for rid in add)
                if ok:
                    possible_pairs.append((c1, c2))
        return possible_pairs

    def backtrack(remaining_rows, col_used, region_used, placed, forbidden):
        if not remaining_rows:
            return True
        candidates = []
        for rr in remaining_rows:
            pairs = get_possible_for_row(rr, col_used, region_used, forbidden)
            candidates.append((len(pairs), rr, pairs))
        if any(count == 0 for count, _, _ in candidates):
            return False
        candidates.sort()
        for _, rr, possible_pairs in candidates:
            for pair in possible_pairs:
                c1, c2 = pair if pair[0] < pair[1] else (pair[1], pair[0])
                rid1 = grid[rr][c1]
                rid2 = grid[rr][c2]
                placed[rr][c1] = 'S'
                placed[rr][c2] = 'S'
                col_used[c1] += 1
                col_used[c2] += 1
                region_used[rid1] += 1
                region_used[rid2] += 1
                to_undo = []
                for pc in [c1, c2]:
                    for neigh_dr in [-1, 1]:
                        neigh_r = rr + neigh_dr
                        if 0 <= neigh_r < N and neigh_r in remaining_rows:
                            for dc in [-1, 0, 1]:
                                nc = pc + dc
                                if 0 <= nc < N and not forbidden[neigh_r][nc]:
                                    forbidden[neigh_r][nc] = True
                                    to_undo.append((neigh_r, nc))
                for pc in {c1, c2}:
                    if col_used[pc] == 2:
                        for rem_r in remaining_rows:
                            if not forbidden[rem_r][pc]:
                                forbidden[rem_r][pc] = True
                                to_undo.append((rem_r, pc))
                for prid in {rid1, rid2}:
                    if region_used[prid] == 2:
                        for rem_r, rem_c in regions[prid]:
                            if rem_r in remaining_rows and not forbidden[rem_r][rem_c]:
                                forbidden[rem_r][rem_c] = True
                                to_undo.append((rem_r, rem_c))
                ok = True
                for rem_r in remaining_rows:
                    avail = sum(1 for cc in range(N) if not forbidden[rem_r][cc])
                    if avail < 2:
                        ok = False
                        break
                if ok:
                    for cc in range(N):
                        needed = 2 - col_used[cc]
                        if needed <= 0:
                            continue
                        avail = sum(1 for rem_r in remaining_rows if not forbidden[rem_r][cc])
                        if avail < needed:
                            ok = False
                            break
                if ok:
                    for rid in range(max_rid + 1):
                        needed = 2 - region_used[rid]
                        if needed <= 0:
                            continue
                        avail = sum(1 for rem_r, cc in regions[rid] if rem_r in remaining_rows and not forbidden[rem_r][cc])
                        if avail < needed:
                            ok = False
                            break
                if ok:
                    new_remaining = remaining_rows - {rr}
                    if backtrack(new_remaining, col_used, region_used, placed, forbidden):
                        return True
                placed[rr][c1] = None
                placed[rr][c2] = None
                col_used[c1] -= 1
                col_used[c2] -= 1
                region_used[rid1] -= 1
                region_used[rid2] -= 1
                for ur, uc in to_undo:
                    forbidden[ur][uc] = False
        return False

    placed = [[None] * N for _ in range(N)]
    col_used = [0] * N
    region_used = [0] * (max_rid + 1)
    forbidden = [[False] * N for _ in range(N)]
    remaining_rows = set(range(N))
    if backtrack(remaining_rows, col_used, region_used, placed, forbidden):
        return placed
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
