import copy
from collections import deque

def get_min_arm(grid, N, r, c, dr, dc):
    count = 0
    rr, cc = r + dr, c + dc
    while 0 <= rr < N and 0 <= cc < N:
        cell = grid[rr][cc]
        if cell == 'B':
            return count, None
        elif isinstance(cell, int) or cell == 'W':
            count += 1
        elif cell is None:
            return count, (rr, cc)
        rr += dr
        cc += dc
    return count, None

def get_max_arm(grid, N, r, c, dr, dc):
    count = 0
    rr, cc = r + dr, c + dc
    while 0 <= rr < N and 0 <= cc < N:
        cell = grid[rr][cc]
        if cell == 'B':
            break
        count += 1
        rr += dr
        cc += dc
    return count

def get_actual_arm(grid, N, r, c, dr, dc):
    count = 0
    rr, cc = r + dr, c + dc
    while 0 <= rr < N and 0 <= cc < N:
        cell = grid[rr][cc]
        if cell == 'B':
            break
        count += 1
        rr += dr
        cc += dc
    return count

def backtrack(grid, clues, N, dirs):
    changed = True
    while changed:
        changed = False
        for r, c, num in clues:
            min_arms = 0
            force_bs = []
            max_arms = 0
            for dr, dc in dirs:
                m, force_pos = get_min_arm(grid, N, r, c, dr, dc)
                min_arms += m
                if force_pos:
                    force_bs.append(force_pos)
                max_arms += get_max_arm(grid, N, r, c, dr, dc)
            min_t = 1 + min_arms
            max_t = 1 + max_arms
            if min_t > num or max_t < num:
                return None
            if min_t == num:
                for fr, fc in force_bs:
                    if grid[fr][fc] == 'B':
                        continue
                    if grid[fr][fc] is not None:
                        return None
                    grid[fr][fc] = 'B'
                    changed = True
                    for adr, adc in dirs:
                        ar, ac = fr + adr, fc + adc
                        if 0 <= ar < N and 0 <= ac < N and grid[ar][ac] == 'B':
                            return None
            if max_t == num:
                for dr, dc in dirs:
                    rr, cc = r + dr, c + dc
                    while 0 <= rr < N and 0 <= cc < N and grid[rr][cc] != 'B':
                        if grid[rr][cc] is None:
                            grid[rr][cc] = 'W'
                            changed = True
                        rr += dr
                        cc += dc
    # Find undecided cell
    pos = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                pos = (i, j)
                break
        if pos:
            break
    if pos is None:
        # Check visibilities
        for r, c, num in clues:
            actual = 1 + sum(get_actual_arm(grid, N, r, c, dr, dc) for dr, dc in dirs)
            if actual != num:
                return None
        # Check connectivity
        whites = [(i, j) for i in range(N) for j in range(N) if grid[i][j] != 'B']
        if not whites:
            return None
        start = whites[0]
        visited = set()
        q = deque([start])
        visited.add(start)
        while q:
            cr, cc = q.popleft()
            for dr, dc in dirs:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] != 'B' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        if len(visited) != len(whites):
            return None
        # Prepare output
        out_grid = [[None] * N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                if isinstance(grid[i][j], int):
                    out_grid[i][j] = grid[i][j]
                elif grid[i][j] == 'B':
                    out_grid[i][j] = 'B'
        return out_grid
    # Try 'W'
    grid[pos[0]][pos[1]] = 'W'
    result = backtrack(grid, clues, N, dirs)
    if result is not None:
        return result
    grid[pos[0]][pos[1]] = None
    # Try 'B' if possible
    can_place = True
    for dr, dc in dirs:
        nr, nc = pos[0] + dr, pos[1] + dc
        if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == 'B':
            can_place = False
            break
    if can_place:
        grid[pos[0]][pos[1]] = 'B'
        result = backtrack(grid, clues, N, dirs)
        if result is not None:
            return result
        grid[pos[0]][pos[1]] = None
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = copy.deepcopy(data)
    clues = []
    for i in range(N):
        for j in range(N):
            if isinstance(grid[i][j], int):
                clues.append((i, j, grid[i][j]))
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    result = backtrack(grid, clues, N, dirs)
    if result is None:
        return "No Solution"
    return result

