from collections import defaultdict, deque

def solve(observation):
    data = observation['data']
    N = len(data)
    groups = []
    # Row groups
    for r in range(N):
        count = defaultdict(list)
        for c in range(N):
            count[data[r][c]].append((r, c))
        for ls in count.values():
            if len(ls) >= 2:
                groups.append(ls)
    # Column groups
    for c in range(N):
        count = defaultdict(list)
        for r in range(N):
            count[data[r][c]].append((r, c))
        for ls in count.values():
            if len(ls) >= 2:
                groups.append(ls)
    # cell_to_groups
    cell_to_groups = defaultdict(list)
    for gid, g in enumerate(groups):
        for pos in g:
            cell_to_groups[pos].append(gid)
    # Order for branching: most constrained first
    all_cells = [(r, c) for r in range(N) for c in range(N)]
    order = sorted(all_cells, key=lambda p: -len(cell_to_groups[p]))
    # State
    state = [[None for _ in range(N)] for _ in range(N)]

    def propagate(pos, trail, state, cell_to_groups, groups, N):
        queue = deque([pos])
        trail[:] = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while queue:
            cur = queue.popleft()
            val = state[cur[0]][cur[1]]
            if val == 'W':
                for gid in cell_to_groups[cur]:
                    g = groups[gid]
                    for other in g:
                        if other != cur:
                            or_, oc = other
                            curr_val = state[or_][oc]
                            if curr_val == 'W':
                                for tr, tc in trail:
                                    state[tr][tc] = None
                                return False
                            elif curr_val is None:
                                state[or_][oc] = 'B'
                                trail.append(other)
                                queue.append(other)
            elif val == 'B':
                for dr, dc in directions:
                    nr, nc = cur[0] + dr, cur[1] + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        curr_val = state[nr][nc]
                        if curr_val == 'B':
                            for tr, tc in trail:
                                state[tr][tc] = None
                            return False
                        elif curr_val is None:
                            state[nr][nc] = 'W'
                            trail.append((nr, nc))
                            queue.append((nr, nc))
        return True

    def is_connected(state, N):
        whites = [(i, j) for i in range(N) for j in range(N) if state[i][j] == 'W']
        if not whites:
            return False
        start = whites[0]
        visited = set()
        q = deque([start])
        visited.add(start)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            cur = q.popleft()
            for dr, dc in directions:
                nr, nc = cur[0] + dr, cur[1] + dc
                np = (nr, nc)
                if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 'W' and np not in visited:
                    visited.add(np)
                    q.append(np)
        return len(visited) == len(whites)

    def backtrack(state, groups, cell_to_groups, order, N):
        pos = None
        for p in order:
            r, c = p
            if state[r][c] is None:
                pos = (r, c)
                break
        if pos is None:
            return is_connected(state, N)
        r, c = pos
        for val in ['W', 'B']:
            state[r][c] = val
            trail = []
            if propagate((r, c), trail, state, cell_to_groups, groups, N):
                if backtrack(state, groups, cell_to_groups, order, N):
                    return True
            state[r][c] = None
            for tr, tc in trail:
                state[tr][tc] = None
        return False

    if backtrack(state, groups, cell_to_groups, order, N):
        out = [['B' if state[r][c] == 'B' else None for c in range(N)] for r in range(N)]
        return out
    else:
        return "No Solution"

