from itertools import combinations
from copy import deepcopy

def solve(observation):
    reg = observation['data']
    N = len(reg)
    # Find max region id
    max_reg = max(max(row) for row in reg)
    # Region to list of cells
    region_to_cells = [[] for _ in range(max_reg + 1)]
    for i in range(N):
        for j in range(N):
            rid = reg[i][j]
            region_to_cells[rid].append((i, j))
    # Grid
    grid = [[None] * N for _ in range(N)]
    # Counts
    col_count = [0] * N
    reg_count = [0] * (max_reg + 1)

    def backtrack(row):
        if row == N:
            return deepcopy(grid)
        # Forbidden columns from previous row
        forbidden = set()
        if row > 0:
            for c in range(N):
                if grid[row - 1][c] == 'S':
                    if c - 1 >= 0:
                        forbidden.add(c - 1)
                    forbidden.add(c)
                    if c + 1 < N:
                        forbidden.add(c + 1)
        # Candidate columns
        candidates = [c for c in range(N) if col_count[c] < 2 and c not in forbidden]
        # Possible pairs
        for comb in combinations(candidates, 2):
            c1, c2 = sorted(comb)
            if c2 - c1 < 2:
                continue
            # Compute added to regions
            added = {}
            for c in (c1, c2):
                rid = reg[row][c]
                added[rid] = added.get(rid, 0) + 1
            # Temp reg_count
            new_reg = reg_count[:]
            skip = False
            for rid, cnt in added.items():
                new_reg[rid] += cnt
                if new_reg[rid] > 2:
                    skip = True
                    break
            if skip:
                continue
            # Check pruning for all regions
            ok = True
            for rid in range(max_reg + 1):
                if not region_to_cells[rid]:
                    continue
                placed = new_reg[rid]
                rem = sum(1 for rr, cc in region_to_cells[rid] if rr > row)
                if placed > 2 or (2 - placed) > rem:
                    ok = False
                    break
            if not ok:
                continue
            # Place
            grid[row] = [None] * N
            grid[row][c1] = 'S'
            grid[row][c2] = 'S'
            # Update counts
            old_col1 = col_count[c1]
            old_col2 = col_count[c2]
            col_count[c1] += 1
            col_count[c2] += 1
            old_regs = {}
            for rid, cnt in added.items():
                old_regs[rid] = reg_count[rid]
                reg_count[rid] += cnt
            # Recurse
            result = backtrack(row + 1)
            if result is not None:
                return result
            # Undo
            col_count[c1] = old_col1
            col_count[c2] = old_col2
            for rid, old in old_regs.items():
                reg_count[rid] = old
        return None

    solution = backtrack(0)
    if solution is None:
        return "No Solution"
    return solution

