import sys
import math

class UF:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n
        self.clue = [0] * n
        self.undo_stack = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union_with_undo(self, x, y):
        px = self.find(x)
        py = self.find(y)
        if px == py:
            return True
        clue_x = self.clue[px]
        clue_y = self.clue[py]
        if clue_x > 0 and clue_y > 0:
            return False
        linked = None
        old_parent = None
        target = None
        old_size = None
        old_clue = None
        old_rank = -1
        if self.rank[px] < self.rank[py]:
            linked = px
            target = py
            old_parent = self.parent[px]
            self.parent[px] = py
            old_size = self.size[py]
            self.size[py] += self.size[px]
            old_clue = self.clue[py]
            if clue_x > 0:
                self.clue[py] = clue_x
        elif self.rank[px] > self.rank[py]:
            linked = py
            target = px
            old_parent = self.parent[py]
            self.parent[py] = px
            old_size = self.size[px]
            self.size[px] += self.size[py]
            old_clue = self.clue[px]
            if clue_y > 0:
                self.clue[px] = clue_y
        else:
            linked = py
            target = px
            old_parent = self.parent[py]
            self.parent[py] = px
            old_size = self.size[px]
            self.size[px] += self.size[py]
            old_clue = self.clue[px]
            if clue_y > 0:
                self.clue[px] = clue_y
            old_rank = self.rank[px]
            self.rank[px] += 1
        self.undo_stack.append(('link', linked, old_parent, target, old_size, old_clue, old_rank))
        return True

    def undo(self):
        if not self.undo_stack:
            return
        typ, linked, old_parent, target, old_size, old_clue, old_rank = self.undo_stack.pop()
        if typ == 'link':
            self.parent[linked] = old_parent
            self.size[target] = old_size
            self.clue[target] = old_clue
            if old_rank != -1:
                self.rank[target] = old_rank

directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def is_possible_black(r, c, state, H, W):
    for dr in [0, -1]:
        for dc in [0, -1]:
            tr = r + dr
            tc = c + dc
            if tr < 0 or tc < 0:
                continue
            all_black = True
            for a in [0, 1]:
                for b in [0, 1]:
                    ar = tr + a
                    ac = tc + b
                    if ar >= H or ac >= W or state[ar][ac] != 2:
                        all_black = False
                        break
                if not all_black:
                    break
            if all_black:
                return False
    return True

def can_set_white(uf, state, r, c, H, W):
    id = r * W + c
    unions_count = 0
    ok = True
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 1:
            if not uf.union_with_undo(id, nr * W + nc):
                ok = False
                break
            unions_count += 1
    if not ok:
        for _ in range(unions_count):
            uf.undo()
        return False, 0
    root = uf.find(id)
    if uf.clue[root] == 0 or uf.size[root] > uf.clue[root]:
        for _ in range(unions_count):
            uf.undo()
        return False, 0
    return True, unions_count

def blacks_connected(state, H, W):
    blacks = [(i, j) for i in range(H) for j in range(W) if state[i][j] == 2]
    if not blacks:
        return True
    visited = set()
    stack = [blacks[0]]
    visited.add(blacks[0])
    while stack:
        r, c = stack.pop()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 2 and (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))
    return len(visited) == len(blacks)

def validate_islands_uf(uf, state, clues, H, W):
    total_whites = sum(1 for row in state for cell in row if cell == 1)
    sum_sizes = 0
    for cr, cc, val in clues:
        id = cr * W + cc
        root = uf.find(id)
        if uf.clue[root] != val or uf.size[root] != val:
            return False
        sum_sizes += uf.size[root]
    if sum_sizes != total_whites:
        return False
    return True

def get_component(state, uf, H, W, root):
    return [(i, j) for i in range(H) for j in range(W) if state[i][j] == 1 and uf.find(i * W + j) == root]

def propagation(uf, state, H, W, clues):
    changed = True
    iterations = 0
    max_iter = H * W * 4  # safety
    while changed and iterations < max_iter:
        changed = False
        iterations += 1

        # Rule 1: complete islands - set adjacent to black
        for cr, cc, val in clues:
            id = cr * W + cc
            rt = uf.find(id)
            if uf.size[rt] == val:
                component = get_component(state, uf, H, W, rt)
                for r, c in component:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 0:
                            state[nr][nc] = 2
                            if not is_possible_black(nr, nc, state, H, W):
                                state[nr][nc] = 0
                                return False
                            changed = True

        # Rule: unfinished islands with insufficient expansion
        for cr, cc, val in clues:
            id = cr * W + cc
            rt = uf.find(id)
            current = uf.size[rt]
            if current < val:
                component = get_component(state, uf, H, W, rt)
                exp = set()
                for r, c in component:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 0:
                            exp.add((nr, nc))
                if len(exp) < val - current:
                    return False

        # Rule 2: cells not adjacent to any unfinished - set to black
        expansion_cells = set()
        for cr, cc, val in clues:
            id = cr * W + cc
            rt = uf.find(id)
            if uf.size[rt] < val:
                component = get_component(state, uf, H, W, rt)
                for r, c in component:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 0:
                            expansion_cells.add((nr, nc))
        for i in range(H):
            for j in range(W):
                if state[i][j] == 0 and (i, j) not in expansion_cells:
                    state[i][j] = 2
                    if not is_possible_black(i, j, state, H, W):
                        state[i][j] = 0
                        return False
                    changed = True

        # Rule 3: cells adjacent to multiple islands - set to black
        for i in range(H):
            for j in range(W):
                if state[i][j] == 0:
                    adj_roots = set()
                    for dr, dc in directions:
                        nr, nc = i + dr, j + dc
                        if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 1:
                            rt = uf.find(nr * W + nc)
                            if uf.clue[rt] > 0:
                                adj_roots.add(rt)
                    if len(adj_roots) > 1:
                        state[i][j] = 2
                        if not is_possible_black(i, j, state, H, W):
                            state[i][j] = 0
                            return False
                        changed = True

        # Rule 4: cells that cannot be black - set to white
        for i in range(H):
            for j in range(W):
                if state[i][j] == 0:
                    temp = state[i][j]
                    state[i][j] = 2
                    if not is_possible_black(i, j, state, H, W):
