                        state[i][j] = 1
                        success, _ = can_set_white(uf, state, i, j, H, W)
                        if not success:
                            state[i][j] = 0
                            return False
                        changed = True
                    else:
                        state[i][j] = temp
    return True

def backtrack(uf, state, H, W, clues):
    # Apply propagation
    if not propagation(uf, state, H, W, clues):
        return None

    # Check if all filled
    unknown = [(i, j) for i in range(H) for j in range(W) if state[i][j] == 0]
    if not unknown:
        if blacks_connected(state, H, W) and validate_islands_uf(uf, state, clues, H, W):
            out = [[None for _ in range(W)] for _ in range(H)]
            for i in range(H):
                for j in range(W):
                    if state[i][j] == 2:
                        out[i][j] = 'B'
            return out
        return None

    # Choose branch cell
    min_rem = math.inf
    selected_clue = None
    for cr, cc, val in clues:
        id = cr * W + cc
        rt = uf.find(id)
        rem = val - uf.size[rt]
        if 0 < rem < min_rem:
            min_rem = rem
            selected_clue = (cr, cc, val)
    if selected_clue is None:
        return None
    cr, cc, val = selected_clue
    rt = uf.find(cr * W + cc)
    component = get_component(state, uf, H, W, rt)
    adj_u = set()
    for r, c in component:
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and state[nr][nc] == 0:
                adj_u.add((nr, nc))
    if not adj_u:
        return None
    pick = min(adj_u, key=lambda x: (x[0], x[1]))
    r, c = pick

    # Try white
    state[r][c] = 1
    success, u_count = can_set_white(uf, state, r, c, H, W)
    if success:
        res = backtrack(uf, state, H, W, clues)
        if res is not None:
            return res
        for _ in range(u_count):
            uf.undo()
    state[r][c] = 0

    # Try black
    state[r][c] = 2
    if is_possible_black(r, c, state, H, W):
        res = backtrack(uf, state, H, W, clues)
        if res is not None:
            return res
    state[r][c] = 0

    return None

def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0])
    clues = [(i, j, data[i][j]) for i in range(H) for j in range(W) if data[i][j] is not None]
    state = [[0 for _ in range(W)] for _ in range(H)]
    uf = UF(H * W)
    for r, c, val in clues:
        id = r * W + c
        state[r][c] = 1
        uf.clue[id] = val
    result = backtrack(uf, state, H, W, clues)
    if result is None:
        return "No Solution"
    return result

