from collections import deque

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    empties = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def propagate(grid, forced_cells):
        changed = True
        while changed:
            changed = False
            for i in range(N - 1):
                for j in range(N - 1):
                    square = [(i + di, j + dj) for di in [0, 1] for dj in [0, 1]]
                    values = [grid[r][c] for r, c in square]
                    none_count = values.count(None)
                    if none_count == 0:
                        if all(v == values[0] for v in values) and values[0] is not None:
                            return False
                    elif none_count == 1:
                        non_nones = [v for v in values if v is not None]
                        if len(non_nones) > 0 and all(v == non_nones[0] for v in non_nones):
                            opp = 'W' if non_nones[0] == 'B' else 'B'
                            for r, c in square:
                                if grid[r][c] is None:
                                    grid[r][c] = opp
                                    forced_cells.append((r, c))
                                    changed = True
                                    break
        return True

    def check_possible_connected(grid, color):
        filled = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
        if not filled:
            return True
        visited = set()
        q = deque([filled[0]])
        visited.add(filled[0])
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in visited and (grid[nr][nc] == color or grid[nr][nc] is None):
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return all(pos in visited for pos in filled)

    def is_connected(grid, color):
        filled = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
        if not filled:
            return True
        visited = set()
        q = deque([filled[0]])
        visited.add(filled[0])
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in visited and grid[nr][nc] == color:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(filled)

    def backtrack(pos):
        if pos == len(empties):
            if is_connected(grid, 'B') and is_connected(grid, 'W'):
                return [row[:] for row in grid]
            return None
        i, j = empties[pos]
        if grid[i][j] is not None:
            forced_cells = []
            if propagate(grid, forced_cells) and check_possible_connected(grid, 'B') and check_possible_connected(grid, 'W'):
                res = backtrack(pos + 1)
                if res is not None:
                    return res
            for fi, fj in forced_cells:
                grid[fi][fj] = None
        else:
            for color in ['B', 'W']:
                grid[i][j] = color
                forced_cells = []
                if propagate(grid, forced_cells) and check_possible_connected(grid, 'B') and check_possible_connected(grid, 'W'):
                    res = backtrack(pos + 1)
                    if res is not None:
                        return res
                grid[i][j] = None
                for fi, fj in forced_cells:
                    grid[fi][fj] = None
        return None

    forced_cells = []
    if not propagate(grid, forced_cells) or not check_possible_connected(grid, 'B') or not check_possible_connected(grid, 'W'):
        return "No Solution"
    result = backtrack(0)
    if result is not None:
        return result
    return "No Solution"

