def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])
    grid = [['.' for _ in range(m)] for _ in range(n)]
    parent = {}
    size_d = {}
    required_d = {}
    roots = []
    for i in range(n):
        for j in range(m):
            if data[i][j] is not None:
                p = (i, j)
                grid[i][j] = 'W'
                parent[p] = p
                size_d[p] = 1
                required_d[p] = data[i][j]
                roots.append(p)
    # Check no two clues adjacent
    for p1 in roots:
        i1, j1 = p1
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i1 + di, j1 + dj
            if 0 <= ni < n and 0 <= nj < m and data[ni][nj] is not None and (ni, nj) != p1:
                return "No Solution"
    def find(p):
        if parent[p] != p:
            return find(parent[p])
        return p
    def get_unknown():
        return [(i, j) for i in range(n) for j in range(m) if grid[i][j] == '.']
    def propagate():
        candidates = set(get_unknown())
        while True:
            changed = False
            for cell in list(candidates):
                i, j = cell
                # can_b
                can_b = True
                for di in [0, 1]:
                    for dj in [0, 1]:
                        r1, c1 = i - di, j - dj
                        if 0 <= r1 < n - 1 and 0 <= c1 < m - 1:
                            cells = [(r1, c1), (r1, c1 + 1), (r1 + 1, c1), (r1 + 1, c1 + 1)]
                            count_b = sum(1 for rr, cc in cells if (rr, cc) != (i, j) and grid[rr][cc] == 'B')
                            if count_b == 3:
                                can_b = False
                                break
                    if not can_b:
                        break
                # can_w
                neighbors_roots = set()
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 'W':
                        root = find((ni, nj))
                        neighbors_roots.add(root)
                num = len(neighbors_roots)
                can_w = False
                temp_root = None
                if num == 1:
                    temp_root = next(iter(neighbors_roots))
                    if size_d[temp_root] + 1 <= required_d[temp_root]:
                        can_w = True
                if not can_b and not can_w:
                    return False
                if can_b and not can_w:
                    grid[i][j] = 'B'
                    changed = True
                    candidates.remove(cell)
                elif not can_b and can_w:
                    grid[i][j] = 'W'
                    p = (i, j)
                    root = temp_root
                    parent[p] = root
                    size_d[root] += 1
                    changed = True
                    candidates.remove(cell)
