    def compute_max_add(root):
        island_cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == 'W' and find((r, c)) == root]
        visited = set()
        q = deque()
        count = 0
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for r, c in island_cells:
