                        count += 1
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    safe = all(find((nnr, nnc)) == root for ddr, ddc in dirs for nnr, nnc in [(nr + ddr, nc + ddc)] if 0 <= nnr < n and 0 <= nnc < m and grid[nnr][nnc] == 'W')
                    if safe:
                        q.append((nr, nc))
                        visited.add((nr, nc))
                        count += 1
        return count
    def can_connect_black():
