        q = deque([start])
        visited.add(start)
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited and grid[nr][nc] in ('B', '.'):
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return all(b in visited for b in blacks)
    def is_connected_black():
        blacks = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'B']
        if not blacks:
            return True
        start = blacks[0]
        visited = set()
        q = deque([start])
        visited.add(start)
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited and grid[nr][nc] == 'B':
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(blacks)
    def backtrack():
        if not propagate():
            return False
        for root in roots:
            curr_size = size_d[root]
            if curr_size > required_d[root]:
