        neighbors_roots = set()
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 'W':
                neighbors_roots.add(find((ni, nj)))
        if len(neighbors_roots) == 1:
            root = next(iter(neighbors_roots))
            if size_d[root] + 1 <= required_d[root]:
                old_grid = grid[i][j]
                p = (i, j)
                parent[p] = root
                size_d[root] += 1
                grid[i][j] = 'W'
                if backtrack():
                    return True
                del parent[p]
                size_d[root] -= 1
                grid[i][j] = old_grid
        # try 'B'
        can_b = True
        for di in [0, 1]:
            for dj in [0, 1]:
                r1, c1 = i - di, j - dj
                if 0 <= r1 < n - 1 and 0 <= c1 < m - 1:
                    count_b = sum(1 for rr, cc in [(r1, c1), (r1, c1 + 1), (r1 + 1, c1), (r1 + 1, c1 + 1)] if (rr, cc) != (i, j) and grid[rr][cc] == 'B')
