                        can_b = False
                        break
            if not can_b:
                break
        if can_b:
            old_grid = grid[i][j]
            grid[i][j] = 'B'
            if backtrack():
                return True
            grid[i][j] = old_grid
        return False
    if backtrack():
        out = [[None if grid[i][j] != 'B' else 'B' for j in range(m)] for i in range(n)]
        return out
    else:
        return "No Solution"

