    possible_black = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None and not forced_black[i][j] and not forced_white[i][j]]
    possible_black.sort()

    def get_vis(gr, rr, cc, dr, dc):
        count = 0
        nr, nc = rr + dr, cc + dc
        while 0 <= nr < N and 0 <= nc < N:
            if gr[nr][nc] == 'B':
                break
            count += 1
            nr += dr
            nc += dc
        return count

    def check_constraints(gr):
        # Check vis
        for rr, cc, kk in clues:
            vis = 1 + get_vis(gr, rr, cc, 0, -1) + get_vis(gr, rr, cc, 0, 1) + get_vis(gr, rr, cc, -1, 0) + get_vis(gr, rr, cc, 1, 0)
            if vis != kk:
                return False
        # Check connectivity
        white = [(ii, jj) for ii in range(N) for jj in range(N) if gr[ii][jj] != 'B']
        if not white:
            return False
        visited = set()
        q = deque([white[0]])
        visited.add(white[0])
        while q:
            ci, cj = q.popleft()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < N and 0 <= nj < N and (ni, nj) not in visited and gr[ni][nj] != 'B':
                    visited.add((ni, nj))
                    q.append((ni, nj))
        return len(visited) == len(white)

    def search(idx):
        if idx == len(possible_black):
            return check_constraints(grid)
        rr, cc = possible_black[idx]
        # Try white
        grid[rr][cc] = None
        if search(idx + 1):
            return True
        # Try black if possible
        can_place = True
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = rr + di, cc + dj
            if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == 'B':
                can_place = False
                break
        if can_place:
            grid[rr][cc] = 'B'
            if search(idx + 1):
                return True
        grid[rr][cc] = None
        return False

    if search(0):
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
