OBSERVATION = {'U': [0,5,0,3,0], 'D': [0,0,2,0,4], 'L': [0,4,0,0,0], 'R': [3,0,0,3,3]}

from itertools import permutations

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    def get_possible_perms(N, front, back):
        all_perms = permutations(range(1, N + 1))
        possible = []
        for perm in all_perms:
            if front > 0:
                vis = 0
                max_h = 0
                for h in perm:
                    if h > max_h:
                        vis += 1
                        max_h = h
                if vis != front:
                    continue
            if back > 0:
                vis = 0
                max_h = 0
                for h in reversed(perm):
                    if h > max_h:
                        vis += 1
                        max_h = h
                if vis != back:
                    continue
            possible.append(perm)
        return possible

    # Compute possibles from rows and columns
    possibles = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    for i in range(N):
        perms = get_possible_perms(N, L[i], R[i])
        for j in range(N):
            possibles[i][j] &= set(p[j] for p in perms)

    for j in range(N):
        perms = get_possible_perms(N, U[j], D[j])
        for i in range(N):
            possibles[i][j] &= set(p[i] for p in perms)

    # Now compute filtered row possible perms
    row_possible_perms = []
    for i in range(N):
        perms = get_possible_perms(N, L[i], R[i])
        filtered = [p for p in perms if all(p[j] in possibles[i][j] for j in range(N))]
        row_possible_perms.append(filtered)

    # Backtracking function
    def bt(cur_row, col_used, grid):
        if cur_row == N:
            # Check column visibilities
            ok = True
            for j in range(N):
                line = [grid[i][j] for i in range(N)]
                if U[j] > 0:
                    vis = 0
                    max_h = 0
                    for h in line:
                        if h > max_h:
                            vis += 1
                            max_h = h
                    if vis != U[j]:
                        ok = False
                        break
                if D[j] > 0:
                    vis = 0
                    max_h = 0
                    for h in reversed(line):
                        if h > max_h:
                            vis += 1
                            max_h = h
                    if vis != D[j]:
                        ok = False
                        break
            if ok:
                return [row[:] for row in grid]
            return None

        for perm in row_possible_perms[cur_row]:
            can_place = True
            for j in range(N):
                if perm[j] in col_used[j]:
                    can_place = False
                    break
            if not can_place:
                continue

            # Place
            grid[cur_row] = list(perm)

            # New col_used
            new_col_used = [col_used[j].copy() for j in range(N)]
            for j in range(N):
                new_col_used[j].add(perm[j])

            # Partial check for U (top)
            ok = True
            for j in range(N):
                if U[j] == 0:
                    continue
                line = [grid[k][j] for k in range(cur_row + 1)]
                vis = 0
                max_h = 0
                for h in line:
                    if h > max_h:
                        vis += 1
                        max_h = h
                remaining = N - cur_row - 1
                if vis > U[j] or vis + remaining < U[j]:
                    ok = False
                    break
            if not ok:
                continue

            # Recurse
            res = bt(cur_row + 1, new_col_used, grid)
            if res is not None:
                return res

        # Backtrack
        grid[cur_row] = [0] * N
        return None

    grid = [[0 for _ in range(N)] for _ in range(N)]
    col_used = [set() for _ in range(N)]
    result = bt(0, col_used, grid)
    if result is not None:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
