import copy
from collections import defaultdict, deque

def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']
    n = len(row_counts)
    m = len(col_counts)

    # Directions for orthogonal neighbors
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # 8 directions for tent no-touch
    adj8 = [(di, dj) for di in range(-1, 2) for dj in range(-1, 2) if not (di == 0 and dj == 0)]

    # Find tree positions
    tree_positions = [(i, j) for i in range(n) for j in range(m) if tree_grid[i][j] == 'T']

    # Find possible tent cells: empty cells adjacent to exactly one tree
    tent_to_tree = {}
    for i in range(n):
        for j in range(m):
            if tree_grid[i][j] is not None:
                continue
            neighbors = [(ni, nj) for di, dj in directions
                         if 0 <= (ni := i + di) < n and 0 <= (nj := j + dj) < m and tree_grid[ni][nj] == 'T']
            if len(neighbors) == 1:
                tent_to_tree[(i, j)] = neighbors[0]

    # Group possible tents by tree
    tree_to_tents = defaultdict(list)
    for tent, tr in tent_to_tree.items():
        tree_to_tents[tr].append(tent)

    # Possibilities for each tree
    possibilities = {tr: tree_to_tents[tr] for tr in tree_positions}
    for tr in possibilities:
        if not possibilities[tr]:
            return "No Solution"

    # Remaining counts
    remaining_row = row_counts[:]
    remaining_col = col_counts[:]

    # Placed tents
    placed = set()

    # Propagate function
    def propagate(poss, rem_row, rem_col, pla):
        while True:
            changed = False

            # Remove from rows with remaining 0
            for i in range(n):
                if rem_row[i] == 0:
                    for tr in list(poss):
                        old_len = len(poss[tr])
                        poss[tr] = [p for p in poss[tr] if p[0] != i]
                        if len(poss[tr]) < old_len:
                            changed = True
                        if len(poss[tr]) == 0:
                            return False

            # Remove from columns with remaining 0
            for j in range(m):
                if rem_col[j] == 0:
                    for tr in list(poss):
                        old_len = len(poss[tr])
                        poss[tr] = [p for p in poss[tr] if p[1] != j]
                        if len(poss[tr]) < old_len:
                            changed = True
                        if len(poss[tr]) == 0:
                            return False

            # Place for trees with exactly one possibility
            for tr in list(poss):
                if len(poss[tr]) == 1:
                    p = poss[tr][0]
                    r, c = p
                    if p in pla or rem_row[r] <= 0 or rem_col[c] <= 0:
                        return False
                    pla.add(p)
                    rem_row[r] -= 1
                    rem_col[c] -= 1
                    del poss[tr]
                    changed = True
                    # Remove adjacent positions
                    for di, dj in adj8:
                        nr, nc = r + di, c + dj
                        if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in pla and (nr, nc) in tent_to_tree:
                            otr = tent_to_tree[(nr, nc)]
                            if otr in poss and (nr, nc) in poss[otr]:
                                poss[otr].remove((nr, nc))
                                if len(poss[otr]) == 0:
                                    return False

            if not changed:
                break
        # Check for any zero possibilities
        for tr in poss:
            if len(poss[tr]) == 0:
                return False
        return True

    # Initial propagation
    if not propagate(possibilities, remaining_row, remaining_col, placed):
        return "No Solution"

    # Search function
    def search(poss, rem_row, rem_col, pla):
        # If no more unassigned
        if not poss:
            return pla

        # Select tree with fewest possibilities
        unassigned = [tr for tr in poss if len(poss[tr]) > 0]
        if not unassigned:
            return pla
        tr = min(unassigned, key=lambda t: len(poss[t]))

        for p in poss[tr][:]:
            # Copy state
            poss2 = {k: v[:] for k, v in poss.items()}
            rem_row2 = rem_row[:]
            rem_col2 = rem_col[:]
            pla2 = pla.copy()

            # Place
            r, c = p
            if rem_row2[r] <= 0 or rem_col2[c] <= 0:
                continue
            pla2.add(p)
            rem_row2[r] -= 1
            rem_col2[c] -= 1

            # Remove the tree
            del poss2[tr]

            # Remove adjacent
            ok = True
            for di, dj in adj8:
                nr, nc = r + di, c + dj
                if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in pla2 and (nr, nc) in tent_to_tree:
                    otr = tent_to_tree[(nr, nc)]
                    if otr in poss2 and (nr, nc) in poss2[otr]:
                        poss2[otr].remove((nr, nc))
                        if len(poss2[otr]) == 0:
                            ok = False
                            break
            if not ok:
                continue

            # Propagate on new state
            if propagate(poss2, rem_row2, rem_col2, pla2):
                result = search(poss2, rem_row2, rem_col2, pla2)
                if result is not None:
                    return result
        return None

    # Run search
    final_placed = search(possibilities, remaining_row, remaining_col, placed)
    if final_placed is None:
        return "No Solution"

    # Build grid
    grid = [[None] * m for _ in range(n)]
    for r, c in final_placed:
        grid[r][c] = 't'
    return grid

