def visibility_left(seq):
    count = 0
    max_so_far = 0
    for h in seq:
        if h > max_so_far:
            count += 1
            max_so_far = h
    return count

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(L)
    import itertools
    row_possible = []
    for i in range(N):
        lc = L[i]
        rc = R[i]
        perms = [p for p in itertools.permutations(range(1, N + 1))
                 if (lc is None or visibility_left(p) == lc) and
                    (rc is None or visibility_left(p[::-1]) == rc)]
        row_possible.append(perms)
    grid = [[0] * N for _ in range(N)]
    used_col = [set() for _ in range(N)]
    def backtrack(row):
        if row == N:
            return [list(r) for r in grid]
        for perm in row_possible[row]:
            can_place = True
            for j in range(N):
                if perm[j] in used_col[j]:
                    can_place = False
                    break
            if not can_place:
                continue
            grid[row] = list(perm)
            old_used = [used_col[j].copy() for j in range(N)]
            for j in range(N):
                used_col[j].add(perm[j])
            can_continue = True
            current_k = row + 1
            for j in range(N):
                prefix = [grid[r][j] for r in range(current_k)]
                used_here = set(prefix)
                remaining = [h for h in range(1, N + 1) if h not in used_here]
                if U[j] is not None:
                    found = False
                    for p in itertools.permutations(remaining):
                        full = prefix + list(p)
                        if visibility_left(full) == U[j]:
                            found = True
                            break
                    if not found:
                        can_continue = False
                        break
                if D[j] is not None:
                    fixed_tail = [grid[r][j] for r in range(row, -1, -1)]
                    found = False
                    for p in itertools.permutations(remaining):
                        full_bottom = list(p) + fixed_tail
                        if visibility_left(full_bottom) == D[j]:
                            found = True
                            break
                    if not found:
                        can_continue = False
                        break
            if can_continue:
                res = backtrack(row + 1)
                if res is not None:
                    return res
            for j in range(N):
                used_col[j] = old_used[j]
            grid[row] = [0] * N
        return None
    result = backtrack(0)
    if result is None:
        return "No Solution"
    else:
        return result

