    R = observation['R']

    def visible_count(lst):
        count = 0
        max_h = 0
        for h in lst:
            if h > max_h:
                count += 1
                max_h = h
        return count

    import itertools
    possible_perms = []
    for i in range(N):
        cl_left = L[i]
        cl_right = R[i]
        poss = []
        for p in itertools.permutations(range(1, N + 1)):
            perm = list(p)
            vis_left = visible_count(perm)
            vis_right = visible_count(perm[::-1])
            if (cl_left is None or vis_left == cl_left) and (cl_right is None or vis_right == cl_right):
                poss.append(perm)
        possible_perms.append(poss)

    grid = [[0] * N for _ in range(N)]
    col_used = [set() for _ in range(N)]

    def backtrack(row_idx):
        if row_idx == N:
            for j in range(N):
                col = [grid[i][j] for i in range(N)]
                if U[j] is not None and visible_count(col) != U[j]:
                    return False
                if D[j] is not None and visible_count(col[::-1]) != D[j]:
                    return False
            return True

        for perm in possible_perms[row_idx]:
            can_place = True
            for j in range(N):
                if perm[j] in col_used[j]:
                    can_place = False
                    break
            if not can_place:
                continue

            # place
            for j in range(N):
                col_used[j].add(perm[j])
            grid[row_idx] = perm[:]

            # partial prune for U
            prune = False
            current_filled = row_idx + 1
            remaining = N - current_filled
            for j in range(N):
                if U[j] is None:
                    continue
                partial = [grid[i][j] for i in range(current_filled)]
                seen = visible_count(partial)
                if seen > U[j] or seen + remaining < U[j]:
                    prune = True
                    break

            if not prune:
                if backtrack(row_idx + 1):
                    return True

            # backtrack
            for j in range(N):
                col_used[j].remove(perm[j])

        return False

    if backtrack(0):
        return grid
    else:
        return "No Solution"

