            return None

    def check_connectivity(color):
        positions = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
        if not positions:
            return True
        def is_allowed(r, c):
            return 0 <= r < N and 0 <= c < N and (grid[r][c] == color or grid[r][c] is None)
        visited = set()
        def dfs(rr, cc):
            key = (rr, cc)
            if key in visited:
                return
            visited.add(key)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = rr + dr, cc + dc
                if is_allowed(nr, nc):
                    dfs(nr, nc)
        start = positions[0]
        dfs(start[0], start[1])
        reached = sum(1 for p in positions if p in visited)
        return reached == len(positions)

    # Initial propagation
    initial_forced = propagate()
    if initial_forced is None:
        return "No Solution"

    # Collect empties after initial propagation
    empty_list = []
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                num = 0
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and grid[ni][nj] is not None:
                        num += 1
                empty_list.append((num, i, j))
    empty_list.sort(reverse=True)
    empties = [(i, j) for num, i, j in empty_list]

    def backtrack(index):
        if index == len(empties):
            return True
        r, c = empties[index]
        for color in ['B', 'W']:
            prev = grid[r][c]
            grid[r][c] = color
            forced_list = propagate()
            if forced_list is not None:
                if check_connectivity('B') and check_connectivity('W'):
                    if backtrack(index + 1):
                        return True
                # Undo forced
                for fr, fc, fprev in forced_list:
                    grid[fr][fc] = fprev
            # Undo guess
            grid[r][c] = prev
        return False

    if backtrack(0):
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
