                    rem_min_col[k] += region_info[rrid]['min_col_add'][k]
                    rem_max_col[k] += region_info[rrid]['max_col_add'][k]
            prune = False
            for k in range(n):
                req = row_req[k]
                if not (new_row[k] + rem_min_row[k] <= req <= new_row[k] + rem_max_row[k]):
                    prune = True
                    break
            if prune:
