from collections import deque

def is_valid_partial(grid):
    N = len(grid)
    for i in range(N - 1):
        for j in range(N - 1):
            cells = [grid[i][j], grid[i][j + 1], grid[i + 1][j], grid[i + 1][j + 1]]
            if all(c is not None for c in cells) and all(c == cells[0] for c in cells):
                return False
    return True

def propagate(grid):
    N = len(grid)
    forced = []
    if not is_valid_partial(grid):
        return False, forced
    changed = True
    while changed:
        changed = False
        for r in range(N - 1):
            for c in range(N - 1):
                cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                col_list = [grid[x][y] for x, y in cells]
                nones = [p for p in cells if grid[p[0]][p[1]] is None]
                colors = [col for col in col_list if col is not None]
                if len(nones) == 1 and len(colors) == 3 and len(set(colors)) == 1:
                    opp = 'W' if colors[0] == 'B' else 'B'
                    x, y = nones[0]
                    old = grid[x][y]
                    if old is not None and old != opp:
                        return False, forced
                    if old is None:
                        grid[x][y] = opp
                        forced.append((x, y))
                        changed = True
        if not is_valid_partial(grid):
            return False, forced
    return True, forced

def is_connected(grid, color):
    N = len(grid)
    all_cells = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
    if not all_cells:
        return True
    start = all_cells[0]
    visited = set()
    q = deque([start])
    visited.add(start)
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and grid[nx][ny] == color:
                visited.add((nx, ny))
                q.append((nx, ny))
    return len(visited) == len(all_cells)

def can_connect(grid, color):
    N = len(grid)
    filled = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
    if not filled:
        return True
    start = filled[0]
    visited = set()
    q = deque([start])
    visited.add(start)
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and (grid[nx][ny] == color or grid[nx][ny] is None):
                visited.add((nx, ny))
                q.append((nx, ny))
    for pos in filled:
        if pos not in visited:
            return False
    return True

def backtrack(grid, unfilled, k, N):
    if k == len(unfilled):
        if all(grid[r][c] is not None for r in range(N) for c in range(N)) and is_connected(grid, 'B') and is_connected(grid, 'W'):
            return True
        return False
    i, j = unfilled[k]
    if grid[i][j] is not None:
        return backtrack(grid, unfilled, k + 1, N)
    for color in ['B', 'W']:
        grid[i][j] = color
        success, forced = propagate(grid)
        if success and can_connect(grid, 'B') and can_connect(grid, 'W'):
            if backtrack(grid, unfilled, k + 1, N):
                return True
        grid[i][j] = None
        for x, y in forced:
            grid[x][y] = None
    return False

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    success, _ = propagate(grid)
    if not success:
        return "No Solution"
    unfilled = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None]
    if backtrack(grid, unfilled, 0, N):
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
