        while changed:
            changed = False
            # Check rows
            for i in range(n):
                fixed = 0
                unknown = []
                for j in range(n):
                    status = grid[i][j]
                    if status == 1:
                        fixed += col_weight[j]
                    elif status is None:
                        unknown.append(j)
                add_max = sum(col_weight[j] for j in unknown)
                if fixed + add_max < row_sum[i] or fixed > row_sum[i]:
                    return False
                if not unknown:
                    if fixed != row_sum[i]:
                        return False
                    continue
                for j in unknown:
                    max_without = fixed + add_max - col_weight[j]
                    if max_without < row_sum[i]:
                        if grid[i][j] == 0:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = 1
                            changed = True
                    min_with = fixed + col_weight[j]
                    if min_with > row_sum[i]:
                        if grid[i][j] == 1:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = 0
                            changed = True
            # Check columns
            for j in range(n):
                fixed = 0
                unknown = []
                for i in range(n):
                    status = grid[i][j]
                    if status == 1:
                        fixed += row_weight[i]
                    elif status is None:
                        unknown.append(i)
                add_max = sum(row_weight[i] for i in unknown)
                if fixed + add_max < col_sum[j] or fixed > col_sum[j]:
                    return False
                if not unknown:
                    if fixed != col_sum[j]:
                        return False
                    continue
                for i in unknown:
                    max_without = fixed + add_max - row_weight[i]
                    if max_without < col_sum[j]:
                        if grid[i][j] == 0:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = 1
                            changed = True
                    min_with = fixed + row_weight[i]
                    if min_with > col_sum[j]:
                        if grid[i][j] == 1:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = 0
                            changed = True
        return True

    def search(grid):
        if not propagate(grid):
            return None
        branch_i = branch_j = -1
        for ii in range(n):
            for jj in range(n):
                if grid[ii][jj] is None:
                    branch_i = ii
                    branch_j = jj
                    break
            if branch_i >= 0:
                break
        if branch_i < 0:
            return [['B' if cell == 1 else None for cell in r] for r in grid]
        for val in [1, 0]:
            grid[branch_i][branch_j] = val
            res = search(grid)
            if res is not None:
                return res
            grid[branch_i][branch_j] = None
        return None

    grid = [[None for _ in range(n)] for _ in range(n)]
    res = search(grid)
    return res if res is not None else "No Solution"

