        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = '.'
                clue_list.append((r, c, data[r][c]))

    def get_ray(r, c, dir):
        ray = []
        if dir == 0:  # up
            for rr in range(r - 1, -1, -1):
                ray.append((rr, c))
        elif dir == 1:  # down
            for rr in range(r + 1, N):
                ray.append((rr, c))
        elif dir == 2:  # left
            for cc in range(c - 1, -1, -1):
                ray.append((r, cc))
        elif dir == 3:  # right
            for cc in range(c + 1, N):
                ray.append((r, cc))
        return ray

    def compute_min_max_for_clue(rr, cc):
        mins = [0] * 4
        maxs = [0] * 4
        for d in range(4):
            ray = get_ray(rr, cc, d)
            L = len(ray)
            # max_len
            first_forced = None
            for i in range(L):
                tr, tc = ray[i]
                if grid[tr][tc] == 'B':
                    first_forced = i
                    break
            maxl = L if first_forced is None else first_forced
            maxs[d] = maxl
            # min_len
            minl = L
            cum_can_dot = True
            for i in range(L):
                tr, tc = ray[i]
                state = grid[tr][tc]
                can_set_b = (state != '.')
                if cum_can_dot and can_set_b:
                    minl = min(minl, i)
                can_set_dot = (state != 'B')
                cum_can_dot = cum_can_dot and can_set_dot
            if cum_can_dot:
                minl = min(minl, L)
            mins[d] = minl
        min_total = 1 + sum(mins)
        max_total = 1 + sum(maxs)
        return min_total, max_total, mins, maxs

    def force_exact_len(rr, cc, d, m):
        ray = get_ray(rr, cc, d)
        L = len(ray)
        ch = False
        if m == L:
            for i in range(L):
                tr, tc = ray[i]
                state = grid[tr][tc]
                if state == 'B':
                    return -1
                if state is None:
                    grid[tr][tc] = '.'
                    ch = True
            return 1 if ch else 0
        else:
            for i in range(m):
                tr, tc = ray[i]
                state = grid[tr][tc]
                if state == 'B':
                    return -1
                if state is None:
                    grid[tr][tc] = '.'
                    ch = True
            tr, tc = ray[m]
            state = grid[tr][tc]
