                min_t, max_t, mins, maxs = compute_min_max_for_clue(rr, cc)
                if min_t > v or max_t < v:
                    return False
                S = v - 1
                sum_mins = sum(mins)
                sum_maxs = sum(maxs)
                if sum_mins == S:
                    for d in range(4):
                        res = force_exact_len(rr, cc, d, mins[d])
                        if res == -1:
