                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == '.' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) != len(whites):
                return False
            # verify visibilities
            for rr, cc, v in clue_list:
                total = 1
                for d in range(4):
                    ray = get_ray(rr, cc, d)
                    for ii in range(len(ray)):
                        tr, tc = ray[ii]
                        if grid[tr][tc] == 'B':
                            total += ii
                            break
                    else:
                        total += len(ray)
                if total != v:
                    return False
            return True
        # find branch cell
        branch_r, branch_c = -1, -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    branch_r, branch_c = r, c
                    break
            if branch_r != -1:
                break
        # try 'B'
        grid[branch_r][branch_c] = 'B'
        if backtrack():
            return True
        grid[branch_r][branch_c] = None
        # try '.'
        grid[branch_r][branch_c] = '.'
        if backtrack():
            return True
        grid[branch_r][branch_c] = None
        return False

    if backtrack():
        out = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if data[r][c] is not None:
                    out[r][c] = data[r][c]
                elif grid[r][c] == 'B':
                    out[r][c] = 'B'
        return out
    return "No Solution"

