    placement = [-1] * N
    unassigned = set(range(N))

    def bt():
        if not unassigned:
            return True
        min_size = float('inf')
        chosen_r = -1
        for r in unassigned:
            size = len(possibles[r])
            if size < min_size or (size == min_size and r < chosen_r):
                min_size = size
                chosen_r = r
        if min_size == 0:
            return False
        for j in list(possibles[chosen_r]):
            compatible = True
            for nr in [chosen_r - 1, chosen_r + 1]:
                if 0 <= nr < N and placement[nr] != -1:
                    if abs(j - placement[nr]) <= 1:
                        compatible = False
                        break
            if not compatible:
                continue
            placement[chosen_r] = j
            unassigned.remove(chosen_r)
            restorations = []
            can = True
            for k in list(unassigned):
                if j in possibles[k]:
                    possibles[k].remove(j)
                    restorations.append((k, j))
            for nr in [chosen_r - 1, chosen_r + 1]:
                if 0 <= nr < N and placement[nr] == -1:
                    for dm in [-1, 0, 1]:
                        m = j + dm
                        if 0 <= m < N and m in possibles[nr]:
                            possibles[nr].remove(m)
                            restorations.append((nr, m))
            for k in unassigned:
                if len(possibles[k]) == 0:
                    can = False
                    break
            if can:
                if bt():
                    return True
            placement[chosen_r] = -1
            unassigned.add(chosen_r)
            for k, m in restorations:
                possibles[k].add(m)
        return False

    if bt():
        grid = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            grid[r][placement[r]] = 'S'
        return str(grid)
    else:
        return "No Solution"

