        r2, c2 = cell2
        return r1 == r2 or c1 == c2

    def is_adjacent(cell1, cell2):
        r1, c1 = cell1
        r2, c2 = cell2
        return abs(r1 - r2) + abs(c1 - c2) == 1

    def satisfies_constraint(cell1, cell2, val1, val2):
        if is_same_row_or_col(cell1, cell2) and val1 == val2:
            return False
        if not is_adjacent(cell1, cell2):
