                    if len(possibles[xxj[0]][xxj[1]]) == 0:
                        cons = False
                    else:
                        for a_xk, a_xjj in arcs:
                            if a_xjj == xxj and a_xk != xxi:
                                q.append((a_xk, a_xjj))
            if cons and backtrack():
                return True
            possibles = saved_poss
        return False

