            possibles[best_r][best_c] = {num}
            grid[best_r][best_c] = num
            saved = []
            for k in range(N):
                if k != best_c and num in possibles[best_r][k]:
                    possibles[best_r][k].remove(num)
                    saved.append((best_r, k, num))
            for k in range(N):
