                        possibles[i][j].remove(num)
                        saved.append((i, j, num))
            # check immediate contradiction
            valid = True
            for k in range(N):
                if grid[best_r][k] is None and len(possibles[best_r][k]) == 0:
                    valid = False
            for k in range(N):
                if grid[k][best_c] is None and len(possibles[k][best_c]) == 0:
                    valid = False
            for i in range(N):
                for j in range(N):
                    if region[i][j] == region[best_r][best_c] and grid[i][j] is None and len(possibles[i][j]) == 0:
