            for rr, cc in cells:
                key = (rr, cc)
                if rr >= h:
                    if key in forced_empty:
                        consistent = False
                        break
                else:
                    if key in forced_water:
                        consistent = False
                        break
            if consistent:
                possible.add(h)
        return possible

    def search():
        possible_for_regions = {id_: get_possible_h(id_) for id_ in regions}
        if any(len(p) == 0 for p in possible_for_regions.values()):
            return None
        if all(len(p) <= 1 for p in possible_for_regions.values()):
            temp_grid = [[None for _ in range(m)] for _ in range(n)]
            for id_ in regions:
                if len(possible_for_regions[id_]) == 1:
                    h = list(possible_for_regions[id_])[0]
                    for rr, cc in region_cells[id_]:
                        temp_grid[rr][cc] = 'W' if rr >= h else None
            ok = True
            for r in range(n):
                count = sum(1 for c in range(m) if temp_grid[r][c] == 'W')
                if count != row_counts[r]:
                    ok = False
            for c in range(m):
                count = sum(1 for r in range(n) if temp_grid[r][c] == 'W')
                if count != col_counts[c]:
                    ok = False
            if ok:
                return temp_grid
            else:
                return None
        candidates = [id_ for id_ in regions if len(possible_for_regions[id_]) > 1]
        candidates.sort(key=lambda id_: len(possible_for_regions[id_]))
        chosen_id = candidates[0]
        possible = possible_for_regions[chosen_id]
        for h in sorted(possible):
            backup_water = forced_water.copy()
            backup_empty = forced_empty.copy()
            consistent = True
            for rr, cc in region_cells[chosen_id]:
                state = 'W' if rr >= h else None
                if not force_cell(rr, cc, state):
                    consistent = False
                    break
            if not consistent:
                forced_water = backup_water
                forced_empty = backup_empty
                continue
            if not propagate():
                forced_water = backup_water
                forced_empty = backup_empty
                continue
            result = search()
            if result is not None:
                return result
            forced_water = backup_water
            forced_empty = backup_empty
        return None

    result = search()
    if result is None:
        return "No Solution"
    return result

