            for i in range(N):
                for j in range(N):
                    if grid[i][j] is not None:
                        continue
                    new_pos = set(range(1, N + 1)) - row_used[i] - col_used[j]
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
