                                if 0 <= top < N - 1:
                                    has_dot = vert_dot[top][j]
                            if has_dot:
                                allowed = {k for k in range(1, N + 1) if abs(k - v) == 1}
                            else:
                                allowed = {k for k in range(1, N + 1) if abs(k - v) != 1}
                            new_pos &= allowed
                    if not new_pos:
                        return False
                    if len(new_pos) < len(possibles[i][j]):
                        changed = True
                    possibles[i][j] = new_pos
