        pos = list(possibles[ci][cj])
        for v in pos:
            grid[ci][cj] = v
            row_used[ci].add(v)
            col_used[cj].add(v)
            possibles[ci][cj] = {v}
            backup_poss = copy.deepcopy(possibles)
            if backtrack():
                return True
            possibles = backup_poss
            grid[ci][cj] = None
            row_used[ci].remove(v)
            col_used[cj].remove(v)
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

