        parts = k[1:-1].split(',')
        row = float(parts[0])
        c = float(parts[1])
        r = int(row - 0.5)
        if sym == '^':
            constraints.append(((r, int(c)), (r + 1, int(c))))
        elif sym == 'v':
            constraints.append(((r + 1, int(c)), (r, int(c))))

    # Initialize grid, domains, used
