            for cons in constraints:
                neighbors = cons['neighbors']
                k = cons['k']
                fixed_black = 0
                unknown = []
                for ni, nj in neighbors:
                    val = grid[ni][nj]
                    if val == 1:
                        fixed_black += 1
                    elif val == -1:
                        unknown.append((ni, nj))
                num_unknown = len(unknown)
                min_possible = fixed_black
                max_possible = fixed_black + num_unknown
                if max_possible < k or min_possible > k:
                    return True
                if max_possible == k:
                    for ui, uj in unknown:
                        if grid[ui][uj] == -1:
                            grid[ui][uj] = 1
                            changed = True
                if min_possible == k:
                    for ui, uj in unknown:
                        if grid[ui][uj] == -1:
                            grid[ui][uj] = 0
