                    if fixed_black + (num_unknown - 1) < k:
                        grid[ui][uj] = 1
                        changed = True
                    # Must be 0 if assuming 1 leads to min > k
                    if fixed_black + 1 > k:
                        grid[ui][uj] = 0
                        changed = True
        return False

    def backtrack(grid):
