        # Try 0
        new_grid = [row[:] for row in grid]
        new_grid[choice_i][choice_j] = 0
        res = backtrack(new_grid)
        if res is not None:
            return res
        # Try 1
        new_grid = [row[:] for row in grid]
        new_grid[choice_i][choice_j] = 1
        res = backtrack(new_grid)
        if res is not None:
            return res
        return None

    grid = [[-1 for _ in range(M)] for _ in range(N)]
    result = backtrack(grid)
    if result is None:
        return "No Solution"
    out_grid = [[None for _ in range(M)] for _ in range(N)]
    for i in range(N):
        for j in range(M):
