from collections import deque

def propagate(grid, N):
    while True:
        changed = False
        for i in range(N - 1):
            for j in range(N - 1):
                cells_pos = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
                colors = [grid[p[0]][p[1]] for p in cells_pos]
                if all(c is not None for c in colors):
                    if all(c == colors[0] for c in colors):
                        return False
                elif sum(1 for c in colors if c is None) == 1:
                    filled = [c for c in colors if c is not None]
                    if len(filled) > 0 and all(c == filled[0] for c in filled):
                        force_c = 'W' if filled[0] == 'B' else 'B'
                        for k, c in enumerate(colors):
                            if c is None:
                                ii, jj = cells_pos[k]
                                grid[ii][jj] = force_c
                                changed = True
                                break
        if not changed:
            break
    return True

def can_connect(color, grid, N):
    fixed = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
    if not fixed:
        return True
    visited = set()
    start = fixed[0]
    q = deque([start])
    visited.add(start)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and (grid[nx][ny] == color or grid[nx][ny] is None):
                visited.add((nx, ny))
                q.append((nx, ny))
    for pos in fixed:
        if pos not in visited:
            return False
    return True

def check_connected(color, grid, N):
    fixed = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == color]
    if not fixed:
        return True
    visited = set()
    start = fixed[0]
    q = deque([start])
    visited.add(start)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and grid[nx][ny] == color:
                visited.add((nx, ny))
                q.append((nx, ny))
    return len(visited) == len(fixed)

def backtrack(grid, N):
    if not propagate(grid, N):
        return None
    if not can_connect('B', grid, N) or not can_connect('W', grid, N):
        return None
    unfilled = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None]
    if not unfilled:
        if check_connected('B', grid, N) and check_connected('W', grid, N):
            return grid
        else:
            return None
    candidates = []
    for ii, jj in unfilled:
        possible = []
        for col in ['B', 'W']:
            temp = [r[:] for r in grid]
            temp[ii][jj] = col
            if propagate(temp, N) and can_connect('B', temp, N) and can_connect('W', temp, N):
                possible.append(col)
        if len(possible) == 0:
            return None
        candidates.append((len(possible), (ii, jj), possible))
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    min_num, best_i_j, best_possible = candidates[0]
    i, j = best_i_j
    for col in best_possible:
        new_grid = [r[:] for r in grid]
        new_grid[i][j] = col
        res = backtrack(new_grid, N)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    res = backtrack(grid, N)
    if res is not None:
        return res
    else:
        return "No Solution"

