            total_max = forced_sum + option_max
            target = col_sum[j]
            if total_min > target or total_max < target:
                return False
            needed = target - forced_sum
            for k_idx in range(len(optional) - 1, -1, -1):
                k = optional[k_idx]
                rw = row_weight[k]
                max_without = option_max - rw
                if max_without < needed:
                    status[k][j] = 1
                    changed = True
                    # Remove from optional and update forced_sum and option_max
                    forced_sum += rw
                    option_max -= rw
                    optional.pop(k_idx)
                    needed -= rw
                min_with = rw
                if min_with > needed:
                    status[k][j] = -1
                    changed = True
                    # Remove from optional and update option_max
                    option_max -= rw
                    optional.pop(k_idx)
    return True

def search(status, possibles, n, row_sum, col_sum, row_weight, col_weight):
    # Check if all decided
    all_decided = True
    undecided_i = -1
    undecided_j = -1
    for i in range(n):
        for j in range(n):
            if status[i][j] == 0:
                all_decided = False
                undecided_i = i
                undecided_j = j
                break
        if not all_decided:
            break
    if all_decided:
        grid = [[None] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if status[i][j] == 1:
                    grid[i][j] = 'B'
        return grid
    # Find row with smallest possibles >1
    min_len = float('inf')
    chosen_i = -1
    for i in range(n):
        l = len(possibles[i])
        if 1 < l < min_len:
            min_len = l
            chosen_i = i
    if chosen_i == -1:
        chosen_i = undecided_i
        chosen_j = undecided_j
    else:
        # Find first unknown in chosen_i
        for j in range(n):
            if status[chosen_i][j] == 0:
                chosen_j = j
                break
    # Try black
    status_copy = copy.deepcopy(status)
    possibles_copy = copy.deepcopy(possibles)
    status_copy[chosen_i][chosen_j] = 1
    if propagate(status_copy, possibles_copy, n, row_sum, col_sum, row_weight, col_weight):
        res = search(status_copy, possibles_copy, n, row_sum, col_sum, row_weight, col_weight)
        if res is not None:
            return res
    # Try white
    status_copy = copy.deepcopy(status)
    possibles_copy = copy.deepcopy(possibles)
    status_copy[chosen_i][chosen_j] = -1
    if propagate(status_copy, possibles_copy, n, row_sum, col_sum, row_weight, col_weight):
        res = search(status_copy, possibles_copy, n, row_sum, col_sum, row_weight, col_weight)
        if res is not None:
            return res
    return None

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n = len(row_sum)
    row_weight = list(range(1, n + 1))
    col_weight = list(range(1, n + 1))
    possibles = [[] for _ in range(n)]
    for i in range(n):
        target = row_sum[i]
        for mask in range(1 << n):
            s = sum(col_weight[j] for j in range(n) if mask & (1 << j))
            if s == target:
                possibles[i].append(mask)
    status = [[0] * n for _ in range(n)]
    if not propagate(status, possibles, n, row_sum, col_sum, row_weight, col_weight):
        return "No Solution"
    res = search(status, possibles, n, row_sum, col_sum, row_weight, col_weight)
    if res is not None:
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
