def solve(observation):
    N = len(observation['data'])
    grid = [row[:] for row in observation['data']]
    region_map = observation['region']
    regions = [[] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            regions[region_map[r][c]].append((r, c))
    possibles = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    rows = [[] for _ in range(N)]
    cols = [[] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            rows[r].append((r, c))
            cols[c].append((r, c))
    all_groups = rows + cols + regions

    # Initialize possibles based on givens
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                val = grid[r][c]
                possibles[r][c].clear()
                # Remove from row
                for i in range(N):
                    if i != c:
                        possibles[r][i].discard(val)
                # Remove from col
                for i in range(N):
                    if i != r:
                        possibles[i][c].discard(val)
                # Remove from region
                rid = region_map[r][c]
                for pr, pc in regions[rid]:
                    if (pr, pc) != (r, c):
                        possibles[pr][pc].discard(val)

    # Check initial consistency
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None and not possibles[r][c]:
                return "No Solution"

    def backtrack():
        # Propagation loop: naked and hidden singles
        while True:
            propagated = False

            # Naked singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None and len(possibles[r][c]) == 1:
                        val = list(possibles[r][c])[0]
                        grid[r][c] = val
                        possibles[r][c].clear()
                        changed = []
                        ok = True
                        # Remove from row
                        for i in range(N):
                            pr, pc = r, i
                            if i != c and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        # Remove from col
                        for i in range(N):
                            pr, pc = i, c
                            if i != r and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        # Remove from region
                        rid = region_map[r][c]
                        for pr, pc in regions[rid]:
                            if (pr, pc) != (r, c) and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        if not ok:
                            # Contradiction, restore not needed as we return False
                            return False
                        propagated = True
                        # Continue propagation
                        break  # Restart the while loop
                if propagated:
                    break
            if propagated:
                continue

            # Hidden singles
            for group in all_groups:
                pos_count = [[] for _ in range(N + 1)]
                for r, c in group:
                    if grid[r][c] is None:
                        for val in possibles[r][c]:
                            pos_count[val].append((r, c))
                for val in range(1, N + 1):
                    if len(pos_count[val]) == 1:
                        rr, cc = pos_count[val][0]
                        grid[rr][cc] = val
                        possibles[rr][cc].clear()
                        changed = []
                        ok = True
                        # Remove from row
                        for i in range(N):
                            pr, pc = rr, i
                            if i != cc and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        # Remove from col
                        for i in range(N):
                            pr, pc = i, cc
                            if i != rr and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        # Remove from region
                        rid = region_map[rr][cc]
                        for pr, pc in regions[rid]:
                            if (pr, pc) != (rr, cc) and grid[pr][pc] is None and val in possibles[pr][pc]:
                                possibles[pr][pc].remove(val)
                                changed.append((pr, pc))
                                if len(possibles[pr][pc]) == 0:
                                    ok = False
                        if not ok:
                            return False
                        propagated = True
                        break  # Break val loop
                if propagated:
                    break  # Break group loop
            if not propagated:
                break  # No more propagation

        # Check if solved
        solved = True
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    solved = False
                    break
            if not solved:
                break
        if solved:
            return True

        # Find cell with minimum possibilities
        min_poss = N + 1
        best_r, best_c = -1, -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    num = len(possibles[r][c])
                    if num == 0:
                        return False
                    if num < min_poss:
                        min_poss = num
                        best_r, best_c = r, c

        # Try values
        for val in list(possibles[best_r][best_c]):
            grid[best_r][best_c] = val
            changed = []
            ok = True
            # Remove from row
            for i in range(N):
                pr, pc = best_r, i
                if i != best_c and grid[pr][pc] is None and val in possibles[pr][pc]:
                    possibles[pr][pc].remove(val)
                    changed.append((pr, pc))
                    if len(possibles[pr][pc]) == 0:
                        ok = False
            # Remove from col
            for i in range(N):
                pr, pc = i, best_c
                if i != best_r and grid[pr][pc] is None and val in possibles[pr][pc]:
                    possibles[pr][pc].remove(val)
                    changed.append((pr, pc))
                    if len(possibles[pr][pc]) == 0:
                        ok = False
            # Remove from region
            rid = region_map[best_r][best_c]
            for pr, pc in regions[rid]:
                if (pr, pc) != (best_r, best_c) and grid[pr][pc] is None and val in possibles[pr][pc]:
                    possibles[pr][pc].remove(val)
                    changed.append((pr, pc))
                    if len(possibles[pr][pc]) == 0:
                        ok = False
            if ok:
                if backtrack():
                    return True
            # Backtrack
            grid[best_r][best_c] = None
            for ch_r, ch_c in changed:
                possibles[ch_r][ch_c].add(val)
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

