OBSERVATION = {'data': [[-1, -1, None, None, None, 1, None], [None, 2, None, None, None, None, None], [None, None, None, None, None, 1, 1], [None, None, None, 1, None, None, None], [1, -1, None, None, None, None, None], [None, None, None, -1, None, -1, None], [0, None, None, 1, -1, None, -1]]}

import copy

def place_bulb(i, j, grid, placement, illuminated, N):
    if placement[i][j] == '.':
        return False
    if placement[i][j] == 'B':
        return True
    placement[i][j] = 'B'
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    for di, dj in dirs:
        ni, nj = i + di, j + dj
        while 0 <= ni < N and 0 <= nj < N and grid[ni][nj] is None:
            if placement[ni][nj] == 'B':
                return False
            illuminated[ni][nj] = True
            if placement[ni][nj] is None:
                placement[ni][nj] = '.'
            ni += di
            nj += dj
    illuminated[i][j] = True
    return True

def apply_wall_constraints(grid, placement, illuminated, N):
    changed = False
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None or grid[i][j] < 0:
                continue
            num = grid[i][j]
            adj = []
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N and grid[ni][nj] is None:
                    adj.append((ni, nj))
            forced_b = 0
            forced_no = 0
            undecided = []
            for p in adj:
                if placement[p[0]][p[1]] == 'B':
                    forced_b += 1
                elif placement[p[0]][p[1]] == '.':
                    forced_no += 1
                else:
                    undecided.append(p)
            total_possible = len(undecided) + forced_b
            if forced_b > num or total_possible < num:
                return False, changed
            if total_possible == num:
                for p in undecided:
                    if not place_bulb(p[0], p[1], grid, placement, illuminated, N):
                        return False, changed
                    changed = True
            if forced_b == num:
                for p in undecided:
                    placement[p[0]][p[1]] = '.'
                    changed = True
    return True, changed

def apply_illum_deductions(grid, placement, illuminated, N):
    changed = False
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None or illuminated[i][j]:
                continue
            if placement[i][j] == 'B':
                continue
            if placement[i][j] == '.':
                return False, changed
            possible = set()
            # row left
            x = j - 1
            while x >= 0 and grid[i][x] is None:
                if placement[i][x] is None:
                    possible.add((i, x))
                x -= 1
            # row right
            x = j + 1
            while x < N and grid[i][x] is None:
                if placement[i][x] is None:
                    possible.add((i, x))
                x += 1
            # col up
            y = i - 1
            while y >= 0 and grid[y][j] is None:
                if placement[y][j] is None:
                    possible.add((y, j))
                y -= 1
            # col down
            y = i + 1
            while y < N and grid[y][j] is None:
                if placement[y][j] is None:
                    possible.add((y, j))
                y += 1
            # self
            possible.add((i, j))
            if len(possible) == 0:
                return False, changed
            if len(possible) == 1:
                p = next(iter(possible))
                if not place_bulb(p[0], p[1], grid, placement, illuminated, N):
                    return False, changed
                changed = True
    return True, changed

def propagate(grid, placement, illuminated, N):
    while True:
        ok1, ch1 = apply_wall_constraints(grid, placement, illuminated, N)
        if not ok1:
            return False
        ok2, ch2 = apply_illum_deductions(grid, placement, illuminated, N)
        if not ok2:
            return False
        if not (ch1 or ch2):
            break
    return True

def is_solved(grid, placement, illuminated, N):
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                continue
            if not illuminated[i][j]:
                return False
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None or grid[i][j] < 0:
                continue
            num = grid[i][j]
            count = 0
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N and placement[ni][nj] == 'B':
                    count += 1
            if count != num:
                return False
    return True

def find_undecided(placement, N):
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None and placement[i][j] is None:
                return i, j
    return None

def recursive_solve(grid, placement, illuminated, N):
    if not propagate(grid, placement, illuminated, N):
        return None
    if is_solved(grid, placement, illuminated, N):
        return placement
    pos = find_undecided(placement, N)
    if pos is None:
        return None
    i, j = pos
    # try 'B'
    p1 = copy.deepcopy(placement)
    illum1 = copy.deepcopy(illuminated)
    if place_bulb(i, j, grid, p1, illum1, N):
        res = recursive_solve(grid, p1, illum1, N)
        if res is not None:
            return res
    # try '.'
    p2 = copy.deepcopy(placement)
    illum2 = copy.deepcopy(illuminated)
    p2[i][j] = '.'
    res = recursive_solve(grid, p2, illum2, N)
    if res is not None:
        return res
    return None

def solve(observation):
    global grid
    grid = observation['data']
    N = len(grid)
    placement = [[None] * N for _ in range(N)]
    illuminated = [[False] * N for _ in range(N)]
    res = recursive_solve(grid, placement, illuminated, N)
    if res is None:
        return "No Solution"
    answer = [['B' if cell == 'B' else None for cell in row] for row in res]
    return answer

if __name__ == "__main__":
    print(solve(OBSERVATION))
