def solve(observation):
    data = observation['data']
    N = len(data)
    islands = []
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                islands.append((r, c, data[r][c]))
    num_islands = len(islands)
    if num_islands == 0:
        return '{}'

    # Find possible bridges
    bridges = []
    for idx in range(num_islands):
        r, c, _ = islands[idx]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                if data[nr][nc] is not None:
                    idx2 = next(i for i in range(num_islands) if islands[i][:2] == (nr, nc))
                    if idx < idx2:
                        bridges.append((idx, idx2))
                    break
                nr += dr
                nc += dc
    num_bridges = len(bridges)

    # Incident bridges for each island
    incident = [[] for _ in range(num_islands)]
    for k in range(num_bridges):
        i1, i2 = bridges[k]
        incident[i1].append(k)
        incident[i2].append(k)

    # Crossers
    crossers = [[] for _ in range(num_bridges)]
    for ka in range(num_bridges):
        for kb in range(ka + 1, num_bridges):
            i1, j1 = bridges[ka]
            r1, c1, _ = islands[i1]
            r2, c2, _ = islands[j1]
            if r1 > r2 or (r1 == r2 and c1 > c2):
                r1, r2, c1, c2 = r2, r1, c2, c1
            is_h_a = (r1 == r2)
            i3, j3 = bridges[kb]
            r3, c3, _ = islands[i3]
            r4, c4, _ = islands[j3]
            if r3 > r4 or (r3 == r4 and c3 > c4):
                r3, r4, c3, c4 = r4, r3, c4, c3
            is_h_b = (r3 == r4)
            if is_h_a == is_h_b:
                continue
            if not is_h_a:
                r1, r2, c1, c2, r3, r4, c3, c4 = r3, r4, c3, c4, r1, r2, c1, c2
            ca, cb = min(c1, c2), max(c1, c2)
            row = r1
            cc = c3
            ra, rb = min(r3, r4), max(r3, r4)
            if ra < row < rb and ca < cc < cb:
                crossers[ka].append(kb)
                crossers[kb].append(ka)

    def propagate(domains):
        changed = True
        while changed:
            changed = False
            for idx in range(num_islands):
                val = islands[idx][2]
                inc = incident[idx]
                cur_min = sum(min(domains[m]) for m in inc)
                cur_max = sum(max(domains[m]) for m in inc)
                if cur_max < val or cur_min > val:
                    return False
                for k in inc:
                    max_others = sum(max(domains[m]) for m in inc if m != k)
                    min_req = max(0, val - max_others)
                    min_others = sum(min(domains[m]) for m in inc if m != k)
                    max_allow = min(2, val - min_others)
                    if min_req > max_allow:
                        return False
                    old = domains[k].copy()
                    domains[k] &= set(range(min_req, max_allow + 1))
                    if not domains[k]:
                        return False
                    if len(domains[k]) < len(old):
                        changed = True
            for k in range(num_bridges):
                if 0 not in domains[k]:
                    for m in crossers[k]:
                        old = domains[m].copy()
                        domains[m] &= {0}
                        if not domains[m]:
                            return False
                        if len(domains[m]) < len(old):
                            changed = True
        return True

    def search(domains):
        if not propagate(domains):
            return None
        all_single = all(len(d) == 1 for d in domains)
        if all_single:
            assign = [list(d)[0] for d in domains]
            for idx in range(num_islands):
                val = islands[idx][2]
                cur = sum(assign[k] for k in incident[idx])
                if cur != val:
                    return None
            parent = list(range(num_islands))
            def find(x):
                if parent[x] != x:
                    parent[x] = find(parent[x])
                return parent[x]
            def union(x, y):
                px, py = find(x), find(y)
                if px != py:
                    parent[px] = py
            for k in range(num_bridges):
                if assign[k] > 0:
                    i1, i2 = bridges[k]
                    union(i1, i2)
            comp = set(find(i) for i in range(num_islands))
            if len(comp) != 1:
                return None
            answer = {}
            for k in range(num_bridges):
                cnt = assign[k]
                if cnt > 0:
                    i1, i2 = bridges[k]
                    p1 = islands[i1][:2]
                    p2 = islands[i2][:2]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    answer[(p1, p2)] = cnt
            return answer
        candidates = [(len(domains[k]), k) for k in range(num_bridges) if len(domains[k]) > 1]
        if not candidates:
            return None
        candidates.sort()
        _, chosen_k = candidates[0]
        for v in domains[chosen_k]:
            new_domains = [d.copy() for d in domains]
            new_domains[chosen_k] = {v}
            res = search(new_domains)
            if res is not None:
                return res
        return None

    domains = [set([0, 1, 2]) for _ in range(num_bridges)]
    result = search(domains)
    if result is None:
        return "No Solution"
    else:
        return str(result)

