    for j in range(N):
        seg = []
        for i in range(N):
            if state[i][j] is None:
                seg.append((i, j))
            else:
                if seg:
                    col_segments.append(seg)
                seg = []
        if seg:
            col_segments.append(seg)
    row_seg_for = {}
    col_seg_for = {}
    for seg in row_segments:
        for p in seg:
            row_seg_for[p] = seg
    for seg in col_segments:
        for p in seg:
            col_seg_for[p] = seg
    numbered = [(i, j, board[i][j]) for i in range(N) for j in range(N) if board[i][j] is not None and board[i][j] >= 0]
    def propagate():
        changed = True
        while changed:
            changed = False
            for p in whites:
                i, j = p
                if state[i][j] == 'B':
                    rseg = row_seg_for[p]
                    cseg = col_seg_for[p]
                    for q in rseg:
                        if q != p and state[q[0]][q[1]] is None:
                            state[q[0]][q[1]] = '.'
                            changed = True
                    for q in cseg:
                        if q != p and state[q[0]][q[1]] is None:
                            state[q[0]][q[1]] = '.'
                            changed = True
            for i, j, k in numbered:
                adj = []
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != '#':
                        adj.append((ni, nj))
                must_b = sum(1 for px in adj if state[px[0]][px[1]] == 'B')
                unknown = sum(1 for px in adj if state[px[0]][px[1]] is None)
                if must_b > k or must_b + unknown < k:
                    return False
                if must_b == k:
                    for px in adj:
                        if state[px[0]][px[1]] is None:
                            state[px[0]][px[1]] = '.'
                            changed = True
                if must_b + unknown == k:
                    for px in adj:
                        if state[px[0]][px[1]] is None:
                            state[px[0]][px[1]] = 'B'
                            changed = True
            forced_no = []
            for seg in row_segments + col_segments:
                has_b = any(state[p[0]][p[1]] == 'B' for p in seg)
                has_u = any(state[p[0]][p[1]] is None for p in seg)
                if not has_b and not has_u:
                    forced_no.append(seg)
            must_have = set()
            for seg in forced_no:
                is_row = all(p[0] == seg[0][0] for p in seg)
                for p in seg:
                    cross = col_seg_for[p] if is_row else row_seg_for[p]
                    must_have.add(id(cross))
            for seg_id in must_have:
                seg = next(s for s in row_segments + col_segments if id(s) == seg_id)
                must_b = sum(1 for p in seg if state[p[0]][p[1]] == 'B')
                unknown = sum(1 for p in seg if state[p[0]][p[1]] is None)
                if must_b > 1 or must_b + unknown < 1:
                    return False
                if must_b == 1:
                    for p in seg:
                        if state[p[0]][p[1]] is None:
                            state[p[0]][p[1]] = '.'
                            changed = True
                if must_b + unknown == 1:
                    for p in seg:
                        if state[p[0]][p[1]] is None:
                            state[p[0]][p[1]] = 'B'
                            changed = True
        return True
    def search():
        if not propagate():
            return None
        all_decided = all(state[i][j] is not None for i, j in whites)
        if all_decided:
            illuminated = [[False for _ in range(N)] for _ in range(N)]
            for i in range(N):
                for j in range(N):
                    if state[i][j] == 'B':
                        for jj in range(j - 1, -1, -1):
                            if state[i][jj] == '#':
                                break
                            illuminated[i][jj] = True
                        for jj in range(j + 1, N):
                            if state[i][jj] == '#':
                                break
                            illuminated[i][jj] = True
                        for ii in range(i - 1, -1, -1):
                            if state[ii][j] == '#':
                                break
                            illuminated[ii][j] = True
                        for ii in range(i + 1, N):
                            if state[ii][j] == '#':
                                break
                            illuminated[ii][j] = True
                        illuminated[i][j] = True
            ok = all(illuminated[i][j] for i, j in whites)
            if ok:
                result = [[ 'B' if state[r][c] == 'B' else None for c in range(N)] for r in range(N)]
                return result
            else:
                return None
        candidate = None
        for p in whites:
            if state[p[0]][p[1]] is None:
                candidate = p
                break
        if candidate is None:
            return None
        i, j = candidate
        original = state[i][j]
        state[i][j] = 'B'
        res = search()
        if res is not None:
            return res
        state[i][j] = original
        state[i][j] = '.'
        res = search()
        if res is not None:
            return res
        state[i][j] = original
        return None
    result = search()
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
