            cols_used[chosen_j].remove(val)
            regions_used[r].remove(val)
            for (p, q), v in zip(updated_cells, updated_vals):
                possible[p][q].add(v)
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

