OBSERVATION = {'data': [[None, 4, None, None, 6, None], [None, None, None, None, None, None], [None, 4, None, None, None, 6], [None, None, None, None, None, 4], [None, None, 3, None, None, None], [None, None, None, None, None, None]], 'horizontal': {'(0,0.5)': '>', '(0,2.5)': '<', '(1,0.5)': '>', '(2,0.5)': '<', '(3,0.5)': '>', '(3,1.5)': '>', '(5,0.5)': '>', '(5,1.5)': '>', '(5,3.5)': '<', '(5,4.5)': '<'}, 'vertical': {'(0.5,1)': 'v', '(1.5,5)': 'v', '(2.5,1)': 'v', '(2.5,5)': 'v', '(4.5,3)': '^'}}

import ast
from collections import defaultdict, deque
import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    poss = [[set() for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                val = grid[i][j]
                row_used[i].add(val)
                col_used[j].add(val)
                poss[i][j] = {val}
            else:
                poss[i][j] = set(range(1, N+1)) - row_used[i] - col_used[j]

    # Compute min max from chains
    min_from_row = [[1] * N for _ in range(N)]
    max_from_row = [[N] * N for _ in range(N)]
    min_from_col = [[1] * N for _ in range(N)]
    max_from_col = [[N] * N for _ in range(N)]

    def dfs(graph, start):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                for neigh in graph[node]:
                    stack.append(neigh)
        return visited

    # For rows
    for r in range(N):
        graph = defaultdict(list)
        inverse = defaultdict(list)
        for key, sym in observation['horizontal'].items():
            if key.startswith(f'({r},'):
                parts = ast.literal_eval(key)
                c = int(parts[1] - 0.5)
                left = c
                right = c + 1
                if sym == '<':
                    graph[right].append(left)
                    inverse[left].append(right)
                elif sym == '>':
                    graph[left].append(right)
                    inverse[right].append(left)
        for pos in range(N):
            desc = len(dfs(graph, pos)) - 1
            anc = len(dfs(inverse, pos)) - 1
            min_from_row[r][pos] = 1 + desc
            max_from_row[r][pos] = N - anc

    # For columns
    for c in range(N):
        graph = defaultdict(list)
        inverse = defaultdict(list)
        for key, sym in observation['vertical'].items():
            if key.endswith(f',{c})'):
                parts = ast.literal_eval(key)
                r = int(parts[0] - 0.5)
                upper = r
                lower = r + 1
                if sym == '^':
                    graph[lower].append(upper)
                    inverse[upper].append(lower)
                elif sym == 'v':
                    graph[upper].append(lower)
                    inverse[lower].append(upper)
        for pos in range(N):
            desc = len(dfs(graph, pos)) - 1
            anc = len(dfs(inverse, pos)) - 1
            min_from_col[pos][c] = 1 + desc
            max_from_col[pos][c] = N - anc

    # Apply min max
    for i in range(N):
        for j in range(N):
            minv = max(min_from_row[i][j], min_from_col[i][j])
            maxv = min(max_from_row[i][j], max_from_col[i][j])
            if minv > maxv:
                return "No Solution"
            poss[i][j] &= set(range(minv, maxv + 1))

    # Constraints
    constraints = []
    for key, sym in observation['horizontal'].items():
        parts = ast.literal_eval(key)
        r = int(parts[0])
        c = int(parts[1] - 0.5)
        cell1 = (r, c)
        cell2 = (r, c + 1)
        is_less = (sym == '<')
        constraints.append((cell1, cell2, is_less))

    for key, sym in observation['vertical'].items():
        parts = ast.literal_eval(key)
        r = int(parts[0] - 0.5)
        c = int(parts[1])
        cell1 = (r, c)
        cell2 = (r + 1, c)
        is_less = (sym == '^')
        constraints.append((cell1, cell2, is_less))

    # All arcs
    all_arcs = []
    for a, b, a_less_b in constraints:
        all_arcs.append((a, b, a_less_b))
        all_arcs.append((b, a, not a_less_b))

    incoming = defaultdict(list)
    for arc in all_arcs:
        _, y, _ = arc
        incoming[y].append(arc)

    def revise(x, y, x_less_y):
        if not poss[x[0]][x[1]]:
            return False
        old_size = len(poss[x[0]][x[1]])
        if poss[y[0]][y[1]]:
            if x_less_y:
                mx = max(poss[y[0]][y[1]])
                poss[x[0]][x[1]] = {v for v in poss[x[0]][x[1]] if v < mx}
            else:
                mn = min(poss[y[0]][y[1]])
                poss[x[0]][x[1]] = {v for v in poss[x[0]][x[1]] if v > mn}
        new_size = len(poss[x[0]][x[1]])
        return new_size < old_size

    def ac3():
        q = deque(all_arcs)
        while q:
            x, y, x_less_y = q.popleft()
            if revise(x, y, x_less_y):
                if not poss[x[0]][x[1]]:
                    return False
                for inc_arc in incoming[x]:
                    z, _, z_less_x = inc_arc
                    if z != y:
                        q.append(inc_arc)
        return True

    # Initial ac3
    if not ac3():
        return "No Solution"

    def assign(i, j, v):
        grid[i][j] = v
        row_used[i].add(v)
        col_used[j].add(v)
        for k in range(N):
            if k != j and grid[i][k] is None:
                if v in poss[i][k]:
                    poss[i][k].remove(v)
                    if not poss[i][k]:
                        return False
        for k in range(N):
            if k != i and grid[k][j] is None:
                if v in poss[k][j]:
                    poss[k][j].remove(v)
                    if not poss[k][j]:
                        return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False
            # Singletons
            for i in range(N):
                for j in range(N):
                    if grid[i][j] is None and len(poss[i][j]) == 1:
                        v = next(iter(poss[i][j]))
                        if v in row_used[i] or v in col_used[j]:
                            return False
                        if not assign(i, j, v):
                            return False
                        changed = True
            # Unique in row
            for i in range(N):
                unass = [j for j in range(N) if grid[i][j] is None]
                if not unass:
                    continue
                val_cands = defaultdict(list)
                for v in range(1, N + 1):
                    if v in row_used[i]:
                        continue
                    for k in unass:
                        if v in poss[i][k]:
                            val_cands[v].append(k)
                for v, cands in val_cands.items():
                    if len(cands) == 0:
                        return False
                    if len(cands) == 1:
                        k = cands[0]
                        if grid[i][k] is None:
                            if not assign(i, k, v):
                                return False
                            changed = True
            # Unique in col
            for j in range(N):
                unass = [i for i in range(N) if grid[i][j] is None]
                if not unass:
                    continue
                val_cands = defaultdict(list)
                for v in range(1, N + 1):
                    if v in col_used[j]:
                        continue
                    for k in unass:
                        if v in poss[k][j]:
                            val_cands[v].append(k)
                for v, cands in val_cands.items():
                    if len(cands) == 0:
                        return False
                    if len(cands) == 1:
                        k = cands[0]
                        if grid[k][j] is None:
                            if not assign(k, j, v):
                                return False
                            changed = True
        return True

    # Initial propagate
    if not propagate():
        return "No Solution"

    def backtrack(grid, poss, row_used, col_used):
        candidate = None
        min_size = float('inf')
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    size = len(poss[i][j])
                    if size == 0:
                        return False
                    if size < min_size:
                        min_size = size
                        candidate = (i, j)
        if candidate is None:
            return True
        i, j = candidate
        poss_copy = [[s.copy() for s in row] for row in poss]
        row_used_copy = [s.copy() for s in row_used]
        col_used_copy = [s.copy() for s in col_used]
        grid_copy = [row[:] for row in grid]
        for v in list(poss[i][j]):
            if v in row_used[i] or v in col_used[j]:
                continue
            grid[i][j] = v
            row_used[i].add(v)
            col_used[j].add(v)
            fail = False
            changed = []
            for k in range(N):
                if k != j and grid[i][k] is None and v in poss[i][k]:
                    poss[i][k].remove(v)
                    changed.append((i, k))
                    if not poss[i][k]:
                        fail = True
            for k in range(N):
                if k != i and grid[k][j] is None and v in poss[k][j]:
                    poss[k][j].remove(v)
                    changed.append((k, j))
                    if not poss[k][j]:
                        fail = True
            if not fail and propagate() and ac3():
                if backtrack(grid, poss, row_used, col_used):
                    return True
            # Undo the removes (assign is undone by copy)
            grid = [row[:] for row in grid_copy]
            poss = [[s.copy() for s in row] for row in poss_copy]
            row_used = [s.copy() for s in row_used_copy]
            col_used = [s.copy() for s in col_used_copy]
        return False

    if backtrack(grid, poss, row_used, col_used):
        return str(grid)
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
