                ver_seg[p] = seg
    # Constraints
    constraints = []
    for i in range(N):
        for j in range(N):
            k = grid[i][j]
            if isinstance(k, int) and k >= 0:
                adj = [(i + di, j + dj) for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                       if 0 <= i + di < N and 0 <= j + dj < N and grid[i + di][j + dj] is None]
                constraints.append({'pos': (i, j), 'k': k, 'adj': adj})
    # is_consistent function
    def is_consistent(assignment, unassigned):
        # Check numbered constraints
        for cons in constraints:
            placed = sum(1 for p in cons['adj'] if assignment.get(p, -1) == 1)
            unas = sum(1 for p in cons['adj'] if p in unassigned)
            k = cons['k']
            if placed > k or placed + unas < k:
                return False
        # Check illumination for assigned 0 cells
        for pos, val in assignment.items():
            if val == 0:
                h_seg = hor_seg[pos]
                h_bulb = any(assignment.get(p, -1) == 1 for p in h_seg)
                h_unas = any(p in unassigned for p in h_seg)
                if h_bulb or h_unas:
                    continue
                # hor all 0, check ver
                v_seg = ver_seg[pos]
                v_bulb = any(assignment.get(p, -1) == 1 for p in v_seg)
                v_unas = any(p in unassigned for p in v_seg)
                if not (v_bulb or v_unas):
                    return False
        return True
    # Initial assignment
    assignment = {}
    queue = []
    seen = set()
    for cons in constraints:
        if cons['k'] == 0:
            for p in cons['adj']:
                if p not in assignment and p not in seen:
                    queue.append((p, 0))
                    seen.add(p)
    while queue:
        pos, val = queue.pop(0)
        if pos in assignment:
            if assignment[pos] != val:
                return "No Solution"
            continue
        assignment[pos] = val
        if val == 1:
            for seg in [hor_seg[pos], ver_seg[pos]]:
                for other in seg:
                    if other != pos:
                        if other in assignment:
                            if assignment[other] == 1:
                                return "No Solution"
                        elif other not in seen:
                            queue.append((other, 0))
                            seen.add(other)
        # Propagate constraints
        for cons in constraints:
            if pos in cons['adj']:
                placed = sum(1 for p in cons['adj'] if assignment.get(p, -1) == 1)
                unas_list = [p for p in cons['adj'] if p not in assignment]
                unas = len(unas_list)
                k = cons['k']
                if placed > k or placed + unas < k:
                    return "No Solution"
                if placed == k:
                    for p in unas_list:
                        if p not in seen:
                            queue.append((p, 0))
                            seen.add(p)
                if placed + unas == k:
                    for p in unas_list:
                        if p not in seen:
                            queue.append((p, 1))
                            seen.add(p)
    if not is_consistent(assignment, set(whites) - set(assignment.keys())):
        return "No Solution"
    # Backtracking function
    def backtrack(assignment):
        if len(assignment) == len(whites):
            if is_consistent(assignment, set()):
                out = [[None for _ in range(N)] for _ in range(N)]
                for pos, val in assignment.items():
                    if val == 1:
                        out[pos[0]][pos[1]] = 'B'
                return out
            return None
        unassigned = [p for p in whites if p not in assignment]
        unassigned.sort(key=lambda p: len(hor_seg[p]) + len(ver_seg[p]))
        pos = unassigned[0]
        for val in [1, 0]:
            new_assignment = assignment.copy()
            new_queue = [(pos, val)]
            failed = False
            temp_seen = set()
            while new_queue and not failed:
                cpos, cval = new_queue.pop(0)
                if cpos in new_assignment:
                    if new_assignment[cpos] != cval:
                        failed = True
                        break
                new_assignment[cpos] = cval
                if cval == 1:
                    for seg in [hor_seg[cpos], ver_seg[cpos]]:
                        for other in seg:
                            if other != cpos:
                                if other in new_assignment:
                                    if new_assignment[other] == 1:
                                        failed = True
                                        break
                                elif other not in temp_seen:
                                    new_queue.append((other, 0))
                                    temp_seen.add(other)
                if failed:
                    break
                for cons in constraints:
                    if cpos in cons['adj']:
                        placed = sum(1 for p in cons['adj'] if new_assignment.get(p, -1) == 1)
                        unas_list = [p for p in cons['adj'] if p not in new_assignment]
                        unas = len(unas_list)
                        k = cons['k']
                        if placed > k or placed + unas < k:
                            failed = True
                            break
                        if placed == k:
                            for p in unas_list:
                                if p not in temp_seen:
                                    new_queue.append((p, 0))
                                    temp_seen.add(p)
                        if placed + unas == k:
                            for p in unas_list:
                                if p not in temp_seen:
                                    new_queue.append((p, 1))
                                    temp_seen.add(p)
                if failed:
                    break
            if not failed:
                if is_consistent(new_assignment, set(whites) - set(new_assignment.keys())):
                    result = backtrack(new_assignment)
                    if result is not None:
                        return result
        return None
    solution = backtrack(assignment)
    if solution is None:
        return "No Solution"
    return solution

if __name__ == "__main__":
    print(solve(OBSERVATION))
