    constraints = []
    for key, sym in horizontal.items():
        r, cp05 = ast.literal_eval(key)
        c = int(cp05 - 0.5)
        left = (r, c)
        right = (r, c+1)
        if sym == '<':
            constraints.append((left, right, '<'))
        else:
            constraints.append((left, right, '>'))
    for key, sym in vertical.items():
        rp05, c = ast.literal_eval(key)
        r = int(rp05 - 0.5)
        upper = (r, c)
        lower = (r+1, c)
        if sym == '^':
            constraints.append((upper, lower, '<'))
        else:
            constraints.append((upper, lower, '>'))

    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(N):
                used = set()
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        used.add(next(iter(domains[r][c])))
                for c in range(N):
                    if len(domains[r][c]) > 1:
                        old_len = len(domains[r][c])
                        domains[r][c] -= used
                        if len(domains[r][c]) < old_len:
                            changed = True
            for c in range(N):
                used = set()
                for r in range(N):
                    if len(domains[r][c]) == 1:
                        used.add(next(iter(domains[r][c])))
                for r in range(N):
                    if len(domains[r][c]) > 1:
                        old_len = len(domains[r][c])
                        domains[r][c] -= used
                        if len(domains[r][c]) < old_len:
                            changed = True
            for cell1, cell2, op in constraints:
                r1, c1 = cell1
                r2, c2 = cell2
                d1 = domains[r1][c1]
                d2 = domains[r2][c2]
                if len(d1) == 0 or len(d2) == 0:
                    return False
                if op == '<':
                    new_d1 = {v for v in d1 if any(w > v for w in d2)}
                    new_d2 = {v for v in d2 if any(w < v for w in d1)}
                    if len(new_d1) < len(d1):
                        domains[r1][c1] = new_d1
                        changed = True
                    if len(new_d2) < len(d2):
                        domains[r2][c2] = new_d2
                        changed = True
                else:
                    new_d1 = {v for v in d1 if any(w < v for w in d2)}
                    new_d2 = {v for v in d2 if any(w > v for w in d1)}
                    if len(new_d1) < len(d1):
                        domains[r1][c1] = new_d1
                        changed = True
                    if len(new_d2) < len(d2):
                        domains[r2][c2] = new_d2
                        changed = True
            for r in range(N):
                possible_positions = {v: [] for v in range(1, N+1)}
                for c in range(N):
                    for v in domains[r][c]:
                        possible_positions[v].append(c)
                for v, positions in possible_positions.items():
                    if len(positions) == 0:
                        return False
                    if len(positions) == 1:
                        cc = positions[0]
                        if len(domains[r][cc]) > 1:
                            domains[r][cc] = {v}
                            changed = True
            for c in range(N):
                possible_positions = {v: [] for v in range(1, N+1)}
                for rr in range(N):
                    for v in domains[rr][c]:
                        possible_positions[v].append(rr)
                for v, positions in possible_positions.items():
                    if len(positions) == 0:
                        return False
                    if len(positions) == 1:
                        rr = positions[0]
                        if len(domains[rr][c]) > 1:
                            domains[rr][c] = {v}
                            changed = True
            for rr in range(N):
                for cc in range(N):
                    if len(domains[rr][cc]) == 0:
                        return False
        return True

    if not propagate():
        return "No Solution"

    def is_solved():
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) != 1:
                    return False
        for cell1, cell2, op in constraints:
            v1 = next(iter(domains[cell1[0]][cell1[1]]))
            v2 = next(iter(domains[cell2[0]][cell2[1]]))
            if op == '<':
                if v1 >= v2:
                    return False
            else:
                if v1 <= v2:
                    return False
        for r in range(N):
            s = set(next(iter(domains[r][c])) for c in range(N))
            if len(s) != N:
                return False
        for c in range(N):
            s = set(next(iter(domains[r][c])) for r in range(N))
            if len(s) != N:
                return False
        return True

    if is_solved():
        grid = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
        return grid

    def find_cell():
        min_len = float('inf')
        cell = None
        for r in range(N):
            for c in range(N):
                l = len(domains[r][c])
                if 1 < l < min_len:
                    min_len = l
                    cell = (r, c)
        return cell

    def search():
        if is_solved():
            return True
        cell = find_cell()
        if cell is None:
            return False
        r, c = cell
        old_domains = copy.deepcopy(domains)
        for v in list(domains[r][c]):
            domains[r][c] = {v}
            if propagate():
                if search():
                    return True
            domains = copy.deepcopy(old_domains)
        return False

    if search():
        grid = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
