OBSERVATION = {'data': [[None, None, None, 1, None], [None, 2, 3, 4, None], [None, 3, 6, 6, None], [None, 5, None, 8, None], [None, None, 6, None, None]]}

import copy

def get_neigh(i, j, n, m):
    return [(r, c) for r in range(max(0, i-1), min(n, i+2)) for c in range(max(0, j-1), min(m, j+2))]

def propagate(grid, data, n, m):
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(m):
                if data[i][j] is not None:
                    N = data[i][j]
                    neigh = get_neigh(i, j, n, m)
                    S = len(neigh)
                    current_B = sum(1 for r, c in neigh if grid[r][c] == 'B')
                    current_W = sum(1 for r, c in neigh if grid[r][c] == 'W')
                    current_U = S - current_B - current_W
                    min_b = current_B
                    max_b = current_B + current_U
                    if min_b > N or max_b < N:
                        return False
                    if max_b == N:
                        for r, c in neigh:
                            if grid[r][c] is None:
                                grid[r][c] = 'B'
                                changed = True
                    if min_b == N:
                        for r, c in neigh:
                            if grid[r][c] is None:
                                grid[r][c] = 'W'
                                changed = True
    return True

def search(grid, data, n, m, degree):
    work_grid = copy.deepcopy(grid)
    if not propagate(work_grid, data, n, m):
        return None
    is_solved = all(work_grid[i][j] is not None for i in range(n) for j in range(m))
    if is_solved:
        for i in range(n):
            for j in range(m):
                if work_grid[i][j] == 'W':
                    work_grid[i][j] = None
        return work_grid
    # find unknown with max degree
    best_degree = -1
    pos_i, pos_j = -1, -1
    for i in range(n):
        for j in range(m):
            if work_grid[i][j] is None:
                d = degree[i * m + j]
                if d > best_degree:
                    best_degree = d
                    pos_i, pos_j = i, j
    if pos_i == -1:
        return None
    # try 'B'
    branch_grid_b = copy.deepcopy(work_grid)
    branch_grid_b[pos_i][pos_j] = 'B'
    res = search(branch_grid_b, data, n, m, degree)
    if res is not None:
        return res
    # try 'W'
    branch_grid_w = copy.deepcopy(work_grid)
    branch_grid_w[pos_i][pos_j] = 'W'
    res = search(branch_grid_w, data, n, m, degree)
    if res is not None:
        return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])
    numbered = [(i, j) for i in range(n) for j in range(m) if data[i][j] is not None]
    degree = [0] * (n * m)
    for ii, jj in numbered:
        for r, c in get_neigh(ii, jj, n, m):
            degree[r * m + c] += 1
    initial_grid = [[None] * m for _ in range(n)]
    result = search(initial_grid, data, n, m, degree)
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
