OBSERVATION = {'U': [2, 0, 1, 0, 0, 6], 'D': [0, 2, 2, 3, 0, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}

import itertools

def visible_count(seq, reverse=False):
    if reverse:
        seq = list(seq)[::-1]
    count = 0
    max_h = 0
    for h in seq:
        if h > max_h:
            count += 1
            max_h = h
    return count

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    # Precompute possible heights for each position in each row based on row clues
    row_poss = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        l_clue = L[r]
        r_clue = R[r]
        for perm in itertools.permutations(range(1, N+1)):
            if (l_clue == 0 or visible_count(perm) == l_clue) and (r_clue == 0 or visible_count(perm, reverse=True) == r_clue):
                for j in range(N):
                    row_poss[r][j].add(perm[j])
    # Precompute possible heights for each position in each column based on column clues
    col_poss = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for c in range(N):
        u_clue = U[c]
        d_clue = D[c]
        for perm in itertools.permutations(range(1, N+1)):
            if (u_clue == 0 or visible_count(perm) == u_clue) and (d_clue == 0 or visible_count(perm, reverse=True) == d_clue):
                for i in range(N):
                    col_poss[c][i].add(perm[i])
    # Combine into possibles[r][c]
    possibles = [[row_poss[r][c] & col_poss[c][r] for c in range(N)] for r in range(N)]
    grid = [[0] * N for _ in range(N)]

    def set_value(r, c, val):
        if grid[r][c] != 0:
            return grid[r][c] == val
        grid[r][c] = val
        for cc in range(N):
            if cc != c and val in possibles[r][cc]:
                possibles[r][cc].discard(val)
        for rr in range(N):
            if rr != r and val in possibles[rr][c]:
                possibles[rr][c].discard(val)
        return True

    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0 and len(possibles[r][c]) == 1:
                        val = next(iter(possibles[r][c]))
                        if set_value(r, c, val):
                            changed = True
            for r in range(N):
                counts = {}
                for c in range(N):
                    if grid[r][c] == 0:
                        for v in possibles[r][c]:
                            counts.setdefault(v, []).append(c)
                for v, locs in counts.items():
                    if len(locs) == 1:
                        c = locs[0]
                        if set_value(r, c, v):
                            changed = True
            for c in range(N):
                counts = {}
                for r in range(N):
                    if grid[r][c] == 0:
                        for v in possibles[r][c]:
                            counts.setdefault(v, []).append(r)
                for v, locs in counts.items():
                    if len(locs) == 1:
                        r = locs[0]
                        if set_value(r, c, v):
                            changed = True
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0 and len(possibles[r][c]) == 0:
                    return False
        return True

    if not propagate():
        return "No Solution"
    if all(grid[r][c] != 0 for r in range(N) for c in range(N)):
        return grid

    def find_min_cell():
        min_size = float('inf')
        min_r, min_c = -1, -1
        for r in range(N):
            for c in range(N):
                size = len(possibles[r][c])
                if grid[r][c] == 0 and 1 < size < min_size:
                    min_size = size
                    min_r, min_c = r, c
        return min_r, min_c

    def bt():
        if all(grid[r][c] != 0 for r in range(N) for c in range(N)):
            return True
        r, c = find_min_cell()
        if r == -1:
            return False
        save_grid = [row[:] for row in grid]
        save_poss = [[s.copy() for s in row] for row in possibles]
        for val in list(possibles[r][c]):
            if set_value(r, c, val):
                if propagate():
                    if bt():
                        return True
            grid = [row[:] for row in save_grid]
            possibles = [[s.copy() for s in row] for row in save_poss]
        return False

    if bt():
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
