from collections import defaultdict

def solve(observation):
    region = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']
    n = len(region)
    m = len(region[0])
    all_ids = set()
    for r in range(n):
        for c in range(m):
            all_ids.add(region[r][c])
    ids = sorted(all_ids)
    k = len(ids)
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            idd = region[r][c]
            region_cells[idd].append((r, c))
    region_col_rows = {}
    for idd in ids:
        col_dict = defaultdict(list)
        for r, c in region_cells[idd]:
            col_dict[c].append(r)
        for c in col_dict:
            col_dict[c].sort()
        region_col_rows[idd] = col_dict
    domains = {}
    for idd in ids:
        domains[idd] = list(range(n + 1))
    lower_bounds = {idd: 0 for idd in ids}
    upper_bounds = {idd: n for idd in ids}
    for r in range(n):
        inter = defaultdict(int)
        for c in range(m):
            idd = region[r][c]
            inter[idd] += 1
        inter_list = list(inter.items())
        mm = len(inter_list)
        if mm == 0:
            if row_targets[r] != 0:
                return "No Solution"
            continue
        possible_chosen = []
        target = row_targets[r]
        for mask in range(1 << mm):
            sum_s = 0
            chosen = set()
            for j in range(mm):
                if mask & (1 << j):
                    idd, s = inter_list[j]
                    sum_s += s
                    chosen.add(idd)
            if sum_s == target:
                possible_chosen.append(chosen)
        if not possible_chosen:
            return "No Solution"
        all_ids_inter = set(inter.keys())
        for idd in all_ids_inter:
            all_include = all(idd in ch for ch in possible_chosen)
            none_include = all(idd not in ch for ch in possible_chosen)
            if all_include:
                upper_bounds[idd] = min(upper_bounds[idd], r)
            if none_include:
                lower_bounds[idd] = max(lower_bounds[idd], r + 1)
    for idd in ids:
        low = lower_bounds[idd]
        up = upper_bounds[idd]
        if low > up:
            return "No Solution"
        domains[idd] = list(range(low, up + 1))
    order = sorted(ids, key=lambda idd: len(domains[idd]))
    assignment = {idd: None for idd in ids}
    grid = [[None for _ in range(m)] for _ in range(n)]
    row_curr = [0] * n
    col_curr = [0] * m
    def backtrack(index):
        if index == k:
            row_cnt = [0] * n
            col_cnt = [0] * m
            for r in range(n):
                for c in range(m):
                    idd = region[r][c]
                    l = assignment[idd]
                    if r >= l:
                        grid[r][c] = 'W'
                        row_cnt[r] += 1
                        col_cnt[c] += 1
                    else:
                        grid[r][c] = None
            if row_cnt == row_targets and col_cnt == col_targets:
                return True
            return False
        idd = order[index]
        for l in domains[idd]:
            assignment[idd] = l
            add_row = [0] * n
            add_col = [0] * m
            for rr, cc in region_cells[idd]:
                if rr >= l:
                    add_row[rr] += 1
                    add_col[cc] += 1
            exceed = False
            for rr in range(n):
                if row_curr[rr] + add_row[rr] > row_targets[rr]:
                    exceed = True
                    break
            if exceed:
                continue
            for cc in range(m):
                if col_curr[cc] + add_col[cc] > col_targets[cc]:
                    exceed = True
                    break
            if exceed:
                continue
            old_row = row_curr[:]
            old_col = col_curr[:]
            for rr in range(n):
                row_curr[rr] += add_row[rr]
            for cc in range(m):
                col_curr[cc] += add_col[cc]
            prune = False
            remaining_ids = [order[j] for j in range(index + 1, k)]
            for rr in range(n):
                min_rem = 0
                max_rem = 0
                for rem_id in remaining_ids:
                    s = 0
                    for cc2 in range(m):
                        if region[rr][cc2] == rem_id:
                            s += 1
                    has_le = any(ll <= rr for ll in domains[rem_id])
                    all_le = all(ll <= rr for ll in domains[rem_id])
                    contrib_min = s if all_le else 0
                    contrib_max = s if has_le else 0
                    min_rem += contrib_min
                    max_rem += contrib_max
                curr = row_curr[rr]
                if curr + min_rem > row_targets[rr] or curr + max_rem < row_targets[rr]:
                    prune = True
                    break
            if prune:
                row_curr[:] = old_row
                col_curr[:] = old_col
                continue
            for cc in range(m):
                min_rem = 0
                max_rem = 0
                for rem_id in remaining_ids:
                    if rem_id not in region_col_rows or cc not in region_col_rows[rem_id]:
                        continue
                    rows_list = region_col_rows[rem_id][cc]
                    min_l = min(domains[rem_id])
                    max_l = max(domains[rem_id])
                    count_max = sum(1 for rrr in rows_list if rrr >= min_l)
                    count_min = sum(1 for rrr in rows_list if rrr >= max_l)
                    min_rem += count_min
                    max_rem += count_max
                curr = col_curr[cc]
                if curr + min_rem > col_targets[cc] or curr + max_rem < col_targets[cc]:
                    prune = True
                    break
            if prune:
                row_curr[:] = old_row
                col_curr[:] = old_col
                continue
            if backtrack(index + 1):
                return True
            row_curr[:] = old_row
            col_curr[:] = old_col
        assignment[idd] = None
        return False
    if backtrack(0):
        return grid
    else:
        return "No Solution"

