def solve(observation):
    data = observation['data']
    N = len(data)
    constraints = []
    # Parse horizontal
    for key, sym in observation['horizontal'].items():
        parts = key[1:-1].split(',')
        r = int(float(parts[0].strip()))
        col = float(parts[1].strip())
        c = int(col - 0.5)
