        row = float(parts[0].strip())
        c = int(float(parts[1].strip()))
        r = int(row - 0.5)
        if 0 <= r < N - 1:
            op = '>' if sym == 'v' else '<'
            constraints.append(((r, c), (r + 1, c), op))

    grid = [[data[i][j] if data[i][j] is not None else 0 for j in range(N)] for i in range(N)]
    possible = [[set(range(1, N + 1)) if grid[i][j] == 0 else {grid[i][j]} for j in range(N)] for i in range(N)]

    def propagate(grid, possible):
        while True:
            changed = False
            # Row latin
            for i in range(N):
                used = {grid[i][j] for j in range(N) if grid[i][j] != 0}
                for j in range(N):
                    if grid[i][j] == 0:
                        old = len(possible[i][j])
                        possible[i][j] &= set(range(1, N + 1)) - used
                        if len(possible[i][j]) < old:
                            changed = True
            # Col latin
            for j in range(N):
                used = {grid[i][j] for i in range(N) if grid[i][j] != 0}
                for i in range(N):
                    if grid[i][j] == 0:
                        old = len(possible[i][j])
                        possible[i][j] &= set(range(1, N + 1)) - used
                        if len(possible[i][j]) < old:
                            changed = True
            # Constraints
            for p1, p2, op in constraints:
                r1, c1 = p1
                r2, c2 = p2
                L = possible[r1][c1]
                R = possible[r2][c2]
                new_L = {l for l in L if any((l > r if op == '>' else l < r) for r in R)}
                if len(new_L) < len(L):
                    possible[r1][c1] = new_L
                    changed = True
                new_R = {r for r in R if any((l > r if op == '>' else l < r) for l in L)}
                if len(new_R) < len(R):
                    possible[r2][c2] = new_R
                    changed = True
            # Set singles
            for i in range(N):
                for j in range(N):
                    if grid[i][j] == 0 and len(possible[i][j]) == 1:
                        grid[i][j] = next(iter(possible[i][j]))
                        changed = True
            # Check empty
            for i in range(N):
                for j in range(N):
                    if grid[i][j] == 0 and not possible[i][j]:
                        return False
            if not changed:
                break
        return True

    def backtrack(grid, possible):
        grid = copy.deepcopy(grid)
        possible = copy.deepcopy(possible)
        if not propagate(grid, possible):
            return None
        if all(grid[i][j] != 0 for i in range(N) for j in range(N)):
            return grid
        cand_i, cand_j, min_sz = -1, -1, math.inf
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 0:
                    sz = len(possible[i][j])
                    if sz < min_sz and sz > 1:
                        min_sz = sz
                        cand_i, cand_j = i, j
        if cand_i == -1:
            return None
        poss = sorted(possible[cand_i][cand_j])
        for val in poss:
            new_grid = copy.deepcopy(grid)
            new_possible = copy.deepcopy(possible)
            new_grid[cand_i][cand_j] = val
            new_possible[cand_i][cand_j] = {val}
            result = backtrack(new_grid, new_possible)
            if result is not None:
                return result
        return None

    if not propagate(grid, possible):
        return "No Solution"
    result = backtrack(grid, possible)
    if result is None:
        return "No Solution"
    return result

