def solve(observation):
    data = observation['data']
    N = len(data)
    horiz = observation['horizontal']
    vert = observation['vertical']

    # Parse inequalities: list of ((r1,c1), (r2,c2)) where grid[r1][c1] < grid[r2][c2]
    inequalities = []
    for k, s in horiz.items():
        pos = ast.literal_eval(k)
        r = int(pos[0])
        c = int(pos[1] - 0.5)
        if s == '<':
            inequalities.append(((r, c), (r, c + 1)))
        elif s == '>':
            inequalities.append(((r, c + 1), (r, c)))
    for k, s in vert.items():
        pos = ast.literal_eval(k)
        r = int(pos[0] - 0.5)
        c = int(pos[1])
        if s == '^':
            inequalities.append(((r, c), (r + 1, c)))
        elif s == 'v':
            inequalities.append(((r + 1, c), (r, c)))

    # Initialize possibilities
    poss = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if data[i][j] is not None:
                poss[i][j] = {data[i][j]}

    def propagate(p):
        changed = True
        while changed:
            changed = False
            # Rows: remove taken
            for i in range(N):
                taken = set()
                for j in range(N):
                    if len(p[i][j]) == 1:
                        taken.add(next(iter(p[i][j])))
                for j in range(N):
                    if len(p[i][j]) > 1:
                        old_len = len(p[i][j])
                        p[i][j] -= taken
                        if len(p[i][j]) == 0:
                            return False
                        if len(p[i][j]) < old_len:
                            changed = True
            # Columns: remove taken
            for j in range(N):
                taken = set()
                for i in range(N):
                    if len(p[i][j]) == 1:
                        taken.add(next(iter(p[i][j])))
                for i in range(N):
                    if len(p[i][j]) > 1:
                        old_len = len(p[i][j])
                        p[i][j] -= taken
                        if len(p[i][j]) == 0:
                            return False
                        if len(p[i][j]) < old_len:
                            changed = True
            # Rows: hidden singles
            for i in range(N):
                val_pos = [[] for _ in range(N + 1)]
                for j in range(N):
                    for v in p[i][j]:
                        val_pos[v].append(j)
                for v in range(1, N + 1):
                    if len(val_pos[v]) == 1:
                        j = val_pos[v][0]
                        if len(p[i][j]) > 1:
                            p[i][j] = {v}
                            changed = True
            # Columns: hidden singles
            for j in range(N):
                val_pos = [[] for _ in range(N + 1)]
                for i in range(N):
                    for v in p[i][j]:
                        val_pos[v].append(i)
                for v in range(1, N + 1):
                    if len(val_pos[v]) == 1:
                        ii = val_pos[v][0]
                        if len(p[ii][j]) > 1:
                            p[ii][j] = {v}
                            changed = True
            # Inequalities propagation
            for (r1, c1), (r2, c2) in inequalities:
                p1 = p[r1][c1]
                p2 = p[r2][c2]
                if not p1 or not p2:
                    return False
                max_p2 = max(p2)
                min_p1 = min(p1)
                new_p1 = {v for v in p1 if v < max_p2}
                new_p2 = {w for w in p2 if w > min_p1}
                if len(new_p1) < len(p1):
                    p[r1][c1] = new_p1
                    changed = True
                if len(new_p2) < len(p2):
                    p[r2][c2] = new_p2
                    changed = True
                if not new_p1 or not new_p2:
                    return False
        return True

    def backtrack(p):
        if not propagate(p):
            return False
        cand_i, cand_j, min_size = -1, -1, N + 1
        solved = True
        for i in range(N):
            for j in range(N):
                s = len(p[i][j])
                if s == 0:
                    return False
                if s > 1:
                    solved = False
                    if s < min_size:
                        min_size = s
                        cand_i = i
                        cand_j = j
        if solved:
            return True
        # Branch
        guesses = list(p[cand_i][cand_j])
        for v in guesses:
            new_p = copy.deepcopy(p)
            new_p[cand_i][cand_j] = {v}
            if backtrack(new_p):
                p[:] = new_p[:]
                return True
        return False

    if backtrack(poss):
        grid = [[next(iter(poss[i][j])) for j in range(N)] for i in range(N)]
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
