def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)

    def get_possible(line):
        Nl = len(line)
        empties = [i for i in range(Nl) if line[i] is None]
        e = len(empties)
        possibles = []
        for mask in range(1 << e):
            temp = line[:]
            nb = 0
            for j in range(e):
                val = 'B' if (mask & (1 << j)) else 'W'
                temp[empties[j]] = val
                if val == 'B':
                    nb += 1
            total_b = nb + sum(1 for x in line if x == 'B')
            if total_b != Nl // 2:
                continue
            valid = True
            for k in range(Nl - 2):
                if temp[k] == temp[k + 1] == temp[k + 2]:
                    valid = False
                    break
            if valid:
                possibles.append(temp[:])
        return possibles

    def propagate():
        changed = True
        iter_count = 0
        while changed and iter_count < 100:
            iter_count += 1
            changed = False
            # rows
            for r in range(N):
                other_full = {tuple(grid[rr]) for rr in range(N) if rr != r and all(grid[rr][j] is not None for j in range(N))}
                possibles = get_possible(grid[r])
                possibles = [p for p in possibles if tuple(p) not in other_full]
                if len(possibles) == 0:
                    return "contradiction"
                if len(possibles) == 1:
                    for j in range(N):
                        if grid[r][j] is None:
                            grid[r][j] = possibles[0][j]
                            changed = True
                else:
                    for j in range(N):
                        if grid[r][j] is None:
                            vals = {p[j] for p in possibles}
                            if len(vals) == 1:
                                grid[r][j] = list(vals)[0]
                                changed = True
            # columns
            for c in range(N):
                other_full = {tuple(grid[rrr][cc] for rrr in range(N)) for cc in range(N) if cc != c and all(grid[rrr][cc] is not None for rrr in range(N))}
                line = [grid[rr][c] for rr in range(N)]
                possibles = get_possible(line)
                possibles = [p for p in possibles if tuple(p) not in other_full]
                if len(possibles) == 0:
                    return "contradiction"
                if len(possibles) == 1:
                    for rr in range(N):
                        if grid[rr][c] is None:
                            grid[rr][c] = possibles[0][rr]
                            changed = True
                else:
                    for rr in range(N):
                        if grid[rr][c] is None:
                            vals = {p[rr] for p in possibles}
                            if len(vals) == 1:
                                grid[rr][c] = list(vals)[0]
                                changed = True
        return "ok"

    empty_list = [(r, c) for r in range(N) for c in range(N) if grid[r][c] is None]

    def backtrack(pos):
        if pos == len(empty_list):
            return [row[:] for row in grid]
        r, c = empty_list[pos]
        if grid[r][c] is not None:
            return backtrack(pos + 1)
        for val in ['B', 'W']:
            grid[r][c] = val
            res = propagate()
            if res != "contradiction":
                solution = backtrack(pos + 1)
                if solution is not None:
                    return solution
            grid[r][c] = None
        return None

    res = propagate()
    if res == "contradiction":
        return "No Solution"
    solution = backtrack(0)
    if solution:
        return solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
