                                    ok = False
                            # up
                            if ok and rr > 0 and grid[rr - 1][cc] is not None:
                                aa = grid[rr - 1][cc]
                                vdot = vert_dot[rr - 1][cc]
                                if vdot != (abs(aa - numm) == 1):
                                    ok = False
                            # down
                            if ok and rr < N - 1 and grid[rr + 1][cc] is not None:
                                aa = grid[rr + 1][cc]
                                vdot = vert_dot[rr][cc]
                                if vdot != (abs(aa - numm) == 1):
                                    ok = False
                            if ok:
                                count += 1
                    if count == 0:
                        return None
                    if count < min_count:
                        min_count = count
                        best_r, best_c = rr, cc
        if best_r == -1:
            return [row[:] for row in grid]

        r, c = best_r, best_c
        possible = []
        for num in range(1, N + 1):
            if (row_used[r] & (1 << (num - 1))) == 0 and (col_used[c] & (1 << (num - 1))) == 0:
                ok = True
                # left
                if c > 0 and grid[r][c - 1] is not None:
                    aa = grid[r][c - 1]
                    hdot = horz_dot[r][c - 1]
                    if hdot != (abs(aa - num) == 1):
                        ok = False
                # right
                if ok and c < N - 1 and grid[r][c + 1] is not None:
                    aa = grid[r][c + 1]
                    hdot = horz_dot[r][c]
                    if hdot != (abs(aa - num) == 1):
                        ok = False
                # up
                if ok and r > 0 and grid[r - 1][c] is not None:
                    aa = grid[r - 1][c]
                    vdot = vert_dot[r - 1][c]
                    if vdot != (abs(aa - num) == 1):
                        ok = False
                # down
                if ok and r < N - 1 and grid[r + 1][c] is not None:
                    aa = grid[r + 1][c]
                    vdot = vert_dot[r][c]
                    if vdot != (abs(aa - num) == 1):
                        ok = False
                if ok:
                    possible.append(num)

        for num in possible:
            grid[r][c] = num
            row_used[r] |= (1 << (num - 1))
            col_used[c] |= (1 << (num - 1))
            if propagate():
                res = backtrack()
                if res is not None:
                    return res
            # backtrack
            grid[r][c] = None
            row_used[r] &= ~(1 << (num - 1))
            col_used[c] &= ~(1 << (num - 1))
        return None

    res = backtrack()
    if res is None:
        return "No Solution"
    return res

