import sys
import math

def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)

    # Find max region ID
    max_region = 0
    for row in region:
        max_region = max(max_region, max(row))

    # Precompute cells for each row, column, region
    row_cells = [[] for _ in range(N)]
    col_cells = [[] for _ in range(N)]
    region_cells = [[] for _ in range(max_region + 1)]
    for r in range(N):
        for c in range(N):
            row_cells[r].append((r, c))
            col_cells[c].append((r, c))
            region_cells[region[r][c]].append((r, c))

    # Precompute peers for each cell
    peers = {}
    for r in range(N):
        for c in range(N):
            united = set(row_cells[r]) | set(col_cells[c]) | set(region_cells[region[r][c]])
            peers[(r, c)] = united - {(r, c)}

    # Initialize grid
    grid = [[data[r][c] for c in range(N)] for r in range(N)]

    # Initialize possibles
    possibles = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                possibles[(r, c)] = set(range(1, N + 1))

    # Propagate givens
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                num = grid[r][c]
                for pr, pc in peers[(r, c)]:
                    if (pr, pc) in possibles:
                        possibles[(pr, pc)].discard(num)

    # Check for immediate contradiction
    if any(len(poss) == 0 for poss in possibles.values()):
        return "No Solution"

    def search():
        # Deduce singles
        changed = True
        while changed:
            changed = False
            singles = [cell for cell in list(possibles) if len(possibles[cell]) == 1]
            for cell in singles:
                r, c = cell
                num = next(iter(possibles[cell]))
                grid[r][c] = num
                del possibles[cell]
                changed = True
                # Propagate
                for pr, pc in peers[(r, c)]:
                    if (pr, pc) in possibles:
                        possibles[(pr, pc)].discard(num)
                        if len(possibles[(pr, pc)]) == 0:
                            return False

        if not possibles:
            return True

        # Choose cell with minimum remaining values
        cell = min(possibles, key=lambda cl: len(possibles[cl]))
        r, c = cell
        poss = list(possibles[cell])
        del possibles[cell]

        for num in poss:
            grid[r][c] = num
            # Forward check
            conflicts = False
            removed = []
            for pr, pc in peers[(r, c)]:
                if (pr, pc) in possibles and num in possibles[(pr, pc)]:
                    possibles[(pr, pc)].remove(num)
                    removed.append((pr, pc, num))
                    if len(possibles[(pr, pc)]) == 0:
                        conflicts = True
                        break
            if not conflicts:
                if search():
                    return True
            # Undo forward check
            for pr, pc, n in removed:
                possibles[(pr, pc)].add(n)
            grid[r][c] = None

        # Restore
        possibles[cell] = set(poss)
        return False

    if search():
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
