def solve(observation):
    data = observation['data']
    N = len(data)
    islands = []
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                islands.append((r, c, data[r][c]))
    num_islands = len(islands)
    pos_to_idx = {(islands[i][0], islands[i][1]): i for i in range(num_islands)}
    links = []
    for r in range(N):
        cols = [c for c in range(N) if data[r][c] is not None]
        for k in range(len(cols) - 1):
            c1 = cols[k]
            c2 = cols[k + 1]
            p1 = (r, c1)
            p2 = (r, c2)
            links.append((p1, p2))
    for c in range(N):
        rows = [r for r in range(N) if data[r][c] is not None]
        for k in range(len(rows) - 1):
            r1 = rows[k]
            r2 = rows[k + 1]
            p1 = (r1, c)
            p2 = (r2, c)
            links.append((p1, p2))
    num_links = len(links)
    link_types = []
    link_ends = []
    for p1, p2 in links:
        if p1[0] == p2[0]:
            link_types.append('h')
            cmin = min(p1[1], p2[1])
            cmax = max(p1[1], p2[1])
            link_ends.append((p1[0], cmin, cmax))
        else:
            link_types.append('v')
            rmin = min(p1[0], p2[0])
            rmax = max(p1[0], p2[0])
            link_ends.append((p1[1], rmin, rmax))
    conflicts = [set() for _ in range(num_links)]
    for i in range(num_links):
        if link_types[i] == 'h':
            r, cmin, cmax = link_ends[i]
            for j in range(num_links):
                if link_types[j] == 'v':
                    c, rmin, rmax = link_ends[j]
                    if cmin < c < cmax and rmin < r < rmax:
                        conflicts[i].add(j)
                        conflicts[j].add(i)
    island_links = [[] for _ in range(num_islands)]
    for li in range(num_links):
        p1, p2 = links[li]
        i1 = pos_to_idx[p1]
        i2 = pos_to_idx[p2]
        island_links[i1].append(li)
        island_links[i2].append(li)
    vals = [islands[i][2] for i in range(num_islands)]
    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]
    def union(parent, rank, x, y):
        px = find(parent, x)
        py = find(parent, y)
        if px != py:
            if rank[px] < rank[py]:
                parent[px] = py
            elif rank[px] > rank[py]:
                parent[py] = px
            else:
                parent[py] = px
                rank[px] += 1
    def backtrack(link_idx, assignments, current_degree, parent, rank):
        if link_idx == num_links:
            root = find(parent, 0)
            if all(find(parent, i) == root for i in range(num_islands)):
                res = {}
                for li in range(num_links):
                    cnt = assignments[li]
                    if cnt > 0:
                        p1, p2 = links[li]
                        if p1 > p2:
                            p1, p2 = p2, p1
                        res[(p1, p2)] = cnt
                return res
            return None
        for cnt in (0, 1, 2):
            ok = True
            if cnt > 0:
                for conf in conflicts[link_idx]:
                    if conf < link_idx and assignments[conf] > 0:
                        ok = False
                        break
            if not ok:
                continue
            p1, p2 = links[link_idx]
            i1 = pos_to_idx[p1]
            i2 = pos_to_idx[p2]
            old_d1 = current_degree[i1]
            old_d2 = current_degree[i2]
            current_degree[i1] += cnt
            current_degree[i2] += cnt
            if current_degree[i1] > vals[i1] or current_degree[i2] > vals[i2]:
                current_degree[i1] = old_d1
                current_degree[i2] = old_d2
                continue
            old_parent = parent[:]
            old_rank = rank[:]
            if cnt > 0:
                union(parent, rank, i1, i2)
            can_continue = True
            for ii in range(num_islands):
                needed = vals[ii] - current_degree[ii]
                if needed < 0:
                    can_continue = False
                    break
                rem = 0
                all_ass = True
                for lli in island_links[ii]:
                    if assignments[lli] == -1:
                        rem += 2
                        all_ass = False
                if needed > rem:
                    can_continue = False
                    break
                if all_ass and needed != 0:
                    can_continue = False
                    break
            if not can_continue:
                current_degree[i1] = old_d1
                current_degree[i2] = old_d2
                parent = old_parent
                rank = old_rank
                continue
            comp_id = [find(parent, ii) for ii in range(num_islands)]
            comp = set(comp_id)
            num_comp = len(comp)
            if num_comp > 1:
                comp_map = {c: idx for idx, c in enumerate(comp)}
                comp_num = [comp_map[comp_id[ii]] for ii in range(num_islands)]
                comp_graph = [set() for _ in range(num_comp)]
                for lli in range(link_idx + 1, num_links):
                    pp1, pp2 = links[lli]
                    ii1 = pos_to_idx[pp1]
                    ii2 = pos_to_idx[pp2]
                    c1 = comp_num[ii1]
                    c2 = comp_num[ii2]
                    if c1 != c2:
                        comp_graph[c1].add(c2)
                        comp_graph[c2].add(c1)
                visited = [False] * num_comp
                from collections import deque
                q = deque([0])
                visited[0] = True
                count = 1
                while q:
                    u = q.popleft()
                    for v in comp_graph[u]:
                        if not visited[v]:
                            visited[v] = True
                            q.append(v)
                            count += 1
                if count < num_comp:
                    can_continue = False
            if not can_continue:
                current_degree[i1] = old_d1
                current_degree[i2] = old_d2
                parent = old_parent
                rank = old_rank
                continue
            assignments[link_idx] = cnt
            res = backtrack(link_idx + 1, assignments, current_degree, parent, rank)
            if res is not None:
                return res
            assignments[link_idx] = -1
            current_degree[i1] = old_d1
            current_degree[i2] = old_d2
            parent = old_parent
            rank = old_rank
        return None
    assignments = [-1] * num_links
    current_degree = [0] * num_islands
    parent = list(range(num_islands))
    rank = [0] * num_islands
    result = backtrack(0, assignments, current_degree, parent, rank)
    if result is not None:
        return str(result)
    else:
        return "No Solution"

