import copy
import itertools

def solve(observation):
    grid = copy.deepcopy(observation['data'])
    n = len(grid)
    k = n // 2

    def is_valid_line(line):
        if line.count('B') != k:
            return False
        s = ''.join(line)
        if 'BBB' in s or 'WWW' in s:
            return False
        return True

    all_patterns = []
    for comb in itertools.combinations(range(n), k):
        pat = ['W'] * n
        for i in comb:
            pat[i] = 'B'
        if is_valid_line(pat):
            all_patterns.append(tuple(pat))

    # Initialize possible_rows and possible_cols
    possible_rows = []
    for i in range(n):
        pr = [pat for pat in all_patterns if all(grid[i][j] is None or pat[j] == grid[i][j] for j in range(n))]
        possible_rows.append(pr)

    possible_cols = []
    for j in range(n):
        curr_col = [grid[r][j] for r in range(n)]
        pc = [pat for pat in all_patterns if all(curr_col[r] is None or pat[r] == curr_col[r] for r in range(n))]
        possible_cols.append(pc)

    # Propagation loop
    changed = True
    while changed:
        changed = False

        # Force from rows
        for i in range(n):
            if not possible_rows[i]:
                return "No Solution"
            for j in range(n):
                if grid[i][j] is None:
                    vals = {p[j] for p in possible_rows[i]}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        grid[i][j] = v
                        changed = True
                        # Prune column
                        possible_cols[j] = [p for p in possible_cols[j] if p[i] == v]
                        # Prune row (redundant)
                        possible_rows[i] = [p for p in possible_rows[i] if p[j] == v]

        # Force from columns
        for j in range(n):
            if not possible_cols[j]:
                return "No Solution"
            for r in range(n):
                if grid[r][j] is None:
                    vals = {p[r] for p in possible_cols[j]}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        grid[r][j] = v
                        changed = True
                        # Prune row
                        possible_rows[r] = [p for p in possible_rows[r] if p[j] == v]
                        # Prune column (redundant)
                        possible_cols[j] = [p for p in possible_cols[j] if p[r] == v]

        # Prune uniqueness for rows
        for i in range(n):
            if len(possible_rows[i]) == 1:
                pat = possible_rows[i][0]
                for ii in range(n):
                    if ii != i and pat in possible_rows[ii]:
                        possible_rows[ii].remove(pat)
                        changed = True

        # Prune uniqueness for columns
        for j in range(n):
            if len(possible_cols[j]) == 1:
                pat = possible_cols[j][0]
                for jj in range(n):
                    if jj != j and pat in possible_cols[jj]:
                        possible_cols[jj].remove(pat)
                        changed = True

    # Check if fully solved
    all_filled = all(grid[i][j] is not None for i in range(n) for j in range(n))
    if all_filled:
        rows = [tuple(grid[i]) for i in range(n)]
        if len(set(rows)) != n:
            return "No Solution"
        cols = [tuple(grid[r][j] for r in range(n)) for j in range(n)]
        if len(set(cols)) != n:
            return "No Solution"
        return grid

    # Backtracking function
    def backtrack(curr_row, used):
        if curr_row == n:
            cols = [tuple(grid[r][c] for r in range(n)) for c in range(n)]
            if len(set(cols)) == n and all(is_valid_line(list(col)) for col in cols):
                return True
            return False

        for pat_t in possible_rows[curr_row]:
            if pat_t in used:
                continue
            # Assign
            save = grid[curr_row][:]
            grid[curr_row] = list(pat_t)
            # Check partial
            can = True
            r_filled = curr_row + 1
            remain = n - r_filled
            for c in range(n):
                partial = [grid[rr][c] for rr in range(r_filled)]
                b = partial.count('B')
                if not (k - remain <= b <= k):
                    can = False
                    break
                pstr = ''.join(partial)
                if 'BBB' in pstr or 'WWW' in pstr:
                    can = False
                    break
            if can:
                if backtrack(curr_row + 1, used | {pat_t}):
                    return True
            # Undo
            grid[curr_row] = save
        return False

    if backtrack(0, set()):
        return grid
    else:
        return "No Solution"

