OBSERVATION = {'data': [[None, 4, 4, None, None, 1, None], [None, None, None, None, None, None, None], [9, 7, 4, 3, 5, None, None], [6, None, 2, None, 5, None, None], [3, 5, None, None, 4, None, None], [None, None, 1, None, None, None, None], [3, 2, None, None, 1, None, None]]}

def get_neighbors(i, j, rows, cols):
    neighbors = []
    for di in [-1, 0, 1]:
        for dj in [-1, 0, 1]:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                neighbors.append((ni, nj))
    return neighbors

def basic_propagate(grid, constraints):
    changed = False
    for neigh, k in constraints:
        current_black = 0
        num_unknown = 0
        unknowns = []
        for r, c in neigh:
            v = grid[r][c]
            if v == 1:
                current_black += 1
            elif v == -1:
                num_unknown += 1
                unknowns.append((r, c))
        min_p = current_black
        max_p = current_black + num_unknown
        if max_p < k or min_p > k:
            return False, False
        if num_unknown == 0:
            if current_black != k:
                return False, False
            continue
        needed = k - current_black
        if needed == 0:
            for r, c in unknowns:
                grid[r][c] = 0
            changed = True
        elif needed == num_unknown:
            for r, c in unknowns:
                grid[r][c] = 1
            changed = True
    return True, changed

def full_propagate(grid, constraints):
    while True:
        consistent, changed = basic_propagate(grid, constraints)
        if not consistent:
            return False
        if not changed:
            break
    return True

def search(grid, constraints, rows, cols):
    unknown = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == -1:
                unknown = (i, j)
                break
        if unknown:
            break
    if not unknown:
        for neigh, k in constraints:
            s = sum(grid[r][c] for r, c in neigh)
            if s != k:
                return None
        return grid
    i, j = unknown
    for val in [0, 1]:
        new_grid = [row[:] for row in grid]
        new_grid[i][j] = val
        if full_propagate(new_grid, constraints):
            result = search(new_grid, constraints, rows, cols)
            if result is not None:
                return result
    return None

def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return []
    cols = len(data[0])
    constraints = []
    for i in range(rows):
        for j in range(cols):
            if data[i][j] is not None:
                neigh = get_neighbors(i, j, rows, cols)
                k = data[i][j]
                if k < 0 or k > len(neigh):
                    return "No Solution"
                constraints.append((neigh, k))
    grid = [[-1] * cols for _ in range(rows)]
    if not full_propagate(grid, constraints):
        return "No Solution"
    sol = search(grid, constraints, rows, cols)
    if sol is None:
        return "No Solution"
    output = [['B' if sol[i][j] == 1 else None for j in range(cols)] for i in range(rows)]
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
