from collections import defaultdict, deque

def solve(observation):
    data = observation['data']
    N = len(data)
    horizontal = observation['horizontal']
    vertical = observation['vertical']
    # build graph: edge A -> B meaning value(A) < value(B)
    graph = defaultdict(list)
    incoming = defaultdict(list)
    # horizontal
    for k, s in horizontal.items():
        parts = k[1:-1].split(', ')
        r = int(float(parts[0]))
        c = float(parts[1]) - 0.5
        left = (r, int(c))
        right = (r, int(c)+1)
        if s == '<':
            graph[left].append(right)
            incoming[right].append(left)
        elif s == '>':
            graph[right].append(left)
            incoming[left].append(right)
    # vertical
    for k, s in vertical.items():
        parts = k[1:-1].split(', ')
        r = float(parts[0]) - 0.5
        c = int(float(parts[1]))
        upper = (int(r), c)
        lower = (int(r)+1, c)
        if s == '^':
            graph[upper].append(lower)
            incoming[lower].append(upper)
        elif s == 'v':
            graph[lower].append(upper)
            incoming[upper].append(lower)
    # detect cycle
    visited = {}
    rec_stack = {}
    def has_cycle(node):
        visited[node] = True
        rec_stack[node] = True
        for succ in graph[node]:
            if not visited.get(succ, False):
                if has_cycle(succ):
                    return True
            elif rec_stack.get(succ, False):
                return True
        rec_stack[node] = False
        return False
    cycle = False
    for i in range(N):
        for j in range(N):
            node = (i, j)
            if not visited.get(node, False):
                if has_cycle(node):
                    cycle = True
                    break
        if cycle: break
    if cycle:
        return "No Solution"
    # compute longest_to for min
    memo = {}
    def longest_to(node):
        if node in memo:
            return memo[node]
        if not incoming[node]:
            memo[node] = 0
            return 0
        max_p = 0
        for pred in incoming[node]:
            p = longest_to(pred) + 1
            max_p = max(max_p, p)
        memo[node] = max_p
        return max_p
    min_grid = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            min_grid[i][j] = longest_to((i, j)) + 1
            if min_grid[i][j] > N:
                return "No Solution"
    # longest_from for max
    memo = {}
    def longest_from(node):
        if node in memo:
            return memo[node]
        if not graph[node]:
            memo[node] = 0
            return 0
        max_p = 0
        for succ in graph[node]:
            p = longest_from(succ) + 1
            max_p = max(max_p, p)
        memo[node] = max_p
        return max_p
    max_grid = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            l = longest_from((i, j))
            max_grid[i][j] = N - l
            if max_grid[i][j] < 1:
                return "No Solution"
            if min_grid[i][j] > max_grid[i][j]:
                return "No Solution"
    # set up grid, used
    grid = [row[:] for row in data]
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                v = grid[i][j]
                if v < min_grid[i][j] or v > max_grid[i][j]:
                    return "No Solution"
                if v in row_used[i] or v in col_used[j]:
                    return "No Solution"
                row_used[i].add(v)
                col_used[j].add(v)
    # check initial inequalities for filled
    for k, s in horizontal.items():
        parts = k[1:-1].split(', ')
        r = int(float(parts[0]))
        c = float(parts[1]) - 0.5
        left = grid[r][int(c)]
        right = grid[r][int(c)+1]
        if left is not None and right is not None:
            if s == '<':
                if not left < right:
                    return "No Solution"
            elif s == '>':
                if not left > right:
                    return "No Solution"
    for k, s in vertical.items():
        parts = k[1:-1].split(', ')
        r = float(parts[0]) - 0.5
        c = int(float(parts[1]))
        upper = grid[int(r)][c]
        lower = grid[int(r)+1][c]
        if upper is not None and lower is not None:
            if s == '^':
                if not upper < lower:
                    return "No Solution"
            elif s == 'v':
                if not upper > lower:
                    return "No Solution"
    # propagation of bounds from placed
    queue = deque()
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                queue.append((i, j))
    def propagate_bounds():
        while queue:
            i, j = queue.popleft()
            v = grid[i][j]
            # tighten succ min
            for si, sj in graph[(i, j)]:
                new_min = v + 1
                if min_grid[si][sj] < new_min:
                    min_grid[si][sj] = new_min
                    if min_grid[si][sj] > max_grid[si][sj]:
                        return False
                    if grid[si][sj] is not None and grid[si][sj] < new_min:
                        return False
                    queue.append((si, sj))
            # tighten pred max
            for pi, pj in incoming[(i, j)]:
                new_max = v - 1
                if max_grid[pi][pj] > new_max:
                    max_grid[pi][pj] = new_max
                    if min_grid[pi][pj] > max_grid[pi][pj]:
                        return False
                    if grid[pi][pj] is not None and grid[pi][pj] > new_max:
                        return False
                    queue.append((pi, pj))
        return True
    if not propagate_bounds():
        return "No Solution"
    # forced placements
    while True:
        forced = False
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    poss = [v for v in range(1, N+1) if min_grid[i][j] <= v <= max_grid[i][j] and v not in row_used[i] and v not in col_used[j]]
                    if len(poss) == 0:
                        return "No Solution"
                    if len(poss) == 1:
                        v = poss[0]
                        grid[i][j] = v
                        row_used[i].add(v)
                        col_used[j].add(v)
                        queue.append((i, j))
                        forced = True
        if not forced:
            break
        if not propagate_bounds():
            return "No Solution"
    # check if all filled
    all_filled = all(grid[i][j] is not None for i in range(N) for j in range(N))
    if all_filled:
        return grid
    # backtracking
    def check_ineq(i, j, v):
        node = (i, j)
        for pi, pj in incoming[node]:
            pv = grid[pi][pj]
            if pv is not None and not (pv < v):
                return False
        for si, sj in graph[node]:
            sv = grid[si][sj]
            if sv is not None and not (v < sv):
                return False
        return True
    def backtrack():
        min_count = float('inf')
        best_i = best_j = -1
        best_poss = []
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    poss = [v for v in range(1, N+1) if min_grid[i][j] <= v <= max_grid[i][j] and v not in row_used[i] and v not in col_used[j] and check_ineq(i, j, v)]
                    count = len(poss)
                    if count == 0:
                        return False
                    if count < min_count:
                        min_count = count
                        best_i, best_j = i, j
                        best_poss = poss
        if best_i == -1:
            return True
        for v in best_poss:
            grid[best_i][best_j] = v
            row_used[best_i].add(v)
            col_used[best_j].add(v)
            if backtrack():
                return True
            grid[best_i][best_j] = None
            row_used[best_i].remove(v)
            col_used[best_j].remove(v)
        return False
    if backtrack():
        return grid
    else:
        return "No Solution"

