import copy

def solve(observation):
    region = observation['region']
    row_stitch_counts = observation['row_stitch_counts']
    col_stitch_counts = observation['col_stitch_counts']
    N = len(region)

    # Find possible edges per interface
    possible_edges = {}
    dirs = [(0, 1), (1, 0)]
    for r in range(N):
        for c in range(N):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if nr < N and nc < N:
                    id1 = region[r][c]
                    id2 = region[nr][nc]
                    if id1 != id2:
                        key = tuple(sorted((id1, id2)))
                        if key not in possible_edges:
                            possible_edges[key] = []
                        p1 = (r, c)
                        p2 = (nr, nc)
                        stitch = sorted([p1, p2])
                        possible_edges[key].append(stitch)

    # Check total match
    num_interfaces = len(possible_edges)
    if num_interfaces * 2 != sum(row_stitch_counts):
        return "No Solution"

    # Forbidden rows/cols
    forbidden_rows = {i for i in range(N) if row_stitch_counts[i] == 0}
    forbidden_cols = {i for i in range(N) if col_stitch_counts[i] == 0}

    # Filter possible edges
    for key in list(possible_edges):
        new_list = [stitch for stitch in possible_edges[key] if stitch[0][0] not in forbidden_rows and stitch[1][0] not in forbidden_rows and stitch[0][1] not in forbidden_cols and stitch[1][1] not in forbidden_cols]
        if not new_list:
            return "No Solution"
        possible_edges[key] = new_list

    # Interface list sorted by num possibilities
    interface_list = sorted(possible_edges, key=lambda k: len(possible_edges[k]))

    def propagate(curr_possible, assigned, used_cells, rem_row, rem_col):
        changed = True
        while changed:
            changed = False

            # Force single possibility
            for inf in list(curr_possible):
                if len(curr_possible[inf]) == 1:
                    stitch = curr_possible[inf][0]
                    (r1, c1), (r2, c2) = stitch
                    if (r1, c1) in used_cells or (r2, c2) in used_cells:
                        return False
                    assigned[inf] = stitch
                    used_cells.update([(r1, c1), (r2, c2)])
                    rem_row[r1] -= 1
                    rem_row[r2] -= 1
                    rem_col[c1] -= 1
                    rem_col[c2] -= 1
                    if rem_row[r1] < 0 or rem_row[r2] < 0 or rem_col[c1] < 0 or rem_col[c2] < 0:
                        return False
                    del curr_possible[inf]
                    changed = True

            # Remove invalid edges
            for inf in curr_possible:
                new_list = [stitch for stitch in curr_possible[inf] if stitch[0] not in used_cells and stitch[1] not in used_cells and rem_row[stitch[0][0]] > 0 and rem_row[stitch[1][0]] > 0 and rem_col[stitch[0][1]] > 0 and rem_col[stitch[1][1]] > 0]
                if len(new_list) < len(curr_possible[inf]):
                    changed = True
                curr_possible[inf] = new_list
                if not new_list:
                    return False

            # Cell forcing
            cell_interfaces = {}
            available = {(r, c) for r in range(N) for c in range(N) if r not in forbidden_rows and c not in forbidden_cols} - used_cells
            for cell in available:
                infs = [inf for inf in curr_possible if any(cell in s for s in curr_possible[inf])]
                cell_interfaces[cell] = infs
            for cell, infs in cell_interfaces.items():
                if len(infs) == 1:
                    inf = infs[0]
                    new_list = [s for s in curr_possible[inf] if cell in s]
                    if len(new_list) < len(curr_possible[inf]):
                        changed = True
                    curr_possible[inf] = new_list
                    if not new_list:
                        return False

        if not curr_possible:
            if all(x == 0 for x in rem_row) and all(x == 0 for x in rem_col):
                return True
            return False
        return None

    def recurse(assigned, used_cells, rem_row, rem_col, curr_possible):
        prop = propagate(curr_possible, assigned, used_cells, rem_row, rem_col)
        if prop is False:
            return None
        if prop is True:
            stitches = list(assigned.values())
            stitches.sort(key=lambda s: (s[0][0], s[0][1], s[1][0], s[1][1]))
            return stitches
        # Choose interface with fewest options
        min_inf = min(curr_possible, key=lambda inf: len(curr_possible[inf]))
        for stitch in curr_possible[min_inf]:
            assigned2 = copy.deepcopy(assigned)
            used2 = copy.copy(used_cells)
            rem_row2 = rem_row[:]
            rem_col2 = rem_col[:]
            curr_possible2 = copy.deepcopy(curr_possible)
            (r1, c1), (r2, c2) = stitch
            if (r1, c1) in used2 or (r2, c2) in used2:
                continue
            assigned2[min_inf] = stitch
            used2.update([(r1, c1), (r2, c2)])
            rem_row2[r1] -= 1
            rem_row2[r2] -= 1
            rem_col2[c1] -= 1
            rem_col2[c2] -= 1
            if rem_row2[r1] < 0 or rem_row2[r2] < 0 or rem_col2[c1] < 0 or rem_col2[c2] < 0:
                continue
            del curr_possible2[min_inf]
            result = recurse(assigned2, used2, rem_row2, rem_col2, curr_possible2)
            if result is not None:
                return result
        return None

    result = recurse({}, set(), list(row_stitch_counts), list(col_stitch_counts), copy.deepcopy(possible_edges))
    if result is None:
        return "No Solution"
    return str(result)

