            row_used[i].add(v)
            col_used[j].add(v)
            restore = []
            valid = True
            for k in range(N):
                if grid[i][k] is None and v in possibles[i][k]:
                    possibles[i][k].remove(v)
                    restore.append((i, k, v))
                    if not possibles[i][k]:
                        valid = False
            for k in range(N):
                if grid[k][j] is None and v in possibles[k][j]:
                    possibles[k][j].remove(v)
                    restore.append((k, j, v))
                    if not possibles[k][j]:
                        valid = False
            if not valid:
                grid[i][j] = None
                row_used[i].remove(v)
                col_used[j].remove(v)
                for a, b, c in restore:
                    possibles[a][b].add(c)
                continue
            # constraint propagation
            queue = deque([(i, j)])
            prop_restore = []
            prop_valid = True
            visited = set()
            while queue:
                a, b = queue.popleft()
                if (a, b) in visited:
                    continue
                visited.add((a, b))
                v2 = grid[a][b]
                for da, db in directions:
                    na, nb = a + da, b + db
                    if 0 <= na < N and 0 <= nb < N and grid[na][nb] is None:
                        pair = frozenset(((a, b), (na, nb)))
                        old = possibles[na][nb].copy()
                        if pair in consecutive:
                            possibles[na][nb] &= {v2 - 1, v2 + 1}
                        else:
                            possibles[na][nb] -= {v2 - 1, v2 + 1}
                        if not possibles[na][nb]:
                            prop_valid = False
                        if len(possibles[na][nb]) < len(old):
                            queue.append((na, nb))
                        prop_restore.append((na, nb, old))
                        if len(possibles[na][nb]) == 1:
                            w = next(iter(possibles[na][nb]))
                            grid[na][nb] = w
                            row_used[na].add(w)
                            col_used[nb].add(w)
                            queue.append((na, nb))
                            restore2 = []
                            for k in range(N):
                                if grid[na][k] is None and w in possibles[na][k]:
                                    possibles[na][k].remove(w)
                                    restore2.append((na, k, w))
                                    if not possibles[na][k]:
                                        prop_valid = False
                            for k in range(N):
                                if grid[k][nb] is None and w in possibles[k][nb]:
                                    possibles[k][nb].remove(w)
                                    restore2.append((k, nb, w))
                                    if not possibles[k][nb]:
                                        prop_valid = False
                            prop_restore.extend([(0,0, None)] )  # marker, but to restore these, we need to track
                            # to make it simple, perhaps skip assigning in the prop for now, to avoid nested assign restore
                            # since N small, we can omit the assign in prop, just reduce possibles
            if not prop_valid:
                grid[i][j] = None
                row_used[i].remove(v)
                col_used[j].remove(v)
                for a, b, c in restore:
                    possibles[a][b].add(c)
                for a, b, old in prop_restore:
                    possibles[a][b] = old
                continue
            if backtrack():
                return True
            grid[i][j] = None
            row_used[i].remove(v)
            col_used[j].remove(v)
            for a, b, c in restore:
                possibles[a][b].add(c)
            for a, b, old in prop_restore:
                possibles[a][b] = old
        return False
    if backtrack():
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
