def solve(observation):
    data = observation['data']
    N = len(data) - 1
    possible_touchers = [[[] for _ in range(N+1)] for _ in range(N+1)]

    def get_connected(ch, r, c):
        if ch == 0:  # \
            return ((r, c), (r+1, c+1))
        else:  # /
            return ((r+1, c), (r, c+1))

    for r in range(N):
        for c in range(N):
            for ch in [0, 1]:
                p1, p2 = get_connected(ch, r, c)
                possible_touchers[p1[0]][p1[1]].append((r, c, ch))
                possible_touchers[p2[0]][p2[1]].append((r, c, ch))

    assignment = [[-1 for _ in range(N)] for _ in range(N)]

    from collections import deque
    queue = deque()

    def force_cell(r, c, ch, add_to_queue=True):
        if assignment[r][c] != -1:
            return assignment[r][c] == ch
        assignment[r][c] = ch
        if add_to_queue:
            for di, dj in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
                if 0 <= di <= N and 0 <= dj <= N and data[di][dj] is not None:
                    queue.append((di, dj))
        return True

    def propagate():
        while queue:
            i, j = queue.popleft()
            k = data[i][j]
            if k is None:
                continue
            touchers = possible_touchers[i][j]
            forced_touch = sum(1 for rr, cc, hh in touchers if assignment[rr][cc] == hh)
            undecided = [(rr, cc, hh) for rr, cc, hh in touchers if assignment[rr][cc] == -1]
            u = len(undecided)
            min_d = forced_touch
            max_d = forced_touch + u
            if k < min_d or k > max_d:
                return False
            if k == max_d and u > 0:
                for rr, cc, hh in undecided:
                    if not force_cell(rr, cc, hh):
                        return False
            if k == min_d and u > 0:
                for rr, cc, hh in undecided:
                    if not force_cell(rr, cc, 1 - hh):
                        return False
        return True

    # Initial queue
    for i in range(N+1):
        for j in range(N+1):
            if data[i][j] is not None:
                queue.append((i, j))

    if not propagate():
        return "No Solution"

    # Now set up union-find and current_degree
    def flat(i, j):
        return i * (N + 1) + j

    parent = list(range((N + 1) * (N + 1)))
    rank = [0] * ((N + 1) * (N + 1))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        return root

    def union(x, y):
        px = find(x)
        py = find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            parent[px] = py
            return (px, py, False)
        elif rank[px] > rank[py]:
            parent[py] = px
            return (py, px, False)
        else:
            parent[py] = px
            rank[px] += 1
            return (py, px, True)

    current_degree = [[0 for _ in range(N+1)] for _ in range(N+1)]

    # Add forced edges
    for r in range(N):
        for c in range(N):
            if assignment[r][c] != -1:
                ch = assignment[r][c]
                p1, p2 = get_connected(ch, r, c)
                f1 = flat(p1[0], p1[1])
                f2 = flat(p2[0], p2[1])
                res = union(f1, f2)
                if not res:
                    return "No Solution"
                current_degree[p1[0]][p1[1]] += 1
                current_degree[p2[0]][p2[1]] += 1

    # Check initial degrees
    for i in range(N+1):
        for j in range(N+1):
            k = data[i][j]
            if k is not None and current_degree[i][j] > k:
                return "No Solution"

    # Undecided cells
    undecided_cells = [(r, c) for r in range(N) for c in range(N) if assignment[r][c] == -1]

    def check_prune():
        for i in range(N+1):
            for j in range(N+1):
                k = data[i][j]
                if k is None:
                    continue
                cd = current_degree[i][j]
                if cd > k:
                    return False
                rem = sum(1 for rr, cc, hh in possible_touchers[i][j] if assignment[rr][cc] == -1)
                if cd + rem < k:
                    return False
        return True

    if not check_prune():
        return "No Solution"

    def search(pos):
        if pos == len(undecided_cells):
            # Check degrees
            for i in range(N+1):
                for j in range(N+1):
                    k = data[i][j]
                    if k is not None and current_degree[i][j] != k:
                        return None
            # Build answer
            ans = [['' for _ in range(N)] for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    ch = assignment[r][c]
                    ans[r][c] = '\\' if ch == 0 else '/'
            return ans
        r, c = undecided_cells[pos]
        for ch in [0, 1]:
            assignment[r][c] = ch
            p1, p2 = get_connected(ch, r, c)
            f1 = flat(p1[0], p1[1])
            f2 = flat(p2[0], p2[1])
            res = union(f1, f2)
            if res:
                current_degree[p1[0]][p1[1]] += 1
                current_degree[p2[0]][p2[1]] += 1
                d_ok = True
                if data[p1[0]][p1[1]] is not None and current_degree[p1[0]][p1[1]] > data[p1[0]][p1[1]]:
                    d_ok = False
                if data[p2[0]][p2[1]] is not None and current_degree[p2[0]][p2[1]] > data[p2[0]][p2[1]]:
                    d_ok = False
                if d_ok and check_prune():
                    result = search(pos + 1)
                    if result is not None:
                        return result
                current_degree[p1[0]][p1[1]] -= 1
                current_degree[p2[0]][p2[1]] -= 1
                changed, newpar, incr = res
                parent[changed] = changed
                if incr:
                    rank[newpar] -= 1
        assignment[r][c] = -1
        return None

    result = search(0)
    if result is not None:
        return result
    return "No Solution"

