OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 3, 2, 2, 1, None], [None, None, 3, None, 3, None], [1, 2, None, 2, None, 1], [1, None, 3, 2, None, 1], [None, None, 1, None, 1, None]]}

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, u, v):
        pu = self.find(u)
        pv = self.find(v)
        if pu == pv:
            return False
        if self.rank[pu] > self.rank[pv]:
            self.history.append((pv, self.parent[pv]))
            self.parent[pv] = pu
        elif self.rank[pu] < self.rank[pv]:
            self.history.append((pu, self.parent[pu]))
            self.parent[pu] = pv
        else:
            self.history.append((pv, self.parent[pv], pu, self.rank[pu]))
            self.parent[pv] = pu
            self.rank[pu] += 1
        return True

    def undo(self):
        if not self.history:
            return
        last = self.history.pop()
        if len(last) == 4:
            self.parent[last[0]] = last[1]
            self.rank[last[2]] = last[3]
        else:
            self.parent[last[0]] = last[1]

def solve(observation):
    data = observation['data']
    N_plus_1 = len(data)
    N = N_plus_1 - 1
    required = data
    flat = lambda i, j: i * N_plus_1 + j
    possible_adders = [[] for _ in range(N_plus_1 * N_plus_1)]
    for i in range(N_plus_1):
        for j in range(N_plus_1):
            vid = flat(i, j)
            if i < N and j < N:
                possible_adders[vid].append((i, j, 0))
            if i < N and j > 0:
                possible_adders[vid].append((i, j - 1, 1))
            if i > 0 and j < N:
                possible_adders[vid].append((i - 1, j, 1))
            if i > 0 and j > 0:
                possible_adders[vid].append((i - 1, j - 1, 0))

    def get_endpoints(r, c, ch):
        if ch == 0:
            return (r, c), (r + 1, c + 1)
        else:
            return (r, c + 1), (r + 1, c)

    def propagate(grid, current_degree, dsu, required, possible_adders, flat, N, N_plus_1):
        forced_list = []
        changed = True
        while changed:
            changed = False
            for i in range(N_plus_1):
                for j in range(N_plus_1):
                    if required[i][j] is None:
                        continue
                    k = required[i][j]
                    vid = flat(i, j)
                    curr = current_degree[vid]
                    rem_list = [(cr, cc, ch) for cr, cc, ch in possible_adders[vid] if grid[cr][cc] == -1]
                    rem = len(rem_list)
                    if curr > k or curr + rem < k:
                        return False
                    if curr + rem == k and rem > 0:
                        for cr, cc, ch in rem_list:
                            if grid[cr][cc] != -1:
                                if grid[cr][cc] != ch:
                                    return False
                                continue
                            grid[cr][cc] = ch
                            u, v = get_endpoints(cr, cc, ch)
                            flatu = flat(u[0], u[1])
                            flatv = flat(v[0], v[1])
                            if not dsu.union(flatu, flatv):
                                return False
                            current_degree[flatu] += 1
                            current_degree[flatv] += 1
                            forced_list.append((cr, cc))
                            changed = True
                    elif curr == k and rem > 0:
                        for cr, cc, ch in rem_list:
                            other = 1 - ch
                            if grid[cr][cc] != -1:
                                if grid[cr][cc] == ch:
                                    return False
                                continue
                            grid[cr][cc] = other
                            u, v = get_endpoints(cr, cc, other)
                            flatu = flat(u[0], u[1])
                            flatv = flat(v[0], v[1])
                            if not dsu.union(flatu, flatv):
                                return False
                            current_degree[flatu] += 1
                            current_degree[flatv] += 1
                            forced_list.append((cr, cc))
                            changed = True
        return forced_list

    grid = [[-1] * N for _ in range(N)]
    current_degree = [0] * (N_plus_1 * N_plus_1)
    dsu = DSU(N_plus_1 * N_plus_1)

    prop = propagate(grid, current_degree, dsu, required, possible_adders, flat, N, N_plus_1)
    if prop is False:
        return "No Solution"

    undecided = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == -1]

    def bt(pos, grid, current_degree, dsu, undecided, required, possible_adders, flat, N, N_plus_1):
        if pos == len(undecided):
            return True
        r, c = undecided[pos]
        for ch in [0, 1]:
            grid[r][c] = ch
            u, v = get_endpoints(r, c, ch)
            flatu = flat(u[0], u[1])
            flatv = flat(v[0], v[1])
            if dsu.union(flatu, flatv):
                current_degree[flatu] += 1
                current_degree[flatv] += 1
                prop = propagate(grid, current_degree, dsu, required, possible_adders, flat, N, N_plus_1)
                if prop is not False:
                    forced = prop
                    if bt(pos + 1, grid, current_degree, dsu, undecided, required, possible_adders, flat, N, N_plus_1):
                        return True
                    for fr, fc in reversed(forced):
                        fch = grid[fr][fc]
                        fu, fv = get_endpoints(fr, fc, fch)
                        fflatu = flat(fu[0], fu[1])
                        fflatv = flat(fv[0], fv[1])
                        current_degree[fflatu] -= 1
                        current_degree[fflatv] -= 1
                        dsu.undo()
                        grid[fr][fc] = -1
                current_degree[flatu] -= 1
                current_degree[flatv] -= 1
                dsu.undo()
            grid[r][c] = -1
        return False

    if bt(0, grid, current_degree, dsu, undecided, required, possible_adders, flat, N, N_plus_1):
        ans = [[''] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                ans[r][c] = '\\' if grid[r][c] == 0 else '/'
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
