OBSERVATION = {'data': [[None, None, -1, 1, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, 2], [1, None, None, None, None, None, 0], [1, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, 1, -1, None, None]]}

def get_ray(data, N, r, c, dr, dc):
    ray = []
    nr = r + dr
    nc = c + dc
    while 0 <= nr < N and 0 <= nc < N and data[nr][nc] is None:
        ray.append((nr, nc))
        nr += dr
        nc += dc
    return ray

def place_bulb(data, N, bulb_status, illuminated, r, c):
    if data[r][c] is not None:
        return False
    if bulb_status[r][c] == False:
        return False
    if bulb_status[r][c] == True:
        return True
    # Check no other bulb in rays
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        ray = get_ray(data, N, r, c, dr, dc)
        for nr, nc in ray:
            if bulb_status[nr][nc] == True:
                return False
    # Place
    bulb_status[r][c] = True
    illuminated[r][c] = True
    # Propagate to rays
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        ray = get_ray(data, N, r, c, dr, dc)
        for nr, nc in ray:
            illuminated[nr][nc] = True
            if bulb_status[nr][nc] == True:
                return False
            if bulb_status[nr][nc] is None:
                bulb_status[nr][nc] = False
    return True

def set_no_bulb(bulb_status, r, c):
    if bulb_status[r][c] == False:
        return True
    if bulb_status[r][c] == True:
        return False
    bulb_status[r][c] = False
    return True

def propagate(data, N, bulb_status, illuminated):
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    changed = True
    while changed:
        changed = False
        # Check unilluminated no-bulb cells
        for r in range(N):
            for c in range(N):
                if data[r][c] is None and bulb_status[r][c] == False and not illuminated[r][c]:
                    return False
        # Numbered constraints
        for r in range(N):
            for c in range(N):
                if data[r][c] is not None and data[r][c] >= 0:
                    k = data[r][c]
                    adj = []
                    for dr,dc in dirs:
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < N and 0 <= nc < N and data[nr][nc] is None:
                            adj.append((nr,nc))
                    num_true = sum(1 for ar,ac in adj if bulb_status[ar][ac] == True)
                    num_none = sum(1 for ar,ac in adj if bulb_status[ar][ac] is None)
                    if num_true > k or num_true + num_none < k:
                        return False
                    if num_true == k:
                        for ar,ac in adj:
                            if bulb_status[ar][ac] is None:
                                set_no_bulb(bulb_status, ar, ac)
                                changed = True
                    if num_true + num_none == k:
                        for ar,ac in adj:
                            if bulb_status[ar][ac] is None:
                                if not place_bulb(data, N, bulb_status, illuminated, ar, ac):
                                    return False
                                changed = True
        # Deduction for unilluminated cells
        for r in range(N):
            for c in range(N):
                if data[r][c] is None and not illuminated[r][c] and bulb_status[r][c] is None:
                    possible = [(r,c)]
                    for dr,dc in dirs:
                        ray = get_ray(data, N, r, c, dr, dc)
                        possible.extend(ray)
                    possible_illum = set(possible)
                    possible_illum = [(pr,pc) for pr,pc in possible_illum if bulb_status[pr][pc] is None]
                    if len(possible_illum) == 0:
                        return False
                    if len(possible_illum) == 1:
                        pr,pc = possible_illum[0]
                        if not place_bulb(data, N, bulb_status, illuminated, pr, pc):
                            return False
                        changed = True
    return True

import copy

def solve_recursive(data, N, bulb_status, illuminated):
    bulb_copy = copy.deepcopy(bulb_status)
    illum_copy = copy.deepcopy(illuminated)
    if not propagate(data, N, bulb_copy, illum_copy):
        return None
    # Check if done
    undecided = []
    for r in range(N):
        for c in range(N):
            if data[r][c] is None:
                if bulb_copy[r][c] is None:
                    undecided.append((r,c))
                elif bulb_copy[r][c] == False and not illum_copy[r][c]:
                    return None
    if not undecided:
        answer = [[None]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if bulb_copy[r][c] == True:
                    answer[r][c] = 'B'
        return answer
    # Choose the one with fewest options
    min_options = float('inf')
    chosen = None
    for ur,uc in undecided:
        possible = [(ur,uc)]
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            ray = get_ray(data, N, ur, uc, dr, dc)
            possible.extend(ray)
        options = set(possible)
        num_opt = len([(pr,pc) for pr,pc in options if bulb_copy[pr][pc] is None])
        if num_opt < min_options:
            min_options = num_opt
            chosen = (ur,uc)
    if chosen is None:
        return None
    rr,cc = chosen
    # Try place bulb
    bulb_try = copy.deepcopy(bulb_copy)
    illum_try = copy.deepcopy(illum_copy)
    if place_bulb(data, N, bulb_try, illum_try, rr, cc):
        res = solve_recursive(data, N, bulb_try, illum_try)
        if res is not None:
            return res
    # Try no bulb
    bulb_try = copy.deepcopy(bulb_copy)
    illum_try = copy.deepcopy(illum_copy)
    if set_no_bulb(bulb_try, rr, cc):
        res = solve_recursive(data, N, bulb_try, illum_try)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    bulb_status = [[False if data[r][c] is not None else None for c in range(N)] for r in range(N)]
    illuminated = [[False]*N for _ in range(N)]
    result = solve_recursive(data, N, bulb_status, illuminated)
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
