            if 0 <= row < N and 0 <= col < N - 1:
                horizontal_consec[row][col] = True
        elif y % 1 != 0:
            row = int(y)
            col = int(x)
            if 0 <= row < N - 1 and 0 <= col < N:
                vertical_consec[row][col] = True
    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(N):
                taken = set()
                for c in range(N):
                    if len(possibles[r][c]) == 1:
                        v = next(iter(possibles[r][c]))
                        if v in taken:
                            return False
                        taken.add(v)
                for c in range(N):
                    if len(possibles[r][c]) > 1:
