                    if len(new2) != len(p2):
                        possibles[r + 1][c] = new2
                        changed = True
                    if len(new1) == 0 or len(new2) == 0:
                        return False
        return True
    def search():
        if not propagate():
            return None
        solved = all(len(possibles[r][c]) == 1 for r in range(N) for c in range(N))
        if solved:
            grid = [[next(iter(possibles[r][c])) for c in range(N)] for r in range(N)]
            return grid
        min_len = float('inf')
        chosen_r, chosen_c = -1, -1
        for r in range(N):
            for c in range(N):
                l = len(possibles[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    chosen_r, chosen_c = r, c
        if chosen_r == -1:
            return None
        poss = list(possibles[chosen_r][chosen_c])
        for v in poss:
            backup = [row[:] for row in possibles]
            possibles[chosen_r][chosen_c] = {v}
            result = search()
            if result is not None:
                return result
            possibles = backup
        return None
    result = search()
    if result is not None:
        return result
    else:
        return "No Solution"

