def solve(observation):
    data = observation['data']
    n = len(data)
    k = n // 2
    possibles = [[] for _ in range(n)]
    for i in range(n):
        row = data[i]
        empty_pos = [j for j in range(n) if row[j] is None]
        m = len(empty_pos)
        for mask in range(1 << m):
            temp = list(row)
            for p in range(m):
                col = empty_pos[p]
                color = 'B' if (mask & (1 << p)) else 'W'
                temp[col] = color
            total_b = sum(1 for c in temp if c == 'B')
            if total_b != k:
                continue
            valid = True
            for j in range(n - 2):
                if temp[j] == temp[j + 1] == temp[j + 2]:
                    valid = False
                    break
            if valid:
                possibles[i].append(tuple(temp))
    def backtrack(row_idx, assigned_patterns, used, col_b, col_last_color, col_last_run):
        if row_idx == n:
            col_patterns = []
            for j in range(n):
                col = tuple(assigned_patterns[r][j] for r in range(n))
                col_patterns.append(col)
            if len(set(col_patterns)) == n:
                return [list(t) for t in assigned_patterns]
            return None
        for pat_tup in possibles[row_idx]:
            if pat_tup in used:
                continue
            can_add = True
            new_col_b = list(col_b)
            new_last_color = list(col_last_color)
            new_last_run = list(col_last_run)
            for j in range(n):
                c = pat_tup[j]
                if c == 'B':
                    new_col_b[j] += 1
                if new_last_color[j] is None:
                    new_last_color[j] = c
                    new_last_run[j] = 1
                elif new_last_color[j] == c:
                    new_last_run[j] += 1
                    if new_last_run[j] >= 3:
                        can_add = False
                        break
                else:
                    new_last_color[j] = c
                    new_last_run[j] = 1
                curr_b = new_col_b[j]
                remain = n - row_idx - 1
                need_b = k - curr_b
                if need_b < 0 or need_b > remain:
                    can_add = False
                    break
            if not can_add:
                continue
            assigned_patterns[row_idx] = pat_tup
            used.add(pat_tup)
            res = backtrack(row_idx + 1, assigned_patterns, used, new_col_b, new_last_color, new_last_run)
            if res is not None:
                return res
            assigned_patterns[row_idx] = None
            used.remove(pat_tup)
        return None
    assigned_patterns = [None] * n
    used = set()
    col_b = [0] * n
    col_last_color = [None] * n
    col_last_run = [0] * n
    result = backtrack(0, assigned_patterns, used, col_b, col_last_color, col_last_run)
    return result if result is not None else "No Solution"

