def solve(observation):
    data = observation['data']
    N = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, data[r][c]))
    num_isl = len(islands)
    edges = []
    for r in range(N):
        isl_in_row = []
        for c in range(N):
            if (r, c) in pos_to_idx:
                isl_in_row.append(c)
        isl_in_row.sort()
        for i in range(len(isl_in_row) - 1):
            c1 = isl_in_row[i]
            c2 = isl_in_row[i + 1]
            p1 = (r, c1)
            p2 = (r, c2)
            edges.append((p1, p2, True))  # True for horizontal
    for c in range(N):
        isl_in_col = []
        for r in range(N):
            if (r, c) in pos_to_idx:
                isl_in_col.append(r)
        isl_in_col.sort()
        for i in range(len(isl_in_col) - 1):
            r1 = isl_in_col[i]
            r2 = isl_in_col[i + 1]
            p1 = (r1, c)
            p2 = (r2, c)
            edges.append((p1, p2, False))  # False for vertical
    num_edges = len(edges)
    incident = [[] for _ in islands]
    for eidx in range(num_edges):
        p1, p2, _ = edges[eidx]
        i1 = pos_to_idx[p1]
        i2 = pos_to_idx[p2]
        incident[i1].append(eidx)
        incident[i2].append(eidx)
    def crosses(e1, e2):
        p11, p12, is_hor1 = edges[e1]
        p21, p22, is_hor2 = edges[e2]
        if is_hor1 == is_hor2:
            return False
        if not is_hor1:
            p11, p12, is_hor1, p21, p22, is_hor2 = p21, p22, is_hor2, p11, p12, is_hor1
        rh = p11[0]
        c1 = min(p11[1], p12[1])
        c2 = max(p11[1], p12[1])
        cv = p21[1]
        r1 = min(p21[0], p22[0])
        r2 = max(p21[0], p22[0])
        return r1 < rh < r2 and c1 < cv < c2
    counts = [0] * num_edges
    def bt(idx):
        if idx == num_edges:
            # check connectivity
            parent = list(range(num_isl))
            def find(x):
                if parent[x] != x:
                    parent[x] = find(parent[x])
                return parent[x]
            def union(x, y):
                px, py = find(x), find(y)
                if px != py:
                    parent[px] = py
            for e in range(num_edges):
                if counts[e] > 0:
                    i1 = pos_to_idx[edges[e][0]]
                    i2 = pos_to_idx[edges[e][1]]
                    union(i1, i2)
            root = find(0)
            for i in range(1, num_isl):
                if find(i) != root:
                    return None
            # build ans
            ans = {}
            for e in range(num_edges):
                cnt = counts[e]
                if cnt > 0:
                    p1 = edges[e][0]
                    p2 = edges[e][1]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    ans[(p1, p2)] = cnt
            return ans
        p1, p2, _ = edges[idx]
        i1 = pos_to_idx[p1]
        i2 = pos_to_idx[p2]
        for choice in (0, 1, 2):
            counts[idx] = choice
            cross_bad = False
            if choice > 0:
                for j in range(idx):
                    if counts[j] > 0 and crosses(j, idx):
                        cross_bad = True
                        break
            if cross_bad:
                continue
            bad = False
            for ii in (i1, i2):
                cur_sum = 0
                num_rem = 0
                for eidx in incident[ii]:
                    if eidx < idx:
                        cur_sum += counts[eidx]
                    elif eidx > idx:
                        num_rem += 1
                    else:
                        cur_sum += choice
                max_add = 2 * num_rem
                if cur_sum > islands[ii][2] or cur_sum + max_add < islands[ii][2]:
                    bad = True
                    break
            if bad:
                continue
            res = bt(idx + 1)
            if res is not None:
                return res
        counts[idx] = 0
        return None
    result = bt(0)
    if result is None:
        return "No Solution"
    return result

