def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)
    grid = [[0 if data[r][c] is None else data[r][c] for c in range(N)] for r in range(N)]
    regions = defaultdict(list)
    for r in range(N):
        for c in range(N):
            regions[region[r][c]].append((r, c))
    num_regions = len(regions)
    row_used = [[False] * (N + 1) for _ in range(N)]
    col_used = [[False] * (N + 1) for _ in range(N)]
    region_used = [[False] * (N + 1) for _ in range(num_regions)]
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v != 0:
                rid = region[r][c]
                if row_used[r][v] or col_used[c][v] or region_used[rid][v]:
                    return "No Solution"
                row_used[r][v] = True
                col_used[c][v] = True
                region_used[rid][v] = True

    def propagate_singles():
        while True:
            filled = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        rid = region[r][c]
                        poss_v = [v for v in range(1, N + 1) if not (row_used[r][v] or col_used[c][v] or region_used[rid][v])]
                        if len(poss_v) == 0:
                            return False
                        if len(poss_v) == 1:
                            v = poss_v[0]
                            grid[r][c] = v
                            row_used[r][v] = True
                            col_used[c][v] = True
                            region_used[rid][v] = True
                            filled = True
            # hidden singles for rows
            for rr in range(N):
                for v in range(1, N + 1):
                    if row_used[rr][v]:
                        continue
                    possible_cells = []
                    for cc in range(N):
                        if grid[rr][cc] == 0:
                            rid = region[rr][cc]
                            if not (col_used[cc][v] or region_used[rid][v]):
                                possible_cells.append((rr, cc))
                    if len(possible_cells) == 1:
                        r2, c2 = possible_cells[0]
                        rid = region[r2][c2]
                        grid[r2][c2] = v
                        row_used[r2][v] = True
                        col_used[c2][v] = True
                        region_used[rid][v] = True
                        filled = True
            # hidden singles for cols
            for cc in range(N):
                for v in range(1, N + 1):
                    if col_used[cc][v]:
                        continue
                    possible_cells = []
                    for rr in range(N):
                        if grid[rr][cc] == 0:
                            rid = region[rr][cc]
                            if not (row_used[rr][v] or region_used[rid][v]):
                                possible_cells.append((rr, cc))
                    if len(possible_cells) == 1:
                        r2, c2 = possible_cells[0]
                        rid = region[r2][c2]
                        grid[r2][c2] = v
                        row_used[r2][v] = True
                        col_used[c2][v] = True
                        region_used[rid][v] = True
                        filled = True
            # hidden singles for regions
            for rid in range(num_regions):
                for v in range(1, N + 1):
                    if region_used[rid][v]:
                        continue
                    possible_cells = []
                    for (rr, cc) in regions[rid]:
                        if grid[rr][cc] == 0:
                            if not (row_used[rr][v] or col_used[cc][v]):
                                possible_cells.append((rr, cc))
                    if len(possible_cells) == 1:
                        r2, c2 = possible_cells[0]
                        grid[r2][c2] = v
                        row_used[r2][v] = True
                        col_used[c2][v] = True
                        region_used[rid][v] = True
                        filled = True
            if not filled:
                break
        return True

    if not propagate_singles():
        return "No Solution"

    def dfs():
        empties = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]
        if not empties:
            return True
        min_count = float('inf')
        chosen_r = -1
        chosen_c = -1
        chosen_poss = []
        for r, c in empties:
            rid = region[r][c]
            poss_v = [v for v in range(1, N + 1) if not (row_used[r][v] or col_used[c][v] or region_used[rid][v])]
            count = len(poss_v)
            if count == 0:
                return False
            if count < min_count:
                min_count = count
                chosen_r = r
                chosen_c = c
                chosen_poss = poss_v
        r = chosen_r
        c = chosen_c
        for v in chosen_poss:
            rid = region[r][c]
            grid[r][c] = v
            row_used[r][v] = True
            col_used[c][v] = True
            region_used[rid][v] = True
            if dfs():
                return True
            grid[r][c] = 0
            row_used[r][v] = False
            col_used[c][v] = False
            region_used[rid][v] = False
        return False

    if dfs():
        return grid
    else:
        return "No Solution"

