                        return "conflict"
        for p1 in range(num_pairs):
            if lb[p1] > 0:
                for p2 in range(p1 + 1, num_pairs):
                    if do_cross(pairs[p1], pairs[p2]):
                        stat = set_ub(p2, 0)
                        if stat == "conflict":
                            return "conflict"
                        stat = set_ub(p1, 0)  # symmetric, but only if needed
                        if stat == "conflict":
                            return "conflict"
    return "ok"

def search(islands, pos_to_idx, pairs, num_islands, num_pairs):
    unfixed = [p for p in range(num_pairs) if lb[p] < ub[p]]
    if not unfixed:
        # check connected
        parent = list(range(num_islands))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            px = find(x)
            py = find(y)
            if px != py:
                parent[px] = py
        for p in range(num_pairs):
            if lb[p] > 0:
                i = pos_to_idx[pairs[p][0]]
                j = pos_to_idx[pairs[p][1]]
                union(i, j)
        if len(set(find(i) for i in range(num_islands))) == 1:
            ans = {}
            for p in range(num_pairs):
                count = lb[p]
                if count > 0:
                    p1, p2 = pairs[p]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    ans[(p1, p2)] = count
            return ans
        return None
    # pick with min choices
    min_choices = min(ub[p] - lb[p] + 1 for p in unfixed)
    p = next(p for p in unfixed if ub[p] - lb[p] + 1 == min_choices)
    for v in range(lb[p], ub[p] + 1):
        save_trail_len = len(trail)
        stat1 = set_lb(p, v)
        if stat1 == "conflict":
            while len(trail) > save_trail_len:
                pp, typ, old = trail.pop()
                if typ == 'lb':
                    lb[pp] = old
                else:
                    ub[pp] = old
            continue
        stat2 = set_ub(p, v)
        if stat2 == "conflict":
            while len(trail) > save_trail_len:
                pp, typ, old = trail.pop()
                if typ == 'lb':
                    lb[pp] = old
                else:
                    ub[pp] = old
            continue
        status = propagate()
        if status != "conflict":
            res = search(islands, pos_to_idx, pairs, num_islands, num_pairs)
            if res is not None:
                return res
        while len(trail) > save_trail_len:
            pp, typ, old = trail.pop()
            if typ == 'lb':
                lb[pp] = old
            else:
                ub[pp] = old
    return None

