from itertools import combinations
from collections import defaultdict

def solve(observation):
    data = observation['data']
    n = len(data)

    def get_possible(row_init):
        fixed_b = sum(1 for x in row_init if x == 'B')
        e = sum(1 for x in row_init if x is None)
        nb = 4 - fixed_b
        if nb < 0 or nb > e:
            return []
        empties = [i for i, x in enumerate(row_init) if x is None]
        possible = []
        for pos in combinations(empties, nb):
            temp = [x for x in row_init]
            for j in empties:
                temp[j] = 'W'
            for j in pos:
                temp[j] = 'B'
            valid = True
            for i in range(n - 2):
                if temp[i] == temp[i + 1] == temp[i + 2] and temp[i] is not None:
                    valid = False
                    break
            if valid:
                possible.append(tuple(temp))
        return possible

    poss_rows = [get_possible(data[r]) for r in range(n)]

    assigned = [None] * n
    used = set()

    def bt(idx):
        if idx == n:
            return [list(assigned[r]) for r in range(n)]
        for pat in poss_rows[idx]:
            if pat in used:
                continue
            can = True
            if idx >= 2:
                for c in range(n):
                    if assigned[idx - 2][c] == assigned[idx - 1][c] == pat[c]:
                        can = False
                        break
            if not can:
                continue
            curr_bs = [sum(assigned[rr][c] == 'B' for rr in range(idx)) + (1 if pat[c] == 'B' else 0) for c in range(n)]
            rem = n - idx - 1
            for cb in curr_bs:
                if cb > 4 or 4 - cb > rem:
                    can = False
                    break
            if not can:
                continue
            groups = defaultdict(int)
            for c in range(n):
                pref = tuple(assigned[rr][c] for rr in range(idx)) + (pat[c],)
                groups[pref] += 1
            if max(groups.values(), default=0) > (1 << rem):
                continue
            assigned[idx] = pat
            used.add(pat)
            res = bt(idx + 1)
            if res is not None:
                return res
            assigned[idx] = None
            used.remove(pat)
        return None

    result = bt(0)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
