def solve(observation):
    grid = observation['data']
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    illuminating_positions = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                pos = set()
                # horizontal
                cc = c
                while cc >= 0 and grid[r][cc] is None:
                    pos.add((r, cc))
                    cc -= 1
                cc = c + 1
                while cc < N and grid[r][cc] is None:
                    pos.add((r, cc))
                    cc += 1
                # vertical
                rr = r
                while rr >= 0 and grid[rr][c] is None:
                    pos.add((rr, c))
                    rr -= 1
                rr = r + 1
                while rr < N and grid[rr][c] is None:
                    pos.add((rr, c))
                    rr += 1
                illuminating_positions[(r, c)] = list(pos)

    def can_place_bulb(r, c, state):
        # row left
        for cc in range(c - 1, -1, -1):
            if grid[r][cc] is not None:
                break
            if state[r][cc] == 'B':
                return False
        # row right
        for cc in range(c + 1, N):
            if grid[r][cc] is not None:
                break
            if state[r][cc] == 'B':
                return False
        # col up
        for rr in range(r - 1, -1, -1):
            if grid[rr][c] is not None:
                break
            if state[rr][c] == 'B':
                return False
        # col down
        for rr in range(r + 1, N):
            if grid[rr][c] is not None:
                break
            if state[rr][c] == 'B':
                return False
        return True

    def is_illuminated(r, c, state):
        if state[r][c] == 'B':
            return True
        # row left
        for cc in range(c - 1, -1, -1):
            if grid[r][cc] is not None:
                break
            if state[r][cc] == 'B':
                return True
        # row right
        for cc in range(c + 1, N):
            if grid[r][cc] is not None:
                break
            if state[r][cc] == 'B':
                return True
        # col up
        for rr in range(r - 1, -1, -1):
            if grid[rr][c] is not None:
                break
            if state[rr][c] == 'B':
                return True
        # col down
        for rr in range(r + 1, N):
            if grid[rr][c] is not None:
                break
            if state[rr][c] == 'B':
                return True
        return False

    def propagate(state):
        while True:
            changed = False
            # check all '.' cells
            for r in range(N):
                for c in range(N):
                    if state[r][c] == '.':
                        ill_set = illuminating_positions[(r, c)]
                        has_B = any(state[rr][cc] == 'B' for rr, cc in ill_set)
                        has_None = any(state[rr][cc] is None for rr, cc in ill_set)
                        if not has_B and not has_None:
                            return False
            # deduce for undecided cells
            for r in range(N):
                for c in range(N):
                    if state[r][c] is None:
                        ill_set = illuminating_positions[(r, c)]
                        has_B = any(state[rr][cc] == 'B' for rr, cc in ill_set)
                        if has_B:
                            continue
                        num_None = sum(1 for rr, cc in ill_set if state[rr][cc] is None)
                        if num_None == 0:
                            return False
                        if num_None == 1:
                            if not can_place_bulb(r, c, state):
                                return False
                            state[r][c] = 'B'
                            changed = True
            # numbered deductions
            for r in range(N):
                for c in range(N):
                    val = grid[r][c]
                    if isinstance(val, int) and val >= 0:
                        k = val
                        adj = [(r + dr, c + dc) for dr, dc in directions if 0 <= r + dr < N and 0 <= c + dc < N and grid[r + dr][c + dc] is None]
                        curr_B = sum(state[rr][cc] == 'B' for rr, cc in adj)
                        undec_list = [(rr, cc) for rr, cc in adj if state[rr][cc] is None]
                        undec = len(undec_list)
                        if curr_B > k or k - curr_B > undec:
                            return False
                        needed = k - curr_B
                        if needed == undec and undec > 0:
                            for rr, cc in undec_list:
                                if not can_place_bulb(rr, cc, state):
                                    return False
                                state[rr][cc] = 'B'
                            changed = True
                        if needed == 0 and undec > 0:
                            for rr, cc in undec_list:
                                state[rr][cc] = '.'
                            changed = True
            if not changed:
                break
        return True

    def search(state):
        if not propagate(state):
            return None
        undecided = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and state[r][c] is None:
                    undecided.append((r, c))
        if not undecided:
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None and not is_illuminated(r, c, state):
                        return None
            return state
        # choose first
        r, c = undecided[0]
        # try 'B'
        if can_place_bulb(r, c, state):
            new_state = [row[:] for row in state]
            new_state[r][c] = 'B'
            res = search(new_state)
            if res is not None:
                return res
        # try '.'
        new_state = [row[:] for row in state]
        new_state[r][c] = '.'
        ill_set = illuminating_positions[(r, c)]
        has_B = any(new_state[rr][cc] == 'B' for rr, cc in ill_set)
        has_None = any(new_state[rr][cc] is None for rr, cc in ill_set)
        if has_B or has_None:
            res = search(new_state)
            if res is not None:
                return res
        return None

    initial_state = [[None for _ in range(N)] for _ in range(N)]
    result = search(initial_state)
    if result is None:
        return "No Solution"
    answer = [[None for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if result[r][c] == 'B':
                answer[r][c] = 'B'
    return answer

