def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])
    numbered = [(i, j, data[i][j]) for i in range(n) for j in range(m) if data[i][j] is not None]

    # Precompute how many numbered constraints affect each cell
    affects = [[0] * m for _ in range(n)]
    for ii, jj, _ in numbered:
        for x in range(max(0, ii - 1), min(n, ii + 2)):
            for y in range(max(0, jj - 1), min(m, jj + 2)):
                affects[x][y] += 1

    state = [[-1] * m for _ in range(n)]

    def propagate():
        changed = True
        while changed:
            changed = False
            for i, j, k in numbered:
                neigh = [(x, y) for x in range(max(0, i - 1), min(n, i + 2))
                         for y in range(max(0, j - 1), min(m, j + 2))]
                unknown = []
                known_black = 0
                for x, y in neigh:
                    s = state[x][y]
                    if s == 1:
                        known_black += 1
                    elif s == -1:
                        unknown.append((x, y))
                min_b = known_black
                max_b = known_black + len(unknown)
                if k < min_b or k > max_b:
                    return False
                if max_b == k:
                    for x, y in unknown:
                        state[x][y] = 1
                        changed = True
                if min_b == k:
                    for x, y in unknown:
                        state[x][y] = 0
                        changed = True
        return True

    def backtrack():
        if not propagate():
            return False
        # Find unknown cell affected by most constraints
        best_i, best_j, max_aff = -1, -1, -1
        all_set = True
        for i in range(n):
            for j in range(m):
                if state[i][j] == -1:
                    all_set = False
                    aff = affects[i][j]
                    if aff > max_aff or (aff == max_aff and (i < best_i or (i == best_i and j < best_j))):
                        max_aff = aff
                        best_i, best_j = i, j
        if all_set:
            return True
        # Branch
        state[best_i][best_j] = 0
        if backtrack():
            return True
        state[best_i][best_j] = -1
        state[best_i][best_j] = 1
        if backtrack():
            return True
        state[best_i][best_j] = -1
        return False

    if backtrack():
        result = [[None] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if state[i][j] == 1:
                    result[i][j] = 'B'
        return result
    return "No Solution"

