import copy

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])
    constraints = [(i, j, grid[i][j]) for i in range(rows) for j in range(cols) if grid[i][j] is not None]

    def propagate(color_grid):
        changed = True
        while changed:
            changed = False
            for r, c, k in constraints:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbors.append((nr, nc))
                known_b = 0
                unk = []
                for nr, nc in neighbors:
                    val = color_grid[nr][nc]
                    if val == 'B':
                        known_b += 1
                    elif val == 'U':
                        unk.append((nr, nc))
                num_unk = len(unk)
                if known_b > k or known_b + num_unk < k:
                    return False
                if known_b == k:
                    for pr, pc in unk:
                        if color_grid[pr][pc] == 'U':
                            color_grid[pr][pc] = None
                            changed = True
                if known_b + num_unk == k:
                    for pr, pc in unk:
                        if color_grid[pr][pc] == 'U':
                            color_grid[pr][pc] = 'B'
                            changed = True
        return True

    def search(color_grid):
        temp_grid = copy.deepcopy(color_grid)
        if not propagate(temp_grid):
            return None
        # Check if fully assigned
        is_done = True
        branch_r, branch_c = -1, -1
        for r in range(rows):
            for c in range(cols):
                if temp_grid[r][c] == 'U':
                    is_done = False
                    branch_r, branch_c = r, c
                    break
            if not is_done:
                break
        if is_done:
            return temp_grid
        # Branch on the found 'U'
        for choice in ['B', None]:
            new_grid = copy.deepcopy(temp_grid)
            new_grid[branch_r][branch_c] = choice
            result = search(new_grid)
            if result is not None:
                return result
        return None

    color_grid = [['U' for _ in range(cols)] for _ in range(rows)]
    result = search(color_grid)
    if result is None:
        return "No Solution"
    return result

