from collections import defaultdict

def crosses(b1, b2):
    (p1, p2) = b1
    (q1, q2) = b2
    if p1[0] == p2[0]:  # horiz
        r = p1[0]
        cmin = min(p1[1], p2[1])
        cmax = max(p1[1], p2[1])
        if q1[1] == q2[1]:  # vert
            cc = q1[1]
            rmin = min(q1[0], q2[0])
            rmax = max(q1[0], q2[0])
            return rmin < r < rmax and cmin < cc < cmax
        return False
    else:  # vert
        c = p1[1]
        rmin = min(p1[0], p2[0])
        rmax = max(p1[0], p2[0])
        if q1[1] != q2[1]:  # horiz
            rr = q1[0]
            ccmin = min(q1[1], q2[1])
            ccmax = max(q1[1], q2[1])
            return ccmin < c < ccmax and rmin < rr < rmax
        return False

def solve(observation):
    data = observation['data']
    N = len(data)
    M = len(data[0]) if data else 0
    islands = []
    for r in range(N):
        for c in range(M):
            if data[r][c] is not None:
                islands.append((r, c, data[r][c]))
    possible_bridges = []
    # horizontal
    for r in range(N):
        cols = [c for c in range(M) if data[r][c] is not None]
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i + 1]
            p1 = (r, c1)
            p2 = (r, c2)
            possible_bridges.append((min(p1, p2), max(p1, p2)))
    # vertical
    for c in range(M):
        rows = [r for r in range(N) if data[r][c] is not None]
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i + 1]
            p1 = (r1, c)
            p2 = (r2, c)
            possible_bridges.append((min(p1, p2), max(p1, p2)))
    num_edges = len(possible_bridges)
    bridges = possible_bridges
    incident = defaultdict(list)
    for eid in range(num_edges):
        p1, p2 = bridges[eid]
        incident[p1].append(eid)
        incident[p2].append(eid)
    domains = [(0, 2) for _ in range(num_edges)]
    def propagate():
        nonlocal domains
        changed = True
        while changed:
            changed = False
            for isl in islands:
                pos = isl[:2]
                req = isl[2]
                inc = incident[pos]
                if not inc and req != 0:
                    raise ValueError("Isolated island with positive requirement")
                for eid in inc:
                    sum_max_other = sum(domains[j][1] for j in inc if j != eid)
                    new_min = max(0, req - sum_max_other)
                    old_min, old_max = domains[eid]
                    if new_min > old_min:
                        domains[eid] = (new_min, old_max)
                        changed = True
                for eid in inc:
                    sum_min_other = sum(domains[j][0] for j in inc if j != eid)
                    new_max = min(2, req - sum_min_other)
                    old_min, old_max = domains[eid]
                    if new_max < old_max:
                        domains[eid] = (old_min, new_max)
                        changed = True
        for i in range(num_edges):
            if domains[i][0] > domains[i][1]:
                raise ValueError("Inconsistent domains")
        for i in range(num_edges):
            if domains[i][0] > 0:
                for j in range(i + 1, num_edges):
                    if domains[j][0] > 0 and crosses(bridges[i], bridges[j]):
                        raise ValueError("Forced crossing")
    try:
        propagate()
    except ValueError:
        return "No Solution"
    order = sorted(range(num_edges), key=lambda i: domains[i][1] - domains[i][0] + 1)
    assignments = [-1] * num_edges
    def backtrack(level):
        if level == num_edges:
            graph = defaultdict(list)
            for eid in range(num_edges):
                if assignments[eid] > 0:
                    p1, p2 = bridges[eid]
                    graph[p1].append(p2)
                    graph[p2].append(p1)
            if not islands:
                return {}
            start = islands[0][:2]
            visited = set()
            stack = [start]
            visited.add(start)
            while stack:
                cur = stack.pop()
                for nei in graph[cur]:
                    if nei not in visited:
                        visited.add(nei)
                        stack.append(nei)
            if len(visited) != len(islands):
                return None
            ans = {}
            for eid in range(num_edges):
                cnt = assignments[eid]
                if cnt > 0:
                    p1, p2 = bridges[eid]
                    ans[(p1, p2)] = cnt
            return ans
        eid = order[level]
        minv, maxv = domains[eid]
        for val in range(minv, maxv + 1):
            assignments[eid] = val
            if val > 0:
                conflict = False
                for j_level in range(level):
                    j = order[j_level]
                    if assignments[j] > 0 and crosses(bridges[eid], bridges[j]):
                        conflict = True
                        break
                if conflict:
                    assignments[eid] = -1
                    continue
            ok = True
            for isl in islands:
                req = isl[2]
                current = 0
                u = 0
                for ie in incident[isl[:2]]:
                    aval = assignments[ie]
                    if aval != -1:
                        current += aval
                    else:
                        u += 1
                if current > req or current + 2 * u < req:
                    ok = False
                    break
            if ok:
                res = backtrack(level + 1)
                if res is not None:
                    return res
            assignments[eid] = -1
        return None
    res = backtrack(0)
    return res if res is not None else "No Solution"

