def solve(observation):
    data = observation['data']
    N = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                idx = len(islands)
                islands.append((r, c, data[r][c]))
                pos_to_idx[(r, c)] = idx
    num_islands = len(islands)
    bridges = []
    for r in range(N):
        in_row = []
        for c in range(N):
            if (r, c) in pos_to_idx:
                in_row.append((c, pos_to_idx[(r, c)]))
        in_row.sort()
        for i in range(len(in_row) - 1):
            c1, id1 = in_row[i]
            c2, id2 = in_row[i + 1]
            bridges.append({'end1': id1, 'end2': id2, 'dir': 'h', 'row': r, 'col1': min(c1, c2), 'col2': max(c1, c2)})
    for c in range(N):
        in_col = []
        for r in range(N):
            if (r, c) in pos_to_idx:
                in_col.append((r, pos_to_idx[(r, c)]))
        in_col.sort()
        for i in range(len(in_col) - 1):
            r1, id1 = in_col[i]
            r2, id2 = in_col[i + 1]
            bridges.append({'end1': id1, 'end2': id2, 'dir': 'v', 'col': c, 'row1': min(r1, r2), 'row2': max(r1, r2)})
    num_bridges = len(bridges)
    incident = [[] for _ in range(num_islands)]
    for b in range(num_bridges):
        br = bridges[b]
        incident[br['end1']].append(b)
        incident[br['end2']].append(b)
    def crosses(b1, b2):
        br1 = bridges[b1]
        br2 = bridges[b2]
        if br1['dir'] == br2['dir']:
            return False
        if br1['dir'] == 'v':
            brv = br1
            brh = br2
        else:
            brv = br2
            brh = br1
        return brh['col1'] < brv['col'] < brh['col2'] and brv['row1'] < brh['row'] < brv['row2']
    def is_connected(assignment):
        parent = list(range(num_islands))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        for b in range(num_bridges):
            if assignment[b] > 0:
                e1 = bridges[b]['end1']
                e2 = bridges[b]['end2']
                p1 = find(e1)
                p2 = find(e2)
                if p1 != p2:
                    parent[p1] = p2
        root = find(0)
        for i in range(num_islands):
            if find(i) != root:
                return False
        return True
    assignment = [0] * num_bridges
    current_deg = [0] * num_islands
    def backtrack(cur):
        if cur == num_bridges:
            if is_connected(assignment):
                sol = {}
                for b in range(num_bridges):
                    cnt = assignment[b]
                    if cnt > 0:
                        id1 = bridges[b]['end1']
                        id2 = bridges[b]['end2']
                        p1 = islands[id1][:2]
                        p2 = islands[id2][:2]
                        if p1 > p2:
                            p1, p2 = p2, p1
                        sol[(p1, p2)] = cnt
                return sol
            return None
        br = bridges[cur]
        e1 = br['end1']
        e2 = br['end2']
        for cnt in (0, 1, 2):
            cross = False
            if cnt > 0:
                for bb in range(cur):
                    if assignment[bb] > 0 and crosses(cur, bb):
                        cross = True
                        break
            if cross:
                continue
            current_deg[e1] += cnt
            current_deg[e2] += cnt
            ok = True
            for i in range(num_islands):
                rem = islands[i][2] - current_deg[i]
                unass = sum(1 for bb in incident[i] if bb > cur)
                if rem < 0 or rem > 2 * unass or (unass == 0 and rem != 0):
                    ok = False
                    break
            if ok:
                assignment[cur] = cnt
                res = backtrack(cur + 1)
                if res is not None:
                    return res
            current_deg[e1] -= cnt
            current_deg[e2] -= cnt
        return None
    res = backtrack(0)
    return str(res) if res is not None else "No Solution"

