def solve(observation):
    grid = observation['data']
    n_rows = len(grid)
    n_cols = len(grid[0])
    numbered = [(i, j) for i in range(n_rows) for j in range(n_cols) if grid[i][j] is not None]
    affected_by = [[[] for _ in range(n_cols)] for _ in range(n_rows)]
    for i, j in numbered:
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                x = i + di
                y = j + dj
                if 0 <= x < n_rows and 0 <= y < n_cols:
                    affected_by[x][y].append((i, j))
    def verify(board):
        for i, j in numbered:
            n = grid[i][j]
            count = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    x = i + di
                    y = j + dj
                    if 0 <= x < n_rows and 0 <= y < n_cols and board[x][y] == 'B':
                        count += 1
            if count != n:
                return False
        return True
    def propagate(board, pending):
        while pending:
            i, j = pending.pop()
            n = grid[i][j]
            fixed_b = 0
            undec = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    x = i + di
                    y = j + dj
                    if 0 <= x < n_rows and 0 <= y < n_cols:
                        cell = board[x][y]
                        if cell == 'B':
                            fixed_b += 1
                        elif cell == '?':
                            undec.append((x, y))
            minp = fixed_b
            maxp = fixed_b + len(undec)
            if minp > n or maxp < n:
                return False
            if minp == n:
                for px, py in undec:
                    if board[px][py] == '?':
                        board[px][py] = 'W'
                        for aff in affected_by[px][py]:
                            pending.add(aff)
                    elif board[px][py] != 'W':
                        return False
            if maxp == n:
                for px, py in undec:
                    if board[px][py] == '?':
                        board[px][py] = 'B'
                        for aff in affected_by[px][py]:
                            pending.add(aff)
                    elif board[px][py] != 'B':
                        return False
        return True
    def backtrack(board):
        best_r, best_c = -1, -1
        max_constraints = -1
        for rr in range(n_rows):
            for cc in range(n_cols):
                if board[rr][cc] == '?':
                    const = len(affected_by[rr][cc])
                    if const > max_constraints:
                        max_constraints = const
                        best_r = rr
                        best_c = cc
        if max_constraints == -1:
            return verify(board)
        r = best_r
        c = best_c
        for val in ['B', 'W']:
            board[r][c] = val
            pending = set(affected_by[r][c])
            if propagate(board, pending):
                if backtrack(board):
                    return True
            board[r][c] = '?'
        return False
    board = [['?' for _ in range(n_cols)] for _ in range(n_rows)]
    pending = set(numbered)
    if not propagate(board, pending):
        return "No Solution"
    if backtrack(board):
        output_grid = [[board[i][j] if board[i][j] == 'B' else None for j in range(n_cols)] for i in range(n_rows)]
        return output_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
