def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    horizontal_dots = [[False] * (N-1) for _ in range(N)]
    vertical_dots = [[False] * N for _ in range(N-1)]
    for p in observation['adjacent']:
        y, x = p
        if x == int(x):
            r = int(y - 0.5)
            c = int(x)
            vertical_dots[r][c] = True
        else:
            r = int(y)
            c = int(x - 0.5)
            horizontal_dots[r][c] = True
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    poss = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    empty_cells = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                v = grid[r][c]
                if v in row_used[r] or v in col_used[c]:
                    return "No Solution"
                row_used[r].add(v)
                col_used[c].add(v)
                poss[r][c] = {v}
            else:
                empty_cells.append((r, c))
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                poss[r][c] -= row_used[r]
                poss[r][c] -= col_used[c]
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                update_poss_for_adj(r, c, grid[r][c])
    changed = True
    while changed:
        changed = False
        i = len(empty_cells) - 1
        while i >= 0:
            r, c = empty_cells[i]
            if len(poss[r][c]) == 0:
                return "No Solution"
            if len(poss[r][c]) == 1:
                v = next(iter(poss[r][c]))
                grid[r][c] = v
                row_used[r].add(v)
                col_used[c].add(v)
                for cc in range(N):
                    if grid[r][cc] is None and v in poss[r][cc]:
                        poss[r][cc].remove(v)
                        changed = True
                for rr in range(N):
                    if grid[rr][c] is None and v in poss[rr][c]:
                        poss[rr][c].remove(v)
                        changed = True
                update_poss_for_adj(r, c, v)
                del empty_cells[i]
                changed = True
            i -= 1
        if propagate_adj():
            changed = True
    if not empty_cells:
        return grid
    empty_cells.sort(key=lambda x: len(poss[x[0]][x[1]]))
    def backtrack(index):
        if index == len(empty_cells):
            return True
        r, c = empty_cells[index]
        for v in list(poss[r][c]):
            if v in row_used[r] or v in col_used[c]:
                continue
            valid = True
            for dr, dc, get_dot in [
                (0, -1, lambda: c > 0 and horizontal_dots[r][c-1]),
                (0, 1, lambda: c < N-1 and horizontal_dots[r][c]),
                (-1, 0, lambda: r > 0 and vertical_dots[r-1][c]),
                (1, 0, lambda: r < N-1 and vertical_dots[r][c])
            ]:
                has_dot = get_dot()
                rr = r + dr
                cc = c + dc
                if has_dot and 0 <= rr < N and 0 <= cc < N and grid[rr][cc] is not None:
                    w = grid[rr][cc]
                    if has_dot != (abs(v - w) == 1):
                        valid = False
                        break
            if not valid:
                continue
            grid[r][c] = v
            row_used[r].add(v)
            col_used[c].add(v)
            saved = []
            for cc in range(N):
                if grid[r][cc] is None and v in poss[r][cc]:
                    poss[r][cc].remove(v)
                    saved.append((r, cc))
            for rr in range(N):
                if rr != r and grid[rr][c] is None and v in poss[rr][c]:
                    poss[rr][c].remove(v)
                    saved.append((rr, c))
            adj_saved = []
            for dr, dc, get_dot in [
                (0, -1, lambda: c > 0 and horizontal_dots[r][c-1]),
                (0, 1, lambda: c < N-1 and horizontal_dots[r][c]),
                (-1, 0, lambda: r > 0 and vertical_dots[r-1][c]),
                (1, 0, lambda: r < N-1 and vertical_dots[r][c])
            ]:
                has_dot = get_dot()
                rr = r + dr
                cc = c + dc
                if has_dot and 0 <= rr < N and 0 <= cc < N and grid[rr][cc] is None:
                    removed = []
                    for val in list(poss[rr][cc]):
                        if has_dot != (abs(val - v) == 1):
                            poss[rr][cc].remove(val)
                            removed.append(val)
                    adj_saved.append((rr, cc, removed))
            bad = False
            for rr, cc in empty_cells[index+1:]:
                if len(poss[rr][cc]) == 0:
                    bad = True
                    break
            if not bad:
                if backtrack(index + 1):
                    return True
            grid[r][c] = None
            row_used[r].remove(v)
            col_used[c].remove(v)
            for s_r, s_c in saved:
                poss[s_r][s_c].add(v)
            for s_r, s_c, removed in adj_saved:
                for val in removed:
                    poss[s_r][s_c].add(val)
        return False
    if backtrack(0):
        return grid
    return "No Solution"

def propagate_adj():
    changed = False
    N = len(poss)
    for r in range(N):
        for c in range(N-1):
            has_dot = horizontal_dots[r][c]
            p1 = poss[r][c]
            p2 = poss[r][c+1]
            new_p1 = {v1 for v1 in p1 if any((abs(v1 - v2) == 1) == has_dot for v2 in p2)}
            if len(new_p1) < len(p1):
                p1.intersection_update(new_p1)
                changed = True
            new_p2 = {v2 for v2 in p2 if any((abs(v2 - v1) == 1) == has_dot for v1 in p1)}
            if len(new_p2) < len(p2):
                p2.intersection_update(new_p2)
                changed = True
    for r in range(N-1):
        for c in range(N):
            has_dot = vertical_dots[r][c]
            p1 = poss[r][c]
            p2 = poss[r+1][c]
            new_p1 = {v1 for v1 in p1 if any((abs(v1 - v2) == 1) == has_dot for v2 in p2)}
            if len(new_p1) < len(p1):
                p1.intersection_update(new_p1)
                changed = True
            new_p2 = {v2 for v2 in p2 if any((abs(v2 - v1) == 1) == has_dot for v1 in p1)}
            if len(new_p2) < len(p2):
                p2.intersection_update(new_p2)
                changed = True
    return changed

def update_poss_for_adj(r, c, v):
    N = len(poss)
    if c > 0 and grid[r][c-1] is None:
        has_dot = horizontal_dots[r][c-1]
        to_remove = [val for val in poss[r][c-1] if has_dot != (abs(val - v) == 1)]
        for val in to_remove:
            poss[r][c-1].discard(val)
    if c < N-1 and grid[r][c+1] is None:
        has_dot = horizontal_dots[r][c]
        to_remove = [val for val in poss[r][c+1] if has_dot != (abs(val - v) == 1)]
        for val in to_remove:
            poss[r][c+1].discard(val)
    if r > 0 and grid[r-1][c] is None:
        has_dot = vertical_dots[r-1][c]
        to_remove = [val for val in poss[r-1][c] if has_dot != (abs(val - v) == 1)]
        for val in to_remove:
            poss[r-1][c].discard(val)
    if r < N-1 and grid[r+1][c] is None:
        has_dot = vertical_dots[r][c]
        to_remove = [val for val in poss[r+1][c] if has_dot != (abs(val - v) == 1)]
        for val in to_remove:
            poss[r+1][c].discard(val)

