    [-1, None, None, None, None, None, None, 2, None, None],
    [-1, None, -1, -1, None, None, None, None, -1, None]
]}

import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    board = [row[:] for row in data]
    placement = [[None] * N for _ in range(N)]
    illuminated = [[False] * N for _ in range(N)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_white(r, c):
        return 0 <= r < N and 0 <= c < N and board[r][c] is None

    def get_adj(r, c):
        adj = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_white(nr, nc):
                adj.append((nr, nc))
        return adj

    def get_row_segment(r, c):
        left = c
        while left > 0 and is_white(r, left - 1):
            left -= 1
        right = c
        while right < N - 1 and is_white(r, right + 1):
            right += 1
        return [(r, cc) for cc in range(left, right + 1)]

    def get_col_segment(r, c):
        up = r
        while up > 0 and is_white(up - 1, c):
            up -= 1
        down = r
        while down < N - 1 and is_white(down + 1, c):
            down += 1
        return [(rr, c) for rr in range(up, down + 1)]

    def set_placement(r, c, val):
        if placement[r][c] is not None:
            return placement[r][c] == val
        placement[r][c] = val
        if val == 'B':
            # Check no other 'B' in segments
            for pr, pc in get_row_segment(r, c):
                if (pr, pc) != (r, c) and placement[pr][pc] == 'B':
                    return False
            for pr, pc in get_col_segment(r, c):
                if (pr, pc) != (r, c) and placement[pr][pc] == 'B':
                    return False
            # Mark illuminated
            illuminated[r][c] = True
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                while 0 <= nr < N and 0 <= nc < N and board[nr][nc] is None:
                    illuminated[nr][nc] = True
                    nr += dr
                    nc += dc
            # Set other cells in segments to '.'
            for pr, pc in get_row_segment(r, c):
                if (pr, pc) != (r, c):
                    if not set_placement(pr, pc, '.'):
                        return False
            for pr, pc in get_col_segment(r, c):
                if (pr, pc) != (r, c):
                    if not set_placement(pr, pc, '.'):
                        return False
            return True
        elif val == '.':
            # Check potentially unilluminable cells
            check_cells = set(get_row_segment(r, c) + get_col_segment(r, c))
            for pr, pc in check_cells:
                if placement[pr][pc] == '.' and not illuminated[pr][pc]:
                    possible = any(placement[qr][qc] is None for qr, qc in get_row_segment(pr, pc) + get_col_segment(pr, pc))
                    if not possible:
                        return False
            return True

    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if board[r][c] is not None and board[r][c] >= 0:
                        k = board[r][c]
                        adj = get_adj(r, c)
                        placed = sum(1 for ar, ac in adj if placement[ar][ac] == 'B')
                        und = [(ar, ac) for ar, ac in adj if placement[ar][ac] is None]
                        if placed > k or placed + len(und) < k:
                            return False
                        if placed + len(und) == k and und:
                            for ar, ac in und:
                                if not set_placement(ar, ac, 'B'):
                                    return False
                            changed = True
                        if placed == k and und:
                            for ar, ac in und:
                                if not set_placement(ar, ac, '.'):
                                    return False
                            changed = True
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Get undecided cells
    undecided = [(r, c) for r in range(N) for c in range(N) if is_white(r, c) and placement[r][c] is None]

    def backtrack(index):
        if index == len(undecided):
            for r in range(N):
                for c in range(N):
                    if is_white(r, c) and not illuminated[r][c]:
                        return False
            return True

        r, c = undecided[index]

        # Try '.'
        place_backup = copy.deepcopy(placement)
        ill_backup = copy.deepcopy(illuminated)
        success = False
        if set_placement(r, c, '.'):
            if propagate():
                if backtrack(index + 1):
                    success = True
        placement = place_backup
        illuminated = ill_backup
        if success:
            return True

        # Try 'B'
        place_backup = copy.deepcopy(placement)
        ill_backup = copy.deepcopy(illuminated)
        if set_placement(r, c, 'B'):
            if propagate():
                if backtrack(index + 1):
                    return True
        placement = place_backup
        illuminated = ill_backup
        return False

    if backtrack(0):
        result = [[None] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if placement[r][c] == 'B':
                    result[r][c] = 'B'
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
