from collections import defaultdict

def solve(observation):
    N = len(observation['region'])
    region_grid = observation['region']
    row_target = observation['row_stitch_counts']
    col_target = observation['col_stitch_counts']

    # Find mandatory stitches
    mandatory = []
    used = set()
    for r in range(N):
        for c in range(N - 1):
            if region_grid[r][c] != region_grid[r][c + 1]:
                h1 = (r, c)
                h2 = (r, c + 1)
                if h1 in used or h2 in used:
                    return "No Solution"
                mandatory.append([h1, h2])
                used.add(h1)
                used.add(h2)
    for r in range(N - 1):
        for c in range(N):
            if region_grid[r][c] != region_grid[r + 1][c]:
                h1 = (r, c)
                h2 = (r + 1, c)
                if h1 in used or h2 in used:
                    return "No Solution"
                mandatory.append([h1, h2])
                used.add(h1)
                used.add(h2)

    # Current counts from mandatory
    curr_row = [0] * N
    curr_col = [0] * N
    for r, c in used:
        curr_row[r] += 1
        curr_col[c] += 1

    add_row = [row_target[i] - curr_row[i] for i in range(N)]
    add_col = [col_target[i] - curr_col[i] for i in range(N)]
    if any(x < 0 for x in add_row) or any(x < 0 for x in add_col):
        return "No Solution"
    if sum(add_row) % 2 != 0:
        return "No Solution"

    # Remaining holes
    remaining = set((r, c) for r in range(N) for c in range(N) if (r, c) not in used)

    # Propagation: remove from zero targets
    changed = True
    while changed:
        changed = False
        for r in range(N):
            avail = sum(1 for c in range(N) if (r, c) in remaining)
            if add_row[r] > avail:
                return "No Solution"
            if add_row[r] == 0 and avail > 0:
                for c in range(N):
                    h = (r, c)
                    if h in remaining:
                        remaining.remove(h)
                        changed = True
        for c in range(N):
            avail = sum(1 for r in range(N) if (r, c) in remaining)
            if add_col[c] > avail:
                return "No Solution"
            if add_col[c] == 0 and avail > 0:
                for r in range(N):
                    h = (r, c)
                    if h in remaining:
                        remaining.remove(h)
                        changed = True

    # Rebuild graph
    graph = defaultdict(list)
    for r in range(N):
        for c in range(N - 1):
            h1 = (r, c)
            h2 = (r, c + 1)
            if h1 in remaining and h2 in remaining and region_grid[r][c] == region_grid[r][c + 1]:
                graph[h1].append(h2)
                graph[h2].append(h1)
    for r in range(N - 1):
        for c in range(N):
            h1 = (r, c)
            h2 = (r + 1, c)
            if h1 in remaining and h2 in remaining and region_grid[r][c] == region_grid[r + 1][c]:
                graph[h1].append(h2)
                graph[h2].append(h1)

    # Sorted free list
    free = sorted(remaining)

    # Matched dict
    matched = {h: None for h in free}

    def backtrack(idx, rem_row, rem_col):
        # Feasibility check
        free_count_row = [0] * N
        free_count_col = [0] * N
        for i in range(idx, len(free)):
            h = free[i]
            if matched[h] is None:
                r, c = h
                free_count_row[r] += 1
                free_count_col[c] += 1
        for r in range(N):
            if rem_row[r] > free_count_row[r]:
                return False
        for c in range(N):
            if rem_col[c] > free_count_col[c]:
                return False

        if idx == len(free):
            return all(x == 0 for x in rem_row) and all(x == 0 for x in rem_col)

        h = free[idx]
        if matched[h] is not None:
            return backtrack(idx + 1, rem_row, rem_col)

        # Leave unmatched
        if backtrack(idx + 1, rem_row, rem_col):
            return True

        # Try pairing
        r, c = h
        for neigh in graph[h]:
            nr, nc = neigh
            if matched[neigh] is None and h < neigh:
                matched[h] = neigh
                matched[neigh] = h
                new_rem_row = rem_row[:]
                new_rem_row[r] -= 1
                new_rem_row[nr] -= 1
                new_rem_col = rem_col[:]
                new_rem_col[c] -= 1
                new_rem_col[nc] -= 1
                if all(x >= 0 for x in new_rem_row) and all(x >= 0 for x in new_rem_col):
                    if backtrack(idx + 1, new_rem_row, new_rem_col):
                        return True
                matched[h] = None
                matched[neigh] = None

        return False

    if backtrack(0, add_row, add_col):
        # Collect added stitches
        added = []
        for i in range(len(free)):
            h = free[i]
            partner = matched[h]
            if partner and h < partner:
                added.append([h, partner])
        all_stitches = mandatory + added
        return all_stitches
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
