]}

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    grid = [[None for _ in range(N)] for _ in range(N)]
    current_deg = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
    parent = list(range((N + 1) ** 2))
    rank = [0] * ((N + 1) ** 2)
    union_stack = []
    undo_stack = []
    constrained = [(r, c) for r in range(N + 1) for c in range(N + 1) if data[r][c] is not None]

    def id_func(r, c):
        return r * (N + 1) + c

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(id1, id2):
        p1 = find(id1)
        p2 = find(id2)
        if p1 == p2:
            return False
        incremented = False
        old_rank_val = None
        link_from = None
        old_parent_val = None
        link_to = None
        if rank[p1] < rank[p2]:
            old_parent_val = parent[p1]
            parent[p1] = p2
            link_from = p1
            link_to = p2
        elif rank[p2] < rank[p1]:
            old_parent_val = parent[p2]
            parent[p2] = p1
            link_from = p2
            link_to = p1
        else:
            old_parent_val = parent[p2]
            parent[p2] = p1
            link_from = p2
            link_to = p1
            incremented = True
            old_rank_val = rank[p1]
            rank[p1] += 1
        union_stack.append((link_from, old_parent_val, link_to, incremented, old_rank_val))
        return True

    def undo_union():
        if not union_stack:
            return
        link_from, old_parent_val, link_to, incremented, old_rank_val = union_stack.pop()
        parent[link_from] = old_parent_val
        if incremented:
            rank[link_to] = old_rank_val

    def set_cell(i, j, choice):
        if grid[i][j] is not None:
            return grid[i][j] == choice
        if choice == '/':
            p1 = (i, j + 1)
            p2 = (i + 1, j)
        else:
            p1 = (i, j)
            p2 = (i + 1, j + 1)
        id1 = id_func(*p1)
        id2 = id_func(*p2)
        if find(id1) == find(id2):
            return False
        old_deg1 = current_deg[p1[0]][p1[1]]
        old_deg2 = current_deg[p2[0]][p2[1]]
        current_deg[p1[0]][p1[1]] += 1
        current_deg[p2[0]][p2[1]] += 1
        union(id1, id2)
        grid[i][j] = choice
        undo_stack.append((i, j, choice, p1, p2, old_deg1, old_deg2))
        return True

    def propagate():
        changed = True
        while changed:
            changed = False
            for vr, vc in constrained:
                k = data[vr][vc]
                current = current_deg[vr][vc]
                rem_list = []
                if vr > 0 and vc > 0:
                    ii, jj = vr - 1, vc - 1
                    if grid[ii][jj] is None:
                        rem_list.append((ii, jj, '\\'))
                if vr > 0 and vc < N:
                    ii, jj = vr - 1, vc
                    if grid[ii][jj] is None:
                        rem_list.append((ii, jj, '/'))
                if vr < N and vc > 0:
                    ii, jj = vr, vc - 1
                    if grid[ii][jj] is None:
                        rem_list.append((ii, jj, '/'))
                if vr < N and vc < N:
                    ii, jj = vr, vc
                    if grid[ii][jj] is None:
                        rem_list.append((ii, jj, '\\'))
                rem = len(rem_list)
                if current > k or current + rem < k:
                    return False
                if current == k:
                    for ii, jj, touch in rem_list:
                        must_choice = '/' if touch == '\\' else '\\'
                        if not set_cell(ii, jj, must_choice):
                            return False
                        changed = True
                elif current + rem == k:
                    for ii, jj, touch in rem_list:
                        must_choice = touch
                        if not set_cell(ii, jj, must_choice):
                            return False
                        changed = True
        return True

    def search():
        if not propagate():
            return False
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    for choice in ['/', '\\']:
                        save_size = len(undo_stack)
                        if not set_cell(i, j, choice):
                            continue
                        if not propagate():
                            while len(undo_stack) > save_size:
                                item = undo_stack.pop()
                                i_, j_, _, p1, p2, old1, old2 = item
                                grid[i_][j_] = None
                                current_deg[p1[0]][p1[1]] = old1
                                current_deg[p2[0]][p2[1]] = old2
                                undo_union()
                            continue
                        if search():
                            return True
                        while len(undo_stack) > save_size:
                            item = undo_stack.pop()
                            i_, j_, _, p1, p2, old1, old2 = item
                            grid[i_][j_] = None
                            current_deg[p1[0]][p1[1]] = old1
                            current_deg[p2[0]][p2[1]] = old2
                            undo_union()
                    return False
        return True

    if not propagate():
        return "No Solution"
    if search():
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
