OBSERVATION = {'region': [[0, 1, 1, 1, 2], [0, 1, 2, 2, 2], [1, 1, 1, 2, 3], [1, 1, 1, 4, 3], [1, 1, 1, 4, 4]], 'row_stitch_counts': [2, 3, 3, 3, 3], 'col_stitch_counts': [4, 3, 2, 2, 3]}

def solve(observation):
    region = observation['region']
    row_counts = observation['row_stitch_counts']
    col_counts = observation['col_stitch_counts']
    N = len(region)
    # Find adjacent region pairs and possible stitches for each
    possible_stitches = {}
    directions = [(0, 1), (1, 0)]
    for r in range(N):
        for c in range(N):
            reg1 = region[r][c]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    reg2 = region[nr][nc]
                    if reg1 != reg2:
                        key = tuple(sorted((reg1, reg2)))
                        stitch = sorted([(r, c), (nr, nc)])
                        if key not in possible_stitches:
                            possible_stitches[key] = []
                        if stitch not in possible_stitches[key]:
                            possible_stitches[key].append(stitch)
    vars = list(possible_stitches.keys())
    vars.sort(key=lambda p: len(possible_stitches[p]))
    M = len(vars)
    assignment = [0] * M
    def backtrack(index, used):
        if index == M:
            chosen_stitches = []
            for i in range(M):
                p = vars[i]
                stitch = possible_stitches[p][assignment[i]]
                chosen_stitches.append(stitch)
            row_used = [0] * N
            col_used = [0] * N
            for stitch in chosen_stitches:
                (r1, c1), (r2, c2) = stitch
                row_used[r1] += 1
                col_used[c1] += 1
                row_used[r2] += 1
                col_used[c2] += 1
            if row_used == row_counts and col_used == col_counts:
                return chosen_stitches
            return None
        var = vars[index]
        domain = possible_stitches[var]
        for choice in range(len(domain)):
            stitch = domain[choice]
            holes = set(stitch)
            if holes.isdisjoint(used):
                new_used = used | holes
                can_continue = True
                for next_i in range(index + 1, M):
                    next_var = vars[next_i]
                    has_possible = any(set(possible_stitches[next_var][nc]).isdisjoint(new_used) for nc in range(len(possible_stitches[next_var])))
                    if not has_possible:
                        can_continue = False
                        break
                if can_continue:
                    assignment[index] = choice
                    result = backtrack(index + 1, new_used)
                    if result is not None:
                        return result
        return None
    result = backtrack(0, set())
    if result is None:
        return "No Solution"
    result.sort(key=lambda s: (s[0][0], s[0][1], s[1][0], s[1][1]))
    return str(result)

if __name__ == "__main__":
