    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                v = grid[r][c]
                if v < 1 or v > N:
                    return "No Solution"
                poss[r][c] = {v}

    # Initial Latin propagation
    for r in range(N):
        taken = {grid[r][c] for c in range(N) if grid[r][c] is not None}
        for c in range(N):
            if grid[r][c] is None:
                poss[r][c] -= taken
    for c in range(N):
        taken = {grid[r][c] for r in range(N) if grid[r][c] is not None}
        for r in range(N):
            if grid[r][c] is None:
                poss[r][c] -= taken

    # Build consecutive_pairs
    consecutive_pairs = set()
    for adj in observation['adjacent']:
        r, c = adj
        if c % 1 == 0.5:
            # horizontal
            col = int(c - 0.5)
            row = int(r)
            if 0 <= row < N and 0 <= col < N - 1:
                p1 = (row, col)
                p2 = (row, col + 1)
                consecutive_pairs.add(frozenset([p1, p2]))
        else:
            # vertical
            row = int(r - 0.5)
            col = int(c)
            if 0 <= row < N - 1 and 0 <= col < N:
                p1 = (row, col)
                p2 = (row + 1, col)
                consecutive_pairs.add(frozenset([p1, p2]))

    # Build non_consecutive_pairs
    all_adj = set()
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                all_adj.add(frozenset([(r, c), (r, c + 1)]))
            if r + 1 < N:
                all_adj.add(frozenset([(r, c), (r + 1, c)]))
    non_consecutive_pairs = all_adj - consecutive_pairs

    # Initial propagation
    poss = propagate(poss, N, consecutive_pairs, non_consecutive_pairs)
    if any(len(p) == 0 for row in poss for p in row):
        return "No Solution"

    def backtrack(poss):
        if any(len(p) == 0 for row in poss for p in row):
            return None
        if all(len(p) == 1 for row in poss for p in row):
            grid = [[list(poss[r][c])[0] for c in range(N)] for r in range(N)]
            # Verify constraints (though propagation should ensure)
            valid = True
            for pair in consecutive_pairs:
                (p1, p2) = list(pair)
                r1, c1 = p1
                r2, c2 = p2
                if abs(grid[r1][c1] - grid[r2][c2]) != 1:
                    valid = False
                    break
            if not valid:
                return None
            for pair in non_consecutive_pairs:
                (p1, p2) = list(pair)
                r1, c1 = p1
                r2, c2 = p2
                if abs(grid[r1][c1] - grid[r2][c2]) == 1:
                    valid = False
                    break
            if valid:
                return grid
            return None

        # Find cell with smallest poss >1
        r, c = -1, -1
        min_len = float('inf')
        for i in range(N):
            for j in range(N):
                l = len(poss[i][j])
                if 1 < l < min_len:
                    min_len = l
                    r, c = i, j
        if r == -1:
            return None

        for v in list(poss[r][c]):
            new_poss = copy.deepcopy(poss)
            new_poss[r][c] = {v}
            new_poss = propagate(new_poss, N, consecutive_pairs, non_consecutive_pairs)
            result = backtrack(new_poss)
            if result is not None:
                return result
        return None

    result = backtrack(poss)
    if result is None:
        return "No Solution"
    return str(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))
