import collections

def solve(observation):
    data = observation['data']
    N_plus_1 = len(data)
    N = N_plus_1 - 1
    num_dots = N_plus_1 * N_plus_1

    # Precompute slots for each dot: list of (cell_r, cell_c, diag)
    slots = [[] for _ in range(num_dots)]
    for i in range(N):
        for j in range(N):
            # For '/'
            p1 = i * N_plus_1 + (j + 1)
            p2 = (i + 1) * N_plus_1 + j
            slots[p1].append((i, j, '/'))
            slots[p2].append((i, j, '/'))
            # For '\\'
            p3 = i * N_plus_1 + j
            p4 = (i + 1) * N_plus_1 + (j + 1)
            slots[p3].append((i, j, '\\'))
            slots[p4].append((i, j, '\\'))

    # Clues
    clue = [None] * num_dots
    for r in range(N_plus_1):
        for c in range(N_plus_1):
            if data[r][c] is not None:
                clue[r * N_plus_1 + c] = data[r][c]

    # Grid
    grid = [[None] * N for _ in range(N)]

    # Propagation
    queue = collections.deque()
    for p in range(num_dots):
        if clue[p] is not None:
            queue.append(p)

    other_diag = {'/': '\\', '\\': '/'}

    while queue:
        p = queue.popleft()
        if clue[p] is None:
            continue
        d = clue[p]
        fixed_connect = 0
        undecided = []
        for ci, cj, req in slots[p]:
            curr = grid[ci][cj]
            if curr is not None:
                if curr == req:
                    fixed_connect += 1
            else:
                undecided.append((ci, cj, req))
        u = len(undecided)
        if fixed_connect > d or fixed_connect + u < d:
            return "No Solution"
        need = d - fixed_connect
        if need == u:
            # Force all to connect
            for ci, cj, req in undecided:
                if grid[ci][cj] is not None:
                    if grid[ci][cj] != req:
                        return "No Solution"
                else:
                    grid[ci][cj] = req
                    # Add affected dots to queue
                    if req == '/':
                        pp1 = ci * N_plus_1 + (cj + 1)
                        pp2 = (ci + 1) * N_plus_1 + cj
                    else:
                        pp1 = ci * N_plus_1 + cj
                        pp2 = (ci + 1) * N_plus_1 + (cj + 1)
                    for pp in [pp1, pp2]:
                        if clue[pp] is not None:
                            queue.append(pp)
        elif need == 0:
            # Force all not to connect
            for ci, cj, req in undecided:
                to_set = other_diag[req]
                if grid[ci][cj] is not None:
                    if grid[ci][cj] != to_set:
                        return "No Solution"
                else:
                    grid[ci][cj] = to_set
                    # Add affected dots to queue
                    if to_set == '/':
                        pp1 = ci * N_plus_1 + (cj + 1)
                        pp2 = (ci + 1) * N_plus_1 + cj
                    else:
                        pp1 = ci * N_plus_1 + cj
                        pp2 = (ci + 1) * N_plus_1 + (cj + 1)
                    for pp in [pp1, pp2]:
                        if clue[pp] is not None:
                            queue.append(pp)

    # Now initialize union-find and degrees with forced
    parent = list(range(num_dots))
    rank = [0] * num_dots
    current_degree = [0] * num_dots

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                choice = grid[i][j]
                if choice == '/':
                    p1 = i * N_plus_1 + (j + 1)
                    p2 = (i + 1) * N_plus_1 + j
                else:
                    p1 = i * N_plus_1 + j
                    p2 = (i + 1) * N_plus_1 + (j + 1)
                current_degree[p1] += 1
                current_degree[p2] += 1
                if (clue[p1] is not None and current_degree[p1] > clue[p1]) or (clue[p2] is not None and current_degree[p2] > clue[p2]):
                    return "No Solution"
                pa = find(p1)
                pb = find(p2)
                if pa == pb:
                    return "No Solution"
                if rank[pa] < rank[pb]:
                    pa, pb = pb, pa
                parent[pb] = pa
                if rank[pa] == rank[pb]:
                    rank[pa] += 1

    # Undecided cells
    undecided = [(i, j) for i in range(N) for j in range(N) if grid[i][j] is None]

    # Backtracking
    def search(idx):
        if idx == len(undecided):
            # Final check
            for p in range(num_dots):
                if clue[p] is not None and current_degree[p] != clue[p]:
                    return False
            return True
        i, j = undecided[idx]
        for choice in ['/', '\\']:
            grid[i][j] = choice
            if choice == '/':
                p1 = i * N_plus_1 + (j + 1)
                p2 = (i + 1) * N_plus_1 + j
            else:
                p1 = i * N_plus_1 + j
                p2 = (i + 1) * N_plus_1 + (j + 1)
            # Check degree exceed
            exceed = False
            if (clue[p1] is not None and current_degree[p1] + 1 > clue[p1]) or (clue[p2] is not None and current_degree[p2] + 1 > clue[p2]):
                exceed = True
            if not exceed:
                # Check if completed and match
                current_degree[p1] += 1
                current_degree[p2] += 1
                completed_check = True
                for pp in [p1, p2]:
                    if clue[pp] is not None:
                        completed = True
                        for ci, cj, req in slots[pp]:
                            if grid[ci][cj] is None:
                                completed = False
                                break
                        if completed and current_degree[pp] != clue[pp]:
                            completed_check = False
                            break
                if completed_check:
                    # Union
                    pa = find(p1)
                    pb = find(p2)
                    if pa != pb:
                        if rank[pa] < rank[pb]:
                            pa, pb = pb, pa
                        old_parent = parent[pb]
                        old_rank = rank[pa]
                        parent[pb] = pa
                        if rank[pa] == rank[pb]:
                            rank[pa] += 1
                        # Recurse
                        if search(idx + 1):
                            return True
                        # Undo union
                        parent[pb] = old_parent
                        rank[pa] = old_rank
                current_degree[p1] -= 1
                current_degree[p2] -= 1
        grid[i][j] = None
        return False

    if search(0):
        return grid
    else:
        return "No Solution"

