OBSERVATION = {'data': [[3, None, None, 4, None, None, None, None, None], [4, 5, 2, 1, None, None, None, None, None], [1, None, 7, None, None, None, None, 2, 5], [None, None, None, 6, 3, 1, None, None, None], [None, 7, None, 9, None, None, None, None, None], [1, 2, 3, None, None, None, None, None, None], [2, 5, None, 3, None, None, None, None, 9], [None, 9, 5, None, 2, None, None, 7, None], [None, 4, None, None, None, None, None, None, 8]], 'unit': '3x3'}

def solve(observation):
    unit = observation['unit']
    if 'x' in unit:
        r, c = map(int, unit.split('x'))
    else:
        r = c = int(unit)
    N = r * c
    grid = [row[:] for row in observation['data']]
    rows = [set() for _ in range(N)]
    cols = [set() for _ in range(N)]
    box_num_h = N // r
    box_num_w = N // c
    boxes = [set() for _ in range(box_num_h * box_num_w)]
    def get_box(i, j):
        br = i // r
        bc = j // c
        return br * box_num_w + bc
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                num = grid[i][j]
                rows[i].add(num)
                cols[j].add(num)
                boxes[get_box(i, j)].add(num)
    possibles = [[set() for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                poss = set(range(1, N + 1)) - rows[i] - cols[j] - boxes[get_box(i, j)]
                possibles[i][j] = poss
    def place(i, j, num):
        removed = []
        grid[i][j] = num
        rows[i].add(num)
        cols[j].add(num)
        boxes[get_box(i, j)].add(num)
        for k in range(N):
            if k != j and possibles[i][k] and num in possibles[i][k]:
                possibles[i][k].remove(num)
                removed.append((i, k))
            if k != i and possibles[k][j] and num in possibles[k][j]:
                possibles[k][j].remove(num)
                removed.append((k, j))
        br_start = (i // r) * r
        bc_start = (j // c) * c
        for di in range(r):
            for dj in range(c):
                ni = br_start + di
                nj = bc_start + dj
                if (ni, nj) != (i, j) and possibles[ni][nj] and num in possibles[ni][nj]:
                    possibles[ni][nj].remove(num)
                    removed.append((ni, nj))
        return removed
    def unplace(i, j, num, removed, original_poss):
        grid[i][j] = None
        rows[i].remove(num)
        cols[j].remove(num)
        boxes[get_box(i, j)].remove(num)
        for x, y in removed:
            possibles[x][y].add(num)
        possibles[i][j] = original_poss.copy()
    def propagate():
        while True:
            filled = 0
            # Naked singles
            for i in range(N):
                for j in range(N):
                    if len(possibles[i][j]) == 1:
                        num = next(iter(possibles[i][j]))
                        place(i, j, num)
                        filled += 1
            # Hidden singles in rows
            for u in range(N):
                counts = {}
                for k in range(N):
                    if possibles[u][k]:
                        for num in possibles[u][k]:
                            counts.setdefault(num, []).append(k)
                for num, poslist in counts.items():
                    if len(poslist) == 1:
                        k = poslist[0]
                        if len(possibles[u][k]) > 1:
                            place(u, k, num)
                            filled += 1
            # Hidden singles in columns
            for u in range(N):
                counts = {}
                for k in range(N):
                    if possibles[k][u]:
                        for num in possibles[k][u]:
                            counts.setdefault(num, []).append(k)
                for num, poslist in counts.items():
                    if len(poslist) == 1:
                        k = poslist[0]
                        if len(possibles[k][u]) > 1:
                            place(k, u, num)
                            filled += 1
            # Hidden singles in boxes
            for b in range(len(boxes)):
                br = b // box_num_w
                bc = b % box_num_w
                start_i = br * r
                start_j = bc * c
                counts = {}
                for di in range(r):
                    for dj in range(c):
                        ii = start_i + di
                        jj = start_j + dj
                        if possibles[ii][jj]:
                            for num in possibles[ii][jj]:
                                counts.setdefault(num, []).append((ii, jj))
                for num, poslist in counts.items():
                    if len(poslist) == 1:
                        ii, jj = poslist[0]
                        if len(possibles[ii][jj]) > 1:
                            place(ii, jj, num)
                            filled += 1
            if filled == 0:
                break
    def search():
        propagate()
        if all(grid[i][j] is not None for i in range(N) for j in range(N)):
            return True
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None and len(possibles[i][j]) == 0:
                    return False
        min_len = float('inf')
        cand_i, cand_j = -1, -1
        for i in range(N):
            for j in range(N):
                plen = len(possibles[i][j])
                if plen > 1 and plen < min_len:
                    min_len = plen
                    cand_i, cand_j = i, j
        if cand_i == -1:
            return False
        poss = list(possibles[cand_i][cand_j])
        original_poss = possibles[cand_i][cand_j].copy()
        possibles[cand_i][cand_j] = set()
        for num in poss:
            removed = place(cand_i, cand_j, num)
            consistent = True
            for a in range(N):
                for b in range(N):
                    if grid[a][b] is None and len(possibles[a][b]) == 0:
                        consistent = False
                        break
                if not consistent:
                    break
            if consistent and search():
                return True
            unplace(cand_i, cand_j, num, removed, original_poss)
        return False
    if search():
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
