from collections import defaultdict

def generate_variants(base):
    variants = set()
    for rot in range(4):
        new = []
        for r, c in base:
            if rot == 0:
                nr, nc = r, c
            elif rot == 1:
                nr, nc = c, -r
            elif rot == 2:
                nr, nc = -r, -c
            elif rot == 3:
                nr, nc = -c, r
            new.append((nr, nc))
        for refl in [False, True]:
            nn = [(rr, cc if not refl else -cc) for rr, cc in new]
            minr = min(rr for rr, cc in nn)
            minc = min(cc for rr, cc in nn)
            normalized = sorted((rr - minr, cc - minc) for rr, cc in nn)
            variants.add(tuple(normalized))
    return list(variants)

def check_2x2_new(grid, new_cells, N):
    checked = set()
    for r, c in new_cells:
        for dr in [0, -1]:
            for dc in [0, -1]:
                tr = r + dr
                tc = c + dc
                if 0 <= tr < N - 1 and 0 <= tc < N - 1:
                    if (tr, tc) in checked:
                        continue
                    checked.add((tr, tc))
                    if all(grid[tr + a][tc + b] is not None for a in [0, 1] for b in [0, 1]):
                        return True
    return False

def is_connected(grid, N):
    shaded = [(r, c) for r in range(N) for c in range(N) if grid[r][c] is not None]
    if not shaded:
        return True
    visited = set()
    stack = [shaded[0]]
    visited.add(shaded[0])
    count = 1
    while stack:
        cr, cc = stack.pop()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] is not None and (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))
                count += 1
    return count == len(shaded)

def solve(observation):
    data = observation['data']
    N = len(data)
    region_to_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            rid = data[r][c]
            region_to_cells[rid].append((r, c))
    regions = list(region_to_cells.keys())

    graph = defaultdict(set)
    for r in range(N):
        for c in range(N):
            rid = data[r][c]
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if nr < N and nc < N:
                    nrid = data[nr][nc]
                    if nrid != rid:
                        graph[rid].add(nrid)
                        graph[nrid].add(rid)

    all_shapes = {
        'I': generate_variants([(0, 0), (0, 1), (0, 2), (0, 3)]),
        'T': generate_variants([(0, 0), (0, 1), (0, 2), (1, 1)]),
        'L': generate_variants([(0, 0), (1, 0), (2, 0), (2, 1)]),
        'S': generate_variants([(0, 1), (0, 2), (1, 0), (1, 1)]),
    }

    placements = {}
    for rid in regions:
        typ_to_sets = defaultdict(set)
        for typ, shape_list in all_shapes.items():
            for shape in shape_list:
                max_dr = max(dr for dr, _ in shape)
                max_dc = max(dc for _, dc in shape)
                for r_offset in range(N):
                    for c_offset in range(N):
                        cells = []
                        valid = True
                        for dr, dc in shape:
                            nr = r_offset + dr
                            nc = c_offset + dc
                            if not (0 <= nr < N and 0 <= nc < N and data[nr][nc] == rid):
                                valid = False
                                break
                            cells.append((nr, nc))
                        if valid:
                            fset = frozenset(cells)
                            typ_to_sets[typ].add(fset)
        poss = []
        for typ, fsets in typ_to_sets.items():
            for fs in fsets:
                poss.append((typ, list(fs)))
        placements[rid] = poss

    regions_sorted = sorted(regions, key=lambda r: len(placements[r]))

    def backtrack(idx, assigned, shaded_grid):
        if idx == len(regions_sorted):
            if is_connected(shaded_grid, N):
                return [row[:] for row in shaded_grid]
            return None
        rid = regions_sorted[idx]
        for typ, cells_list in placements[rid]:
            if any(assigned.get(adj, None) == typ for adj in graph[rid]):
                continue
            new_shaded = cells_list
            for r, c in new_shaded:
                shaded_grid[r][c] = typ
            if check_2x2_new(shaded_grid, new_shaded, N):
                for r, c in new_shaded:
                    shaded_grid[r][c] = None
                continue
            assigned[rid] = typ
            res = backtrack(idx + 1, assigned, shaded_grid)
            if res is not None:
                return res
            del assigned[rid]
            for r, c in new_shaded:
                shaded_grid[r][c] = None
        return None

    assigned = {}
    shaded_grid = [[None] * N for _ in range(N)]
    result = backtrack(0, assigned, shaded_grid)
    if result is not None:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
