class UF:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        px = self.find(x)
        py = self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            self.parent[px] = py
            return (px, None)
        elif self.rank[px] > self.rank[py]:
            self.parent[py] = px
            return (py, None)
        else:
            self.parent[py] = px
            self.rank[px] += 1
            return (py, px)

    def undo(self, change):
        if change is False or change is None:
            return
        changed_p, rank_i = change
        self.parent[changed_p] = changed_p
        if rank_i is not None:
            self.rank[rank_i] -= 1

def solve(observation):
    clues = observation['data']
    N = len(clues) - 1
    adjs = [[None for _ in range(N+1)] for _ in range(N+1)]
    for dr in range(N+1):
        for dc in range(N+1):
            if clues[dr][dc] is not None:
                lst = []
                if dr > 0 and dc > 0:
                    lst.append((dr-1, dc-1, '\\'))
                if dr > 0 and dc < N:
                    lst.append((dr-1, dc, '/'))
                if dr < N and dc > 0:
                    lst.append((dr, dc-1, '/'))
                if dr < N and dc < N:
                    lst.append((dr, dc, '\\'))
                adjs[dr][dc] = lst
    grid = [[None for _ in range(N)] for _ in range(N)]
    uf = UF((N+1) * (N+1))

    def get_id(r, c):
        return r * (N + 1) + c

    def get_dots(i, j, ch):
        if ch == '/':
            return (i, j+1), (i+1, j)
        else:
            return (i, j), (i+1, j+1)

    def propagate():
        forced_cells = []
        union_changes = []
        while True:
            changed = False
            for dr in range(N+1):
                for dc in range(N+1):
                    if clues[dr][dc] is None:
                        continue
                    val = clues[dr][dc]
                    adj = adjs[dr][dc]
                    yes = 0
                    unass = []
                    for cr, cc, req in adj:
                        curr = grid[cr][cc]
                        if curr is None:
                            unass.append((cr, cc, req))
                        elif curr == req:
                            yes += 1
                    if yes > val or yes + len(unass) < val:
                        return False, forced_cells, union_changes
                    if len(unass) > 0:
                        if yes + len(unass) == val:
                            for cr, cc, req in unass:
                                if grid[cr][cc] is not None:
                                    if grid[cr][cc] != req:
                                        return False, forced_cells, union_changes
                                    continue
                                grid[cr][cc] = req
                                forced_cells.append((cr, cc))
                                d1, d2 = get_dots(cr, cc, req)
                                v1 = get_id(d1[0], d1[1])
                                v2 = get_id(d2[0], d2[1])
                                change = uf.union(v1, v2)
                                if change is False:
                                    return False, forced_cells, union_changes
                                union_changes.append(change)
                            changed = True
                        elif yes == val:
                            for cr, cc, req in unass:
                                other = '/' if req == '\\' else '\\'
                                if grid[cr][cc] is not None:
                                    if grid[cr][cc] != other:
                                        return False, forced_cells, union_changes
                                    continue
                                grid[cr][cc] = other
                                forced_cells.append((cr, cc))
                                d1, d2 = get_dots(cr, cc, other)
                                v1 = get_id(d1[0], d1[1])
                                v2 = get_id(d2[0], d2[1])
                                change = uf.union(v1, v2)
                                if change is False:
                                    return False, forced_cells, union_changes
                                union_changes.append(change)
                            changed = True
            if not changed:
                break
        return True, forced_cells, union_changes

    def backtrack(pos):
        if pos == N * N:
            return [row[:] for row in grid]
        r, c = divmod(pos, N)
        if grid[r][c] is not None:
            return backtrack(pos + 1)
        for choice in ['/', '\\']:
            grid[r][c] = choice
            d1, d2 = get_dots(r, c, choice)
            v1 = get_id(d1[0], d1[1])
            v2 = get_id(d2[0], d2[1])
            change = uf.union(v1, v2)
            if change is not False:
                succ, forced, uchanges = propagate()
                if succ:
                    res = backtrack(pos + 1)
                    if res is not None:
                        return res
                for chg in reversed(uchanges):
                    uf.undo(chg)
                for fr, fc in reversed(forced):
                    grid[fr][fc] = None
            if change is not False:
                uf.undo(change)
            grid[r][c] = None
        return None

    succ, forced, uchanges = propagate()
    if not succ:
        return "No Solution"
    res = backtrack(0)
    if res is not None:
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
