def generate_masks(n, runs):
    if not runs:
        return [[0] * n]
    total = sum(runs)
    num_runs = len(runs)
    min_len = total + max(0, num_runs - 1)
    if min_len > n:
        return []
    def helper(pos, run_idx, current):
        if run_idx == num_runs:
            return [current + [0] * (n - pos)]
        res = []
        r = runs[run_idx]
        min_gap = 0 if run_idx == 0 else 1
        m = num_runs - run_idx - 1
        rem_sum = sum(runs[run_idx + 1:])
        rem_min = rem_sum + max(0, m - 1) if m > 0 else 0
        max_start = n - r - rem_min
        for start in range(pos + min_gap, max_start + 1):
            new_pos = start + r
            new_current = current[:] + [0] * (start - pos) + [1] * r
            res.extend(helper(new_pos, run_idx + 1, new_current))
        return res
    return helper(0, 0, [])

def solve(observation):
    row_runs = observation['row_black_runs']
    col_runs = observation['col_black_runs']
    m = len(row_runs)
    n = len(col_runs)
    grid = [[-1] * n for _ in range(m)]
    def propagate():
        changed = True
        while changed:
            changed = False
            for i in range(m):
                current_line = [grid[i][j] for j in range(n)]
                masks = generate_masks(n, row_runs[i])
                consistent = [mask for mask in masks if all(current_line[j] == -1 or current_line[j] == mask[j] for j in range(n))]
                if not consistent:
                    return False
                for j in range(n):
                    all_black = all(mask[j] == 1 for mask in consistent)
                    all_white = all(mask[j] == 0 for mask in consistent)
                    if all_black and grid[i][j] != 1:
                        grid[i][j] = 1
                        changed = True
                    elif all_white and grid[i][j] != 0:
                        grid[i][j] = 0
                        changed = True
            for j in range(n):
                current_line = [grid[i][j] for i in range(m)]
                masks = generate_masks(m, col_runs[j])
                consistent = [mask for mask in masks if all(current_line[i] == -1 or current_line[i] == mask[i] for i in range(m))]
                if not consistent:
                    return False
                for i in range(m):
                    all_black = all(mask[i] == 1 for mask in consistent)
                    all_white = all(mask[i] == 0 for mask in consistent)
                    if all_black and grid[i][j] != 1:
                        grid[i][j] = 1
                        changed = True
                    elif all_white and grid[i][j] != 0:
                        grid[i][j] = 0
                        changed = True
        return True
    def search():
        if not propagate():
            return None
        solved = all(grid[i][j] != -1 for i in range(m) for j in range(n))
        if solved:
            return [['B' if grid[i][j] == 1 else None for j in range(n)] for i in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == -1:
                    grid_copy = [row[:] for row in grid]
                    grid[i][j] = 1
                    res = search()
                    if res is not None:
                        return res
                    grid[:] = grid_copy
                    grid[i][j] = 0
                    res = search()
                    if res is not None:
                        return res
                    grid[:] = grid_copy
                    return None
        return None
    result = search()
    return result if result is not None else "No Solution"

