            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    rid2 = data[nr][nc]
                    if rid1 != rid2:
                        adj_regions[rid1].add(rid2)
                        adj_regions[rid2].add(rid1)
    # Tetromino configurations
    configs = {
        'I': [
            [(0, 0), (0, 1), (0, 2), (0, 3)],
            [(0, 0), (1, 0), (2, 0), (3, 0)]
        ],
        'T': [
            [(0, 0), (0, 1), (0, 2), (1, 1)],
            [(0, 0), (1, 0), (1, 1), (2, 0)],
            [(0, 0), (1, 0), (1, 1), (1, 2)],
