            [(0, 1), (1, 1), (2, 0), (2, 1)],
            [(0, 0), (1, 0), (1, 1), (1, 2)],
            [(0, 0), (0, 1), (1, 0), (2, 0)],
            [(0, 0), (0, 1), (0, 2), (1, 0)],
            [(0, 0), (1, 0), (2, 0), (1, 1)],
            [(0, 0), (0, 1), (1, 1), (2, 1)]
        ]
    }
    # Possible placements per region per type
    possible_placements = {rid: {t: set() for t in configs} for rid in rids}
    for rid in rids:
        cells = list(region_cells[rid])
        for t in configs:
            for base_r, base_c in cells:
                for shape in configs[t]:
                    placement = set()
                    valid = True
                    for dr, dc in shape:
                        nr, nc = base_r + dr, base_c + dc
                        if (nr, nc) not in region_cells[rid]:
                            valid = False
                            break
                        placement.add((nr, nc))
                    if valid and len(placement) == 4:
                        possible_placements[rid][t].add(frozenset(placement))
    # Choices per region: list of (type, frozenset)
    choices = {rid: [] for rid in rids}
    for rid in rids:
        for t in possible_placements[rid]:
            for p in possible_placements[rid][t]:
                choices[rid].append((t, p))
    # Order regions by number of choices ascending
    order = sorted(rids, key=lambda rid: len(choices[rid]))
    # Function to check for 2x2
    def has_2x2(shaded_set):
        for r in range(N - 1):
            for c in range(N - 1):
                if all((rr, cc) in shaded_set for rr in [r, r + 1] for cc in [c, c + 1]):
                    return True
        return False
    # Function to check connectivity
    def is_connected(shaded):
        if not shaded:
            return True
        start = next(iter(shaded))
        visited = set()
        q = deque([start])
        visited.add(start)
        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(shaded)
    # Backtracking
    def backtrack(index, assigned, current_shaded):
        if index == len(order):
            return is_connected(current_shaded)
        rid = order[index]
        for typ, plac in choices[rid]:
            # Check type compatibility
            compatible = True
            for neigh in adj_regions[rid]:
                if neigh in assigned and assigned[neigh][0] == typ:
                    compatible = False
                    break
            if not compatible:
                continue
            # New shaded
            new_shaded = current_shaded | set(plac)
            # Check 2x2
            if has_2x2(new_shaded):
                continue
            # Assign and recurse
            assigned[rid] = (typ, plac)
            if backtrack(index + 1, assigned, new_shaded):
                return True
            del assigned[rid]
        return False
    # Run backtrack
    assigned = {}
    current_shaded = set()
    if backtrack(0, assigned, current_shaded):
        # Build grid
        grid = [[None] * N for _ in range(N)]
        for rid, (typ, plac) in assigned.items():
            for r, c in plac:
                grid[r][c] = typ
        return grid
    else:
        return "No Solution"

