    for r in range(N):
        for c in range(N):
            if grid[r][c] != 0:
                poss[r][c] = {grid[r][c]}
            else:
                poss[r][c] -= used_row[r]
                poss[r][c] -= used_col[c]
                poss[r][c] -= used_reg[region[r][c]]

