                        removed.append((pr, pc, v))
                        if len(poss[pr][pc]) == 0:
                            conflicts = True
            if not conflicts:
                if search():
                    return True
            grid[mr][mc] = 0
            poss[mr][mc] = old_poss
            for pr, pc, vv in removed:
                poss[pr][pc].add(vv)
        return False

    if search():
        return grid
    return "No Solution"

