                    count = bin(poss[r][c]).count('1')
                    if 0 < count < min_count:
                        min_count = count
                        chosen_r, chosen_c = r, c
        if chosen_r == -1:
            return None
        bit_p = poss[chosen_r][chosen_c]
        for vv in range(1, N + 1):
            bit = 1 << (vv - 1)
            if bit & bit_p:
                grid2 = [g[:] for g in grid]
                row_used2 = row_used[:]
                col_used2 = col_used[:]
                poss2 = [p[:] for p in poss]
                grid2[chosen_r][chosen_c] = vv
                row_used2[chosen_r] |= bit
                col_used2[chosen_c] |= bit
                poss2[chosen_r][chosen_c] = bit
                queue2 = deque([(chosen_r, chosen_c)])
                if propagate(grid2, row_used2, col_used2, poss2, queue2):
                    result = solver(grid2, row_used2, col_used2, poss2)
                    if result is not None:
                        return result
        return None
    result = solver(grid, row_used, col_used, poss)
    if result is None:
        return "No Solution"
    return result

