                    if grid[r1] != [None] * N and grid[r2] != [None] * N and grid[r3] != [None] * N:
                        c1 = grid[r1][j]
                        c2 = grid[r2][j]
                        c3 = grid[r3][j]
                        if c1 == c2 == c3 and c1 is not None:
                            possible_three = False
                            break
                if not possible_three:
                    break
            if not possible_three:
                grid[r] = [None] * N
                continue
            used.add(m)
            res = backtrack(temp_unfilled, used, temp_col_counts)
            if res is not None:
                return res
            used.remove(m)
            grid[r] = [None] * N
        return None

    res = backtrack(set(range(N)), set(), [0] * N)
    return res if res is not None else "No Solution"

