    def bt(row, current_col_sums, chosen_masks):
        if row == n:
            if current_col_sums == col_targets:
                grid = [[None] * m for _ in range(n)]
                for i in range(n):
                    mask = chosen_masks[i]
                    for j in range(m):
                        if mask & (1 << j):
                            grid[i][j] = 'B'
                return grid
            return None
        for mask in poss[row]:
            new_sums = [current_col_sums[j] for j in range(m)]
            can = True
            for j in range(m):
                if mask & (1 << j):
                    new_sums[j] += r_weights[row]
                if new_sums[j] > col_targets[j]:
                    can = False
                    break
            if not can:
                continue
            rem_needed = [col_targets[j] - new_sums[j] for j in range(m)]
            if any(x < 0 for x in rem_needed):
                continue
