                    continue
            chosen_masks.append(mask)
            result = bt(row + 1, new_sums, chosen_masks)
            if result is not None:
                return result
            chosen_masks.pop()
        return None
    result = bt(0, [0] * m, [])
    return result if result is not None else "No Solution"

