from collections import defaultdict, deque

def is_valid(r, c, n):
    return 0 <= r < n and 0 <= c < n

directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def propagate(board, region_cells, region_clue, n):
    while True:
        changed = False
        for rid, cells in region_cells.items():
            clue = region_clue.get(rid, None)
            if clue is None:
                continue
            size = len(cells)
            num_black = 0
            num_white = 0
            undecided = []
            for r, c in cells:
                if board[r][c] == 1:
                    num_black += 1
                elif board[r][c] == 0:
                    num_white += 1
                else:
                    undecided.append((r, c))
            num_und = len(undecided)
            if num_black > clue or num_black + num_und < clue or num_white > size - clue or num_white + num_und < size - clue:
                return False
            k = clue - num_black
            if k == 0:
                for r, c in undecided:
                    board[r][c] = 0
                    changed = True
            elif k == num_und:
                can = True
                und_set = set(undecided)
                for r1, c1 in undecided:
                    for dr, dc in directions:
                        nr, nc = r1 + dr, c1 + dc
                        if is_valid(nr, nc, n):
                            if board[nr][nc] == 1:
                                can = False
                                break
                            if (nr, nc) in und_set:
                                can = False
                                break
                    if not can:
                        break
                if can:
                    for r, c in undecided:
                        board[r][c] = 1
                    changed = True
                else:
                    return False
        for r in range(n):
            for c in range(n):
                if board[r][c] == 1:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if is_valid(nr, nc, n) and board[nr][nc] is None:
                            board[nr][nc] = 0
                            changed = True
        if not changed:
            break
    return True

def check_white_connected(board, n):
    whites = [(r, c) for r in range(n) for c in range(n) if board[r][c] == 0]
    if not whites:
        return True
    start = whites[0]
    visited = set()
    q = deque([start])
    visited.add(start)
    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc, n) and board[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(whites)

def check_segment_rule(board, region, n):
    for r in range(n):
        i = 0
        while i < n:
            if board[r][i] != 0:
                i += 1
                continue
            regions_set = set()
            while i < n and board[r][i] == 0:
                regions_set.add(region[r][i])
                i += 1
            if len(regions_set) > 2:
                return False
    for c in range(n):
        i = 0
        while i < n:
            if board[i][c] != 0:
                i += 1
                continue
            regions_set = set()
            while i < n and board[i][c] == 0:
                regions_set.add(region[i][c])
                i += 1
            if len(regions_set) > 2:
                return False
    return True

def solve_board(board, region_cells, region_clue, n, region):
    if not propagate(board, region_cells, region_clue, n):
        return None
    fully_decided = all(all(x is not None for x in row) for row in board)
    if fully_decided:
        if check_white_connected(board, n) and check_segment_rule(board, region, n):
            return [['B' if board[r][c] == 1 else None for c in range(n)] for r in range(n)]
        return None
    branch_r, branch_c = -1, -1
    for r in range(n):
        for c in range(n):
            if board[r][c] is None:
                branch_r, branch_c = r, c
                break
        if branch_r != -1:
            break
    if branch_r == -1:
        return None
    orig_board = [row[:] for row in board]
    board[branch_r][branch_c] = 0
    res = solve_board(board, region_cells, region_clue, n, region)
    if res is not None:
        return res
    board = [row[:] for row in orig_board]
    conflict = False
    changes = []
    for dr, dc in directions:
        nr, nc = branch_r + dr, branch_c + dc
        if is_valid(nr, nc, n):
            if board[nr][nc] == 1:
                conflict = True
                break
            if board[nr][nc] is None:
                board[nr][nc] = 0
                changes.append((nr, nc))
    if not conflict:
        board[branch_r][branch_c] = 1
        res = solve_board(board, region_cells, region_clue, n, region)
        if res is not None:
            return res
    board = [row[:] for row in orig_board]
    return None

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    region_cells = defaultdict(list)
    region_clue = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells[rid].append((r, c))
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]
    board = [[None] * n for _ in range(n)]
    res = solve_board(board, region_cells, region_clue, n, region)
    if res is None:
        return "No Solution"
    return res

