    rank = [0] * ((N + 1) * (N + 1))
    undo_stack = []
    def find(x):
        if parent[x] != x:
            return find(parent[x])
        return x
    def union(x, y):
        px = find(x)
        py = find(y)
        if px == py:
            return False
        changes = []
        if rank[px] < rank[py]:
            changes.append(('p', px, parent[px]))
            parent[px] = py
        elif rank[px] > rank[py]:
            changes.append(('p', py, parent[py]))
            parent[py] = px
        else:
            changes.append(('p', py, parent[py]))
            parent[py] = px
            changes.append(('r', px, rank[px]))
            rank[px] += 1
        undo_stack.extend(changes)
