            x = id_func(u[0], u[1])
            y = id_func(v[0], v[1])
            saved_len = len(undo_stack)
            if find(x) == find(y):
                grid[r][c] = None
                continue
            if not union(x, y):
                grid[r][c] = None
                continue
            prop_queue = deque()
            add_affected_to_queue(r, c, prop_queue)
            forced = []
            prop_ok = propagate(prop_queue, forced)
            if prop_ok:
                if backtrack():
                    return True
            # undo
            for fr, fc in reversed(forced):
                grid[fr][fc] = None
            while len(undo_stack) > saved_len:
                typ, idx, old = undo_stack.pop()
                if typ == 'p':
                    parent[idx] = old
                else:
                    rank[idx] = old
            grid[r][c] = None
        return False
    if not initial_propagate():
        return "No Solution"
    if backtrack():
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
