OBSERVATION = {'data': [[None, None, 1, None, None], [2, None, 1, 1, None], [2, None, 2, None, None], [1, 2, 0, 2, None], [None, 3, 3, 3, None]]}

from collections import deque

def build_graph(h, v, N):
    graph = {(r, c): [] for r in range(N + 1) for c in range(N + 1)}
    for r in range(N + 1):
        for c in range(N):
            if h[r][c] == 1:
                graph[(r, c)].append((r, c + 1))
                graph[(r, c + 1)].append((r, c))
    for r in range(N):
        for c in range(N + 1):
            if v[r][c] == 1:
                graph[(r, c)].append((r + 1, c))
                graph[(r + 1, c)].append((r, c))
    return graph

def is_single_loop(h, v, N):
    graph = build_graph(h, v, N)
    visited = set()
    num_cycles = 0
    for dot in graph:
        if dot not in visited and len(graph[dot]) > 0:
            num_cycles += 1
            if num_cycles > 1:
                return False
            q = deque([dot])
            visited.add(dot)
            while q:
                curr = q.popleft()
                for neigh in graph[curr]:
                    if neigh not in visited:
                        visited.add(neigh)
                        q.append(neigh)
    return num_cycles == 1

def extract_loop(h, v, N):
    graph = build_graph(h, v, N)
    candidates = [dot for dot in graph if len(graph[dot]) == 2]
    if not candidates:
        return None
    start = min(candidates)
    loop = [start]
    current = start
    prev = None
    while True:
        found = False
        for neigh in graph[current]:
            if neigh != prev:
                loop.append(neigh)
                prev = current
                current = neigh
                found = True
                break
        if not found:
            return None
        if current == start:
            break
    return loop

def propagate(h, v, data, N):
    changed = True
    while changed:
        changed = False
        # Cell propagation
        for i in range(N):
            for j in range(N):
                if data[i][j] is None:
                    continue
                k = data[i][j]
                edges = [h[i][j], h[i + 1][j], v[i][j], v[i][j + 1]]
                p = sum(1 for e in edges if e == 1)
                u = sum(1 for e in edges if e == -1)
                remaining = k - p
                if remaining < 0 or remaining > u:
                    return False
                if remaining == 0 or remaining == u:
                    new_val = 1 if remaining == u else 0
                    edge_list = [(True, i, j), (True, i + 1, j), (False, i, j), (False, i, j + 1)]
                    for idx, (is_h, rr, cc) in enumerate(edge_list):
                        arr = h if is_h else v
                        if edges[idx] == -1:
                            if arr[rr][cc] != -1 and arr[rr][cc] != new_val:
                                return False
                            if arr[rr][cc] == -1:
                                arr[rr][cc] = new_val
                                changed = True
        # Vertex propagation
        for r in range(N + 1):
            for c in range(N + 1):
                inc = []
                if r > 0:
                    inc.append((v, r - 1, c))
                if r < N:
                    inc.append((v, r, c))
                if c > 0:
                    inc.append((h, r, c - 1))
                if c < N:
                    inc.append((h, r, c))
                p = sum(1 for arr, rr, cc in inc if arr[rr][cc] == 1)
                u = sum(1 for arr, rr, cc in inc if arr[rr][cc] == -1)
                possible_s = set()
                for target in [0, 2]:
                    s = target - p
                    if 0 <= s <= u:
                        possible_s.add(s)
                if not possible_s:
                    return False
                if possible_s == {0} and u > 0:
                    for arr, rr, cc in inc:
                        if arr[rr][cc] == -1:
                            arr[rr][cc] = 0
                            changed = True
                elif possible_s == {u} and u > 0:
                    for arr, rr, cc in inc:
                        if arr[rr][cc] == -1:
                            arr[rr][cc] = 1
                            changed = True
    return True

def search(h, v, data, N):
    if not propagate(h, v, data, N):
        return None
    # Find if all decided and find branch edge
    branch_edge = None
    all_decided = True
    for r in range(N + 1):
        for c in range(N):
            if h[r][c] == -1:
                all_decided = False
                branch_edge = ('h', r, c)
                break
        if branch_edge is not None:
            break
    if all_decided:
        for r in range(N):
            for c in range(N + 1):
                if v[r][c] == -1:
                    all_decided = False
                    branch_edge = ('v', r, c)
                    break
            if branch_edge is not None:
                break
    if all_decided:
        if is_single_loop(h, v, N):
            return extract_loop(h, v, N)
        else:
            return None
    # Branch
    typ, r, c = branch_edge
    arr = h if typ == 'h' else v
    # Try 0
    original = arr[r][c]
    arr[r][c] = 0
    res = search(h, v, data, N)
    if res is not None:
        return res
    arr[r][c] = original
    # Try 1
    arr[r][c] = 1
    res = search(h, v, data, N)
    if res is not None:
        return res
    arr[r][c] = original
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    h = [[-1] * N for _ in range(N + 1)]
    v = [[-1] * (N + 1) for _ in range(N)]
    res = search(h, v, data, N)
    if res is None:
        return "No Solution"
    return res

if __name__ == "__main__":
    print(solve(OBSERVATION))
