OBSERVATION = {'region': [[0, 1, 1, 2, 2], [0, 1, 1, 2, 2], [0, 3, 1, 4, 2], [0, 3, 4, 4, 4], [0, 3, 3, 3, 4]], 'data': [[None, 4, None, None, None], [None, None, 5, None, None], [2, None, 1, None, 5], [None, None, 2, None, None], [None, None, None, 2, None]]}

import copy

def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)
    grid = [[data[r][c] if data[r][c] is not None else 0 for c in range(N)] for r in range(N)]
    region_cells = [[] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            region_cells[region[r][c]].append((r, c))
    row_used = [0] * N
    col_used = [0] * N
    region_used = [0] * N
    for r in range(N):
        for c in range(N):
            num = grid[r][c]
            if num != 0:
                bit = 1 << (num - 1)
                row_used[r] |= bit
                col_used[c] |= bit
                region_used[region[r][c]] |= bit
    possible = [[0] * N for _ in range(N)]

    def update_possible():
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    used = row_used[r] | col_used[c] | region_used[region[r][c]]
                    p = ((1 << N) - 1) ^ used
                    possible[r][c] = p
                    if p == 0:
                        return False
        return True

    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    return False
        return True

    def get_num(p):
        num = 1
        while p > 0:
            if p & 1:
                return num
            p >>= 1
            num += 1
        return 0

    def fill(r, c, num):
        grid[r][c] = num
        bit = 1 << (num - 1)
        row_used[r] |= bit
        col_used[c] |= bit
        region_used[region[r][c]] |= bit

    def unfill(r, c, num):
        grid[r][c] = 0
        bit = 1 << (num - 1)
        row_used[r] &= ~bit
        col_used[c] &= ~bit
        region_used[region[r][c]] &= ~bit

    unit_types = [
        [[(i, j) for j in range(N)] for i in range(N)],  # rows
        [[(j, i) for j in range(N)] for i in range(N)],  # cols
        region_cells
    ]

    def backtrack():
        if not update_possible():
            return False
        if is_solved():
            return True
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        p = possible[r][c]
                        if p == 0:
                            return False
                        if bin(p).count('1') == 1:
                            num = get_num(p)
                            fill(r, c, num)
                            changed = True
            if changed:
                if not update_possible():
                    return False
                if is_solved():
                    return True
            changed_hidden = False
            for ut in unit_types:
                for uid in range(N):
                    unit = ut[uid]
                    for num in range(1, N + 1):
                        bit = 1 << (num - 1)
                        count = 0
                        pos = None
                        for rr, cc in unit:
                            if grid[rr][cc] == 0 and (possible[rr][cc] & bit) != 0:
                                count += 1
                                pos = (rr, cc)
                        if count == 1:
                            r, c = pos
                            fill(r, c, num)
                            changed_hidden = True
            if changed_hidden:
                changed = True
            if changed_hidden:
                if not update_possible():
                    return False
                if is_solved():
                    return True
        # guess
        min_count = float('inf')
        min_r, min_c, min_p = -1, -1, 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    count = bin(possible[r][c]).count('1')
                    if count > 1 and count < min_count:
                        min_count = count
                        min_r = r
                        min_c = c
                        min_p = possible[r][c]
        if min_count == float('inf'):
            return False
        for num in range(1, N + 1):
            bit = 1 << (num - 1)
            if min_p & bit:
                fill(min_r, min_c, num)
                if backtrack():
                    return True
                unfill(min_r, min_c, num)
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
