from collections import defaultdict, deque
from copy import deepcopy
from math import inf

def solve(observation):
    data = observation['data']
    N = len(data)
    adjacent = observation['adjacent']
    dot_set = set(tuple(p) for p in adjacent)
    constraints = {}
    for r in range(N):
        for c in range(N-1):
            var1 = (r, c)
            var2 = (r, c+1)
            mid_y = float(r)
            mid_x = float(c) + 0.5
            is_consec = (mid_y, mid_x) in dot_set
            constraints[(var1, var2)] = is_consec
            constraints[(var2, var1)] = is_consec
    for r in range(N-1):
        for c in range(N):
            var1 = (r, c)
            var2 = (r+1, c)
            mid_y = float(r) + 0.5
            mid_x = float(c)
            is_consec = (mid_y, mid_x) in dot_set
            constraints[(var1, var2)] = is_consec
            constraints[(var2, var1)] = is_consec
    for r in range(N):
        for c1 in range(N):
            for c2 in range(c1+1, N):
                var1 = (r, c1)
                var2 = (r, c2)
                constraints[(var1, var2)] = 'diff'
                constraints[(var2, var1)] = 'diff'
    for c in range(N):
        for r1 in range(N):
            for r2 in range(r1+1, N):
                var1 = (r1, c)
                var2 = (r2, c)
                constraints[(var1, var2)] = 'diff'
                constraints[(var2, var1)] = 'diff'
    neighbors = defaultdict(list)
    for (v1, v2) in constraints:
        neighbors[v1].append(v2)
    domains = {}
    for r in range(N):
        for c in range(N):
            var = (r, c)
            if data[r][c] is not None:
                domains[var] = {data[r][c]}
            else:
                domains[var] = set(range(1, N+1))
    def revise(x, y, domains):
        revised = False
        constraint = constraints.get((x, y))
        if constraint is None:
            return False
        new_domain = set()
        for v in domains[x]:
            supported = False
            for w in domains[y]:
                if constraint == 'diff':
                    if v != w:
                        supported = True
                        break
                else:
                    if (constraint and abs(v - w) == 1) or (not constraint and abs(v - w) != 1):
                        supported = True
                        break
            if supported:
                new_domain.add(v)
            else:
                revised = True
        domains[x] = new_domain
        return revised
    def ac3(domains):
        queue = deque()
        for (x, y) in constraints:
            queue.append((x, y))
        while queue:
            (x, y) = queue.popleft()
            if revise(x, y, domains):
                if not domains[x]:
                    return False
                for z in neighbors[x]:
                    if z != y:
                        queue.append((z, x))
        return True
    if not ac3(domains):
        return "No Solution"
    def is_solved(domains):
        for var in domains:
            if len(domains[var]) != 1:
                return False
        return True
    def get_grid(domains):
        grid = [[0 for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                grid[r][c] = next(iter(domains[(r, c)]))
        return grid
    if is_solved(domains):
        return get_grid(domains)
    def solve_search(domains):
        min_size = inf
        chosen_var = None
        for var in domains:
            size = len(domains[var])
            if size > 1 and size < min_size:
                min_size = size
                chosen_var = var
        if chosen_var is None:
            return get_grid(domains)
        for v in list(domains[chosen_var]):
            new_domains = deepcopy(domains)
            new_domains[chosen_var] = {v}
            if ac3(new_domains):
                result = solve_search(new_domains)
                if result is not None:
                    return result
        return None
    solution = solve_search(domains)
    if solution is None:
        return "No Solution"
    return solution

if __name__ == "__main__":
    print(solve(OBSERVATION))
