OBSERVATION = {'data': [[None, None, None, None, 'W', None], [None, None, None, None, 'W', None], [None, 'W', 'B', None, None, 'W'], ['B', None, 'B', None, None, 'B'], [None, None, None, None, None, None], ['W', None, None, 'W', None, 'W']]}

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    opposite = {'B': 'W', 'W': 'B'}

    def get_line(line_idx, is_row):
        if is_row:
            return grid[line_idx]
        else:
            return [grid[j][line_idx] for j in range(n)]

    def set_line(line_idx, is_row, pos, color):
        if is_row:
            grid[line_idx][pos] = color
        else:
            grid[pos][line_idx] = color

    def is_valid_line(line):
        count_B = sum(1 for x in line if x == 'B')
        if count_B != n // 2:
            return False
        for j in range(n - 2):
            if line[j] == line[j + 1] == line[j + 2]:
                return False
        return True

    def apply_local_rules():
        changed = False
        for is_row in [True, False]:
            for line_idx in range(n):
                line = get_line(line_idx, is_row)
                count_B = 0
                count_W = 0
                empty = []
                for j in range(n):
                    if line[j] == 'B':
                        count_B += 1
                    elif line[j] == 'W':
                        count_W += 1
                    else:
                        empty.append(j)
                miss_B = n // 2 - count_B
                miss_W = n // 2 - count_W
                num_empty = len(empty)
                if miss_B < 0 or miss_W < 0 or miss_B + miss_W != num_empty:
                    return False, True
                if miss_B == 0 and num_empty > 0:
                    for j in empty:
                        set_line(line_idx, is_row, j, 'W')
                    changed = True
                elif miss_W == 0 and num_empty > 0:
                    for j in empty:
                        set_line(line_idx, is_row, j, 'B')
                    changed = True
                elif miss_B == num_empty and num_empty > 0:
                    for j in empty:
                        set_line(line_idx, is_row, j, 'B')
                    changed = True
                elif miss_W == num_empty and num_empty > 0:
                    for j in empty:
                        set_line(line_idx, is_row, j, 'W')
                    changed = True
                for j in range(n):
                    if j < n - 1 and line[j] == line[j + 1] and line[j] is not None:
                        color = line[j]
                        opp = opposite[color]
                        if j > 0:
                            if line[j - 1] is None:
                                set_line(line_idx, is_row, j - 1, opp)
                                changed = True
                            elif line[j - 1] == color:
                                return changed, True
                        if j + 2 < n:
                            if line[j + 2] is None:
                                set_line(line_idx, is_row, j + 2, opp)
                                changed = True
                            elif line[j + 2] == color:
                                return changed, True
                    if j < n - 2 and line[j] == line[j + 2] and line[j] is not None and line[j + 1] is None:
                        set_line(line_idx, is_row, j + 1, opposite[line[j]])
                        changed = True
                    if j < n - 2 and line[j] == line[j + 1] == line[j + 2] and line[j] is not None:
                        return changed, True
        return changed, False

    def apply_uniqueness():
        changed = False
        # Rows
        row_strings = set()
        partial_rows = []
        for i in range(n):
            line = grid[i]
            if None in line:
                partial_rows.append(i)
            else:
                s = ''.join(line)
                if s in row_strings:
                    return changed, True
                row_strings.add(s)
        for i in partial_rows:
            line = grid[i]
            empty_pos = [j for j in range(n) if line[j] is None]
            k = len(empty_pos)
            if k > 5:
                continue
            possible = []
            for mask in range(1 << k):
                temp_line = line[:]
                for b in range(k):
                    color = 'B' if (mask & (1 << b)) else 'W'
                    temp_line[empty_pos[b]] = color
                if is_valid_line(temp_line):
                    s = ''.join(temp_line)
                    if s not in row_strings:
                        possible.append(temp_line)
            if not possible:
                return changed, True
            for p in empty_pos:
                colors = {pl[p] for pl in possible}
                if len(colors) == 1:
                    grid[i][p] = next(iter(colors))
                    changed = True
        # Columns
        col_strings = set()
        partial_cols = []
        for i in range(n):
            line = [grid[j][i] for j in range(n)]
            if None in line:
                partial_cols.append(i)
            else:
                s = ''.join(line)
                if s in col_strings:
                    return changed, True
                col_strings.add(s)
        for i in partial_cols:
            line = [grid[j][i] for j in range(n)]
            empty_pos = [j for j in range(n) if line[j] is None]
            k = len(empty_pos)
            if k > 5:
                continue
            possible = []
            for mask in range(1 << k):
                temp_line = line[:]
                for b in range(k):
                    color = 'B' if (mask & (1 << b)) else 'W'
                    temp_line[empty_pos[b]] = color
                if is_valid_line(temp_line):
                    s = ''.join(temp_line)
                    if s not in col_strings:
                        possible.append(temp_line)
            if not possible:
                return changed, True
            for p in empty_pos:
                colors = {pl[p] for pl in possible}
                if len(colors) == 1:
                    grid[p][i] = next(iter(colors))
                    changed = True
        return changed, False

    def propagate():
        while True:
            changed, imp = apply_local_rules()
            if imp:
                return True
            ch2, imp2 = apply_uniqueness()
            if imp2:
                return True
            if not (changed or ch2):
                break
        return False

    def search():
        imp = propagate()
        if imp:
            return None
        filled = all(all(cell is not None for cell in row) for row in grid)
        if filled:
            rows = [''.join(row) for row in grid]
            if len(set(rows)) != n:
                return None
            cols = [''.join(grid[r][c] for r in range(n)) for c in range(n)]
            if len(set(cols)) != n:
                return None
            return [row[:] for row in grid]
        r_guess = c_guess = -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    r_guess = r
                    c_guess = c
                    break
            if r_guess != -1:
                break
        for color in ['B', 'W']:
            grid[r_guess][c_guess] = color
            result = search()
            if result is not None:
                return result
            grid[r_guess][c_guess] = None
        return None

    result = search()
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
