OBSERVATION = {'data': [[None, None, None, None, None, None], ['W', None, None, None, 'B', None], ['B', None, None, 'W', None, None], [None, 'W', None, None, 'W', None], [None, None, None, None, None, None], ['W', None, None, None, None, 'W']], 'horizontal': {'(0.0,0.5)': 'x', '(0.0,3.5)': '=', '(3.0,0.5)': '=', '(3.0,2.5)': 'x', '(3.0,3.5)': '=', '(3.0,4.5)': 'x'}, 'vertical': {}}

import copy
import ast
from collections import deque

def apply_pattern_forcing(grid, n):
    changed = False
    valid = True
    # Rows
    for r in range(n):
        for i in range(n):
            if grid[r][i] is not None:
                continue
            forced = set()
            # Left two
            if i >= 2 and grid[r][i-1] == grid[r][i-2] is not None:
                force = 'W' if grid[r][i-1] == 'B' else 'B'
                forced.add(force)
            # Right two
            if i <= n - 3 and grid[r][i+1] == grid[r][i+2] is not None:
                force = 'W' if grid[r][i+1] == 'B' else 'B'
                forced.add(force)
            # Left and right
            if i >= 1 and i <= n - 2 and grid[r][i-1] == grid[r][i+1] is not None:
                force = 'W' if grid[r][i-1] == 'B' else 'B'
                forced.add(force)
            if len(forced) > 1:
                valid = False
            elif len(forced) == 1:
                grid[r][i] = next(iter(forced))
                changed = True
    # Columns
    for c in range(n):
        for i in range(n):
            if grid[i][c] is not None:
                continue
            forced = set()
            # Upper two
            if i >= 2 and grid[i-1][c] == grid[i-2][c] is not None:
                force = 'W' if grid[i-1][c] == 'B' else 'B'
                forced.add(force)
            # Lower two
            if i <= n - 3 and grid[i+1][c] == grid[i+2][c] is not None:
                force = 'W' if grid[i+1][c] == 'B' else 'B'
                forced.add(force)
            # Upper and lower
            if i >= 1 and i <= n - 2 and grid[i-1][c] == grid[i+1][c] is not None:
                force = 'W' if grid[i-1][c] == 'B' else 'B'
                forced.add(force)
            if len(forced) > 1:
                valid = False
            elif len(forced) == 1:
                grid[i][c] = next(iter(forced))
                changed = True
    return valid, changed

def apply_count_forcing(grid, n, target):
    changed = False
    valid = True
    # Rows
    for r in range(n):
        b = sum(1 for x in grid[r] if x == 'B')
        w = sum(1 for x in grid[r] if x == 'W')
        u = n - b - w
        if b > target or w > target or target - b > u or target - w > u:
            valid = False
            break
        if b == target and u == target - w:
            for j in range(n):
                if grid[r][j] is None:
                    grid[r][j] = 'W'
            changed = True
        if w == target and u == target - b:
            for j in range(n):
                if grid[r][j] is None:
                    grid[r][j] = 'B'
            changed = True
    # Columns
    for c in range(n):
        b = sum(1 for rr in range(n) if grid[rr][c] == 'B')
        w = sum(1 for rr in range(n) if grid[rr][c] == 'W')
        u = n - b - w
        if b > target or w > target or target - b > u or target - w > u:
            valid = False
            break
        if b == target and u == target - w:
            for rr in range(n):
                if grid[rr][c] is None:
                    grid[rr][c] = 'W'
            changed = True
        if w == target and u == target - b:
            for rr in range(n):
                if grid[rr][c] is None:
                    grid[rr][c] = 'B'
            changed = True
    return valid, changed

def propagate(grid, n, same_pairs, diff_pairs):
    queue = deque()
    for r in range(n):
        for c in range(n):
            if grid[r][c] is not None:
                queue.append((r, c))
    changed = False
    while queue:
        r, c = queue.popleft()
        color = grid[r][c]
        # Same pairs
        for pair in same_pairs:
            if pair[0] == (r, c):
                orr, oc = pair[1]
            elif pair[1] == (r, c):
                orr, oc = pair[0]
            else:
                continue
            if grid[orr][oc] is None:
                grid[orr][oc] = color
                changed = True
                queue.append((orr, oc))
            elif grid[orr][oc] != color:
                return False, False
        # Diff pairs
        for pair in diff_pairs:
            if pair[0] == (r, c):
                orr, oc = pair[1]
            elif pair[1] == (r, c):
                orr, oc = pair[0]
            else:
                continue
            opp = 'W' if color == 'B' else 'B'
            if grid[orr][oc] is None:
                grid[orr][oc] = opp
                changed = True
                queue.append((orr, oc))
            elif grid[orr][oc] != opp:
                return False, False
    return True, changed

def full_propagate(grid, n, same_pairs, diff_pairs, target):
    while True:
        v, c1 = apply_pattern_forcing(grid, n)
        if not v:
            return False
        v, c2 = apply_count_forcing(grid, n, target)
        if not v:
            return False
        v, c3 = propagate(grid, n, same_pairs, diff_pairs)
        if not v:
            return False
        if not (c1 or c2 or c3):
            break
    return True

def backtrack(grid, n, same_pairs, diff_pairs, target):
    if not full_propagate(grid, n, same_pairs, diff_pairs, target):
        return None
    if all(all(cell is not None for cell in row) for row in grid):
        # Verify
        for r in range(n):
            if sum(1 for cell in grid[r] if cell == 'B') != target:
                return None
        for c in range(n):
            if sum(1 for r in range(n) if grid[r][c] == 'B') != target:
                return None
        for r in range(n):
            for i in range(n - 2):
                if grid[r][i] == grid[r][i + 1] == grid[r][i + 2]:
                    return None
        for c in range(n):
            for i in range(n - 2):
                if grid[i][c] == grid[i + 1][c] == grid[i + 2][c]:
                    return None
        return grid
    # Find first None
    r, c = -1, -1
    for rr in range(n):
        for cc in range(n):
            if grid[rr][cc] is None:
                r, c = rr, cc
                break
        if r != -1:
            break
    # Try 'B'
    grid_b = copy.deepcopy(grid)
    grid_b[r][c] = 'B'
    sol = backtrack(grid_b, n, same_pairs, diff_pairs, target)
    if sol is not None:
        return sol
    # Try 'W'
    grid_w = copy.deepcopy(grid)
    grid_w[r][c] = 'W'
    sol = backtrack(grid_w, n, same_pairs, diff_pairs, target)
    if sol is not None:
        return sol
    return None

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    target = n // 2
    same_pairs = []
    diff_pairs = []
    for key_str, v in observation['horizontal'].items():
        tup = ast.literal_eval(key_str)
        r = int(tup[0])
        c = int(tup[1] - 0.5)
        pair = ((r, c), (r, c + 1))
        if v == '=':
            same_pairs.append(pair)
        elif v == 'x':
            diff_pairs.append(pair)
    for key_str, v in observation['vertical'].items():
        tup = ast.literal_eval(key_str)
        r = int(tup[0] - 0.5)
        c = int(tup[1])
        pair = ((r, c), (r + 1, c))
        if v == '=':
            same_pairs.append(pair)
        elif v == 'x':
            diff_pairs.append(pair)
    sol = backtrack(grid, n, same_pairs, diff_pairs, target)
    if sol is None:
        return "No Solution"
    return sol

