def solve(observation):
    data = observation['data']
    unit = observation['unit']
    sub_r, sub_c = map(int, unit.split('x'))
    N = len(data)
    grid = [row[:] for row in data]
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    box_num = (N // sub_r) * (N // sub_c)
    box_used = [set() for _ in range(box_num)]
    def get_box(i, j):
        return (i // sub_r) * (N // sub_c) + (j // sub_c)
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                val = grid[i][j]
                b = get_box(i, j)
                if val in row_used[i] or val in col_used[j] or val in box_used[b]:
                    return "No Solution"
                row_used[i].add(val)
                col_used[j].add(val)
                box_used[b].add(val)
    def solve_puzzle():
        while True:
            filled = False
            contradiction = False
            # naked singles
            for i in range(N):
                for j in range(N):
                    if grid[i][j] is None:
                        poss = set(range(1, N + 1)) - row_used[i] - col_used[j] - box_used[get_box(i, j)]
                        if len(poss) == 0:
                            contradiction = True
                            break
                        if len(poss) == 1:
                            val = poss.pop()
                            grid[i][j] = val
                            row_used[i].add(val)
                            col_used[j].add(val)
                            box_used[get_box(i, j)].add(val)
                            filled = True
                if contradiction:
                    break
            if contradiction:
                break
            # hidden singles in rows
            for i in range(N):
                for num in range(1, N + 1):
                    if num not in row_used[i]:
                        candidates = []
                        for j in range(N):
                            if grid[i][j] is None:
                                b = get_box(i, j)
                                if num not in col_used[j] and num not in box_used[b]:
                                    candidates.append(j)
                        if len(candidates) == 0:
                            contradiction = True
                            break
                        elif len(candidates) == 1:
                            j = candidates[0]
                            grid[i][j] = num
                            row_used[i].add(num)
                            col_used[j].add(num)
                            box_used[get_box(i, j)].add(num)
                            filled = True
                if contradiction:
                    break
            if contradiction:
                break
            # hidden singles in cols
            for j in range(N):
                for num in range(1, N + 1):
                    if num not in col_used[j]:
                        candidates = []
                        for i in range(N):
                            if grid[i][j] is None:
                                b = get_box(i, j)
                                if num not in row_used[i] and num not in box_used[b]:
                                    candidates.append(i)
                        if len(candidates) == 0:
                            contradiction = True
                            break
                        elif len(candidates) == 1:
                            i = candidates[0]
                            grid[i][j] = num
                            row_used[i].add(num)
                            col_used[j].add(num)
                            box_used[get_box(i, j)].add(num)
                            filled = True
                if contradiction:
                    break
            if contradiction:
                break
            # hidden singles in boxes
            for bx in range(box_num):
                box_row_start = (bx // (N // sub_c)) * sub_r
                box_col_start = (bx % (N // sub_c)) * sub_c
                for num in range(1, N + 1):
                    if num not in box_used[bx]:
                        candidates = []
                        for di in range(sub_r):
                            for dj in range(sub_c):
                                i = box_row_start + di
                                j = box_col_start + dj
                                if grid[i][j] is None:
                                    if num not in row_used[i] and num not in col_used[j]:
                                        candidates.append((i, j))
                        if len(candidates) == 0:
                            contradiction = True
                            break
                        elif len(candidates) == 1:
                            i, j = candidates[0]
                            grid[i][j] = num
                            row_used[i].add(num)
                            col_used[j].add(num)
                            box_used[bx].add(num)
                            filled = True
                if contradiction:
                    break
            if contradiction:
                break
            if not filled:
                break
        if contradiction:
            return False
        if all(grid[i][j] is not None for i in range(N) for j in range(N)):
            return True
        # find cell with min possibles
        min_poss = N + 1
        cand_i, cand_j, cand_poss = -1, -1, set()
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    poss = set(range(1, N + 1)) - row_used[i] - col_used[j] - box_used[get_box(i, j)]
                    if len(poss) < min_poss:
                        min_poss = len(poss)
                        cand_i, cand_j, cand_poss = i, j, poss
        for val in list(cand_poss):
            grid[cand_i][cand_j] = val
            row_used[cand_i].add(val)
            col_used[cand_j].add(val)
            b = get_box(cand_i, cand_j)
            box_used[b].add(val)
            if solve_puzzle():
                return True
            grid[cand_i][cand_j] = None
            row_used[cand_i].remove(val)
            col_used[cand_j].remove(val)
            box_used[b].remove(val)
        return False
    if solve_puzzle():
        return grid
    else:
        return "No Solution"

