import ast
import copy

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    half = n // 2

    # Parse horizontal and vertical constraints into dicts with int keys
    horizontal = {}
    for key in observation.get('horizontal', {}):
        r, cp5 = ast.literal_eval(key)
        c = int(cp5 - 0.5)
        horizontal[(int(r), int(c))] = observation['horizontal'][key]

    vertical = {}
    for key in observation.get('vertical', {}):
        rp5, c = ast.literal_eval(key)
        r = int(rp5 - 0.5)
        vertical[(int(r), int(c))] = observation['vertical'][key]

    def opposite(col):
        return 'W' if col == 'B' else 'B'

    # Initial propagation
    changed = True
    while changed:
        changed = False
        for (r, c), sym in horizontal.items():
            if r >= n or c >= n - 1:
                continue
            a = grid[r][c]
            b = grid[r][c + 1]
            if sym == '=':
                if a is not None and b is not None:
                    if a != b:
                        return "No Solution"
                elif a is not None and b is None:
                    grid[r][c + 1] = a
                    changed = True
                elif b is not None and a is None:
                    grid[r][c] = b
                    changed = True
            elif sym == 'x':
                if a is not None and b is not None:
                    if a == b:
                        return "No Solution"
                elif a is not None and b is None:
                    grid[r][c + 1] = opposite(a)
                    changed = True
                elif b is not None and a is None:
                    grid[r][c] = opposite(b)
                    changed = True
        for (r, c), sym in vertical.items():
            if r >= n - 1 or c >= n:
                continue
            a = grid[r][c]
            b = grid[r + 1][c]
            if sym == '=':
                if a is not None and b is not None:
                    if a != b:
                        return "No Solution"
                elif a is not None and b is None:
                    grid[r + 1][c] = a
                    changed = True
                elif b is not None and a is None:
                    grid[r][c] = b
                    changed = True
            elif sym == 'x':
                if a is not None and b is not None:
                    if a == b:
                        return "No Solution"
                elif a is not None and b is None:
                    grid[r + 1][c] = opposite(a)
                    changed = True
                elif b is not None and a is None:
                    grid[r][c] = opposite(b)
                    changed = True

    # Backtracking function
    def dfs(pos):
        if pos == n * n:
            # Final check for all rows and columns
            for i in range(n):
                row_b = sum(1 for j in range(n) if grid[i][j] == 'B')
                col_b = sum(1 for k in range(n) if grid[k][i] == 'B')
                if row_b != half or col_b != half:
                    return None
                # Check no three consecutive in row
                for j in range(n - 2):
                    if grid[i][j] == grid[i][j + 1] == grid[i][j + 2]:
                        return None
                # Check no three consecutive in col
                for j in range(n - 2):
                    if grid[j][i] == grid[j + 1][i] == grid[j + 2][i]:
                        return None
            return [row[:] for row in grid]
        r = pos // n
        c = pos % n
        if grid[r][c] is not None:
            if is_valid_placement(r, c) and is_count_possible(r, c):
                res = dfs(pos + 1)
                if res is not None:
                    return res
            return None
        for color in ['B', 'W']:
            grid[r][c] = color
            if is_valid_placement(r, c) and is_count_possible(r, c):
                res = dfs(pos + 1)
                if res is not None:
                    return res
        grid[r][c] = None
        return None

    def is_valid_placement(r, c):
        color = grid[r][c]
        # Left horizontal constraint
        if c > 0 and (r, c - 1) in horizontal:
            sym = horizontal[(r, c - 1)]
            left = grid[r][c - 1]
            if sym == '=' and left != color:
                return False
            if sym == 'x' and left == color:
                return False
        # Upper vertical constraint
        if r > 0 and (r - 1, c) in vertical:
            sym = vertical[(r - 1, c)]
            up = grid[r - 1][c]
            if sym == '=' and up != color:
                return False
            if sym == 'x' and up == color:
                return False
        # Three consecutive in row
        if c >= 2 and grid[r][c - 2] == grid[r][c - 1] == color:
            return False
        # Three consecutive in column
        if r >= 2 and grid[r - 2][c] == grid[r - 1][c] == color:
            return False
        return True

    def is_count_possible(r, c):
        # Current row
        rem_row = n - c - 1
        cur_b_row = sum(1 for j in range(c + 1) if grid[r][j] == 'B')
        need_b_row = half - cur_b_row
        if need_b_row < 0 or need_b_row > rem_row:
            return False
        # Columns
        for j in range(n):
            cur_b_col = sum(1 for i in range(r) if grid[i][j] == 'B')
            filled = r
            if j <= c:
                filled += 1
                if grid[r][j] == 'B':
                    cur_b_col += 1
                rem_col = n - filled
            else:
                rem_col = n - filled
            if cur_b_col > half:
                return False
            need_b_col = half - cur_b_col
            if need_b_col < 0 or need_b_col > rem_col:
                return False
        return True

    result = dfs(0)
    if result is not None:
        return result
    return "No Solution"

