import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    possibles = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    adjacent_set = set(tuple(p) for p in observation['adjacent'])
    assigned = set()
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                v = data[r][c]
                if not assign_and_remove(possibles, r, c, v, N):
                    return "No Solution"
                assigned.add((r, c))
    arcs = get_arcs(N, adjacent_set)
    if not full_propagate(possibles, assigned, arcs, N):
        return "No Solution"
    if len(assigned) == N * N:
        return [[next(iter(possibles[r][c])) for c in range(N)] for r in range(N)]
    return solve_recursive(possibles, assigned, arcs, N) or "No Solution"

def assign_and_remove(possibles, r, c, v, N):
    if v not in possibles[r][c]:
        return False
    possibles[r][c] = {v}
    for cc in range(N):
        if cc != c and v in possibles[r][cc]:
            possibles[r][cc].remove(v)
            if len(possibles[r][cc]) == 0:
                return False
    for rr in range(N):
        if rr != r and v in possibles[rr][c]:
            possibles[rr][c].remove(v)
            if len(possibles[rr][c]) == 0:
                return False
    return True

def get_arcs(N, adjacent_set):
    arcs = []
    for r in range(N):
        for c in range(N - 1):
            mid = (float(r), c + 0.5)
            is_consec = mid in adjacent_set
            var1 = (r, c)
            var2 = (r, c + 1)
            arcs.append((var1, var2, is_consec))
            arcs.append((var2, var1, is_consec))
    for c in range(N):
        for r in range(N - 1):
            mid = (r + 0.5, float(c))
            is_consec = mid in adjacent_set
            var1 = (r, c)
            var2 = (r + 1, c)
            arcs.append((var1, var2, is_consec))
            arcs.append((var2, var1, is_consec))
    return arcs

def ac3(possibles, arcs, N):
    queue = list(arcs)
    while queue:
        var1, var2, is_consec = queue.pop(0)
        if revise(possibles, var1, var2, is_consec, N):
            r, c = var1
            if len(possibles[r][c]) == 0:
                return False
            for arc in arcs:
                if arc[1] == var1 and arc[0] != var2:
                    queue.append(arc)
    return True

def revise(possibles, var1, var2, is_consec, N):
    r1, c1 = var1
    r2, c2 = var2
    revised = False
    to_remove = []
    for v1 in possibles[r1][c1]:
        supported = any((is_consec and abs(v1 - v2) == 1) or (not is_consec and abs(v1 - v2) != 1) for v2 in possibles[r2][c2])
        if not supported:
            to_remove.append(v1)
            revised = True
    for v in to_remove:
        possibles[r1][c1].remove(v)
    return revised

def full_propagate(possibles, assigned, arcs, N):
    changed = True
    while changed:
        changed = False
        if not ac3(possibles, arcs, N):
            return False
        # find_forced for rows and columns
        for row_or_col in range(N):
            for is_row in [True, False]:
                val_to_pos = {v: [] for v in range(1, N + 1)}
                for idx in range(N):
                    if is_row:
                        r, c = row_or_col, idx
                    else:
                        r, c = idx, row_or_col
                    if (r, c) not in assigned:
                        for v in possibles[r][c]:
                            val_to_pos[v].append((r, c))
                for v in range(1, N + 1):
                    pos = val_to_pos[v]
                    if len(pos) == 1:
                        rr, cc = pos[0]
                        if not assign_and_remove(possibles, rr, cc, v, N):
                            return False
                        assigned.add((rr, cc))
                        changed = True
    return True

def solve_recursive(possibles, assigned, arcs, N):
    min_len = float('inf')
    chosen = None
    for r in range(N):
        for c in range(N):
            if (r, c) not in assigned:
                l = len(possibles[r][c])
                if l < min_len:
                    min_len = l
                    chosen = (r, c)
    if chosen is None:
        return None
    r, c = chosen
    for val in list(possibles[r][c]):
        new_poss = copy.deepcopy(possibles)
        new_assigned = assigned.copy()
        if assign_and_remove(new_poss, r, c, val, N):
            new_assigned.add((r, c))
            if full_propagate(new_poss, new_assigned, arcs, N):
                if len(new_assigned) == N * N:
                    return [[next(iter(new_poss[rr][cc])) for cc in range(N)] for rr in range(N)]
                result = solve_recursive(new_poss, new_assigned, arcs, N)
                if result is not None:
                    return result
    return None

if __name__ == "__main__":
    print(solve(OBSERVATION))
