def solve(observation):
    data = observation['data']
    N = len(data)
    # Find max_id
    max_id = 0
    for row in data:
        for rid in row:
            max_id = max(max_id, rid)
    M = max_id + 1  # assuming 0 to max_id consecutive

    # Generate all dominoes
    dominoes = []
    for r in range(N):
        for c in range(N - 1):
            dominoes.append(((r, c), (r, c + 1)))
    for r in range(N - 1):
        for c in range(N):
            dominoes.append(((r, c), (r + 1, c)))
    num_dom = len(dominoes)

    # Contribs
    contribs = []
    for dom in dominoes:
        cont = [0] * M
        for r, c in dom:
            rid = data[r][c]
            cont[rid] += 1
        contribs.append(cont)

    # Conflicts
    def is_adjacent(r1, c1, r2, c2):
        return (r1 == r2 and abs(c1 - c2) == 1) or (c1 == c2 and abs(r1 - r2) == 1)

    conflicts = [[] for _ in range(num_dom)]
    for i in range(num_dom):
        for j in range(i + 1, num_dom):
            cells_i = set(dominoes[i])
            cells_j = set(dominoes[j])
            if cells_i & cells_j:
                conflicts[i].append(j)
                conflicts[j].append(i)
                continue
            conflict = False
            for p1 in dominoes[i]:
                for p2 in dominoes[j]:
                    if is_adjacent(p1[0], p1[1], p2[0], p2[1]):
                        conflict = True
                        break
                if conflict:
                    break
            if conflict:
                conflicts[i].append(j)
                conflicts[j].append(i)

    # Possible dominoes per region
    possible_dominoes = [[] for _ in range(M)]
    for i in range(num_dom):
        for rid in range(M):
            if contribs[i][rid] > 0:
                possible_dominoes[rid].append(i)

    # Backtracking function
    is_available = [True] * num_dom

    def find(current_selected, current_counts):
        if all(c == 2 for c in current_counts):
            grid = [[None] * N for _ in range(N)]
            for i in current_selected:
                (r1, c1), (r2, c2) = dominoes[i]
                grid[r1][c1] = 'S'
                grid[r2][c2] = 'S'
            return grid

        # Find region with min remaining options
        min_num = float('inf')
        best_rid = -1
        for rid in range(M):
            if current_counts[rid] == 2:
                continue
            num = sum(1 for i in possible_dominoes[rid] if is_available[i])
            if num < min_num:
                min_num = num
                best_rid = rid

        if best_rid == -1:
            return None
        if min_num == 0:
            return None

        # Possible i for this rid
        poss_i = [i for i in possible_dominoes[best_rid] if is_available[i]]

        for i in poss_i:
            # Check exceed
            new_counts = [current_counts[rd] + contribs[i][rd] for rd in range(M)]
            if any(nc > 2 for nc in new_counts):
                continue

            # Place
            disabled = []
            for j in conflicts[i]:
                if is_available[j]:
                    is_available[j] = False
                    disabled.append(j)
            if is_available[i]:
                is_available[i] = False
                disabled.append(i)

            # Recurse
            result = find(current_selected + [i], new_counts)
            if result is not None:
                return result

            # Backtrack
            for j in disabled:
                is_available[j] = True

        return None

    result = find([], [0] * M)
    if result is None:
        return "No Solution"
    return result

