def solve(observation):
    data = observation['data']
    unit = observation['unit']
    if 'x' not in unit:
        row_unit = col_unit = int(unit)
    else:
        row_unit, col_unit = map(int, unit.split('x'))
    n = row_unit * col_unit
    grid = [row[:] for row in data]
    rows = [set() for _ in range(n)]
    cols = [set() for _ in range(n)]
    boxes = [set() for _ in range(n)]
    def box_index(i, j):
        return (i // row_unit) * (n // col_unit) + (j // col_unit)
    # Initialize constraints
    for i in range(n):
        for j in range(n):
            if grid[i][j] is not None:
                num = grid[i][j]
                rows[i].add(num)
                cols[j].add(num)
                boxes[box_index(i, j)].add(num)
    def assign(i, j, num):
        grid[i][j] = num
        rows[i].add(num)
        cols[j].add(num)
        boxes[box_index(i, j)].add(num)
    def solve_backtrack():
        while True:
            changed = False
            current_poss = {}
            for i in range(n):
                for j in range(n):
                    if grid[i][j] is None:
                        poss_set = set(range(1, n + 1)) - rows[i] - cols[j] - boxes[box_index(i, j)]
                        if len(poss_set) == 0:
                            return False
                        current_poss[(i, j)] = poss_set
            if not current_poss:
                return True
            # Naked singles
            for (i, j), poss_set in current_poss.items():
                if len(poss_set) == 1:
                    num = next(iter(poss_set))
                    assign(i, j, num)
                    changed = True
                    break
            if changed:
                continue
            # Hidden singles in rows
            for i in range(n):
                num_places = {k: [] for k in range(1, n + 1) if k not in rows[i]}
                for j in range(n):
                    pos = (i, j)
                    if pos in current_poss:
                        for k in current_poss[pos]:
                            num_places[k].append(j)
                for k, places in num_places.items():
                    if len(places) == 1:
                        j = places[0]
                        assign(i, j, k)
                        changed = True
                        break
                if changed:
                    break
            if changed:
                continue
            # Hidden singles in columns
            for j in range(n):
                num_places = {k: [] for k in range(1, n + 1) if k not in cols[j]}
                for i in range(n):
                    pos = (i, j)
                    if pos in current_poss:
                        for k in current_poss[pos]:
                            num_places[k].append(i)
                for k, places in num_places.items():
                    if len(places) == 1:
                        i = places[0]
                        assign(i, j, k)
                        changed = True
                        break
                if changed:
                    break
            if changed:
                continue
            # Hidden singles in boxes
            num_box_cols = n // col_unit
            for b in range(n):
                num_places = {k: [] for k in range(1, n + 1) if k not in boxes[b]}
                box_row_start = (b // num_box_cols) * row_unit
                box_col_start = (b % num_box_cols) * col_unit
                for di in range(row_unit):
                    for dj in range(col_unit):
                        i = box_row_start + di
                        j = box_col_start + dj
                        pos = (i, j)
                        if pos in current_poss:
                            for k in current_poss[pos]:
                                num_places[k].append((i, j))
                for k, places in num_places.items():
                    if len(places) == 1:
                        (i, j) = places[0]
                        assign(i, j, k)
                        changed = True
                        break
                if changed:
                    break
            if changed:
                continue
            # No more changes
            break
        # Branching
        (best_i, best_j) = min(current_poss, key=lambda p: len(current_poss[p]))
        best_poss = list(current_poss[(best_i, best_j)])
        for num in best_poss:
            assign(best_i, best_j, num)
            if solve_backtrack():
                return True
            grid[best_i][best_j] = None
            rows[best_i].remove(num)
            cols[best_j].remove(num)
            boxes[box_index(best_i, best_j)].remove(num)
        return False
    if solve_backtrack():
        return grid
    else:
        return "No Solution"

