from collections import defaultdict
import sys

def generate_shapes(base):
    def normalize(offs):
        min_r = min(r for r, c in offs)
        min_c = min(c for r, c in offs)
        shifted = [(r - min_r, c - min_c) for r, c in offs]
        return tuple(sorted(shifted))

    all_shapes = set()

    current = base
    for _ in range(4):
        all_shapes.add(normalize(current))
        current = [(c, -r) for r, c in current]

    mirrored = [(r, -c) for r, c in base]
    current = mirrored
    for _ in range(4):
        all_shapes.add(normalize(current))
        current = [(c, -r) for r, c in current]

    return [list(s) for s in all_shapes]

def solve(observation):
    data = observation['data']
    N = len(data)
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            region_cells[reg].append((r, c))

    regions = list(region_cells.keys())

    region_adj = defaultdict(set)
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if nr < N and nc < N and data[nr][nc] != reg:
                    nreg = data[nr][nc]
                    region_adj[reg].add(nreg)
                    region_adj[nreg].add(reg)

    shapes = {}
    shapes['I'] = generate_shapes([(0, 0), (0, 1), (0, 2), (0, 3)])
    shapes['L'] = generate_shapes([(0, 0), (1, 0), (2, 0), (2, 1)])
    shapes['T'] = generate_shapes([(0, 0), (0, 1), (0, 2), (1, 1)])
    shapes['S'] = generate_shapes([(0, 1), (0, 2), (1, 0), (1, 1)])

    region_possible = {}
    for reg in regions:
        cells_set = set(region_cells[reg])
        possibles = set()
        for typ in 'LITS':
            for sh in shapes[typ]:
                for base_r in range(N):
                    for base_c in range(N):
                        placement = []
                        valid = True
                        seen = set()
                        for dr, dc in sh:
                            pr = base_r + dr
                            pc = base_c + dc
                            if not (0 <= pr < N and 0 <= pc < N) or (pr, pc) in seen or (pr, pc) not in cells_set:
                                valid = False
                                break
                            placement.append((pr, pc))
                            seen.add((pr, pc))
                        if valid:
                            possibles.add((typ, frozenset(placement)))
        region_possible[reg] = list(possibles)

    assignment = {}
    current_shaded = set()

    def backtrack():
        if len(assignment) == len(regions):
            grid = [[None] * N for _ in range(N)]
            for regg, (typp, cellss) in assignment.items():
                for rr, cc in cellss:
                    grid[rr][cc] = typp
            return grid

        assigned_regs = set(assignment.keys())
        candidates = []
        for reg in regions:
            if reg not in assigned_regs:
                if assigned_regs:
                    if any(a in assigned_regs for a in region_adj[reg]):
                        candidates.append(reg)
                else:
                    candidates.append(reg)

        if not candidates:
            return None

        min_count = sys.maxsize
        chosen_reg = None
        for cand in candidates:
            forbidden = set()
            for neigh in region_adj[cand]:
                if neigh in assignment:
                    forbidden.add(assignment[neigh][0])
            count = sum(1 for typp, _ in region_possible[cand] if typp not in forbidden)
            if count < min_count:
                min_count = count
                chosen_reg = cand

        if chosen_reg is None or min_count == 0:
            return None

        forbidden = set(assignment[neigh][0] for neigh in region_adj[chosen_reg] if neigh in assignment)
        for typ, cells in region_possible[chosen_reg]:
            if typ in forbidden:
                continue

            connects = (len(assignment) == 0) or any(
                (rr + dr, cc + dc) in current_shaded
                for rr, cc in cells
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                if 0 <= rr + dr < N and 0 <= cc + dc < N
            )
            if not connects:
                continue

            new_shaded = current_shaded | cells
            violation = any(
                all((pr + drr, pc + dcc) in new_shaded for drr, dcc in [(0,0), (0,1), (1,0), (1,1)])
                for pr in range(N - 1)
                for pc in range(N - 1)
            )
            if violation:
                continue

            assignment[chosen_reg] = (typ, cells)
            old_shaded = current_shaded.copy()
            current_shaded.update(cells)

            result = backtrack()
            if result is not None:
                return result

            del assignment[chosen_reg]
            current_shaded = old_shaded

        return None

    result = backtrack()
    if result is not None:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
