                curr = stack.pop()
                for neigh in adj[curr]:
                    if neigh not in visited:
                        visited.add(neigh)
                        stack.append(neigh)
            if len(visited) != len(used_dots):
                return None
            # Extract loop
            loop = [start]
            curr = adj[start][0]
            loop.append(curr)
            prev = start
            while curr != start:
                next = None
                for neigh in adj[curr]:
                    if neigh != prev:
                        next = neigh
                        break
                if next is None:
                    return None
                prev = curr
                curr = next
                loop.append(curr)
            return loop

    res = search(h_edges, v_edges)
    if res is None:
        return "No Solution"
    else:
        return '[' + ','.join(f'({r},{c})' for r, c in res) + ']'

