import itertools

def has_three_consec(line):
    n = len(line)
    for i in range(n - 2):
        if line[i] is not None and line[i] == line[i + 1] == line[i + 2]:
            return True
    return False

def deduce_line(line, line_cons, half):
    n = len(line)
    num_b = sum(1 for x in line if x == 'B')
    num_w = sum(1 for x in line if x == 'W')
    num_empty = n - num_b - num_w
    needed_b = half - num_b
    needed_w = half - num_w
    if needed_b < 0 or needed_w < 0 or needed_b + needed_w != num_empty:
        return False, False
    empty_indices = [i for i, x in enumerate(line) if x is None]
    valid_configs = []
    for combo in itertools.combinations(empty_indices, needed_b):
        temp = [x for x in line]
        b_set = set(combo)
        for i in empty_indices:
            temp[i] = 'B' if i in b_set else 'W'
        if has_three_consec(temp):
            continue
        satisfies = True
        for k in range(n - 1):
            if line_cons[k] is not None:
                a, b = temp[k], temp[k + 1]
                if (a == b) != (line_cons[k] == '='):
                    satisfies = False
                    break
        if satisfies:
            valid_configs.append(temp)
    if not valid_configs:
        return False, False
    ch = False
    for j in empty_indices:
        colors = set(conf[j] for conf in valid_configs)
        if len(colors) == 1:
            line[j] = next(iter(colors))
            ch = True
    return True, ch

def propagate(grid, horiz, vert, n, half):
    changed = True
    while changed:
        changed = False
        # Propagate constraints
        for r in range(n):
            for c in range(n - 1):
                if horiz[r][c] is not None:
                    a = grid[r][c]
                    b = grid[r][c + 1]
                    cons = horiz[r][c]
                    if a is not None and b is None:
                        grid[r][c + 1] = a if cons == '=' else ('W' if a == 'B' else 'B')
                        changed = True
                    elif b is not None and a is None:
                        grid[r][c] = b if cons == '=' else ('W' if b == 'B' else 'B')
                        changed = True
                    elif a is not None and b is not None:
                        if (a == b) != (cons == '='):
                            return False
        for r in range(n - 1):
            for c in range(n):
                if vert[r][c] is not None:
                    a = grid[r][c]
                    b = grid[r + 1][c]
                    cons = vert[r][c]
                    if a is not None and b is None:
                        grid[r + 1][c] = a if cons == '=' else ('W' if a == 'B' else 'B')
                        changed = True
                    elif b is not None and a is None:
                        grid[r][c] = b if cons == '=' else ('W' if b == 'B' else 'B')
                        changed = True
                    elif a is not None and b is not None:
                        if (a == b) != (cons == '='):
                            return False
        # Deduce for rows
        for r in range(n):
            ok, ch = deduce_line(grid[r], horiz[r], half)
            if not ok:
                return False
            if ch:
                changed = True
        # Deduce for columns
        for c in range(n):
            col_line = [grid[rr][c] for rr in range(n)]
            col_cons = [vert[rr][c] for rr in range(n - 1)]
            ok, ch = deduce_line(col_line, col_cons, half)
            if not ok:
                return False
            if ch:
                changed = True
                for rr in range(n):
                    if col_line[rr] is not None and grid[rr][c] is None:
                        grid[rr][c] = col_line[rr]
