def backtrack(grid, horiz, vert, n, half):
    if not propagate(grid, horiz, vert, n, half):
        return None
    if all(all(x is not None for x in row) for row in grid):
        return [row[:] for row in grid]
    # Find empties
    empties = [(r, c) for r in range(n) for c in range(n) if grid[r][c] is None]
    if not empties:
        return None
    # Compute filled counts
    row_filled = [n - sum(1 for x in grid[rr] if x is None) for rr in range(n)]
    col_filled = [n - sum(1 for rr in range(n) if grid[rr][cc] is None) for cc in range(n)]
    # Pick with max score
    max_score = -1
    branch_r, branch_c = -1, -1
    for rr, cc in empties:
        score = row_filled[rr] + col_filled[cc]
        if score > max_score:
            max_score = score
            branch_r, branch_c = rr, cc
    # Try both colors
    for color in ['B', 'W']:
        new_grid = [row[:] for row in grid]
        new_grid[branch_r][branch_c] = color
        res = backtrack(new_grid, horiz, vert, n, half)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    if n % 2 != 0 or any(len(row) != n for row in data):
        return "No Solution"
    half = n // 2
    grid = [row[:] for row in data]
    horiz = [[None] * (n - 1) for _ in range(n)]
    vert = [[None] * n for _ in range(n - 1)]
    for s, val in observation['horizontal'].items():
        row, colh = ast.literal_eval(s)
        r = int(row)
        c = int(colh - 0.5)
        if 0 <= r < n and 0 <= c < n - 1:
