    for s, val in observation['vertical'].items():
        rowh, col = ast.literal_eval(s)
        r = int(rowh - 0.5)
        c = int(col)
        if 0 <= r < n - 1 and 0 <= c < n:
            vert[r][c] = val
    result = backtrack(grid, horiz, vert, n, half)
    if result is None:
        return "No Solution"
    return result

