def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n = len(row_sum)
    row_weights = [i + 1 for i in range(n)]
    col_weights = [i + 1 for i in range(n)]

    # Function to get possible masks for a target sum with given weights
    def get_possible_masks(target, weights):
        m = len(weights)
        possibles = []
        for mask in range(1 << m):
            s = sum(weights[j] for j in range(m) if mask & (1 << j))
            if s == target:
                possibles.append(mask)
        return possibles

    # Precompute possible masks for rows and columns
    row_poss = [get_possible_masks(row_sum[i], col_weights) for i in range(n)]
    col_poss = [get_possible_masks(col_sum[j], row_weights) for j in range(n)]

    # Aggressive constraint propagation
    changed = True
    while changed:
        changed = False

        # Filter row_poss based on consistent with column possibilities (dual propagation)
        for i in range(n):
            new_poss = []
            for mask in row_poss[i]:
                consistent = True
                temp_col_counts = [0] * n
                for j in range(n):
                    if mask & (1 << j):
                        temp_col_counts[j] += 1
                # Check if this mask is consistent with col_poss, but to avoid heavy, we use the force logic below
                # Actually, we implement force detection here
                new_poss.append(mask)  # Temporarily keep, force is in the loop below

        # Force detection and filtering
        for i in range(n):
            if len(row_poss[i]) == 0:
                return "No Solution"
            set_counts = [0] * n
            for mask in row_poss[i]:
                for j in range(n):
                    if mask & (1 << j):
                        set_counts[j] += 1
            new_poss = []
            for mask in row_poss[i]:
                ok = True
                for j in range(n):
                    is_set = bool(mask & (1 << j))
                    if set_counts[j] == len(row_poss[i]) and not is_set:
                        ok = False
                        break
                    if set_counts[j] == 0 and is_set:
                        ok = False
                        break
                if ok:
                    new_poss.append(mask)
            if len(new_poss) < len(row_poss[i]):
                changed = True
            row_poss[i] = new_poss

        for j in range(n):
            if len(col_poss[j]) == 0:
                return "No Solution"
            set_counts = [0] * n
            for mask in col_poss[j]:
                for i in range(n):
                    if mask & (1 << i):
                        set_counts[i] += 1
            new_poss = []
            for mask in col_poss[j]:
                ok = True
                for i in range(n):
                    is_set = bool(mask & (1 << i))
                    if set_counts[i] == len(col_poss[j]) and not is_set:
                        ok = False
                        break
                    if set_counts[i] == 0 and is_set:
                        ok = False
                        break
                if ok:
                    new_poss.append(mask)
            if len(new_poss) < len(col_poss[j]):
                changed = True
            col_poss[j] = new_poss

    # Now backtracking to solve the reduced problem
    grid = [[None] * n for _ in range(n)]
    current_col_sums = [0] * n

    def backtrack(row):
        if row == n:
            return all(current_col_sums[j] == col_sum[j] for j in range(n))

        for mask in row_poss[row]:
            # Add
            exceed = False
            added = []
            for j in range(n):
                if mask & (1 << j):
                    current_col_sums[j] += row_weights[row]
                    added.append(j)
                    if current_col_sums[j] > col_sum[j]:
                        exceed = True
            if exceed:
                for j in added:
                    current_col_sums[j] -= row_weights[row]
                continue

            # Prune if cannot reach
            can_reach = True
            remaining_max = sum(row_weights[r] for r in range(row + 1, n))
            for j in range(n):
                if current_col_sums[j] + remaining_max < col_sum[j]:
                    can_reach = False
                    break
            if not can_reach:
                for j in added:
                    current_col_sums[j] -= row_weights[row]
                continue

            # Set grid
            for j in range(n):
                grid[row][j] = 'B' if mask & (1 << j) else None

            # Recurse
            if backtrack(row + 1):
                return True

            # Undo
            for j in added:
                current_col_sums[j] -= row_weights[row]

        return False

    if backtrack(0):
        return grid
    else:
        return "No Solution"

