        queue_dots.add((rr, cc))
        queue_dots.add((rr + 1, cc))

def process_cell(i, j, horz, vert, data, N, queue_cells, queue_dots):
    k = data[i][j]
    edges = [
        ('h', i, j),    # top
        ('v', i, j),    # left
        ('v', i, j + 1),# right
        ('h', i + 1, j) # bottom
    ]
    num_in = 0
    num_out = 0
    unks = []
    for e in edges:
        typ, rr, cc = e
        val = horz[rr][cc] if typ == 'h' else vert[rr][cc]
        if val is True:
            num_in += 1
        elif val is False:
            num_out += 1
        else:
            unks.append(e)
    num_unk = len(unks)
    min_i = num_in
    max_i = num_in + num_unk
    if k < min_i or k > max_i:
        raise Impossible()
    changed = False
    if max_i == k and num_unk > 0:
        for e in unks:
            set_edge(e, True, horz, vert, queue_cells, queue_dots)
        changed = True
    if min_i == k and num_unk > 0:
        for e in unks:
            set_edge(e, False, horz, vert, queue_cells, queue_dots)
