def is_single_loop(graph, used):
    if not used:
        return False
    start = min(used, key=lambda p: (p[0], p[1]))
    visited = set()
    stack = [start]
    visited.add(start)
    while stack:
        curr = stack.pop()
        for nb in graph[curr]:
            if nb not in visited:
                visited.add(nb)
                stack.append(nb)
    return len(visited) == len(used)

def get_loop(graph, used):
    start = min(used, key=lambda p: (p[0], p[1]))
    neighs = sorted(graph[start], key=lambda p: (p[0], p[1]))
    next = neighs[0]
    path = [start, next]
    prev = start
    current = next
    while current != start:
        neighs = graph[current]
        next = [nb for nb in neighs if nb != prev][0]
        path.append(next)
        prev = current
        current = next
    return path

def solve_it(horz, vert, data, N):
