    branch_edge = None
    for r in range(N + 1):
        for c in range(N):
            if horz[r][c] is None:
                all_decided = False
                branch_edge = ('h', r, c)
                break
        if not all_decided:
            break
    if all_decided:
        for r in range(N):
            for c in range(N + 1):
                if vert[r][c] is None:
                    all_decided = False
                    branch_edge = ('v', r, c)
                    break
            if not all_decided:
