        used = set()
        for r in range(N + 1):
            for c in range(N):
                if horz[r][c] == True:
                    p1 = (r, c)
                    p2 = (r, c + 1)
                    graph[p1].append(p2)
                    graph[p2].append(p1)
                    used.add(p1)
                    used.add(p2)
        for r in range(N):
            for c in range(N + 1):
