                    p1 = (r, c)
                    p2 = (r + 1, c)
                    graph[p1].append(p2)
                    graph[p2].append(p1)
                    used.add(p1)
                    used.add(p2)
        for p in graph:
            if len(graph[p]) != 2:
                return None
        if not is_single_loop(graph, used):
            return None
        return get_loop(graph, used)
    # Branch
    horz_copy = [row[:] for row in horz]
    vert_copy = [row[:] for row in vert]
    # Try True
    dummy_qc = set()
    dummy_qd = set()
    set_edge(branch_edge, True, horz, vert, dummy_qc, dummy_qd)
    sol = solve_it(horz, vert, data, N)
    if sol is not None:
        return sol
    horz[:] = [row[:] for row in horz_copy]
    vert[:] = [row[:] for row in vert_copy]
    # Try False
    set_edge(branch_edge, False, horz, vert, dummy_qc, dummy_qd)
    sol = solve_it(horz, vert, data, N)
    if sol is not None:
        return sol
    horz[:] = [row[:] for row in horz_copy]
    vert[:] = [row[:] for row in vert_copy]
    return None

