                    all_placements.append(('S', cells))

    # Now, assign to regions
    possible = defaultdict(list)
    for typ, cells in all_placements:
        ids = set(data[r][c] for r, c in cells)
        if len(ids) == 1:
            reg = ids.pop()
            possible[reg].append((typ, frozenset(cells)))

    # Dedup
    for reg in possible:
        possible[reg] = list(set(possible[reg]))

    # Check if all regions have possibilities
    for reg in regions:
        if not possible[reg]:
            return "No Solution"

    # Compute adjacent regions
    adj = defaultdict(set)
    for r in range(n):
        for c in range(n):
            reg = data[r][c]
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if nr < n and nc < n:
                    nreg = data[nr][nc]
                    if nreg != reg:
                        adj[reg].add(nreg)
                        adj[nreg].add(reg)

    # Region list sorted by number of possibilities
    region_list = sorted(regions.keys(), key=lambda reg: len(possible[reg]))

    # Backtrack
    def backtrack(index, assigned):
        if index == len(region_list):
            shaded = set()
            for cells in assigned.values():
                shaded.update(cells)
            if not shaded:
                return None
            # Check connected
            start = next(iter(shaded))
            visited = set()
            q = deque([start])
            visited.add(start)
            while q:
                cr, cc = q.popleft()
                for dr, dc in directions:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < n and 0 <= nc < n and (nr, nc) in shaded and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) != len(shaded):
                return None
            # Check no 2x2
            for rr in range(n - 1):
                for cc in range(n - 1):
                    sq = [(rr, cc), (rr, cc + 1), (rr + 1, cc), (rr + 1, cc + 1)]
                    if all(pos in shaded for pos in sq):
                        return None
            # Build grid
            grid = [[None] * n for _ in range(n)]
            for reg, (typ, cells) in assigned.items():
                for r, c in cells:
                    grid[r][c] = typ
            return grid
        reg = region_list[index]
        for typ, cells in possible[reg]:
            ok = True
            for nreg in adj[reg]:
                if nreg in assigned and assigned[nreg][0] == typ:
                    ok = False
                    break
            if ok:
                assigned[reg] = (typ, cells)
                res = backtrack(index + 1, assigned)
                if res is not None:
                    return res
                del assigned[reg]
        return None

    result = backtrack(0, {})
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
