        return True, changed
    def deduce_counts():
        changed = False
        for i in range(n):
            b_count = 0
            w_count = 0
            empties = []
            for j in range(n):
                if grid[i][j] == 'B': b_count += 1
                elif grid[i][j] == 'W': w_count += 1
                else: empties.append(j)
            needed_b = n // 2 - b_count
            needed_w = n // 2 - w_count
            if needed_b < 0 or needed_w < 0: return False, changed
            if len(empties) == needed_b and needed_b > 0:
                for j in empties:
                    grid[i][j] = 'B'
                changed = True
            elif len(empties) == needed_w and needed_w > 0:
                for j in empties:
                    grid[i][j] = 'W'
