                else: empties.append(i)
            needed_b = n // 2 - b_count
            needed_w = n // 2 - w_count
            if needed_b < 0 or needed_w < 0: return False, changed
            if len(empties) == needed_b and needed_b > 0:
                for i in empties:
                    grid[i][j] = 'B'
                changed = True
            elif len(empties) == needed_w and needed_w > 0:
                for i in empties:
                    grid[i][j] = 'W'
                changed = True
        return True, changed
    def deduce_three():
        changed = False
        for i in range(n):
            for k in range(n - 1):
                a = grid[i][k]
                b = grid[i][k + 1]
                if a is None or b is None: continue
                if a == b:
                    if k > 0 and grid[i][k - 1] is None:
                        grid[i][k - 1] = opposite(a)
                        changed = True
                    if k + 1 < n - 1 and grid[i][k + 2] is None:
                        grid[i][k + 2] = opposite(a)
                        changed = True
            for k in range(n - 2):
                a = grid[i][k]
                c = grid[i][k + 2]
                if a is None or c is None: continue
                if a == c:
                    if grid[i][k + 1] is None:
                        grid[i][k + 1] = opposite(a)
                        changed = True
        for j in range(n):
            for k in range(n - 1):
                a = grid[k][j]
                b = grid[k + 1][j]
                if a is None or b is None: continue
                if a == b:
                    if k > 0 and grid[k - 1][j] is None:
                        grid[k - 1][j] = opposite(a)
                        changed = True
                    if k + 1 < n - 1 and grid[k + 2][j] is None:
                        grid[k + 2][j] = opposite(a)
                        changed = True
            for k in range(n - 2):
                a = grid[k][j]
                c = grid[k + 2][j]
                if a is None or c is None: continue
                if a == c:
                    if grid[k + 1][j] is None:
                        grid[k + 1][j] = opposite(a)
