        for r in range(n):
            if grid[r].count('B') != n // 2: return False
        for c in range(n):
            if [grid[r][c] for r in range(n)].count('B') != n // 2: return False
        return is_valid_grid(check_counts=False, check_three=True)
    def backtrack():
        if is_solved(): return True
        if not full_propagation(): return False
        if is_solved(): return True
        min_rem = n + 1
        candidate = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    empty_row = sum(1 for j in range(n) if grid[r][j] is None)
                    empty_col = sum(1 for i in range(n) if grid[i][c] is None)
                    rem = min(empty_row, empty_col)
                    if rem < min_rem:
                        min_rem = rem
                        candidate = (r, c)
        if candidate is None: return False
        r, c = candidate
        original = grid[r][c]
        for color in ['B', 'W']:
            grid[r][c] = color
            if backtrack():
                return True
            grid[r][c] = original
        return False
    if not full_propagation():
        return "No Solution"
    if is_solved():
        return grid
    if backtrack():
        return grid
    else:
        return "No Solution"

