OBSERVATION = {'row_weight': [0, 1, 2, 3, 4, 5], 'col_weight': [1, 2, 3, 4, 5, 6], 'row_sum': [11, 1, 8, 4, 3, 1], 'col_sum': [8, 4, 5, 5, 1, 3]}

def solve(observation):
    row_w = observation['row_weight']
    col_w = observation['col_weight']
    row_s = observation['row_sum']
    col_s = observation['col_sum']
    m = len(row_w)
    n = len(col_w)

    # Precompute possible masks for each row to mimic pattern recognition of feasible combinations
    possible_masks = []
    for i in range(m):
        target = row_s[i]
        masks = []
        for mask in range(1 << n):
            s = sum(col_w[j] for j in range(n) if mask & (1 << j))
            if s == target:
                masks.append(mask)
        possible_masks.append(masks)

    # To mimic human deduction, identify rows with unique possibilities and fix them first
    # Also, sort rows by number of possibilities for efficient search (most constrained first)
    row_order = sorted(range(m), key=lambda i: len(possible_masks[i]))

    grid = [[None] * n for _ in range(m)]
    current_col_sums = [0] * n

    # Remaining needed for each column
    remaining = col_s[:]

    def dfs(idx):
        if idx == m:
            return all(current_col_sums[j] == col_s[j] for j in range(n))

        row_idx = row_order[idx]
        for mask in possible_masks[row_idx]:
            # Check if this mask violates remaining max for columns
            exceed = False
            added = [0] * n
            for j in range(n):
                if mask & (1 << j):
                    add = row_w[row_idx]
                    if current_col_sums[j] + add > col_s[j]:
                        exceed = True
                        break
                    added[j] = add
            if exceed:
                continue

            # Apply
            for j in range(n):
                current_col_sums[j] += added[j]
                remaining[j] -= added[j]

            # Aggressive pruning: check if remaining can be achieved with future rows
            # For each col, min remaining contrib 0, max sum of remaining positive row_w
            prune = False
            remaining_rows = row_order[idx+1:]
            max_possible = sum(row_w[r] for r in remaining_rows if row_w[r] > 0)
            for j in range(n):
                if remaining[j] < 0 or remaining[j] > max_possible:
                    prune = True
                    break
            if not prune:
                if dfs(idx + 1):
                    # Fill grid
                    for j in range(n):
                        if mask & (1 << j):
                            grid[row_idx][j] = 'B'
                    return True

            # Backtrack
            for j in range(n):
                current_col_sums[j] -= added[j]
                remaining[j] += added[j]
        return False

    # Initial fixing of forced rows (unique possibility) to simulate deduction
    for i in range(m):
        if len(possible_masks[i]) == 1:
            mask = possible_masks[i][0]
            for j in range(n):
                if mask & (1 << j):
                    grid[i][j] = 'B'
                    current_col_sums[j] += row_w[i]
                    remaining[j] -= row_w[i]

    # Now run DFS on the remaining
    if dfs(0):
        return grid
    return "No Solution"

