import copy

OBSERVATION = {'data': [['B3', None, None, 'B5', 'W2', None], [None, None, None, None, None, 'B3'], ['B2', None, None, None, None, None], [None, None, None, None, None, None], [None, 'B2', None, 'B2', None, 'B2'], ['B3', None, None, None, None, None]]}

def solve(observation):
    data = observation['data']
    height = len(data)
    width = len(data[0])
    deltas = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    op = [2, 3, 0, 1]

    def get_configs(r, c, color, k):
        configs = []
        avail = [d for d in range(4) if 0 <= r + deltas[d][0] < height and 0 <= c + deltas[d][1] < width]
        for d1 in range(4):
            for d2 in range(d1 + 1, 4):
                if d1 in avail and d2 in avail:
                    diff = d2 - d1
                    if (color == 'W' and diff == 2) or (color == 'B' and diff in (1, 3)):
                        max1 = 0
                        rr, cc = r, c
                        while True:
                            rr += deltas[d1][0]
                            cc += deltas[d1][1]
                            if not (0 <= rr < height and 0 <= cc < width):
                                break
                            max1 += 1
                        max2 = 0
                        rr, cc = r, c
                        while True:
                            rr += deltas[d2][0]
                            cc += deltas[d2][1]
                            if not (0 <= rr < height and 0 <= cc < width):
                                break
                            max2 += 1
                        for a in range(1, max1 + 1):
                            for b in range(1, max2 + 1):
                                if a + b == k:
                                    configs.append((d1, a, d2, b))
        return configs

    clues = []
    for r in range(height):
        for c in range(width):
            if data[r][c] is not None:
                color = data[r][c][0]
                k = int(data[r][c][1:])
                configs = get_configs(r, c, color, k)
                clues.append((r, c, configs))

    clues.sort(key=lambda x: len(x[2]))

    possibles = [[set() for _ in range(width)] for _ in range(height)]
    can_be_unused = [[True for _ in range(width)] for _ in range(height)]

    for r in range(height):
        for c in range(width):
            avail = [d for d in range(4) if 0 <= r + deltas[d][0] < height and 0 <= c + deltas[d][1] < width]
            pairs = [frozenset([i, j]) for i in avail for j in avail if i < j]
            if data[r][c] is None:
                possibles[r][c] = set(pairs)
                can_be_unused[r][c] = True
            else:
                filt = [p for p in pairs if (max(p) - min(p) in (1, 3) if data[r][c][0] == 'B' else max(p) - min(p) == 2)]
                possibles[r][c] = set(filt)
                can_be_unused[r][c] = False

    assigned = [[None for _ in range(width)] for _ in range(height)]

    def assign(rr, cc, pair):
        if pair not in possibles[rr][cc]:
            return False
        possibles[rr][cc] = {pair}
        can_be_unused[rr][cc] = False
        for dd in pair:
            nr, nc = rr + deltas[dd][0], rr + deltas[dd][1]
            if not add_constraint(nr, nc, op[dd]):
                return False
        return True

    def add_constraint(rr, cc, req_d):
        old_can = can_be_unused[rr][cc]
        can_be_unused[rr][cc] = False
        old_len = len(possibles[rr][cc])
        possibles[rr][cc] = {p for p in possibles[rr][cc] if req_d in p}
        if len(possibles[rr][cc]) == 0:
            return False
        changed = old_len > len(possibles[rr][cc]) or (old_can and not can_be_unused[rr][cc])
        if changed and len(possibles[rr][cc]) == 1:
            p = next(iter(possibles[rr][cc]))
            if not assign(rr, cc, p):
                return False
        return True

    def remove_possibility(rr, cc, bad_p):
        old_len = len(possibles[rr][cc])
        possibles[rr][cc].discard(bad_p)
        if old_len > len(possibles[rr][cc]):
            if len(possibles[rr][cc]) == 0 and not can_be_unused[rr][cc]:
                return False
            if len(possibles[rr][cc]) == 1:
                p = next(iter(possibles[rr][cc]))
                if not assign(rr, cc, p):
                    return False
        return True

    def force_arm(r, c, d, length):
        delta = deltas[d]
        opd = op[d]
        straight_pair = frozenset([d, opd])
        curr_r, curr_c = r, c
        for i in range(1, length):
            curr_r += delta[0]
            curr_c += delta[1]
            if not (0 <= curr_r < height and 0 <= curr_c < width):
                return False
            if not assign(curr_r, curr_c, straight_pair):
                return False
        curr_r += delta[0]
        curr_c += delta[1]
        if not (0 <= curr_r < height and 0 <= curr_c < width):
            return False
        if not add_constraint(curr_r, curr_c, opd):
            return False
        bad_pair = frozenset([opd, d])
        if not remove_possibility(curr_r, curr_c, bad_pair):
            return False
        return True

    def get_path(assg, dlt, h, w):
        used_count = sum(1 for rr in range(h) for cc in range(w) if assg[rr][cc] is not None)
        start = None
        for rr in range(h):
            for cc in range(w):
                if assg[rr][cc] is not None:
                    start = (rr, cc)
                    break
            if start is not None:
                break
        if start is None:
            return None
        path = [start]
        prev = None
        curr = start
        visited = set([start])
        while True:
            found = False
            for dd in assg[curr[0]][curr[1]]:
                nxp = (curr[0] + dlt[dd][0], curr[1] + dlt[dd][1])
                if nxp != prev and nxp not in visited:
                    path.append(nxp)
                    visited.add(nxp)
                    prev = curr
                    curr = nxp
                    found = True
                    break
            if not found:
                for dd in assg[curr[0]][curr[1]]:
                    nxp = (curr[0] + dlt[dd][0], curr[1] + dlt[dd][1])
                    if nxp == start and nxp != prev:
                        path.append(start)
                        if len(visited) == used_count:
                            return path
                        else:
                            return None
                return None

    def remaining_search():
        var = None
        max_opt = 1
        for rr in range(height):
            for cc in range(width):
                opts = len(possibles[rr][cc])
                if can_be_unused[rr][cc]:
                    opts += 1
                if opts > max_opt:
                    max_opt = opts
                    var = (rr, cc)
        if var is None:
            for rr in range(height):
                for cc in range(width):
                    if assigned[rr][cc] is None:
                        if len(possibles[rr][cc]) == 1:
                            assigned[rr][cc] = next(iter(possibles[rr][cc]))
                        elif len(possibles[rr][cc]) == 0 and can_be_unused[rr][cc]:
                            assigned[rr][cc] = None
                        else:
                            return None
            path = get_path(assigned, deltas, height, width)
            if path:
                return path
            else:
                return None
        rr, cc = var
        save_poss = possibles[rr][cc].copy()
        save_can = can_be_unused[rr][cc]
        save_ass = assigned[rr][cc]
        if can_be_unused[rr][cc]:
            possibles[rr][cc] = set()
            can_be_unused[rr][cc] = True
            assigned[rr][cc] = None
            res = remaining_search()
            if res is not None:
                return res
        for p in save_poss:
            possibles[rr][cc] = {p}
            can_be_unused[rr][cc] = False
            assigned[rr][cc] = p
            if assign(rr, cc, p):
                res = remaining_search()
                if res is not None:
                    return res
            possibles[rr][cc] = save_poss.copy()
            can_be_unused[rr][cc] = save_can
            assigned[rr][cc] = save_ass
        return None

    def search(idx):
        if idx == len(clues):
            return remaining_search()
        rr, cc, cfgs = clues[idx]
        save_poss = copy.deepcopy(possibles)
        save_can = copy.deepcopy(can_be_unused)
        save_ass = copy.deepcopy(assigned)
        for conf in cfgs:
            possibles = copy.deepcopy(save_poss)
            can_be_unused = copy.deepcopy(save_can)
            assigned = copy.deepcopy(save_ass)
            d1, a, d2, b = conf
            pair = frozenset([d1, d2])
            if not assign(rr, cc, pair):
                continue
            if not force_arm(rr, cc, d1, a):
                continue
            if not force_arm(rr, cc, d2, b):
                continue
            res = search(idx + [0, 1, 2, 3, 4, 5]

            return res
        return "No Solution"

    return search(0)

if __name__ == "__main__":
    print(solve(OBSERVATION))
