from collections import defaultdict, deque
import ast

def solve(observation):
    data = observation['data']
    N = len(data)
    h = [[-1] * N for _ in range(N + 1)]
    v = [[-1] * (N + 1) for _ in range(N)]

    def get_edge(r, c, is_h):
        if is_h:
            return h[r][c]
        else:
            return v[r][c]

    def set_edge(r, c, is_h, val):
        if is_h:
            if h[r][c] != -1 and h[r][c] != val:
                return False
            h[r][c] = val
        else:
            if v[r][c] != -1 and v[r][c] != val:
                return False
            v[r][c] = val
        return True

    def propagate():
        forced = []
        changed = True
        while changed:
            changed = False
            # Cell constraints
            for i in range(N):
                for j in range(N):
                    if data[i][j] is None:
                        continue
                    k = data[i][j]
                    edge_list = [(i, j, True), (i + 1, j, True), (i, j, False), (i, j + 1, False)]
                    edges = [get_edge(*e) for e in edge_list]
                    p = sum(1 for e in edges if e == 1)
                    unk = [idx for idx, e in enumerate(edges) if e == -1]
                    u = len(unk)
                    a = 4 - p - u
                    if p > k or p + u < k:
                        return False, []
                    if u > 0:
                        if p + u == k:
                            for idx in unk:
                                rr, cc, ish = edge_list[idx]
                                prev = get_edge(rr, cc, ish)
                                if prev != -1:
                                    if prev != 1:
                                        return False, []
                                else:
                                    set_edge(rr, cc, ish, 1)
                                    forced.append((rr, cc, ish, prev))
                            changed = True
                        if p == k:
                            for idx in unk:
                                rr, cc, ish = edge_list[idx]
                                prev = get_edge(rr, cc, ish)
                                if prev != -1:
                                    if prev != 0:
                                        return False, []
                                else:
                                    set_edge(rr, cc, ish, 0)
                                    forced.append((rr, cc, ish, prev))
                            changed = True
            # Dot degree constraints
            for r in range(N + 1):
                for c in range(N + 1):
                    inc = []
                    if r > 0:
                        inc.append((r - 1, c, False))
                    if r < N:
                        inc.append((r, c, False))
                    if c > 0:
                        inc.append((r, c - 1, True))
                    if c < N:
                        inc.append((r, c, True))
                    present = 0
                    unk = []
                    for idx, (rr, cc, ish) in enumerate(inc):
                        val = get_edge(rr, cc, ish)
                        if val == 1:
                            present += 1
                        elif val == -1:
                            unk.append(idx)
                    u = len(unk)
                    if present > 2:
                        return False, []
                    if present == 2 and u > 0:
                        for ii in unk:
                            rr, cc, ish = inc[ii]
                            prev = get_edge(rr, cc, ish)
                            set_edge(rr, cc, ish, 0)
                            forced.append((rr, cc, ish, prev))
                        changed = True
                    if present == 1:
                        if u == 0:
                            return False, []
                        if u == 1:
                            ii = unk[0]
                            rr, cc, ish = inc[ii]
                            prev = get_edge(rr, cc, ish)
                            set_edge(rr, cc, ish, 1)
                            forced.append((rr, cc, ish, prev))
                            changed = True
                    if present == 0 and u < 2 and u > 0:
                        for ii in unk:
                            rr, cc, ish = inc[ii]
                            prev = get_edge(rr, cc, ish)
                            set_edge(rr, cc, ish, 0)
                            forced.append((rr, cc, ish, prev))
                        changed = True
        return True, forced

    def is_valid_loop():
        graph = defaultdict(list)
        for r in range(N + 1):
            for c in range(N):
                if h[r][c] == 1:
                    graph[(r, c)].append((r, c + 1))
                    graph[(r, c + 1)].append((r, c))
        for r in range(N):
            for c in range(N + 1):
                if v[r][c] == 1:
                    graph[(r, c)].append((r + 1, c))
                    graph[(r + 1, c)].append((r, c))
        component_dots = set(graph.keys())
        for dot in list(graph):
            if len(graph[dot]) not in (0, 2):
                return False
        if not component_dots:
            return False
        visited = set()
        components = 0
        for dot in component_dots:
            if dot not in visited:
                components += 1
                if components > 1:
                    return False
                q = deque([dot])
                visited.add(dot)
                while q:
                    cur = q.popleft()
                    for nei in graph[cur]:
                        if nei not in visited:
                            visited.add(nei)
                            q.append(nei)
        return len(visited) == len(component_dots)

    def get_loop_path():
        graph = defaultdict(list)
        for r in range(N + 1):
            for c in range(N):
                if h[r][c] == 1:
                    graph[(r, c)].append((r, c + 1))
                    graph[(r, c + 1)].append((r, c))
        for r in range(N):
            for c in range(N + 1):
                if v[r][c] == 1:
                    graph[(r, c)].append((r + 1, c))
                    graph[(r + 1, c)].append((r, c))
        component_dots = sorted(graph.keys())
        if not component_dots:
            return None
        start = component_dots[0]
        path = [start]
        neighbors = sorted(graph[start])
        if not neighbors:
            return None
        current = start
        next_dot = neighbors[0]
        prev = current
        current = next_dot
        path.append(current)
        while current != start:
            neis = graph[current]
            next_dot = neis[0] if neis[0] != prev else neis[1]
            path.append(next_dot)
            prev = current
            current = next_dot
        return path

    def search():
        ok, forced = propagate()
        if not ok:
            return None
        all_decided = True
        branch_edge = None
        for r in range(N + 1):
            for c in range(N):
                if h[r][c] == -1:
                    all_decided = False
                    if branch_edge is None:
                        branch_edge = (r, c, True)
        for r in range(N):
            for c in range(N + 1):
                if v[r][c] == -1:
                    all_decided = False
                    if branch_edge is None:
                        branch_edge = (r, c, False)
        if all_decided:
            if is_valid_loop():
                return get_loop_path()
            else:
                return None
        # Branch
        r, c, is_h = branch_edge
        prev = get_edge(r, c, is_h)
        # Try 0
        if set_edge(r, c, is_h, 0):
            res = search()
            if res is not None:
                return res
        set_edge(r, c, is_h, prev)
        # Try 1
        if set_edge(r, c, is_h, 1):
            res = search()
            if res is not None:
                return res
        set_edge(r, c, is_h, prev)
        # Undo forced
        for rr, cc, ish, pval in reversed(forced):
            set_edge(rr, cc, ish, pval)
        return None

    result = search()
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
