from collections import defaultdict, deque
import copy

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)

    # Group cells by region and get numbers
    region_cells = defaultdict(list)
    region_num = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells[rid].append((r, c))
            if data[r][c] is not None:
                region_num[rid] = data[r][c]

    grid = [['?' for _ in range(n)] for _ in range(n)]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(g):
        # Check no adjacent blacks
        for r in range(n):
            for c in range(n):
                if g[r][c] == 'B':
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and g[nr][nc] == 'B':
                            return False

        # Check region counts
        for rid, cells in region_cells.items():
            if rid not in region_num:
                continue
            k = region_num[rid]
            count_b = sum(1 for pr, pc in cells if g[pr][pc] == 'B')
            count_u = sum(1 for pr, pc in cells if g[pr][pc] == '?')
            if count_b > k or count_b + count_u < k:
                return False

        # Check white segments in rows
        for r in range(n):
            i = 0
            while i < n:
                if g[r][i] != 'W':
                    i += 1
                    continue
                regs = set()
                j = i
                while j < n and g[r][j] == 'W':
                    regs.add(region[r][j])
                    j += 1
                if len(regs) > 2:
                    return False
                i = j

        # Check white segments in columns
        for c in range(n):
            i = 0
            while i < n:
                if g[i][c] != 'W':
                    i += 1
                    continue
                regs = set()
                j = i
                while j < n and g[j][c] == 'W':
                    regs.add(region[j][c])
                    j += 1
                if len(regs) > 2:
                    return False
                i = j
        return True

    def is_connected(g):
        whites = [(r, c) for r in range(n) for c in range(n) if g[r][c] == 'W']
        if not whites:
            return True
        visited = set()
        q = deque([whites[0]])
        visited.add(whites[0])
        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and g[nr][nc] == 'W' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(whites)

    def backtrack(pos):
        if pos == n * n:
            return is_connected(grid) and is_valid(grid)

        r = pos // n
        c = pos % n
        if grid[r][c] != '?':
            return backtrack(pos + 1)

        # Try 'W'
        grid[r][c] = 'W'
        if is_valid(grid):
            if backtrack(pos + 1):
                return True
        grid[r][c] = '?'

        # Try 'B'
        can_b = True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 'B':
                can_b = False
                break
        if can_b:
            grid[r][c] = 'B'
            forced = []
            force_fail = False
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == '?':
                    grid[nr][nc] = 'W'
                    forced.append((nr, nc))
            if is_valid(grid):
                if backtrack(pos + 1):
                    return True
            for fr, fc in forced:
                grid[fr][fc] = '?'
            grid[r][c] = '?'

        return False

    # Initial forcing
    for rid, k in list(region_num.items()):
        if k == 0:
            for pr, pc in region_cells[rid]:
                grid[pr][pc] = 'W'

    if backtrack(0):
        ans = [[None if grid[r][c] == 'W' else 'B' for c in range(n)] for r in range(n)]
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
