def get_possible_masks_for_row(row, grid, col_weights, target, n):
    masks = []
    for m in range(1 << n):
        s = 0
        consistent = True
        for j in range(n):
            on = (m & (1 << j)) != 0
            if on:
                s += col_weights[j]
            if (grid[row][j] == 1 and not on) or (grid[row][j] == -1 and on):
                consistent = False
                break
        if consistent and s == target:
            masks.append(m)
    return masks

def get_possible_masks_for_col(col, grid, row_weights, target, n):
    masks = []
    for m in range(1 << n):
        s = 0
        consistent = True
        for i in range(n):
            on = (m & (1 << i)) != 0
            if on:
                s += row_weights[i]
            if (grid[i][col] == 1 and not on) or (grid[i][col] == -1 and on):
                consistent = False
                break
        if consistent and s == target:
            masks.append(m)
    return masks

def deduce(grid, row_sums, col_sums, row_weights, col_weights, n):
    changed = True
    while changed:
        changed = False
        for i in range(n):
            possible = get_possible_masks_for_row(i, grid, col_weights, row_sums[i], n)
            if not possible:
                return False
            for j in range(n):
                all_on = all((m & (1 << j)) != 0 for m in possible)
                if all_on:
                    if grid[i][j] == -1:
                        return False
                    if grid[i][j] == 0:
                        grid[i][j] = 1
                        changed = True
                all_off = all((m & (1 << j)) == 0 for m in possible)
                if all_off:
                    if grid[i][j] == 1:
                        return False
                    if grid[i][j] == 0:
                        grid[i][j] = -1
                        changed = True
        for j in range(n):
            possible = get_possible_masks_for_col(j, grid, row_weights, col_sums[j], n)
            if not possible:
                return False
            for i in range(n):
                all_on = all((m & (1 << i)) != 0 for m in possible)
                if all_on:
                    if grid[i][j] == -1:
                        return False
                    if grid[i][j] == 0:
                        grid[i][j] = 1
                        changed = True
                all_off = all((m & (1 << i)) == 0 for m in possible)
                if all_off:
                    if grid[i][j] == 1:
                        return False
                    if grid[i][j] == 0:
                        grid[i][j] = -1
                        changed = True
    return True

def verify(grid, row_sums, col_sums, row_weights, col_weights, n):
    for i in range(n):
        s = sum(col_weights[j] for j in range(n) if grid[i][j] == 1)
        if s != row_sums[i]:
            return False
    for j in range(n):
        s = sum(row_weights[i] for i in range(n) if grid[i][j] == 1)
        if s != col_sums[j]:
            return False
    return True

def search(grid, row_sums, col_sums, row_weights, col_weights, n):
    if not deduce(grid, row_sums, col_sums, row_weights, col_weights, n):
        return None
    solved = all(grid[r][c] != 0 for r in range(n) for c in range(n))
    if solved:
        if verify(grid, row_sums, col_sums, row_weights, col_weights, n):
            return grid
        else:
            return None
    min_len = float('inf')
    chosen_row = -1
    for i in range(n):
        poss = get_possible_masks_for_row(i, grid, col_weights, row_sums[i], n)
        l = len(poss)
        if l > 1 and l < min_len:
            min_len = l
            chosen_row = i
    if chosen_row == -1:
        return None
    poss = get_possible_masks_for_row(chosen_row, grid, col_weights, row_sums[chosen_row], n)
    for m in poss:
        new_grid = [row[:] for row in grid]
        for j in range(n):
            on = (m & (1 << j)) != 0
            new_grid[chosen_row][j] = 1 if on else -1
        res = search(new_grid, row_sums, col_sums, row_weights, col_weights, n)
        if res is not None:
            return res
    return None

def solve(observation):
    row_sums = observation['row_sum']
    col_sums = observation['col_sum']
    n = len(row_sums)
    row_weights = [i + 1 for i in range(n)]
    col_weights = [i + 1 for i in range(n)]
    grid = [[0 for _ in range(n)] for _ in range(n)]
    res = search(grid, row_sums, col_sums, row_weights, col_weights, n)
    if res is None:
        return "No Solution"
    answer = [['B' if cell == 1 else None for cell in row] for row in res]
    return answer

if __name__ == "__main__":
    print(solve(OBSERVATION))
