                return "No Solution"
            if len(poss) == 1:
                p = poss[0]
                x, y = p
                placed_tents.add(p)
                remaining_row[x] -= 1
                remaining_col[y] -= 1
                assigned[k] = p
                unassigned.remove(k)
                changed = True

    if not unassigned:
        # Build grid
        grid = [[None for _ in range(cols)] for _ in range(rows)]
        for kk in range(num_trees):
            if assigned[kk]:
                xx, yy = assigned[kk]
                grid[xx][yy] = 't'
        return grid

    # Backtracking function
    def backtrack(unassgd, plcd_tnts, rem_row, rem_col):
        if not unassgd:
            return True

        # Select tree with fewest possibilities
        min_count = float('inf')
        best_k = -1
        for k in unassgd:
            poss = get_possibles(trees[k][0], trees[k][1], plcd_tnts, tree_positions, rows, cols)
            l = len(poss)
            if l == 0:
                return False
            if l < min_count:
                min_count = l
                best_k = k

        # Try possibilities for best_k
        poss = get_possibles(trees[best_k][0], trees[best_k][1], plcd_tnts, tree_positions, rows, cols)
        for p in poss:
            x, y = p
            if rem_row[x] <= 0 or rem_col[y] <= 0:
                continue
            touching = any((x + di, y + dj) in plcd_tnts for di in [-1, 0, 1] for dj in [-1, 0, 1] if di != 0 or dj != 0)
            if touching:
                continue
            # Place
            plcd_tnts.add(p)
            rem_row[x] -= 1
            rem_col[y] -= 1
            new_unassgd = unassgd - {best_k}
            # Prune: check remaining trees have at least one possible
            can_continue = True
            for k2 in new_unassgd:
                if len(get_possibles(trees[k2][0], trees[k2][1], plcd_tnts, tree_positions, rows, cols)) == 0:
                    can_continue = False
                    break
            if can_continue:
                # Prune on row counts
                for rr in range(rows):
                    if rem_row[rr] <= 0:
                        continue
                    avail = set()
                    for k2 in new_unassgd:
                        for pp in get_possibles(trees[k2][0], trees[k2][1], plcd_tnts, tree_positions, rows, cols):
                            if pp[0] == rr:
                                avail.add(pp)
                    if len(avail) < rem_row[rr]:
                        can_continue = False
                        break
                if can_continue:
                    # Prune on col counts
                    for cc in range(cols):
                        if rem_col[cc] <= 0:
                            continue
                        avail = set()
                        for k2 in new_unassgd:
                            for pp in get_possibles(trees[k2][0], trees[k2][1], plcd_tnts, tree_positions, rows, cols):
                                if pp[1] == cc:
                                    avail.add(pp)
                        if len(avail) < rem_col[cc]:
                            can_continue = False
                            break
            if can_continue:
                if backtrack(new_unassgd, plcd_tnts, rem_row, rem_col):
                    assigned[best_k] = p
                    return True
            # Backtrack
            plcd_tnts.remove(p)
            rem_row[x] += 1
            rem_col[y] += 1
        return False

    if backtrack(unassigned, placed_tents, remaining_row, remaining_col):
        # Build grid
        grid = [[None for _ in range(cols)] for _ in range(rows)]
        for kk in range(num_trees):
            if assigned[kk]:
                xx, yy = assigned[kk]
                grid[xx][yy] = 't'
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
