from collections import defaultdict
import copy
from itertools import product

def get_dirs(pos, N):
    r, c = pos
    res = {}
    for d, (dr, dc) in enumerate([(-1, 0), (0, 1), (1, 0), (0, -1)]):
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            res[d] = (nr, nc)
    return res

def trace_path(start, connected):
    path = [start]
    prev = start
    curr = next(iter(connected[start]))
    while curr != start:
        path.append(curr)
        next_curr = [n for n in connected[curr] if n != prev][0]
        prev = curr
        curr = next_curr
    path.append(start)
    return path

def solve(observation):
    data = observation['data']
    N = len(data)
    all_pos = list(product(range(N), range(N)))
    clues = [(i, j) for i, j in all_pos if data[i][j] is not None]
    connected = defaultdict(set)
    forbidden = defaultdict(set)
    forced_edges = set()
    possible_configs = {}
    for cl in clues:
        type_ = data[cl[0]][cl[1]]
        dirs_dict = get_dirs(cl, N)
        configs = []
        if type_ == 'W':
            opp = {0: 2, 1: 3, 2: 0, 3: 1}
            for d1 in list(dirs_dict):
                if opp[d1] in dirs_dict:
                    conf = frozenset([dirs_dict[d1], dirs_dict[opp[d1]]])
                    configs.append(conf)
        else:
            for d1 in list(dirs_dict):
                for d2 in list(dirs_dict):
                    if d1 < d2:
                        diff = (d2 - d1) % 4
                        if diff == 1 or diff == 3:
                            conf = frozenset([dirs_dict[d1], dirs_dict[d2]])
                            valid = True
                            for neigh in conf:
                                for dd, nn in dirs_dict.items():
                                    if nn == neigh:
                                        d = dd
                                        break
                                ext_dir = d
                                neigh_dirs = get_dirs(neigh, N)
                                if ext_dir not in neigh_dirs:
                                    valid = False
                                    break
                            if valid:
                                configs.append(conf)
        possible_configs[cl] = configs

    def propagate():
        queue = set(clues)
        while queue:
            p = queue.pop()
            is_clue = data[p[0]][p[1]] is not None
            type_ = data[p[0]][p[1]] if is_clue else None
            curr_deg = len(connected[p])
            neigh_dict = get_dirs(p, N)
            possible_add = [n for n in neigh_dict.values() if n not in connected[p] and n not in forbidden[p]]
            num_possible = len(possible_add)
            min_deg = 2 if is_clue else (2 if curr_deg > 0 else 0)
            max_deg = 2
            if curr_deg > max_deg:
                raise ValueError("contradiction")
            if curr_deg + num_possible < min_deg:
                raise ValueError("contradiction")
            if curr_deg == max_deg:
                for n in neigh_dict.values():
                    if n not in connected[p] and n not in forbidden[p]:
                        forbidden[p].add(n)
                        forbidden[n].add(p)
                        queue.add(n)
            if curr_deg == 1 and min_deg == 2:
                if num_possible == 0:
                    raise ValueError("contradiction")
                if num_possible == 1:
                    n = possible_add[0]
                    connected[p].add(n)
                    connected[n].add(p)
                    forced_edges.add(frozenset([p, n]))
                    queue.add(p)
                    queue.add(n)
            if is_clue:
                current_connected = frozenset(connected[p])
                new_configs = []
                for conf in possible_configs[p]:
                    if current_connected <= conf and conf.isdisjoint(forbidden[p]) and len(conf - current_connected) <= 2 - curr_deg:
                        new_configs.append(conf)
                if not new_configs:
                    raise ValueError("contradiction")
                possible_configs[p] = new_configs
                if len(new_configs) == 1 and curr_deg < 2:
                    conf = new_configs[0]
                    to_add = conf - current_connected
                    for n in to_add:
                        connected[p].add(n)
                        connected[n].add(p)
                        forced_edges.add(frozenset([p, n]))
                        queue.add(n)
                    if to_add:
                        queue.add(p)
                if type_ == 'B' and len(new_configs) == 1 and len(connected[p]) == 2:
                    conf = new_configs[0]
                    for neigh in conf:
                        dirs_dict = get_dirs(p, N)
                        d = [dd for dd, nn in dirs_dict.items() if nn == neigh][0]
                        ext_dir = d
                        neigh_dirs_dict = get_dirs(neigh, N)
                        if ext_dir not in neigh_dirs_dict:
                            raise ValueError("contradiction")
                        ext_pos = neigh_dirs_dict[ext_dir]
                        if ext_pos not in connected[neigh]:
                            connected[neigh].add(ext_pos)
                            connected[ext_pos].add(neigh)
                            forced_edges.add(frozenset([neigh, ext_pos]))
                            queue.add(neigh)
                            queue.add(ext_pos)
                if type_ == 'W' and curr_deg == 2:
                    adj_list = list(connected[p])
                    straight_count = 0
                    both_determined = True
                    for adj in adj_list:
                        adj_deg = len(connected[adj])
                        if adj_deg != 2:
                            both_determined = False
                            break
                        adj_neighs = list(connected[adj])
                        dirs_dict = get_dirs(adj, N)
                        d1 = [dd for dd, nn in dirs_dict.items() if nn == adj_neighs[0]][0]
                        d2 = [dd for dd, nn in dirs_dict.items() if nn == adj_neighs[1]][0]
                        if (d1 + 2) % 4 == d2:
                            straight_count += 1
                    if both_determined and straight_count == 2:
                        raise ValueError("contradiction")
            if curr_deg == 2:
                for n in neigh_dict.values():
                    if data[n[0]][n[1]] == 'W':
                        queue.add(n)

    def search():
        try:
            propagate()
        except ValueError:
            return None
        visited = {pos for pos in all_pos if len(connected[pos]) == 2}
        if all(len(connected[cl]) == 2 for cl in clues) and visited:
            start = next(iter(visited))
            path = trace_path(start, connected)
            if len(path) - 1 == len(visited):
                return path
        candidates = []
        for pos in all_pos:
            curr_deg = len(connected[pos])
            possible_add = [n for n in get_dirs(pos, N).values() if n not in connected[pos] and n not in forbidden[pos]]
            if curr_deg == 1 and len(possible_add) > 1:
                candidates.append((len(possible_add), pos, possible_add))
        for cl in clues:
            if len(connected[cl]) == 0 and len(possible_configs[cl]) > 1:
                candidates.append((len(possible_configs[cl]), cl, possible_configs[cl]))
        if not candidates:
            return None
        candidates.sort()
        _, branch_point, options = candidates[0]
        for opt in options:
            conn_copy = copy.deepcopy(connected)
            forb_copy = copy.deepcopy(forbidden)
            force_copy = copy.deepcopy(forced_edges)
            p_configs_copy = copy.deepcopy(possible_configs)
            if isinstance(opt, tuple):
                n = opt
                forced_edges.add(frozenset([branch_point, n]))
                connected[branch_point].add(n)
                connected[n].add(branch_point)
            else:
                for n in opt:
                    forced_edges.add(frozenset([branch_point, n]))
                    connected[branch_point].add(n)
                    connected[n].add(branch_point)
                possible_configs[branch_point] = [opt]
            res = search()
            if res is not None:
                return res
            connected = conn_copy
            forbidden = forb_copy
            forced_edges = force_copy
            possible_configs = p_configs_copy
        return None

    res = search()
    if res is None:
        return "No Solution"
    return res

if __name__ == "__main__":
    print(solve(OBSERVATION))
