            if len(poss[i][j]) == 1 and grid[i][j] is None:
                grid[i][j] = next(iter(poss[i][j]))
                changed = True
        return changed, True

    def update_col(j):
        unknowns = [i for i in range(n) if grid[i][j] is None]
        k = len(unknowns)
        possible_values = [set() for _ in range(n)]
        has_any = False
