                    break
            if i_sel != -1:
                break
        if i_sel == -1:
            return None
        save_grid = [row[:] for row in grid]
        save_poss = [[s.copy() for s in row] for row in poss]
        for val in ['B', 'W']:
            if val not in save_poss[i_sel][j_sel]:
                continue
            grid[i_sel][j_sel] = val
            poss[i_sel][j_sel] = {val}
            res = search()
            if res is not None:
                return res
            grid = [row[:] for row in save_grid]
            poss = [[s.copy() for s in row] for row in save_poss]
        return None

    res = search()
    if res is None:
        return "No Solution"
    return res

