from collections import defaultdict
from itertools import product

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if data else 0
    h_edges = [[None for _ in range(m)] for _ in range(n + 1)]
    v_edges = [[None for _ in range(m + 1)] for _ in range(n)]

    def get_edge(typ, i, j):
        if typ == 'h':
            return h_edges[i][j]
        else:
            return v_edges[i][j]

    def set_edge(typ, i, j, val):
        if typ == 'h':
            if h_edges[i][j] is not None:
                return h_edges[i][j] == val
            h_edges[i][j] = val
            return True
        else:
            if v_edges[i][j] is not None:
                return v_edges[i][j] == val
            v_edges[i][j] = val
            return True

    def propagate():
        changed = True
        while changed:
            changed = False
            # process cells
            for r in range(n):
                for c in range(m):
                    if data[r][c] is None: continue
                    required = data[r][c]
                    edges = [
                        ('h', r, c),    # top
                        ('v', r, c),    # left
                        ('h', r + 1, c),  # bottom
                        ('v', r, c + 1)   # right
                    ]
                    states = [get_edge(*ed) for ed in edges]
                    ins = sum(1 for s in states if s == True)
                    outs = sum(1 for s in states if s == False)
                    unks = 4 - ins - outs
                    # check possible
                    if ins > required or ins + unks < required:
                        return False
                    # simple force all
                    need = required - ins
                    if need == unks and unks > 0:
                        for ed in edges:
                            if get_edge(*ed) is None:
                                if not set_edge(*ed, True):
                                    return False
                                changed = True
                    elif need == 0 and unks > 0:
                        for ed in edges:
                            if get_edge(*ed) is None:
                                if not set_edge(*ed, False):
                                    return False
                                changed = True
                    # individual force
                    for k in range(4):
                        if states[k] is not None: continue
                        ed = edges[k]
                        # can True?
                        can_true = (ins + 1 <= required <= ins + unks)
                        # can False?
                        can_false = (ins <= required <= ins + unks - 1)
                        if not can_true:
                            if not set_edge(*ed, False):
                                return False
                            changed = True
                        if not can_false:
                            if not set_edge(*ed, True):
                                return False
                            changed = True
            # process vertices
            for i in range(n + 1):
                for j in range(m + 1):
                    inc = []
                    if i > 0: inc.append(('v', i - 1, j))  # up
                    if j > 0: inc.append(('h', i, j - 1))  # left
                    if i < n: inc.append(('v', i, j))  # down
                    if j < m: inc.append(('h', i, j))  # right
                    states = [get_edge(*ed) for ed in inc]
                    ins = sum(1 for s in states if s == True)
                    unks = sum(1 for s in states if s is None)
                    # check possible
                    possible = False
                    for target in [0, 2]:
                        if ins <= target <= ins + unks:
                            possible = True
                            break
                    if not possible:
                        return False
                    # individual
                    for k in range(len(inc)):
                        if states[k] is not None: continue
                        ed = inc[k]
                        # can True?
                        can_true = False
                        for target in [0, 2]:
                            temp = target - ins - 1
                            if temp >= 0 and temp <= unks - 1:
                                can_true = True
                                break
                        # can False?
                        can_false = False
                        for target in [0, 2]:
                            temp = target - ins
                            if temp >= 0 and temp <= unks - 1:
                                can_false = True
                                break
                        if not can_true:
                            if not set_edge(*ed, False):
                                return False
                            changed = True
                        if not can_false:
                            if not set_edge(*ed, True):
                                return False
                            changed = True
        return True

    def get_loop():
        neighbors = defaultdict(list)
        for i in range(n + 1):
            for j in range(m):
                if get_edge('h', i, j) == True:
                    neighbors[(i, j)].append((i, j + 1))
                    neighbors[(i, j + 1)].append((i, j))
        for i in range(n):
            for j in range(m + 1):
                if get_edge('v', i, j) == True:
                    neighbors[(i, j)].append((i + 1, j))
                    neighbors[(i + 1, j)].append((i, j))
        # check degrees
        for i in range(n + 1):
            for j in range(m + 1):
                deg = len(neighbors[(i, j)])
                if deg not in (0, 2): return None
        # find used
        used = [(i, j) for i in range(n + 1) for j in range(m + 1) if len(neighbors[(i, j)]) == 2]
        if not used: return None
        # check components
        visited = set()
        components = 0
        path = None
        for start in sorted(used):
            if start in visited: continue
            components += 1
            if components > 1: return None
            # traverse
            path = []
            current = start
            prev = None
            while True:
                path.append(current)
                nexts = [nb for nb in neighbors[current] if nb != prev]
                if len(nexts) != 1:
                    return None
                prev = current
                current = nexts[0]
                if current == start:
                    path.append(start)
                    break
            visited.update(path[:-1])
        return path

    def backtrack():
        if not propagate():
            return None
        # check if all decided
        has_unk = False
        for row in h_edges:
            for e in row:
                if e is None:
                    has_unk = True
                    break
            if has_unk: break
        if not has_unk:
            for row in v_edges:
                for e in row:
                    if e is None:
                        has_unk = True
                        break
                if has_unk: break
        if not has_unk:
            return get_loop()
        # find and branch on first unknown
        for typ in ['h', 'v']:
            if typ == 'h':
                grid = h_edges
                rn = n + 1
                cn = m
            else:
                grid = v_edges
                rn = n
                cn = m + 1
            for i in range(rn):
                for j in range(cn):
                    if grid[i][j] is None:
                        for val in [True, False]:
                            if set_edge(typ, i, j, val):
                                sol = backtrack()
                                if sol is not None:
                                    return sol
                            grid[i][j] = None
                        return None
        return None

    sol = backtrack()
    if sol is None:
        return "No Solution"
    return str(sol)

if __name__ == "__main__":
    print(solve(OBSERVATION))
