# Helper function to generate all rotations and reflections of a base shape
def get_all_shapes(base_offsets, num_rot=4, reflect=False):
    shapes = []
    existing = set()
    for rot in range(num_rot):
        new_offsets = []
        for dr, dc in base_offsets:
            if rot == 0:
                new = (dr, dc)
            elif rot == 1:
                new = (dc, -dr)
            elif rot == 2:
                new = (-dr, -dc)
            elif rot == 3:
                new = (-dc, dr)
            new_offsets.append(new)
        min_r = min(d[0] for d in new_offsets)
        min_c = min(d[1] for d in new_offsets)
        normalized = tuple(sorted((d[0] - min_r, d[1] - min_c) for d in new_offsets))
        if normalized not in existing:
            existing.add(normalized)
            shapes.append(list(normalized))
    if reflect:
        reflected = [(dr, -dc) for dr, dc in base_offsets]
        for rot in range(num_rot):
            new_offsets = []
            for dr, dc in reflected:
                if rot == 0:
                    new = (dr, dc)
                elif rot == 1:
                    new = (dc, -dr)
                elif rot == 2:
                    new = (-dr, -dc)
                elif rot == 3:
                    new = (-dc, dr)
                new_offsets.append(new)
            min_r = min(d[0] for d in new_offsets)
            min_c = min(d[1] for d in new_offsets)
            normalized = tuple(sorted((d[0] - min_r, d[1] - min_c) for d in new_offsets))
            if normalized not in existing:
                existing.add(normalized)
                shapes.append(list(normalized))
    return shapes

def solve(observation):
    data = observation['data']
    N = len(data)
    regions = sorted(set(id for row in data for id in row))
    adj = {rid: set() for rid in regions}
    for r in range(N):
        for c in range(N):
            id1 = data[r][c]
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if nr < N and nc < N:
                    id2 = data[nr][nc]
                    if id1 != id2:
                        adj[id1].add(id2)
                        adj[id2].add(id1)

    # Define shapes
    shape_defs = {}
    shape_defs['I'] = get_all_shapes([(0, 0), (0, 1), (0, 2), (0, 3)], num_rot=2, reflect=False)
    shape_defs['L'] = get_all_shapes([(0, 0), (1, 0), (2, 0), (2, 1)], num_rot=4, reflect=True)
    shape_defs['T'] = get_all_shapes([(0, 0), (0, 1), (0, 2), (1, 1)], num_rot=4, reflect=False)
    shape_defs['S'] = get_all_shapes([(0, 1), (0, 2), (1, 0), (1, 1)], num_rot=2, reflect=True)

    # Generate all possible placements
    placements = {rid: set() for rid in regions}  # use set to avoid duplicates
    for typ, shape_list in shape_defs.items():
        for offsets in shape_list:
            max_dr = max(dr for dr, dc in offsets)
            max_dc = max(dc for dr, dc in offsets)
            for br in range(N - max_dr + 1):
                for bc in range(N - max_dc + 1):
                    cells = [(br + dr, bc + dc) for dr, dc in offsets]
                    ids = set(data[r][c] for r, c in cells)
                    if len(ids) == 1:
                        rid = list(ids)[0]
                        fs = frozenset(cells)
                        placements[rid].add((typ, fs))

    # Convert to lists
    for rid in regions:
        placements[rid] = list(placements[rid])

    # Precompute 2x2
    two_by_two = []
    for r in range(N - 1):
        for c in range(N - 1):
            cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            two_by_two.append(cells)

    # Initial states
    states = [[0] * N for _ in range(N)]

    # Initial propagation
    possible_placements = {rid: placements[rid][:] for rid in regions}
    if not propagate(possible_placements, states, adj, regions, data, N, two_by_two):
        return "No Solution"

    # Now search if necessary
    result = search(possible_placements, states, adj, regions, data, N, two_by_two)
    if result is None:
        return "No Solution"
    return result

def propagate(possible, states, adj, regions, data, N, two_by_two):
    while True:
        changed = False
        for rid in regions:
            if not possible[rid]:
                return False
            region_cells = [(i, j) for i in range(N) for j in range(N) if data[i][j] == rid]
            all_shaded = set.intersection(*(sh for _, sh in possible[rid])) if possible[rid] else set()
            for r, c in all_shaded:
                if states[r][c] == 0:
                    states[r][c] = 1
                    changed = True
                elif states[r][c] == -1:
                    return False
            some_shaded = set.union(*(sh for _, sh in possible[rid])) if possible[rid] else set()
            for r, c in set(region_cells) - some_shaded:
                if states[r][c] == 0:
                    states[r][c] = -1
                    changed = True
                elif states[r][c] == 1:
                    return False
        for cells in two_by_two:
            s = [states[rr][cc] for rr, cc in cells]
            num_shaded = sum(1 for x in s if x == 1)
            num_unknown = sum(1 for x in s if x == 0)
            if num_shaded == 4:
                return False
            if num_shaded == 3 and num_unknown == 1:
                for k in range(4):
                    rr, cc = cells[k]
                    if states[rr][cc] == 0:
                        states[rr][cc] = -1
                        changed = True
                        break
        for rid in regions:
            region_cells = set((i, j) for i in range(N) for j in range(N) if data[i][j] == rid)
            new_list = []
            for typ, sh in possible[rid]:
                if all(states[r][c] != -1 for r, c in sh) and all((r, c) not in sh for r, c in region_cells if states[r][c] == 1) == False:
                    new_list.append((typ, sh))
            if len(new_list) != len(possible[rid]):
                changed = True
            possible[rid] = new_list
        poss_types = {rid: set(typ for typ, _ in possible[rid]) for rid in regions}
        for rid in regions:
            if len(poss_types[rid]) == 1:
                t = list(poss_types[rid])[0]
                for neigh in adj[rid]:
                    if t in poss_types[neigh]:
                        poss_types[neigh].remove(t)
                        changed = True
        for rid in regions:
            new_list = [(typ, sh) for typ, sh in possible[rid] if typ in poss_types[rid]]
            if len(new_list) != len(possible[rid]):
                changed = True
            possible[rid] = new_list
        if not changed:
            break
    return True

def is_connected(shaded, N):
    if not shaded:
        return True
    shaded = set(shaded)
    start = next(iter(shaded))
    visited = set()
    stack = [start]
    while stack:
        cell = stack.pop()
        if cell in visited:
            continue
        visited.add(cell)
        r, c = cell
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and (nr, nc) in shaded:
                stack.append((nr, nc))
    return len(visited) == len(shaded)

def search(possible, states, adj, regions, data, N, two_by_two):
    if all(len(possible[rid]) == 1 for rid in regions):
        shaded = set()
        type_dict = {}
        for rid in regions:
            typ, sh = possible[rid][0]
            type_dict[rid] = typ
            shaded.update(sh)
        for rid in regions:
            for neigh in adj[rid]:
                if type_dict[rid] == type_dict[neigh]:
                    return None
        if is_connected(shaded, N):
            answer = [[None] * N for _ in range(N)]
            for rid in regions:
                typ, sh = possible[rid][0]
                for r, c in sh:
                    answer[r][c] = typ
            return answer
        return None
    candidates = [rid for rid in regions if len(possible[rid]) > 1]
    if not candidates:
        return None
    candidates.sort(key=lambda rid: len(possible[rid]))
    chosen_rid = candidates[0]
    for typ, sh in possible[chosen_rid]:
        new_possible = {r: possible[r][:] for r in regions}
        new_states = [row[:] for row in states]
        new_possible[chosen_rid] = [(typ, sh)]
        if propagate(new_possible, new_states, adj, regions, data, N, two_by_two):
            ans = search(new_possible, new_states, adj, regions, data, N, two_by_two)
            if ans is not None:
                return ans
    return None

