    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Collect region cells and clues
    all_rids = set()
    for i in range(N):
        for j in range(N):
            all_rids.add(region[i][j])
    region_cells = {rid: [] for rid in all_rids}
    for i in range(N):
        for j in range(N):
            region_cells[region[i][j]].append((i, j))
    clues = {}
    for rid in all_rids:
        clue = None
        for i, j in region_cells[rid]:
            if data[i][j] is not None:
                if clue is not None:
                    return "No Solution"
                clue = data[i][j]
        clues[rid] = clue

    # Check for immediate impossibilities
    for rid in all_rids:
        if clues[rid] is not None and clues[rid] > len(region_cells[rid]):
            return "No Solution"

    # Grid: 'B', 'W', or None
    grid = [[None for _ in range(N)] for _ in range(N)]

    # Pre-set forced cells
    for rid in all_rids:
        size = len(region_cells[rid])
        clue = clues[rid]
        if clue is not None:
            if clue == 0:
                for cell in region_cells[rid]:
                    grid[cell[0]][cell[1]] = 'W'
            elif clue == size:
                # Check if no two adjacent in region
                adjacent_in_region = False
                for idx1 in range(size):
                    for idx2 in range(idx1 + 1, size):
                        ci1, cj1 = region_cells[rid][idx1]
                        ci2, cj2 = region_cells[rid][idx2]
                        if abs(ci1 - ci2) + abs(cj1 - cj2) == 1:
                            adjacent_in_region = True
                            break
                    if adjacent_in_region:
                        break
                if adjacent_in_region:
                    return "No Solution"
                else:
                    for cell in region_cells[rid]:
                        grid[cell[0]][cell[1]] = 'B'

    # Initialize counts
    current_b = {rid: 0 for rid in all_rids}
    undecided = {rid: len(region_cells[rid]) for rid in all_rids}
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                rid = region[i][j]
                undecided[rid] -= 1
                if grid[i][j] == 'B':
                    current_b[rid] += 1

    # Cells list
    cells = [(i, j) for i in range(N) for j in range(N)]

    def is_adjacent(c1, c2):
        return abs(c1[0] - c2[0]) + abs(c1[1] - c2[1]) == 1

    def check_decided_segments():
        # Check rows
        for i in range(N):
            j = 0
            while j < N:
                if grid[i][j] != 'W':
                    j += 1
                    continue
                start = j
                while j < N and grid[i][j] == 'W':
                    j += 1
                # Check if this is a complete segment
                left_bounded = (start == 0 or grid[i][start - 1] == 'B')
                right_bounded = (j == N or grid[i][j] == 'B')
                if left_bounded and right_bounded:
                    reg_set = set(region[i][k] for k in range(start, j))
                    if len(reg_set) > 2:
                        return False
        # Check columns
        for j in range(N):
            i = 0
            while i < N:
                if grid[i][j] != 'W':
                    i += 1
                    continue
                start = i
                while i < N and grid[i][j] == 'W':
                    i += 1
                left_bounded = (start == 0 or grid[start - 1][j] == 'B')
                right_bounded = (i == N or grid[i][j] == 'B')
                if left_bounded and right_bounded:
                    reg_set = set(region[k][j] for k in range(start, i))
                    if len(reg_set) > 2:
                        return False
        return True

    def check_white_connected():
        whites = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 'W']
        if not whites:
            return True
        visited = set()
        from collections import deque
        q = deque([whites[0]])
        visited.add(whites[0])
        while q:
            ci, cj = q.popleft()
            for di, dj in directions:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < N and 0 <= nj < N and grid[ni][nj] == 'W' and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    q.append((ni, nj))
        return len(visited) == len(whites)

    def is_possible(pos):
        i, j = cells[pos]
        color = grid[i][j]
        # Check no adjacent 'B'
        if color == 'B':
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N and grid[ni][nj] == 'B':
                    return False
        # Check region counts
        rid = region[i][j]
        clue = clues[rid]
        if clue is not None:
            if current_b[rid] > clue:
                return False
            if undecided[rid] == 0 and current_b[rid] != clue:
                return False
        # Check all regions for min possible
        for r in all_rids:
            c = clues[r]
            if c is not None and current_b[r] + undecided[r] < c:
                return False
        # Check decided segments
        if not check_decided_segments():
            return False
        return True

    def backtrack(pos):
        if pos == len(cells):
            if check_white_connected() and check_decided_segments():
                return [[grid[r][c] if grid[r][c] == 'B' else None for c in range(N)] for r in range(N)]
            return None
        i, j = cells[pos]
        if grid[i][j] is not None:
            if is_possible(pos):
                res = backtrack(pos + 1)
                if res is not None:
                    return res
            return None
        # Try 'W'
        grid[i][j] = 'W'
        undecided[region[i][j]] -= 1
        if is_possible(pos):
            res = backtrack(pos + 1)
            if res is not None:
                return res
        undecided[region[i][j]] += 1
        grid[i][j] = None
        # Try 'B'
        grid[i][j] = 'B'
        undecided[region[i][j]] -= 1
        current_b[region[i][j]] += 1
        if is_possible(pos):
            res = backtrack(pos + 1)
            if res is not None:
                return res
        undecided[region[i][j]] += 1
        current_b[region[i][j]] -= 1
        grid[i][j] = None
        return None

    return backtrack(0) or "No Solution"

