import sys
sys.setrecursionlimit(10000)

def solve(observation):
    grid = observation['data']
    N = len(grid)
    # Find unique regions
    regions = set()
    for r in range(N):
        for c in range(N):
            regions.add(grid[r][c])
    num_regions = len(regions)
    region_list = sorted(regions)
    region_index = {rid: idx for idx, rid in enumerate(region_list)}
    # Region cells
    from collections import defaultdict
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[grid[r][c]].append((r, c))
    # States
    shaded = [[False] * N for _ in range(N)]
    forbidden_count = [[0] * N for _ in range(N)]
    region_count = [0] * num_regions
    # Directions
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    # Function to place domino, returns success and list of marked for backtrack
    def place_domino(cell1, cell2, is_forced=False):
        r1, c1 = cell1
        r2, c2 = cell2
        if shaded[r1][c1] or forbidden_count[r1][c1] > 0:
            return False, None
        if shaded[r2][c2] or forbidden_count[r2][c2] > 0:
            return False, None
        reg1 = region_index[grid[r1][c1]]
        reg2 = region_index[grid[r2][c2]]
        if region_count[reg1] + 1 > 2 or region_count[reg2] + 1 > 2:
            return False, None
        # Place
        shaded[r1][c1] = True
        shaded[r2][c2] = True
        region_count[reg1] += 1
        region_count[reg2] += 1
        # Mark forbidden
        marked = []
        for pr, pc in [cell1, cell2]:
            for dr, dc in directions:
                nr, nc = pr + dr, pc + dc
                if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in [cell1, cell2]:
                    forbidden_count[nr][nc] += 1
                    marked.append((nr, nc))
        return True, marked
    # Function to unplace
    def unplace_domino(cell1, cell2, marked):
        r1, c1 = cell1
        r2, c2 = cell2
        shaded[r1][c1] = False
        shaded[r2][c2] = False
        reg1 = region_index[grid[r1][c1]]
        reg2 = region_index[grid[r2][c2]]
        region_count[reg1] -= 1
        region_count[reg2] -= 1
        for nr, nc in marked:
            forbidden_count[nr][nc] -= 1
    # Find forced dominoes
    forced = []
    for rid in region_list:
        cells = region_cells[rid]
        if len(cells) == 2:
            cell1, cell2 = sorted(cells)
            r1, c1 = cell1
            r2, c2 = cell2
            if abs(r1 - r2) + abs(c1 - c2) == 1:
                forced.append((cell1, cell2))
    # Place forced
    for cell1, cell2 in forced:
        success, _ = place_domino(cell1, cell2, True)  # no marked needed, no backtrack
        if not success:
            return "No Solution"
    # Search function
    def search():
        # Check if all ==2
        if all(c == 2 for c in region_count):
            return True
        # Find region with count <2, smallest avail cells
        min_size = float('inf')
        chosen_idx = -1
        for idx in range(num_regions):
            if region_count[idx] == 2:
                continue
            avail = sum(1 for r, c in region_cells[region_list[idx]] if not shaded[r][c] and forbidden_count[r][c] == 0)
            if avail == 0:
                return False
            if avail < min_size:
                min_size = avail
                chosen_idx = idx
        if chosen_idx == -1:
            return all(c == 2 for c in region_count)
        # Avail cells
        rid = region_list[chosen_idx]
        avail_cells = [(r, c) for r, c in region_cells[rid] if not shaded[r][c] and forbidden_count[r][c] == 0]
        # Pick cell with min partners
        min_partners = float('inf')
        chosen_cell = None
        for cell in avail_cells:
            partners = sum(1 for dr, dc in directions if (nr := cell[0] + dr) in range(N) and (nc := cell[1] + dc) in range(N) and not shaded[nr][nc] and forbidden_count[nr][nc] == 0)
            if partners == 0:
                return False
            if partners < min_partners:
                min_partners = partners
                chosen_cell = cell
        # Try partners
        r, c = chosen_cell
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and not shaded[nr][nc] and forbidden_count[nr][nc] == 0:
                cell1 = (r, c)
                cell2 = (nr, nc)
                # Order them
                if cell1 > cell2:
                    cell1, cell2 = cell2, cell1
                success, marked = place_domino(cell1, cell2)
                if success:
                    if search():
                        return True
                    unplace_domino(cell1, cell2, marked)
        return False
    # Call search
    if search():
        answer = [[None] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if shaded[r][c]:
                    answer[r][c] = 'S'
        return answer
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
