                if row_used[i] & bit or col_used[j] & bit or box_used[b] & bit:
                    return "No Solution"
                row_used[i] |= bit
                col_used[j] |= bit
                box_used[b] |= bit
    def get_box_index(i, j):
        return (i // box_height) * num_box_cols + (j // box_width)
    def perform_deduction():
        nonlocal changed
        changed = False
        # Naked singles and conflict check
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 0:
                    b = get_box_index(i, j)
                    mask = ~(row_used[i] | col_used[j] | box_used[b]) & full
                    count = bin(mask).count('1')
                    if count == 0:
                        return True  # conflict
                    if count == 1:
                        bit_pos = mask.bit_length() - 1
                        num = bit_pos + 1
                        grid[i][j] = num
                        bit = 1 << bit_pos
                        row_used[i] |= bit
                        col_used[j] |= bit
                        box_used[b] |= bit
                        changed = True
