        for i in range(N):
            possible_places = [[] for _ in range(N + 1)]
            for j in range(N):
                if grid[i][j] == 0:
                    b = get_box_index(i, j)
                    mask = ~(row_used[i] | col_used[j] | box_used[b]) & full
                    bit = 1
                    for num in range(1, N + 1):
                        if mask & bit:
                            possible_places[num].append(j)
                        bit <<= 1
            for num in range(1, N + 1):
                pl = possible_places[num]
                if len(pl) == 0 and not (row_used[i] & (1 << (num - 1))):
                    return True  # conflict
                if len(pl) == 1:
                    j = pl[0]
                    b = get_box_index(i, j)
                    bit = 1 << (num - 1)
                    grid[i][j] = num
                    row_used[i] |= bit
                    col_used[j] |= bit
                    box_used[b] |= bit
                    changed = True
        # Hidden singles and missing number check for columns
        for j in range(N):
            possible_places = [[] for _ in range(N + 1)]
            for i in range(N):
                if grid[i][j] == 0:
                    b = get_box_index(i, j)
                    mask = ~(row_used[i] | col_used[j] | box_used[b]) & full
                    bit = 1
                    for num in range(1, N + 1):
                        if mask & bit:
                            possible_places[num].append(i)
                        bit <<= 1
            for num in range(1, N + 1):
                pl = possible_places[num]
                if len(pl) == 0 and not (col_used[j] & (1 << (num - 1))):
                    return True  # conflict
                if len(pl) == 1:
                    i = pl[0]
                    b = get_box_index(i, j)
                    bit = 1 << (num - 1)
                    grid[i][j] = num
                    row_used[i] |= bit
                    col_used[j] |= bit
                    box_used[b] |= bit
                    changed = True
        # Hidden singles and missing number check for boxes
        for bx in range(num_box_rows):
            for by in range(num_box_cols):
                possible_places = [[] for _ in range(N + 1)]
                for di in range(box_height):
                    for dj in range(box_width):
                        i = bx * box_height + di
                        j = by * box_width + dj
                        if grid[i][j] == 0:
                            b = bx * num_box_cols + by
                            mask = ~(row_used[i] | col_used[j] | box_used[b]) & full
                            bit = 1
                            for num in range(1, N + 1):
                                if mask & bit:
                                    possible_places[num].append((i, j))
                                bit <<= 1
                for num in range(1, N + 1):
                    pl = possible_places[num]
                    if len(pl) == 0 and not (box_used[bx * num_box_cols + by] & (1 << (num - 1))):
                        return True  # conflict
                    if len(pl) == 1:
                        i, j = pl[0]
                        b = bx * num_box_cols + by
                        bit = 1 << (num - 1)
                        grid[i][j] = num
                        row_used[i] |= bit
                        col_used[j] |= bit
                        box_used[b] |= bit
                        changed = True
        return False  # no conflict
    changed = True
    while changed:
        if perform_deduction():
            return "No Solution"
    # Check if solved
    solved = all(all(cell != 0 for cell in row) for row in grid)
    if solved:
        return grid
    # Backtracking function
    def backtrack():
        min_count = N + 1
        best_i, best_j = -1, -1
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 0:
                    b = get_box_index(i, j)
                    mask = ~(row_used[i] | col_used[j] | box_used[b]) & full
                    count = bin(mask).count('1')
                    if count == 0:
                        return False
                    if count < min_count:
                        min_count = count
                        best_i, best_j = i, j
        if best_i == -1:
            return True
        b = get_box_index(best_i, best_j)
        mask = ~(row_used[best_i] | col_used[best_j] | box_used[b]) & full
        for bb in range(N):
            bit = 1 << bb
            if mask & bit:
                num = bb + 1
                grid[best_i][best_j] = num
                row_used[best_i] |= bit
                col_used[best_j] |= bit
                box_used[b] |= bit
                if backtrack():
                    return True
                grid[best_i][best_j] = 0
                row_used[best_i] &= ~bit
                col_used[best_j] &= ~bit
                box_used[b] &= ~bit
        return False
    if backtrack():
        return grid
    else:
        return "No Solution"

