import ast
from collections import deque

def solve(observation):
    data = observation['data']
    size = len(data)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    clues = {}
    for r in range(size):
        for c in range(size):
            if data[r][c] is not None:
                color = data[r][c][0]
                k = int(data[r][c][1:])
                clues[(r, c)] = (color, k)
    all_clues = set(clues.keys())

    def is_valid(r, c):
        return 0 <= r < size and 0 <= c < size

    def is_adjacent(p1, p2):
        dr = abs(p1[0] - p2[0])
        dc = abs(p1[1] - p2[1])
        return dr + dc == 1

    def is_compatible(typ, delta1, delta2):
        if typ == 'E':
            return True
        opp = (delta1[0] == -delta2[0] and delta1[1] == -delta2[1])
        if typ == 'W':
            return opp
        if typ == 'B':
            return not opp
        return False

    def compute_straight(idx, cycle, forward, n):
        count = 0
        current = idx
        step = 1 if forward else -1
        prev_dir = None
        while count < n:
            cr, cc = cycle[current]
            next_idx = (current + step) % n
            nr, nc = cycle[next_idx]
            this_dir = (nr - cr, nc - cc)
            if count > 0 and this_dir != prev_dir:
                break
            count += 1
            prev_dir = this_dir
            current = next_idx
        return count

    def verify_numbers(cycle, clues):
        n = len(cycle) - 1
        for i in range(n):
            p = cycle[i]
            if p not in clues:
                continue
            color, k = clues[p]
            arm1 = compute_straight(i, cycle, True, n)
            arm2 = compute_straight(i, cycle, False, n)
            if arm1 + arm2 != k:
                return False
        return True

    def can_reach_remaining(path, visited, remaining_clues):
        if not remaining_clues:
            return True
        reachable = set()
        for end in [path[0], path[-1]]:
            q = deque()
            vis = set(visited)
            for dr, dc in directions:
                nr = end[0] + dr
                nc = end[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in vis:
                    q.append((nr, nc))
                    vis.add((nr, nc))
            while q:
                curr = q.popleft()
                reachable.add(curr)
                for dr, dc in directions:
                    nr = curr[0] + dr
                    nc = curr[1] + dc
                    if is_valid(nr, nc) and (nr, nc) not in vis:
                        vis.add((nr, nc))
                        q.append((nr, nc))
        reached_clues = reachable & remaining_clues
        return len(reached_clues) == len(remaining_clues)

    def recurse(path, visited, covered):
        remaining_clues = all_clues - covered
        if not can_reach_remaining(path, visited, remaining_clues):
            return None
        if len(covered) == len(all_clues) and len(path) >= 3:
            a = path[0]
            b = path[-1]
            if is_adjacent(a, b):
                dir1_a = (path[1][0] - a[0], path[1][1] - a[1])
                dir2_a = (b[0] - a[0], b[1] - a[1])
                type_a = clues.get(a, 'E')
                dir1_b = (path[-2][0] - b[0], path[-2][1] - b[1])
                dir2_b = (a[0] - b[0], a[1] - b[1])
                type_b = clues.get(b, 'E')
                if is_compatible(type_a, dir1_a, dir2_a) and is_compatible(type_b, dir1_b, dir2_b):
                    cycle = path + [path[0]]
                    if verify_numbers(cycle, clues):
                        return cycle
        # Choose end to extend: the one with larger lex
        end1 = path[0]
        end2 = path[-1]
        if end1 > end2:
            to_extend_left = True
            end = end1
            incoming_delta = (path[1][0] - end[0], path[1][1] - end[1])
        else:
            to_extend_left = False
            end = end2
            incoming_delta = (path[-2][0] - end[0], path[-2][1] - end[1])
        for dr, dc in directions:
            if (dr, dc) == incoming_delta:
                continue
            nr = end[0] + dr
            nc = end[1] + dc
            if not is_valid(nr, nc) or (nr, nc) in visited:
                continue
            new_pos = (nr, nc)
            out_delta = (dr, dc)
            type_e = clues.get(end, 'E')
            if not is_compatible(type_e, incoming_delta, out_delta):
                continue
            if to_extend_left:
                new_path = [new_pos] + path
            else:
                new_path = path + [new_pos]
            new_visited = visited | {new_pos}
            new_covered = covered | {new_pos} if new_pos in all_clues else covered
            res = recurse(new_path, new_visited, new_covered)
            if res is not None:
                return res
        return None

    # Choose start with fewest options
    options = []
    for pos in clues:
        color, _ = clues[pos]
        if color == 'B':
            pair_list = [(0, 2), (0, 3), (1, 2), (1, 3)]
        else:
            pair_list = [(0, 1), (2, 3)]
        count = 0
        for pr in pair_list:
            d1 = directions[pr[0]]
            d2 = directions[pr[1]]
            n1 = (pos[0] + d1[0], pos[1] + d1[1])
            n2 = (pos[0] + d2[0], pos[1] + d2[1])
            if is_valid(n1[0], n1[1]) and is_valid(n2[0], n2[1]):
                count += 1
        options.append((count, pos))
    options.sort()
    start_pos = options[0][1]

    color, _ = clues[start_pos]
    if color == 'B':
        pair_list = [(0, 2), (0, 3), (1, 2), (1, 3)]
    else:
        pair_list = [(0, 1), (2, 3)]
    for pr in pair_list:
        d1 = directions[pr[0]]
        d2 = directions[pr[1]]
        n1 = (start_pos[0] + d1[0], start_pos[1] + d1[1])
        n2 = (start_pos[0] + d2[0], start_pos[1] + d2[1])
        if not is_valid(n1[0], n1[1]) or not is_valid(n2[0], n2[1]):
            continue
        n_list = [n1, n2]
        n_list.sort()
        path = [n_list[0], start_pos, n_list[1]]
        visited = set(path)
        covered = set(p for p in path if p in all_clues)
        res = recurse(path, visited, covered)
        if res is not None:
            return res[:-1] + [res[0]]  # ensure closed
    return "No Solution"

