    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def get_neighbors(r, c):
        ns = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                ns.append((nr, nc))
        return ns

    clues = []
    all_clues_set = set()
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                typ = data[r][c][0]
                num = int(data[r][c][1:])
                pos = (r, c)
                clues.append((pos, typ, num))
                all_clues_set.add(pos)

    if not clues:
        return str([(0, 0), (0, 0)])

    start = min(all_clues_set, key=lambda p: (p[0], p[1]))

    def is_adjacent(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

    def bfs_reachable(start_pos, visited):
        q = collections.deque([start_pos])
        reach = set([start_pos])
        while q:
            r, c = q.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited and (nr, nc) not in reach:
                    reach.add((nr, nc))
                    q.append((nr, nc))
        return reach

    def check_cycle(cycle):
        n = len(cycle) - 1
        for cl_pos, typ, num in clues:
            i = -1
            for j in range(n):
                if cycle[j] == cl_pos:
                    i = j
                    break
            if i == -1:
                return False
            prev_i = (i - 1) % n
            next_i = (i + 1) % n
            delta_prev = (cycle[prev_i][0] - cycle[i][0], cycle[prev_i][1] - cycle[i][1])
            delta_next = (cycle[next_i][0] - cycle[i][0], cycle[next_i][1] - cycle[i][1])
            is_opposite = delta_prev == (-delta_next[0], -delta_next[1])
            if typ == 'W' and not is_opposite:
                return False
            if typ == 'B' and is_opposite:
                return False
            # l_next
            cur_delta = delta_next
            l_next = 1
            j = next_i
            count = 0
            while count < n:
                next_j = (j + 1) % n
                next_delta = (cycle[next_j][0] - cycle[j][0], cycle[next_j][1] - cycle[j][1])
                if next_delta != cur_delta:
                    break
                l_next += 1
                j = next_j
                count += 1
            # l_prev
            cur_delta = delta_prev
            l_prev = 1
            j = prev_i
            count = 0
            while count < n:
                next_j = (j - 1 + n) % n
                next_delta = (cycle[next_j][0] - cycle[j][0], cycle[next_j][1] - cycle[j][1])
                if next_delta != cur_delta:
                    break
                l_prev += 1
                j = next_j
                count += 1
            if l_prev + l_next != num:
                return False
        return True

    def backtrack(path, visited, clue_set):
        current = path[-1]
        if len(path) >= 3 and is_adjacent(current, start) and len(clue_set) == len(all_clues_set):
            cycle = path + [start]
            if check_cycle(cycle):
                return cycle
        # pruning for remaining clues
        remaining_clues = all_clues_set - clue_set
        reachable = bfs_reachable(current, visited)
        if remaining_clues:
            for cl in remaining_clues:
                if cl not in reachable:
                    return None
        else:
            # when all clues visited, check if can reach a closer
            neighbors_of_start = set(get_neighbors(*start))
            possible_closers = {pos for pos in reachable if is_adjacent(pos, start)}
            if not possible_closers:
                return None
        # early check for middle clues
        for cl_pos, typ, _ in clues:
            if cl_pos in visited:
                try:
                    i = path.index(cl_pos)
                    if i == 0 or i == len(path) - 1:
                        continue
                    delta_prev = (path[i - 1][0] - path[i][0], path[i - 1][1] - path[i][1])
                    delta_next = (path[i + 1][0] - path[i][0], path[i + 1][1] - path[i][1])
                    is_opposite = delta_prev == (-delta_next[0], -delta_next[1])
                    if typ == 'W' and not is_opposite:
                        return None
                    if typ == 'B' and is_opposite:
                        return None
                except ValueError:
                    pass
        # extend
        for nr, nc in get_neighbors(*current):
            if (nr, nc) not in visited:
                new_pos = (nr, nc)
                path.append(new_pos)
                visited.add(new_pos)
                new_clue_set = clue_set.copy()
                if new_pos in all_clues_set:
                    new_clue_set.add(new_pos)
                res = backtrack(path, visited, new_clue_set)
                if res is not None:
                    return res
                path.pop()
                visited.remove(new_pos)
        return None

    path = [start]
    visited = set([start])
    clue_set = set([start])
    result = backtrack(path, visited, clue_set)
    if result is None:
        return "No Solution"
    return str(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))
