def solve(observation):
    data = observation['data']
    N = len(data)
    dominoes = []
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                reg1 = data[r][c]
                reg2 = data[r][c + 1]
                dominoes.append({'cells': [(r, c), (r, c + 1)], 'regs': [reg1, reg2]})
            if r + 1 < N:
                reg1 = data[r][c]
                reg2 = data[r + 1][c]
                dominoes.append({'cells': [(r, c), (r + 1, c)], 'regs': [reg1, reg2]})
    M = len(dominoes)
    conflicting = [[] for _ in range(M)]
    for i in range(M):
        for j in range(i + 1, M):
            cells1 = dominoes[i]['cells']
            cells2 = dominoes[j]['cells']
            touch = False
            for p1 in cells1:
                for p2 in cells2:
                    if abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) == 1:
                        touch = True
                        break
                if touch:
                    break
            if touch:
                conflicting[i].append(j)
                conflicting[j].append(i)
    unique_regions = set()
    for row in data:
        for rid in row:
            unique_regions.add(rid)
    R = len(unique_regions)
    if R == 0:
        return [[None for _ in range(N)] for _ in range(N)]

    def bt(placed, current_counts, available):
        if placed == R:
            if all(current_counts.get(rid, 0) == 2 for rid in unique_regions):
                return []
            return None
        for i in range(M):
            if not available[i]:
                continue
            dom = dominoes[i]
            regs = dom['regs']
            new_counts = current_counts.copy()
            if regs[0] == regs[1]:
                new_counts[regs[0]] = new_counts.get(regs[0], 0) + 2
            else:
                new_counts[regs[0]] = new_counts.get(regs[0], 0) + 1
                new_counts[regs[1]] = new_counts.get(regs[1], 0) + 1
            if any(new_counts.get(rid, 0) > 2 for rid in unique_regions):
                continue
            to_restore = []
            for j in conflicting[i]:
                if available[j]:
                    available[j] = False
                    to_restore.append(j)
            available[i] = False
            to_restore.append(i)
            res = bt(placed + 1, new_counts, available)
            if res is not None:
                return [i] + res
            for j in to_restore:
                available[j] = True
        return None

    available = [True] * M
    current_counts = {}
    selected = bt(0, current_counts, available)
    if selected is None:
        return "No Solution"
    grid = [[None for _ in range(N)] for _ in range(N)]
    for idx in selected:
        for r, c in dominoes[idx]['cells']:
            grid[r][c] = 'S'
    return grid

