import copy

def get_degree(r, c, h, v, N):
    deg = 0
    if c > 0 and h[r][c - 1] == 1:
        deg += 1
    if c < N and h[r][c] == 1:
        deg += 1
    if r > 0 and v[r - 1][c] == 1:
        deg += 1
    if r < N and v[r][c] == 1:
        deg += 1
    return deg

def is_valid_loop(h, v, N):
    # Check degrees
    for dr in range(N + 1):
        for dc in range(N + 1):
            deg = get_degree(dr, dc, h, v, N)
            if deg not in (0, 2):
                return False
    # Check connected components of non-zero degree dots
    visited = [[False] * (N + 1) for _ in range(N + 1)]
    components = 0
    for sr in range(N + 1):
        for sc in range(N + 1):
            if get_degree(sr, sc, h, v, N) > 0 and not visited[sr][sc]:
                components += 1
                if components > 1:
                    return False
                stack = [(sr, sc)]
                visited[sr][sc] = True
                while stack:
                    cr, cc = stack.pop()
                    directions = [(-1, 0, 'v', cr - 1, cc), (1, 0, 'v', cr, cc), (0, -1, 'h', cr, cc - 1), (0, 1, 'h', cr, cc)]
                    for ddr, ddc, typ, ei, ej in directions:
                        nr = cr + ddr
                        nc = cc + ddc
                        if 0 <= nr <= N and 0 <= nc <= N and not visited[nr][nc]:
                            val = v[ei][ej] if typ == 'v' else h[ei][ej]
                            if val == 1:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
    return components == 1

def extract_loop(h, v, N):
    # Find starting dot
    start = None
    for r in range(N + 1):
        for c in range(N + 1):
            if get_degree(r, c, h, v, N) == 2:
                start = (r, c)
                break
        if start:
            break
    if not start:
        return None
    # Get neighbors
    directions = [(-1, 0, 'v', start[0] - 1, start[1]), (1, 0, 'v', start[0], start[1]), (0, -1, 'h', start[0], start[1] - 1), (0, 1, 'h', start[0], start[1])]
    neighbors = []
    for ddr, ddc, typ, ei, ej in directions:
        nr = start[0] + ddr
        nc = start[1] + ddc
        if 0 <= nr <= N and 0 <= nc <= N:
            val = v[ei][ej] if typ == 'v' else h[ei][ej]
            if val == 1:
                neighbors.append((nr, nc))
    # Start path
    path = [start]
    current = start
    next_dot = neighbors[0]
    previous = None
    while next_dot != start:
        path.append(next_dot)
        previous = current
        current = next_dot
        # Get neighbors of current
        neigh = []
        for ddr, ddc, typ, ei, ej in directions:
            nr = current[0] + ddr
            nc = current[1] + ddc
            if 0 <= nr <= N and 0 <= nc <= N:
                val = v[ei][ej] if typ == 'v' else h[ei][ej]
                if val == 1:
                    neigh.append((nr, nc))
        if neigh[0] == previous:
            next_dot = neigh[1]
        else:
            next_dot = neigh[0]
    path.append(start)
    return path

def propagate(h, v, data, N):
    changed = False
    # Cell constraints
    for r in range(N):
        for c in range(N):
            if data[r][c] is None:
                continue
            k = data[r][c]
            edges = [('h', r, c), ('v', r, c), ('h', r + 1, c), ('v', r, c + 1)]
            lines = 0
            unknowns = []
            for typ, i, j in edges:
                val = h[i][j] if typ == 'h' else v[i][j]
                if val == 1:
                    lines += 1
                elif val is None:
                    unknowns.append((typ, i, j))
            u = len(unknowns)
            if lines > k or lines + u < k:
                return 'impossible'
            if lines + u == k:
                for typ, i, j in unknowns:
                    if typ == 'h':
                        h[i][j] = 1
                    else:
                        v[i][j] = 1
                changed = True
            if lines == k:
                for typ, i, j in unknowns:
                    if typ == 'h':
                        h[i][j] = 0
                    else:
                        v[i][j] = 0
                changed = True
    # Degree constraints
    for dr in range(N + 1):
        for dc in range(N + 1):
            incidents = []
            if dc > 0:
                incidents.append(('h', dr, dc - 1))
            if dc < N:
                incidents.append(('h', dr, dc))
            if dr > 0:
                incidents.append(('v', dr - 1, dc))
            if dr < N:
                incidents.append(('v', dr, dc))
            lines = 0
            unknowns = []
            for typ, i, j in incidents:
                val = h[i][j] if typ == 'h' else v[i][j]
                if val == 1:
                    lines += 1
                elif val is None:
                    unknowns.append((typ, i, j))
            u = len(unknowns)
            min_d = lines
            max_d = lines + u
            has0 = (min_d <= 0 <= max_d)
            has2 = (min_d <= 2 <= max_d)
            if not (has0 or has2):
                return 'impossible'
            for typ, pi, pj in unknowns:
                # Check setting to 1
                min1 = lines + 1
                max1 = lines + u
                has0_1 = (min1 <= 0 <= max1)
                has2_1 = (min1 <= 2 <= max1)
                if not (has0_1 or has2_1):
                    if typ == 'h':
                        h[pi][pj] = 0
                    else:
                        v[pi][pj] = 0
                    changed = True
                    continue
                # Check setting to 0
                min0 = lines
                max0 = lines + u - 1
                has0_0 = (min0 <= 0 <= max0)
                has2_0 = (min0 <= 2 <= max0)
                if not (has0_0 or has2_0):
                    if typ == 'h':
                        h[pi][pj] = 1
                    else:
                        v[pi][pj] = 1
                    changed = True
    return changed

def solver(h, v, data, N):
    while True:
        ch = propagate(h, v, data, N)
        if ch == 'impossible':
            return None
        if not ch:
            break
    # Check if all decided
    all_decided = all(all(x is not None for x in row) for row in h) and all(all(x is not None for x in row) for row in v)
    if all_decided:
        if is_valid_loop(h, v, N):
            return extract_loop(h, v, N)
        return None
    # Branch on first unknown horizontal
    for i in range(N + 1):
        for j in range(N):
            if h[i][j] is None:
                for trial in [1, 0]:
                    h_copy = copy.deepcopy(h)
                    v_copy = copy.deepcopy(v)
                    h_copy[i][j] = trial
                    result = solver(h_copy, v_copy, data, N)
                    if result is not None:
                        return result
                return None
    # Then vertical
    for i in range(N):
        for j in range(N + 1):
            if v[i][j] is None:
                for trial in [1, 0]:
                    h_copy = copy.deepcopy(h)
                    v_copy = copy.deepcopy(v)
                    v_copy[i][j] = trial
                    result = solver(h_copy, v_copy, data, N)
                    if result is not None:
                        return result
                return None
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    h_edges = [[None] * N for _ in range(N + 1)]
    v_edges = [[None] * (N + 1) for _ in range(N)]
    result = solver(h_edges, v_edges, data, N)
    if result is None:
        return "No Solution"
    return str(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))
