from collections import defaultdict, deque

def solve(observation):
    n = len(observation['region'])
    region_to_cells = defaultdict(list)
    cell_to_region = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rid = observation['region'][r][c]
            region_to_cells[rid].append((r, c))
            cell_to_region[r][c] = rid

    region_to_num = {}
    for r in range(n):
        for c in range(n):
            val = observation['data'][r][c]
            if val is not None:
                rid = cell_to_region[r][c]
                if rid in region_to_num and region_to_num[rid] != val:
                    return "No Solution"
                region_to_num[rid] = val

    # Precompute possible independent subsets for each region
    possible = defaultdict(list)
    for rid, cells in region_to_cells.items():
        m = len(cells)
        for mask in range(1 << m):
            subset = []
            is_independent = True
            for i in range(m):
                if mask & (1 << i):
                    subset.append(cells[i])
            # Check if subset is independent (no two orthogonal adjacent)
            for a in range(len(subset)):
                for b in range(a + 1, len(subset)):
                    r1, c1 = subset[a]
                    r2, c2 = subset[b]
                    if abs(r1 - r2) + abs(c1 - c2) == 1:
                        is_independent = False
                        break
                if not is_independent:
                    break
            if is_independent:
                size = len(subset)
                if rid in region_to_num:
                    if size == region_to_num[rid]:
                        possible[rid].append(tuple(subset))  # Use tuple for set compatibility
                else:
                    possible[rid].append(tuple(subset))

    # If any region has no possible subsets, no solution
    for rid in region_to_cells:
        if not possible[rid]:
            return "No Solution"

    # Sort regions by number of possible subsets (fewest first for pruning)
    regions = sorted(region_to_cells.keys(), key=lambda rid: len(possible[rid]))

    def bt(idx, blacks):
        if idx == len(regions):
            if check_white_connected(blacks, n) and check_segments(blacks, n, observation['region']):
                grid = [[None] * n for _ in range(n)]
                for r, c in blacks:
                    grid[r][c] = 'B'
                return grid
            return None

        rid = regions[idx]
        for subset in possible[rid]:
            can_place = True
            for cell in subset:
                r, c = cell
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and (nr, nc) in blacks:
                        can_place = False
                        break
                if not can_place:
                    break
            if can_place:
                new_blacks = blacks | set(subset)
                res = bt(idx + 1, new_blacks)
                if res is not None:
                    return res
        return None

    return bt(0, set()) or "No Solution"

def check_white_connected(blacks, n):
    whites = [(r, c) for r in range(n) for c in range(n) if (r, c) not in blacks]
    if not whites:
        return True
    visited = set()
    q = deque([whites[0]])
    visited.add(whites[0])
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in blacks and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(whites)

def check_segments(blacks, n, region_grid):
    # Check rows
    for r in range(n):
        i = 0
        while i < n:
            if (r, i) in blacks:
                i += 1
                continue
            seg_regions = set()
            j = i
            while j < n and (r, j) not in blacks:
                seg_regions.add(region_grid[r][j])
                j += 1
            if len(seg_regions) > 2:
                return False
            i = j
    # Check columns
    for c in range(n):
        i = 0
        while i < n:
            if (i, c) in blacks:
                i += 1
                continue
            seg_regions = set()
            j = i
            while j < n and (j, c) not in blacks:
                seg_regions.add(region_grid[j][c])
                j += 1
            if len(seg_regions) > 2:
                return False
            i = j
    return True

if __name__ == "__main__":
    print(solve(OBSERVATION))
