def solve(observation):
    row_s = observation['row_sum']
    col_s = observation['col_sum']
    m = len(row_s)
    n = len(col_s)
    row_w = [i + 1 for i in range(m)]
    col_w = [j + 1 for j in range(n)]

    # Find possible masks for each row
    possibles = []
    for i in range(m):
        target = row_s[i]
        subs = []
        for mask in range(1 << n):
            s = 0
            for j in range(n):
                if mask & (1 << j):
                    s += col_w[j]
            if s == target:
                subs.append(mask)
        possibles.append(subs)

    # Sort rows by number of possibilities (fewest first)
    row_order = sorted(range(m), key=lambda i: len(possibles[i]))

    chosen = [None] * m

    def bt(level, current_sums):
        if level == m:
            return True

        i = row_order[level]
        for mask in possibles[i]:
            new_sums = current_sums[:]
            added = row_w[i]
            ok = True
            for j in range(n):
                if mask & (1 << j):
                    new_sums[j] += added
                    if new_sums[j] > col_s[j]:
                        ok = False
                        break
            if not ok:
                continue

            # Compute max remaining for pruning
            rem_max = sum(row_w[row_order[k]] for k in range(level + 1, m))
            ok = True
            for j in range(n):
                need = col_s[j] - new_sums[j]
                if need < 0 or need > rem_max:
                    ok = False
                    break
            if not ok:
                continue

            chosen[i] = mask
            if bt(level + 1, new_sums):
                return True
        return False

    initial_sums = [0] * n
    if bt(0, initial_sums):
        grid = [[None] * n for _ in range(m)]
        for i in range(m):
            mask = chosen[i]
            for j in range(n):
                if mask & (1 << j):
                    grid[i][j] = 'B'
        return grid
    return "No Solution"

