OBSERVATION = {'data': [[0, 0, 1, 1, 1, 2], [0, 0, 0, 3, 3, 2], [0, 4, 0, 0, 3, 3], [4, 4, 5, 5, 7, 3], [4, 5, 5, 6, 7, 3], [4, 4, 5, 6, 7, 7]]}

import math
from bisect import bisect_left

def solve(observation):
    data = observation['data']
    N = len(data)
    M = 0
    for row in data:
        M = max(M, max(row))
    M += 1  # number of regions

    # build D
    D = []
    for r in range(N):
        for c in range(N - 1):
            D.append(((r, c), (r, c + 1)))
    for r in range(N - 1):
        for c in range(N):
            D.append(((r, c), (r + 1, c)))

    # compute region_size
    region_size = [0] * M
    for r in range(N):
        for c in range(N):
            region_size[data[r][c]] += 1

    # score function
    def score(d):
        (p1, p2) = d
        r1 = data[p1[0]][p1[1]]
        r2 = data[p2[0]][p2[1]]
        if r1 == r2:
            return 2 / region_size[r1] if region_size[r1] > 0 else 0
        else:
            return (1 / region_size[r1] if region_size[r1] > 0 else 0) + (1 / region_size[r2] if region_size[r2] > 0 else 0)

    # sort D by score descending
    D.sort(key=score, reverse=True)

    # build region_dominoes
    region_dominoes = [[] for _ in range(M)]
    for idx in range(len(D)):
        (p1, p2) = D[idx]
        r1 = data[p1[0]][p1[1]]
        r2 = data[p2[0]][p2[1]]
        region_dominoes[r1].append(idx)
        if r2 != r1:
            region_dominoes[r2].append(idx)
    for i in range(M):
        region_dominoes[i].sort()

    def backtrack(pos, current_placed, current_counts, shaded):
        if current_placed == M:
            if all(c == 2 for c in current_counts):
                return []
            return None
        if pos == len(D):
            return None

        # prune: check needy regions have possible dominoes
        needy = 0
        for i in range(M):
            if current_counts[i] < 2:
                needy += 1
                l = region_dominoes[i]
                idx = bisect_left(l, pos)
                if idx == len(l):
                    return None

        # prune: enough placements left
        remaining = len(D) - pos
        if remaining < math.ceil(needy / 2):
            return None

        # skip
        res = backtrack(pos + 1, current_placed, current_counts, shaded)
        if res is not None:
            return res

        # try include
        (p1, p2) = D[pos]
        r1 = data[p1[0]][p1[1]]
        r2 = data[p2[0]][p2[1]]

        if p1 in shaded or p2 in shaded:
            return None

        # check not touching
        cells = {p1, p2}
        touching = False
        for r, c in cells:
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) in shaded and (nr, nc) not in cells:
                        touching = True
                        break
            if touching:
                break
        if touching:
            return None

        # check counts
        add1 = 1 if r1 != r2 else 2
        add2 = 1 if r1 != r2 else 0
        if current_counts[r1] + add1 > 2:
            return None
        if add2 > 0 and current_counts[r2] + add2 > 2:
            return None

        # add
        new_counts = current_counts[:]
        new_counts[r1] += add1
        if add2 > 0:
            new_counts[r2] += add2
        new_shaded = shaded | cells

        res = backtrack(pos + 1, current_placed + 1, new_counts, new_shaded)
        if res is not None:
            return [pos] + res

        return None

    included = backtrack(0, 0, [0] * M, set())
    if included is None:
        return "No Solution"

    # build answer
    answer = [[None for _ in range(N)] for _ in range(N)]
    for idx in included:
        (p1, p2) = D[idx]
        answer[p1[0]][p1[1]] = 'S'
        answer[p2[0]][p2[1]] = 'S'
    return answer

if __name__ == "__main__":
    print(solve(OBSERVATION))
