        possible = []
        for k in range(size + 1):
            for combo in combinations(range(size), k):
                if sum(weights[c] for c in combo) == target:
                    mask = 0
                    for c in combo:
                        mask |= 1 << c
                    possible.append(mask)
        return possible

    row_poss = [get_possible(col_weights, row_targets[i], n) for i in range(m)]
    col_poss = [get_possible(row_weights, col_targets[j], m) for j in range(n)]

    def deduce(grid, row_poss, col_poss):
        changed = True
        while changed:
            changed = False
            for i in range(m):
                if len(row_poss[i]) == 1:
                    mask = row_poss[i][0]
                    for j in range(n):
                        val = 'B' if (mask & (1 << j)) else '.'
                        if grid[i][j] is not None and grid[i][j] != val:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = val
                            changed = True
            for j in range(n):
                if len(col_poss[j]) == 1:
                    mask = col_poss[j][0]
                    for i in range(m):
                        val = 'B' if (mask & (1 << i)) else '.'
                        if grid[i][j] is not None and grid[i][j] != val:
                            return False
                        if grid[i][j] is None:
                            grid[i][j] = val
                            changed = True
            for i in range(m):
