                    return False
                for j in range(n):
                    all_b = all((mask & (1 << j)) != 0 for mask in row_poss[i])
                    all_w = all((mask & (1 << j)) == 0 for mask in row_poss[i])
                    if all_b:
                        val = 'B'
                    elif all_w:
                        val = '.'
                    else:
                        continue
                    if grid[i][j] is not None and grid[i][j] != val:
                        return False
                    if grid[i][j] is None:
                        grid[i][j] = val
                        changed = True
            for j in range(n):
                if len(col_poss[j]) == 0:
                    return False
                for i in range(m):
                    all_b = all((mask & (1 << i)) != 0 for mask in col_poss[j])
                    all_w = all((mask & (1 << i)) == 0 for mask in col_poss[j])
                    if all_b:
                        val = 'B'
                    elif all_w:
                        val = '.'
                    else:
                        continue
                    if grid[i][j] is not None and grid[i][j] != val:
                        return False
                    if grid[i][j] is None:
                        grid[i][j] = val
                        changed = True
            for i in range(m):
                new_p = []
                for mask in row_poss[i]:
                    cons = True
                    for j in range(n):
                        is_b = (mask & (1 << j)) != 0
                        if (grid[i][j] == 'B' and not is_b) or (grid[i][j] == '.' and is_b):
                            cons = False
                            break
                    if cons:
                        new_p.append(mask)
                if len(new_p) < len(row_poss[i]):
                    changed = True
                row_poss[i] = new_p
                if not row_poss[i]:
                    return False
            for j in range(n):
                new_p = []
                for mask in col_poss[j]:
                    cons = True
                    for i_ in range(m):
                        is_b = (mask & (1 << i_)) != 0
                        if (grid[i_][j] == 'B' and not is_b) or (grid[i_][j] == '.' and is_b):
                            cons = False
                            break
                    if cons:
                        new_p.append(mask)
                if len(new_p) < len(col_poss[j]):
                    changed = True
                col_poss[j] = new_p
                if not col_poss[j]:
                    return False
        return True

    def backtrack(grid, row_poss, col_poss):
        if not deduce(grid, row_poss, col_poss):
            return None
        if all(all(cell is not None for cell in r) for r in grid):
            out = [['B' if cell == 'B' else None for cell in r] for r in grid]
            return out
        branch_i = -1
        min_len = float('inf')
        for ii in range(m):
            l = len(row_poss[ii])
            if l > 1 and l < min_len:
                min_len = l
                branch_i = ii
        if branch_i == -1:
            return None
        for mask in row_poss[branch_i]:
            grid2 = copy.deepcopy(grid)
            row_poss2 = copy.deepcopy(row_poss)
            col_poss2 = copy.deepcopy(col_poss)
            consistent = True
            for j in range(n):
                val = 'B' if (mask & (1 << j)) else '.'
                if grid2[branch_i][j] is not None and grid2[branch_i][j] != val:
                    consistent = False
                    break
                grid2[branch_i][j] = val
            if not consistent:
                continue
            row_poss2[branch_i] = [mask]
            result = backtrack(grid2, row_poss2, col_poss2)
            if result is not None:
                return result
        return None

    grid = [[None for _ in range(n)] for _ in range(m)]
    result = backtrack(grid, row_poss, col_poss)
    if result is None:
        return "No Solution"
    return result

