        e_d = list(config - {opp_in})[0]
        nr = e[0] + dirs[e_d][0]
        nc = e[1] + dirs[e_d][1]
        if not (0 <= nr < size and 0 <= nc < size):
            continue
        next = (nr, nc)
        if next == incoming:
            continue
        if next in nbs:
            continue
        next_nbs_len = len(neighbors.get(next, set()))
        if next_nbs_len + 1 > 2:
            continue
        if next_nbs_len + 1 == 2:
            new_nbs = neighbors.get(next, set()).copy()
            new_nbs.add(e)
            d_set = set(get_dir(next, nb) for nb in new_nbs)
            if frozenset(d_set) not in possible[next[0]][next[1]]:
                continue
        # add
        neighbors[e].add(next)
        if next not in neighbors:
            neighbors[next] = set()
        neighbors[next].add(e)
        new_visited = visited_clued
        if len(neighbors[next]) == 2 and next in set(clued):
            new_visited += 1
        result = backtrack(neighbors, new_visited, size, clued, possible)
        if result is not None:
            return result
        # undo
        neighbors[e].remove(next)
        neighbors[next].remove(e)
        if not neighbors[next]:
            del neighbors[next]
    return None

def get_dir(a, b):
    dr = b[0] - a[0]
    dc = b[1] - a[1]
    if dr == -1 and dc == 0: return 0
    if dr == 0 and dc == 1: return 1
    if dr == 1 and dc == 0: return 2
    if dr == 0 and dc == -1: return 3
    return -1

