from collections import defaultdict, deque

def assign_and_propagate(grid, N, to_force_list, directions):
    queue = deque(to_force_list)
    while queue:
        r, c, val = queue.popleft()
        if grid[r][c] is not None:
            if grid[r][c] != val:
                return False
            continue
        grid[r][c] = val
        if val == 'B':
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    queue.append((nr, nc, 'W'))
    return True

def check_connectivity(grid, N, directions):
    whites = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 'W']
    if not whites:
        return True
    visited = set()
    start = whites[0]
    q = deque([start])
    visited.add(start)
    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == 'W' and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(whites)

def check_segments(grid, N, region_map):
    # rows
    for r in range(N):
        i = 0
        while i < N:
            if grid[r][i] == 'B':
                i += 1
                continue
            start = i
            regions = set()
            while i < N and grid[r][i] == 'W':
                regions.add(region_map[r][i])
                i += 1
            if len(regions) > 2:
                return False
    # columns
    for c in range(N):
        i = 0
        while i < N:
            if grid[i][c] == 'B':
                i += 1
                continue
            start = i
            regions = set()
            while i < N and grid[i][c] == 'W':
                regions.add(region_map[i][c])
                i += 1
            if len(regions) > 2:
                return False
    return True

def solver(grid, N, region_map, region_to_cells, region_to_num, directions):
    changed = True
    while changed:
        changed = False
        # Force 'W' on cells adjacent to 'B'
        forces = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    adjacent_b = any(grid[nr][nc] == 'B' for dr, dc in directions if 0 <= (nr := r + dr) < N and 0 <= (nc := c + dc) < N)
                    if adjacent_b:
                        forces.append((r, c, 'W'))
        if forces:
            if not assign_and_propagate(grid, N, forces, directions):
                return None
            changed = True
        # Region sum propagation
        for rid, cells in region_to_cells.items():
            if region_to_num[rid] is None:
                continue
            k = region_to_num[rid]
            forced_b = len([ (rr, cc) for rr, cc in cells if grid[rr][cc] == 'B' ])
            undecided = [ (rr, cc) for rr, cc in cells if grid[rr][cc] is None ]
            u = len(undecided)
            remaining = k - forced_b
            if forced_b > k or u + forced_b < k:
                return None
            if u == remaining:
                forces = [(rr, cc, 'B') for rr, cc in undecided]
                if not assign_and_propagate(grid, N, forces, directions):
                    return None
                changed = True
            if remaining == 0:
                forces = [(rr, cc, 'W') for rr, cc in undecided]
                if not assign_and_propagate(grid, N, forces, directions):
                    return None
                changed = True
        # Segment rule propagation
        forces = []
        # rows
        for r in range(N):
            for start in range(N):
                for end in range(start + 2, N):
                    seq_regions = set(region_map[r][j] for j in range(start, end + 1))
                    if len(seq_regions) < 3:
                        continue
                    forced_b_count = sum(grid[r][j] == 'B' for j in range(start, end + 1))
                    undecided_count = sum(grid[r][j] is None for j in range(start, end + 1))
                    if forced_b_count == 0:
                        if undecided_count == 0:
                            return None
                        if undecided_count == 1:
                            for j in range(start, end + 1):
                                if grid[r][j] is None:
                                    forces.append((r, j, 'B'))
                                    break
        # columns
        for c in range(N):
            for start in range(N):
                for end in range(start + 2, N):
                    seq_regions = set(region_map[j][c] for j in range(start, end + 1))
                    if len(seq_regions) < 3:
                        continue
                    forced_b_count = sum(grid[j][c] == 'B' for j in range(start, end + 1))
                    undecided_count = sum(grid[j][c] is None for j in range(start, end + 1))
                    if forced_b_count == 0:
                        if undecided_count == 0:
                            return None
                        if undecided_count == 1:
                            for j in range(start, end + 1):
                                if grid[j][c] is None:
                                    forces.append((j, c, 'B'))
                                    break
        if forces:
            if not assign_and_propagate(grid, N, forces, directions):
                return None
            changed = True
    # Check if solved
    if all(all(x is not None for x in row) for row in grid):
        if check_connectivity(grid, N, directions) and check_segments(grid, N, region_map):
            return [[None if x == 'W' else x for x in row] for row in grid]
        else:
            return None
    # Choose next cell
    min_score = float('inf')
    candidate = None
    for rid, cells in region_to_cells.items():
        if region_to_num[rid] is None:
            continue
        k = region_to_num[rid]
        forced_b = sum(1 for rr, cc in cells if grid[rr][cc] == 'B')
        u = sum(1 for rr, cc in cells if grid[rr][cc] is None)
        remaining = k - forced_b
        score = u - remaining
        if score < min_score and u > 0:
            min_score = score
            for rr, cc in cells:
                if grid[rr][cc] is None:
                    candidate = (rr, cc)
                    break
    if candidate is None:
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    candidate = (r, c)
                    break
            if candidate:
                break
    if candidate is None:
        return None
    r, c = candidate
    # Branch
    for val in ['W', 'B']:
        new_grid = [row[:] for row in grid]
        if assign_and_propagate(new_grid, N, [(r, c, val)], directions):
            res = solver(new_grid, N, region_map, region_to_cells, region_to_num, directions)
            if res is not None:
                return res
    return None

def solve(observation):
    region_map = observation['region']
    data = observation['data']
    N = len(region_map)
    region_to_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_to_cells[region_map[r][c]].append((r, c))
    region_to_num = {}
    for rid, cells in region_to_cells.items():
        nums = set(data[r][c] for r, c in cells if data[r][c] is not None)
        if len(nums) > 1:
            return "No Solution"
        region_to_num[rid] = list(nums)[0] if nums else None
    grid = [[None for _ in range(N)] for _ in range(N)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    initial_forces = []
    for rid, num in region_to_num.items():
        if num == 0:
            for r, c in region_to_cells[rid]:
                initial_forces.append((r, c, 'W'))
    if not assign_and_propagate(grid, N, initial_forces, directions):
        return "No Solution"
    res = solver(grid, N, region_map, region_to_cells, region_to_num, directions)
    if res is None:
        return "No Solution"
    return res

