                    if 0 <= nr < n and 0 <= nc < m and tree_grid[nr][nc] is None and placed_new[nr][nc] is None:
                        forbidden_new.add((nr, nc))
            result = backtrack(placed_new, remaining_row_new, remaining_col_new, unsatisfied_new, forbidden_new)
