            for i in range(n):
                for j in range(n):
                    if grid[i][j] != -1:
                        continue
                    num_pos = (1 if can_black[i][j] else 0) + (1 if can_white[i][j] else 0)
                    if num_pos == 0:
                        return False
                    if num_pos == 1:
                        if can_black[i][j]:
                            grid[i][j] = 'B'
                        else:
                            grid[i][j] = None
