                forced_w = 0
                unknown = []
                candidates = []
                for r, c in cells:
                    if grid[r][c] == 'B':
                        forced_b += 1
                    elif grid[r][c] == None:
                        forced_w += 1
                    else:
                        unknown.append((r, c))
                    if grid[r][c] == -1 and can_black[r][c]:
                        candidates.append((r, c))
                num_u = len(unknown)
                if forced_b > k or forced_b + len(candidates) < k:
                    return False

                # Compute alpha
                m = len(candidates)
                if m == 0:
                    alpha = 0
                else:
                    adj = [[False] * m for _ in range(m)]
                    for a in range(m):
                        for b in range(a + 1, m):
                            ra, ca = candidates[a]
                            rb, cb = candidates[b]
                            if abs(ra - rb) + abs(ca - cb) == 1:
                                adj[a][b] = adj[b][a] = True
                    def max_is(pos, taken):
                        if pos == m:
                            return 0
                        res = max_is(pos + 1, taken)
                        can = True
                        for t in taken:
                            if adj[pos][t]:
                                can = False
                                break
                        if can:
                            taken.append(pos)
                            res = max(res, 1 + max_is(pos + 1, taken))
                            taken.pop()
                        return res
                    alpha = max_is(0, [])

                if forced_b + alpha < k:
                    return False
                if forced_b == k:
                    for r, c in unknown:
                        if can_black[r][c]:
                            can_black[r][c] = False
                            changed = True
                if forced_b + num_u == k:
                    for r, c in unknown:
                        if can_white[r][c]:
                            can_white[r][c] = False
                            changed = True

            # Segment rule for rows
            for r in range(n):
                for start in range(n):
