                        if num_forced_w == total - 1 and len(not_forced_list) == 1:
                            the_row = not_forced_list[0]
                            if can_white[the_row][c]:
                                can_white[the_row][c] = False
                                changed = True

            # Connectivity
            forced_whites = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == None]
            if len(forced_whites) > 0:
                parent = {}
                def find(x):
                    if parent[x] != x:
                        parent[x] = find(parent[x])
                    return parent[x]
                def union(x, y):
                    px, py = find(x), find(y)
                    if px != py:
                        parent[px] = py
                pos_white = set()
                for i in range(n):
                    for j in range(n):
                        if grid[i][j] == None or (grid[i][j] == -1 and can_white[i][j]):
                            pos_white.add((i, j))
                            parent[(i, j)] = (i, j)
                for i in range(n):
                    for j in range(n):
                        if (i, j) in pos_white:
                            for di, dj in [(0, 1), (1, 0)]:
                                ni, nj = i + di, j + dj
                                if (ni, nj) in pos_white:
                                    union((i, j), (ni, nj))
