                while i < n and valid:
                    if g[i][c] == 'B':
                        i += 1
                        continue
                    start = i
                    regs = set()
                    while i < n and g[i][c] == None:
                        regs.add(region[i][c])
                        i += 1
                    if len(regs) > 2:
