            return g

        # Choose cell with fewest possibilities
        min_pos = 3
        chosen = None
        for i in range(n):
            for j in range(n):
                if g[i][j] == -1:
                    num = (1 if cb[i][j] else 0) + (1 if cw[i][j] else 0)
                    if 0 < num < min_pos:
                        min_pos = num
                        chosen = (i, j)
        if chosen is None:
            return None
        r, c = chosen

        attempts = []
        if cb[r][c]:
            attempts.append('B')
        if cw[r][c]:
