            if color == 'B':
                cw2[r][c] = False
            else:
                cb2[r][c] = False
            result = backtrack(g2, cb2, cw2)
            if result is not None:
                return result
        return None

    grid = [[-1] * n for _ in range(n)]
    can_black = [[True] * n for _ in range(n)]
    can_white = [[True] * n for _ in range(n)]
    result = backtrack(grid, can_black, can_white)
    if result is None:
        return "No Solution"
    return result

