    cols = len(data[0])
    clues = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                clues.append((r, c, data[r][c]))
    num_islands = len(clues)
    required = [clue[2] for clue in clues]
    grid = [[None] * cols for _ in range(rows)]
    for i, (r, c, _) in enumerate(clues):
        grid[r][c] = i
    current_sizes = [1] * num_islands
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def get_adj_ids(r, c):
        adj_set = set()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and isinstance(grid[nr][nc], int):
                adj_set.add(grid[nr][nc])
        return adj_set

    def has_2x2_black():
        for r in range(rows - 1):
            for c in range(cols - 1):
                cells = [grid[r + dr][c + dc] for dr in [0, 1] for dc in [0, 1]]
                if all(x == 'B' for x in cells):
                    return True
        return False

    def blacks_connected():
        visited = [[False] * cols for _ in range(rows)]
        start = None
        num_b = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'B':
                    num_b += 1
                    if start is None:
                        start = (r, c)
        if num_b == 0:
            return True
        from collections import deque
        q = deque([start])
        visited[start[0]][start[1]] = True
        reached = 1
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and not visited[nr][nc] and grid[nr][nc] == 'B':
                    visited[nr][nc] = True
                    q.append((nr, nc))
                    reached += 1
        return reached == num_b

    def can_blacks_connect():
        black_pos = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 'B']
        if not black_pos:
            return True
        from collections import deque
        visited = [[False] * cols for _ in range(rows)]
        q = deque([black_pos[0]])
        visited[black_pos[0][0]][black_pos[0][1]] = True
        reached_blacks = 1
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and not visited[nr][nc] and (grid[nr][nc] == 'B' or grid[nr][nc] is None):
                    visited[nr][nc] = True
                    q.append((nr, nc))
                    if grid[nr][nc] == 'B':
                        reached_blacks += 1
        return reached_blacks == len(black_pos)

    def propagate():
