                    pos = [(rr, cc), (rr, cc + 1), (rr + 1, cc), (rr + 1, cc + 1)]
                    states = [grid[p[0]][p[1]] for p in pos]
                    count_b = sum(1 for s in states if s == 'B')
                    count_u = sum(1 for s in states if s is None)
                    count_w = 4 - count_b - count_u
                    if count_w == 0:
                        if count_u == 0:
                            return False
                        can_white = False
                        for i in range(4):
                            if states[i] is None:
                                r_, c_ = pos[i]
                                adj = get_adj_ids(r_, c_)
                                if len(adj) == 1:
                                    id_ = list(adj)[0]
                                    if current_sizes[id_] < required[id_]:
                                        can_white = True
                                        break
                        if not can_white:
                            return False
                    if count_b == 3 and count_u == 1:
                        for i in range(4):
                            if states[i] is None:
                                r_, c_ = pos[i]
                                adj = get_adj_ids(r_, c_)
                                if len(adj) == 1:
                                    id_ = list(adj)[0]
                                    if current_sizes[id_] < required[id_]:
                                        grid[r_][c_] = id_
                                        current_sizes[id_] += 1
                                        changed = True
                                    else:
                                        return False
                                else:
                                    return False
                                break
            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] is None:
                        adj = get_adj_ids(r, c)
                        force_black = False
                        if len(adj) > 1:
                            force_black = True
                        elif len(adj) == 0:
                            force_black = True
                        elif len(adj) == 1:
                            id_ = list(adj)[0]
                            if current_sizes[id_] >= required[id_]:
                                force_black = True
                        if force_black:
                            grid[r][c] = 'B'
                            changed = True
            for i in range(num_islands):
                if current_sizes[i] > required[i]:
                    return False
        return True

    def backtrack():
        if not propagate():
            return False
        all_decided = all(grid[r][c] is not None for r in range(rows) for c in range(cols))
        if all_decided:
            if any(current_sizes[i] != required[i] for i in range(num_islands)):
                return False
            if has_2x2_black():
                return False
            if not blacks_connected():
                return False
            return True
        if not can_blacks_connect():
            return False
        candidates = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is None:
                    adj = get_adj_ids(r, c)
                    if len(adj) == 1:
                        id_ = list(adj)[0]
                        if current_sizes[id_] < required[id_]:
                            remaining = required[id_] - current_sizes[id_]
                            candidates.append((remaining, r, c, id_))
        if not candidates:
            return False
        candidates.sort(key=lambda x: x[0])
        _, r, c, id_ = candidates[0]
        # Try white
        grid[r][c] = id_
        current_sizes[id_] += 1
        if backtrack():
            return True
        grid[r][c] = None
        current_sizes[id_] -= 1
        # Try black
        grid[r][c] = 'B'
        if backtrack():
            return True
        grid[r][c] = None
        return False

    if backtrack():
        out_grid = [[None if isinstance(grid[r][c], int) else grid[r][c] for c in range(cols)] for r in range(rows)]
        return out_grid
    else:
        return "No Solution"

