                v = grid[i][j]
                for k in range(n):
                    if k != j:
                        possibles[i][k].discard(v)
                    if k != i:
                        possibles[k][j].discard(v)
    # check for empty
    for i in range(n):
        for j in range(n):
            if len(possibles[i][j]) == 0:
                return "No Solution"
    # constraints
    constraints = []
    for key, sym in observation['horizontal'].items():
        r, c5 = ast.literal_eval(key)
        c = int(c5 - 0.5)
        cell1 = (r, c)
        cell2 = (r, c+1)
        if sym == '<':
            constraints.append((cell1, cell2, '<'))
        elif sym == '>':
            constraints.append((cell1, cell2, '>'))
    for key, sym in observation['vertical'].items():
        r5, c = ast.literal_eval(key)
        r = int(r5 - 0.5)
        cell1 = (r, c)
        cell2 = (r+1, c)
        if sym == '^':
            constraints.append((cell1, cell2, '<'))
        elif sym == 'v':
            constraints.append((cell1, cell2, '>'))
    # AC3 for inequalities
    flip = {'<': '>', '>': '<'}
    arcs = []
    for c1, c2, op in constraints:
        arcs.append((c1, c2, op))
        arcs.append((c2, c1, flip[op]))
    def revise(cell_x, cell_y, op):
        ix, jx = cell_x
        iy, jy = cell_y
        px = possibles[ix][jx]
        if not px:
            return False
        py = possibles[iy][jy]
        if not py:
            return False
        min_py = min(py)
        max_py = max(py)
        to_remove = set()
        if op == '<':
            to_remove = {v for v in px if max_py <= v}
        elif op == '>':
            to_remove = {v for v in px if min_py >= v}
        changed = bool(to_remove)
        for v in to_remove:
            px.remove(v)
        return changed
    def ac3():
        queue = deque(arcs)
        while queue:
            cell_x, cell_y, op = queue.popleft()
            if revise(cell_x, cell_y, op):
                if len(possibles[cell_x[0]][cell_x[1]]) == 0:
                    return False
                for a in arcs:
                    if a[1] == cell_x and a != (cell_x, cell_y, op):
                        queue.append(a)
        return True
    if not ac3():
        return "No Solution"
    # assign singletons loop
    while True:
        assigned = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None and len(possibles[i][j]) == 1:
                    v = next(iter(possibles[i][j]))
                    grid[i][j] = v
                    assigned = True
                    for k in range(n):
                        if k != j:
                            possibles[i][k].discard(v)
                        if k != i:
                            possibles[k][j].discard(v)
        if not assigned:
            break
        if not ac3():
            return "No Solution"
    # check for empty
    for i in range(n):
        for j in range(n):
            if len(possibles[i][j]) == 0:
                return "No Solution"
    # check if all filled
    all_filled = all(grid[i][j] is not None for i in range(n) for j in range(n))
    if all_filled:
        return grid
    # backtrack
    def backtrack():
        candidate = None
        min_len = n + 1
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None:
                    l = len(possibles[i][j])
                    if l == 0:
                        return False
                    if l < min_len:
                        min_len = l
                        candidate = (i, j)
        if candidate is None:
            return True
        i, j = candidate
        for v in list(possibles[i][j]):
            grid[i][j] = v
            # forward check row column
            removed = []
            fail = False
            for k in range(n):
                if k != j and v in possibles[i][k]:
                    possibles[i][k].remove(v)
                    removed.append((i, k, v))
                    if len(possibles[i][k]) == 0:
                        fail = True
                if k != i and v in possibles[k][j]:
                    possibles[k][j].remove(v)
                    removed.append((k, j, v))
                    if len(possibles[k][j]) == 0:
                        fail = True
            if fail:
                for x, y, w in removed:
                    possibles[x][y].add(w)
                grid[i][j] = None
                continue
            # forward check inequalities
            removed_ineq = []
            fail_ineq = False
            for c1, c2, op in constraints:
                if c1 == (i, j):
                    x2, y2 = c2
                    if grid[x2][y2] is not None:
                        v2 = grid[x2][y2]
                        if (op == '<' and not (v < v2)) or (op == '>' and not (v > v2)):
                            fail_ineq = True
                    else:
                        to_remove = set()
                        for w in possibles[x2][y2]:
                            if (op == '<' and not (v < w)) or (op == '>' and not (v > w)):
                                to_remove.add(w)
                        for w in to_remove:
                            possibles[x2][y2].remove(w)
                            removed_ineq.append((x2, y2, w))
                        if len(possibles[x2][y2]) == 0:
                            fail_ineq = True
                if c2 == (i, j):
                    x1, y1 = c1
                    if grid[x1][y1] is not None:
                        v1 = grid[x1][y1]
                        if (op == '<' and not (v1 < v)) or (op == '>' and not (v1 > v)):
                            fail_ineq = True
                    else:
                        to_remove = set()
                        for w in possibles[x1][y1]:
                            if (op == '<' and not (w < v)) or (op == '>' and not (w > v)):
                                to_remove.add(w)
                        for w in to_remove:
                            possibles[x1][y1].remove(w)
                            removed_ineq.append((x1, y1, w))
                        if len(possibles[x1][y1]) == 0:
                            fail_ineq = True
            if fail_ineq:
                for x, y, w in removed_ineq:
                    possibles[x][y].add(w)
                for x, y, w in removed:
                    possibles[x][y].add(w)
                grid[i][j] = None
                continue
            if backtrack():
                return True
            for x, y, w in removed_ineq:
                possibles[x][y].add(w)
            for x, y, w in removed:
                possibles[x][y].add(w)
            grid[i][j] = None
        return False
    if backtrack():
        return grid
    else:
        return "No Solution"

