OBSERVATION = {'U': [None, None, None, None], 'D': [None, None, None, None], 'L': [None, None, 2, None], 'R': [None, 1, None, 3]}

import itertools

def visible_left(arr):
    if not arr:
        return 0
    count = 1
    max_h = arr[0]
    for h in arr[1:]:
        if h > max_h:
            count += 1
            max_h = h
    return count

def visible_right(arr):
    return visible_left(arr[::-1])

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    all_perms = list(itertools.permutations(range(1, N + 1)))
    row_possibles = []
    for i in range(N):
        left_clue = L[i]
        right_clue = R[i]
        possibles = []
        for p in all_perms:
            if left_clue is not None and visible_left(p) != left_clue:
                continue
            if right_clue is not None and visible_right(p) != right_clue:
                continue
            possibles.append(p)
        row_possibles.append(possibles)
    grid = [[0] * N for _ in range(N)]
    col_used = [set() for _ in range(N)]
    def backtrack(row):
        if row == N:
            for j in range(N):
                col = [grid[i][j] for i in range(N)]
                if U[j] is not None and visible_left(col) != U[j]:
                    return False
                if D[j] is not None and visible_right(col) != D[j]:
                    return False
            return True
        for perm in row_possibles[row]:
            can_place = True
            for j in range(N):
                h = perm[j]
                if h in col_used[j]:
                    can_place = False
                    break
            if not can_place:
                continue
            for j in range(N):
                h = perm[j]
                col_used[j].add(h)
                grid[row][j] = h
            if backtrack(row + 1):
                return True
            for j in range(N):
                h = perm[j]
                col_used[j].remove(h)
                grid[row][j] = 0
        return False
    if backtrack(0):
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
