                possible_masks[i].append(curr_mask)
                return
            if curr_sum > target or start == n:
                return
            find_subsets(curr_sum, curr_mask, start + 1)
            find_subsets(curr_sum + col_weights[start], curr_mask | (1 << start), start + 1)
        find_subsets(0, 0, 0)

