            return "No Solution"
        all_set = (1 << n) - 1
        some_set = 0
        for mask in possible_masks[i]:
            all_set &= mask
            some_set |= mask
        for j in range(n):
            bit = 1 << j
            cell = (i, j)
            if all_set & bit:
                forced_black.add(cell)
            if not (some_set & bit):
                forced_white.add(cell)

    # From columns
