            some_set |= mask
        for i in range(m):
            bit = 1 << i
            cell = (i, j)
            if all_set & bit:
                forced_black.add(cell)
            if not (some_set & bit):
                forced_white.add(cell)

    if forced_black & forced_white:
        return "No Solution"

    # Propagate
    updated = True
    while updated:
        updated = False

        # Update row possible masks based on forced
        for i in range(m):
