                if not (some_set & bit):
                    new_forced_white.add(cell)

        old_black = forced_black.copy()
        old_white = forced_white.copy()
        forced_black |= new_forced_black
        forced_white |= new_forced_white
        if forced_black != old_black or forced_white != old_white:
