                curr = col_current[jj]
                targ = col_sums[jj]
                if not (curr + min_rem <= targ <= curr + max_rem):
                    can_continue = False
                    break

            if can_continue:
                chosen_masks[i] = mask
                if backtrack(row_idx + 1):
                    return True

            # Backtrack
            for j in add_list:
                col_current[j] -= row_weights[i]

        return False

