def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n = len(row_sum)
    m = len(col_sum)
    row_w = list(range(n))
    col_w = list(range(m))

    # Precompute possible masks for each column
    col_masks = [[] for _ in range(m)]
    for c in range(m):
        target = col_sum[c]
        for mask in range(1 << n):
            s = 0
            for r in range(n):
                if mask & (1 << r):
                    s += row_w[r]
            if s == target:
                col_masks[c].append(mask)

    # Precompute for each column c and row r: can include r, can exclude r
    col_possible_include = [[any((mask & (1 << r)) != 0 for mask in col_masks[c]) for r in range(n)] for c in range(m)]
    col_possible_exclude = [[any((mask & (1 << r)) == 0 for mask in col_masks[c]) for r in range(n)] for c in range(m)]

    # Order columns by number of possible masks (fewest first)
    col_order = list(range(m))
    col_order.sort(key=lambda c: len(col_masks[c]))

    # Backtracking function
    def backtrack(idx, current_row_sums, assignment):
        if idx == m:
            return all(current_row_sums[r] == row_sum[r] for r in range(n))

        c = col_order[idx]
        for mask in col_masks[c]:
            new_sums = current_row_sums[:]
            for r in range(n):
                if mask & (1 << r):
                    new_sums[r] += col_w[c]

            # Pruning with min/max remaining
            good = True
            remaining_cols = col_order[idx + 1:]
            min_rems = [0] * n
            max_rems = [0] * n
            for cc in remaining_cols:
                for r in range(n):
                    if not col_possible_exclude[cc][r]:
                        min_rems[r] += col_w[cc]
                    if col_possible_include[cc][r]:
                        max_rems[r] += col_w[cc]
            for r in range(n):
                curr = new_sums[r]
                target = row_sum[r]
                if curr > target or curr + max_rems[r] < target or curr + min_rems[r] > target:
                    good = False
                    break
            if not good:
                continue

            assignment[c] = mask
            if backtrack(idx + 1, new_sums, assignment):
                return True
        return False

    assignment = [None] * m
    if backtrack(0, [0] * n, assignment):
        grid = [[None] * m for _ in range(n)]
        for c in range(m):
            mask = assignment[c]
            for r in range(n):
                if mask & (1 << r):
                    grid[r][c] = 'B'
        return grid
    else:
        return "No Solution"

