        if dr == -1 and dc == 0: return 0
        if dr == 0 and dc == 1: return 1
        if dr == 1 and dc == 0: return 2
        if dr == 0 and dc == -1: return 3
        raise ValueError("not adjacent")
    def is_straight(p, graph):
        if len(graph[p]) != 2:
            return False
        d1 = get_dir_from(p, graph[p][0])
        d2 = get_dir_from(p, graph[p][1])
        return abs(d1 - d2) % 4 == 2
    def is_turn(p, graph):
        if len(graph[p]) != 2:
            return False
        d1 = get_dir_from(p, graph[p][0])
        d2 = get_dir_from(p, graph[p][1])
        return abs(d1 - d2) % 4 in (1, 3)
    def check_partial(graph, clues, data):
