        return True
    def backtrack(ends, graph, visited, remaining_clues, data, clues, N):
        if not remaining_clues and abs(ends[0][0] - ends[1][0]) + abs(ends[0][1] - ends[1][1]) == 1 and ends[1] not in graph[ends[0]]:
            temp_graph = graph.copy()
            temp_graph[ends[0]].append(ends[1])
            temp_graph[ends[1]].append(ends[0])
            valid = True
            for end in ends:
                typ = data[end[0]][end[1]]
                if typ is not None:
                    d1 = get_dir_from(end, temp_graph[end][0])
                    d2 = get_dir_from(end, temp_graph[end][1])
                    diff = abs(d1 - d2) % 4
                    if (typ == 'W' and diff != 2) or (typ == 'B' and diff not in (1, 3)):
                        valid = False
            if valid:
                valid = True
                for cr, cc in clues:
                    typ = data[cr][cc]
                    n1, n2 = temp_graph[(cr, cc)]
                    turn1 = is_turn(n1, temp_graph)
                    turn2 = is_turn(n2, temp_graph)
                    if typ == 'W':
                        if not (turn1 or turn2):
                            valid = False
                            break
                    else:
                        if not (not turn1 and not turn2):
                            valid = False
                            break
            if valid:
                # extract path
                path = [start]
                current = start
                next_ = temp_graph[start][0]
                while next_ != start:
                    path.append(next_)
                    temp = next_
                    for cand in temp_graph[next_]:
                        if cand != current:
                            next_ = cand
                            break
                    current = temp
                path.append(start)
                return path
            # no need to pop since temp
        poss = [[], []]
        for i in range(2):
            r, c = ends[i]
            for d in get_possible_dirs(r, c):
                nb = get_neighbor(r, c, d)
                if nb not in visited:
                    poss[i].append(nb)
        candidates = []
        if poss[0]: candidates.append((len(poss[0]), 0, poss[0]))
        if poss[1]: candidates.append((len(poss[1]), 1, poss[1]))
        if not candidates and remaining_clues:
            return None
        candidates.sort()
        for _, idx, pos_list in candidates:
            current_end = ends[idx]
            for new_dot in pos_list:
                graph[current_end].append(new_dot)
                graph[new_dot].append(current_end)
                typ = data[current_end[0]][current_end[1]]
                local_valid = True
                if typ is not None:
                    d1 = get_dir_from(current_end, graph[current_end][0])
                    d2 = get_dir_from(current_end, graph[current_end][1])
                    diff = abs(d1 - d2) % 4
                    if (typ == 'W' and diff != 2) or (typ == 'B' and diff not in (1, 3)):
                        local_valid = False
                if local_valid and check_partial(graph, clues, data):
                    visited.add(new_dot)
                    new_remaining = remaining_clues - {new_dot}
                    new_ends = ends[:]
                    new_ends[idx] = new_dot
                    result = backtrack(new_ends, graph, visited, new_remaining, data, clues, N)
                    if result is not None:
                        return result
                    visited.remove(new_dot)
                graph[current_end].pop()
                graph[new_dot].pop()
        return None
    for pair_set in possible_pairs[start]:
        d1, d2 = list(pair_set)
        n1 = get_neighbor(start[0], start[1], d1)
        n2 = get_neighbor(start[0], start[1], d2)
        if n1 == n2 or n1 is None or n2 is None:
            continue
        graph = defaultdict(list)
        graph[start].extend([n1, n2])
        graph[n1].append(start)
        graph[n2].append(start)
        visited = set([start, n1, n2])
        remaining = clues - visited
        ends = [n1, n2]
        if check_partial(graph, clues, data):
            result = backtrack(ends, graph, visited, remaining, data, clues, N)
            if result is not None:
                return str(result)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
