            visited.add(whites[0])
            while q:
                x, y = q.popleft()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx = x + dx
                    ny = y + dy
                    if 0 <= nx < N and 0 <= ny < N and mask[nx][ny] is None and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        q.append((nx, ny))
            return len(visited) == len(whites)

        r = pos // N
        c = pos % N
        num = data[r][c]

        # Try white (None)
        can_white = True
        # Check row
        for j in range(c):
            if mask[r][j] is None and data[r][j] == num:
                can_white = False
                break
        # Check column
        for i in range(r):
            if mask[i][c] is None and data[i][c] == num:
                can_white = False
                break
        if can_white:
            mask[r][c] = None
            if backtrack(pos + 1):
                return True
            mask[r][c] = 0

        # Try black ('B')
        can_black = True
        # Check up
        if r > 0 and mask[r - 1][c] == 'B':
            can_black = False
        # Check left
        if c > 0 and mask[r][c - 1] == 'B':
            can_black = False
        if can_black:
            mask[r][c] = 'B'
            if backtrack(pos + 1):
                return True
            mask[r][c] = 0

        return False

    if backtrack(0):
        return mask
    return "No Solution"

