OBSERVATION = {'data': [[None, None, 1, 5, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None]], 'horizontal': {'(0, 0.5)': '>', '(0, 1.5)': '>'}, 'vertical': {'(1.5, 0)': 'v', '(2.5, 1)': 'v', '(2.5, 2)': 'v', '(2.5, 3)': 'v', '(3.5, 0)': 'v', '(3.5, 3)': 'v'}}

import ast
import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [row[:] for row in data]
    horizontal = observation['horizontal']
    vertical = observation['vertical']

    constraints = []
    for key, sym in horizontal.items():
        r, c05 = ast.literal_eval(key)
        c = int(c05 - 0.5)
        cell1 = (r, c)
        cell2 = (r, c + 1)
        if sym == '>':
            constraints.append((cell1, cell2, True))
        elif sym == '<':
            constraints.append((cell1, cell2, False))
    for key, sym in vertical.items():
        r05, c = ast.literal_eval(key)
        r = int(r05 - 0.5)
        cell1 = (r, c)
        cell2 = (r + 1, c)
        if sym == 'v':
            constraints.append((cell1, cell2, True))
        elif sym == '^':
            constraints.append((cell1, cell2, False))

    domains = [[set() for _ in range(N)] for _ in range(N)]
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                v = grid[i][j]
                domains[i][j] = {v}
                row_used[i].add(v)
                col_used[j].add(v)
            else:
                domains[i][j] = set(range(1, N + 1))

    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                domains[i][j] -= row_used[i]
                domains[i][j] -= col_used[j]

    def propagate():
        nonlocal domains
        changed = True
        while changed:
            changed = False
            for cell1, cell2, is_greater in constraints:
                r1, c1 = cell1
                r2, c2 = cell2
                d1 = domains[r1][c1]
                d2 = domains[r2][c2]
                if not d1 or not d2:
                    continue
                if is_greater:
                    min_d2 = min(d2)
                    new_d1 = {v for v in d1 if v > min_d2}
                    if len(new_d1) < len(d1):
                        domains[r1][c1] = new_d1
                        changed = True
                    max_d1 = max(d1)
                    new_d2 = {v for v in d2 if v < max_d1}
                    if len(new_d2) < len(d2):
                        domains[r2][c2] = new_d2
                        changed = True
                else:
                    max_d2 = max(d2)
                    new_d1 = {v for v in d1 if v < max_d2}
                    if len(new_d1) < len(d1):
                        domains[r1][c1] = new_d1
                        changed = True
                    min_d1 = min(d1)
                    new_d2 = {v for v in d2 if v > min_d1}
                    if len(new_d2) < len(d2):
                        domains[r2][c2] = new_d2
                        changed = True

    def check_consistency():
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None and not domains[i][j]:
                    return False
        return True

    def check_all_different():
        for i in range(N):
            empty = [j for j in range(N) if grid[i][j] is None]
            if not empty:
                continue
            avail = set()
            for j in empty:
                avail |= domains[i][j]
            if len(avail) < len(empty):
                return False
        for j in range(N):
            empty = [i for i in range(N) if grid[i][j] is None]
            if not empty:
                continue
            avail = set()
            for i in empty:
                avail |= domains[i][j]
            if len(avail) < len(empty):
                return False
        return True

    propagate()
    if not check_consistency() or not check_all_different():
        return "No Solution"

    def backtrack():
        min_size = float('inf')
        best_i, best_j = -1, -1
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    size = len(domains[i][j])
                    if size == 0:
                        return False
                    if size < min_size:
                        min_size = size
                        best_i, best_j = i, j
        if best_i == -1:
            return True

        original_domains = copy.deepcopy(domains)
        original_row_used = [s.copy() for s in row_used]
        original_col_used = [s.copy() for s in col_used]

        for v in list(domains[best_i][best_j]):
            grid[best_i][best_j] = v
            row_used[best_i].add(v)
            col_used[best_j].add(v)

            # forward checking
            fc_changed = False
            for k in range(N):
                if grid[best_i][k] is None and v in domains[best_i][k]:
                    domains[best_i][k].remove(v)
                    fc_changed = True
                if grid[k][best_j] is None and v in domains[k][best_j]:
                    domains[k][best_j].remove(v)
                    fc_changed = True

            propagate()

            if check_consistency() and check_all_different():
                if backtrack():
                    return True

            # restore
            grid[best_i][best_j] = None
            domains = copy.deepcopy(original_domains)
            row_used = [s.copy() for s in original_row_used]
            col_used = [s.copy() for s in original_col_used]

        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

