from collections import defaultdict, deque

def solve(observation):
    data = observation['data']
    N = len(data)
    delta = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    all_pos = [(i, j) for i in range(N) for j in range(N)]
    initial_possible_dirs = {}
    initial_possible = {}
    for pos in all_pos:
        r, c = pos
        initial_possible_dirs[pos] = [d for d in range(4) if 0 <= r + delta[d][0] < N and 0 <= c + delta[d][1] < N]
        poss_dirs = initial_possible_dirs[pos]
        configs = set()
        typ = data[r][c]
        if typ is None:
            configs.add(frozenset())
        if typ is None or typ == 'W':
            if 0 in poss_dirs and 2 in poss_dirs:
                configs.add(frozenset([0, 2]))
            if 1 in poss_dirs and 3 in poss_dirs:
                configs.add(frozenset([1, 3]))
        if typ is None or typ == 'B':
            for pair in [{0, 1}, {1, 2}, {2, 3}, {3, 0}]:
                if all(d in poss_dirs for d in pair):
                    if typ == 'B':
                        can = True
                        for d in pair:
                            ur = r + delta[d][0]
                            uc = c + delta[d][1]
                            if not (0 <= ur < N and 0 <= uc < N):
                                can = False
                                break
                            sr = ur + delta[d][0]
                            sc = uc + delta[d][1]
                            if not (0 <= sr < N and 0 <= sc < N):
                                can = False
                                break
                        if can:
                            configs.add(frozenset(pair))
                    else:
                        configs.add(frozenset(pair))
        initial_possible[pos] = configs

    def get_neighbor(pos, d):
        r, c = pos
        nr, nc = r + delta[d][0], c + delta[d][1]
        if 0 <= nr < N and 0 <= nc < N:
            return (nr, nc)
        return None

    def get_edge_key(p1, p2):
        return tuple(sorted([p1, p2]))

    def compute_current_poss(pos, edge_status):
        curr = initial_possible[pos].copy()
        for d in initial_possible_dirs[pos]:
            q = get_neighbor(pos, d)
            if q:
                ekey = get_edge_key(pos, q)
                status = edge_status.get(ekey, 0)
                if status == 1:
                    curr = {c for c in curr if d in c}
                if status == -1:
                    curr = {c for c in curr if d not in c}
        return curr

    def propagate(edge_status):
        queue = deque(all_pos)
        while queue:
            pos = queue.popleft()
            curr_poss = compute_current_poss(pos, edge_status)
            if not curr_poss:
                return "contradiction"
            if len(curr_poss) > 1:
                continue
            conf = list(curr_poss)[0]
            changed = False
            for d in initial_possible_dirs[pos]:
                q = get_neighbor(pos, d)
                if q:
                    ekey = get_edge_key(pos, q)
                    if d in conf:
                        if edge_status.get(ekey, 0) == -1:
                            return "contradiction"
                        if edge_status.get(ekey, 0) != 1:
                            edge_status[ekey] = 1
                            changed = True
                    else:
                        if edge_status.get(ekey, 0) == 1:
                            return "contradiction"
                        if edge_status.get(ekey, 0) != -1:
                            edge_status[ekey] = -1
                            changed = True
            if data[pos[0]][pos[1]] == 'B' and len(conf) == 2:
                for d in conf:
                    u = get_neighbor(pos, d)
                    s = get_neighbor(u, d)
                    ekey = get_edge_key(u, s)
                    if edge_status.get(ekey, 0) == -1:
                        return "contradiction"
                    if edge_status.get(ekey, 0) != 1:
                        edge_status[ekey] = 1
                        changed = True
            if changed:
                for d in initial_possible_dirs[pos]:
                    q = get_neighbor(pos, d)
                    if q:
                        queue.append(q)
                if data[pos[0]][pos[1]] == 'B' and len(conf) == 2:
                    for d in conf:
                        u = get_neighbor(pos, d)
                        s = get_neighbor(u, d)
                        queue.append(u)
                        queue.append(s)
        return "ok"

    def search(edge_status):
        if propagate(edge_status) == "contradiction":
            return None
        multi = []
        for pos in all_pos:
            curr = compute_current_poss(pos, edge_status)
            l = len(curr)
            if l == 0:
                return None
            if l > 1:
                multi.append((l, pos))
        if not multi:
            graph = defaultdict(list)
            conf_map = {}
            for pos in all_pos:
                curr = compute_current_poss(pos, edge_status)
                conf = list(curr)[0]
                conf_map[pos] = conf
                if len(conf) == 2:
                    for d in conf:
                        q = get_neighbor(pos, d)
                        graph[pos].append(q)
            non_zero = [pos for pos in all_pos if graph[pos]]
            if not non_zero:
                return None
            visited = set()
            def dfs(p):
                if p in visited:
                    return
                visited.add(p)
                for nb in graph[p]:
                    dfs(nb)
            dfs(non_zero[0])
            if len(visited) != len(non_zero):
                return None
            for pos in all_pos:
                if data[pos[0]][pos[1]] == 'W':
                    conf = conf_map[pos]
                    dirs = list(conf)
                    u = get_neighbor(pos, dirs[0])
                    w = get_neighbor(pos, dirs[1])
                    conf_u = conf_map[u]
                    turn_u = len(conf_u) == 2 and abs(list(conf_u)[0] - list(conf_u)[1]) % 4 == 1
                    conf_w = conf_map[w]
                    turn_w = len(conf_w) == 2 and abs(list(conf_w)[0] - list(conf_w)[1]) % 4 == 1
                    if not (turn_u or turn_w):
                        return None
            start = min(non_zero, key=lambda p: (p[0], p[1]))
            path = [start]
            prev = start
            current = graph[start][0]
            while current != start:
                path.append(current)
                nexts = [nb for nb in graph[current] if nb != prev]
                prev = current
                current = nexts[0]
            path.append(start)
            return path
        multi.sort()
        _, chosen_pos = multi[0]
        curr_poss = compute_current_poss(chosen_pos, edge_status)
        for conf in curr_poss:
            new_status = edge_status.copy()
            skip = False
            for d in initial_possible_dirs[chosen_pos]:
                q = get_neighbor(chosen_pos, d)
                if q:
                    ekey = get_edge_key(chosen_pos, q)
                    if d in conf:
                        if new_status.get(ekey, 0) == -1:
                            skip = True
                            break
                        new_status[ekey] = 1
                    else:
                        if new_status.get(ekey, 0) == 1:
                            skip = True
                            break
                        new_status[ekey] = -1
            if skip:
                continue
            if len(conf) == 2 and data[chosen_pos[0]][chosen_pos[1]] == 'B':
                skip = False
                for d in conf:
                    u = get_neighbor(chosen_pos, d)
                    s = get_neighbor(u, d)
                    ekey = get_edge_key(u, s)
                    if new_status.get(ekey, 0) == -1:
                        skip = True
                        break
                    new_status[ekey] = 1
                if skip:
                    continue
            result = search(new_status)
            if result is not None:
                return result
        return None

    result = search({})
    if result is None:
        return "No Solution"
    return result

