OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, 2, None, None, None, 2, None], [2, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, 6, None], [None, 1, None, 3, None, None, None], [None, None, None, None, None, None, None]]}

import sys
sys.setrecursionlimit(10000)  # For deeper recursion if needed

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid_pos(r, c):
        return 0 <= r < R and 0 <= c < C

    grid = [[0] * C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            if data[i][j] is not None:
                grid[i][j] = 1  # white

    def find_white_components(g):
        visited = [[False] * C for _ in range(R)]
        components = []
        comp_id = [[-1] * C for _ in range(R)]
        cid = 0
        for i in range(R):
            for j in range(C):
                if g[i][j] == 1 and not visited[i][j]:
                    comp = []
                    stack = [(i, j)]
                    visited[i][j] = True
                    while stack:
                        x, y = stack.pop()
                        comp.append((x, y))
                        comp_id[x][y] = cid
                        for dr, dc in directions:
                            nx, ny = x + dr, y + dc
                            if is_valid_pos(nx, ny) and g[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
                    components.append(comp)
                    cid += 1
        return components, comp_id

    def propagate(g):
        changes = []
        changed = True
        while changed:
            changed = False
            components, comp_id = find_white_components(g)

            # Check invalid components and complete islands
            for cid_, comp in enumerate(components):
                nums = [data[p][q] for p, q in comp if data[p][q] is not None]
                if len(nums) > 1:
                    undo_changes(g, changes)
                    return False, []
                if len(nums) == 1:
                    n = nums[0]
                    s = len(comp)
                    if s > n:
                        undo_changes(g, changes)
                        return False, []
                    if s == n:
                        # Surround with B
                        for p, q in comp:
