                                ni, nj = p + dr, q + dc
                                if is_valid_pos(ni, nj) and g[ni][nj] == 0:
                                    changes.append((ni, nj, 0))
                                    g[ni][nj] = 2
                                    changed = True

            # Check for 2x2 full B
            for i in range(R - 1):
                for j in range(C - 1):
                    if all(g[a][b] == 2 for a in [i, i + 1] for b in [j, j + 1]):
                        undo_changes(g, changes)
                        return False, []

            # Force W in almost 2x2 B
            for i in range(R - 1):
                for j in range(C - 1):
                    square = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
                    num_b = sum(g[a][b] == 2 for a, b in square)
                    num_u = sum(g[a][b] == 0 for a, b in square)
                    if num_b == 3 and num_u == 1:
                        for a, b in square:
