                        adj_ids = set()
                        for dr, dc in directions:
                            ni, nj = i + dr, j + dc
                            if is_valid_pos(ni, nj) and g[ni][nj] == 1:
                                adj_ids.add(comp_id[ni][nj])
                        if len(adj_ids) >= 2:
                            changes.append((i, j, 0))
                            g[i][j] = 2
                            changed = True

            # Isolated U comps -> B
            u_visited = [[False] * C for _ in range(R)]
            u_components = []
            for i in range(R):
                for j in range(C):
                    if g[i][j] == 0 and not u_visited[i][j]:
                        comp = []
                        stack = [(i, j)]
                        u_visited[i][j] = True
                        while stack:
                            x, y = stack.pop()
                            comp.append((x, y))
                            for dr, dc in directions:
                                nx, ny = x + dr, y + dc
                                if is_valid_pos(nx, ny) and g[nx][ny] == 0 and not u_visited[nx][ny]:
                                    u_visited[nx][ny] = True
                                    stack.append((nx, ny))
                        u_components.append(comp)
            for comp in u_components:
                if comp:
                    adj_white = False
                    for p, q in comp:
