            # Force for incomplete islands
            for cid_, comp in enumerate(components):
                nums = [data[p][q] for p, q in comp if data[p][q] is not None]
                if len(nums) == 1 and len(comp) < nums[0]:
                    n = nums[0]
                    s = len(comp)
                    k = n - s
                    frontier = set()
                    for p, q in comp:
                        for dr, dc in directions:
                            ni, nj = p + dr, q + dc
                            if is_valid_pos(ni, nj) and g[ni][nj] == 0:
