                        if k > 0:
                            undo_changes(g, changes)
                            return False, []
                        continue
                    possible = set()
                    u_visited = [[False] * C for _ in range(R)]
                    stack = list(frontier)
                    for fx, fy in frontier:
                        u_visited[fx][fy] = True
                        possible.add((fx, fy))
                    while stack:
                        x, y = stack.pop()
                        for dr, dc in directions:
                            nx, ny = x + dr, y + dc
