                    max_add = len(possible)
                    if max_add < k:
                        undo_changes(g, changes)
                        return False, []
                    if max_add == k:
                        for px, py in possible:
                            changes.append((px, py, 0))
                            g[px][py] = 1
                        changed = True

        return True, changes

    def undo_changes(g, chgs):
        for r, c, old in chgs:
            g[r][c] = old

    def check_black_connectable(g):
        b_pos = [(i, j) for i in range(R) for j in range(C) if g[i][j] == 2]
        if not b_pos:
            return True
        visited = [[False] * C for _ in range(R)]
        stack = [b_pos[0]]
        visited[b_pos[0][0]][b_pos[0][1]] = True
        reached = 1
        while stack:
            x, y = stack.pop()
            for dr, dc in directions:
                nx, ny = x + dr, y + dc
                if is_valid_pos(nx, ny) and not visited[nx][ny] and g[nx][ny] != 1:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
                    if g[nx][ny] == 2:
                        reached += 1
        return reached == len(b_pos)

    def check_all(g):
        # No 2x2 B
        for i in range(R - 1):
            for j in range(C - 1):
                if all(g[a][b] == 2 for a in [i, i + 1] for b in [j, j + 1]):
                    return False
        # Blacks connected
        b_pos = [(i, j) for i in range(R) for j in range(C) if g[i][j] == 2]
        if not b_pos:
            return True
        visited = [[False] * C for _ in range(R)]
        stack = [b_pos[0]]
        visited[b_pos[0][0]][b_pos[0][1]] = True
        reached = 1
        while stack:
            x, y = stack.pop()
            for dr, dc in directions:
                nx, ny = x + dr, y + dc
                if is_valid_pos(nx, ny) and not visited[nx][ny] and g[nx][ny] == 2:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
                    reached += 1
        if reached != len(b_pos):
            return False
        # White islands correct
        components, _ = find_white_components(g)
        for comp in components:
            nums = [data[p][q] for p, q in comp if data[p][q] is not None]
            if len(nums) != 1:
                return False
            if len(comp) != nums[0]:
                return False
        return True

    def find_branch_cell(g):
        components, comp_id = find_white_components(g)
        incompletes = set()
        for cid_, comp in enumerate(components):
            nums = [data[p][q] for p, q in comp if data[p][q] is not None]
            if len(nums) == 1 and len(comp) < nums[0]:
                incompletes.add(cid_)
        if incompletes:
            for i in range(R):
                for j in range(C):
                    if g[i][j] == 0:
                        adj_inc = False
                        for dr, dc in directions:
                            ni, nj = i + dr, j + dc
                            if is_valid_pos(ni, nj) and g[ni][nj] == 1 and comp_id[ni][nj] in incompletes:
                                adj_inc = True
                                break
                        if adj_inc:
                            return i, j
        # Any U
        for i in range(R):
            for j in range(C):
                if g[i][j] == 0:
                    return i, j
        return -1, -1

    def backtrack(g):
        success, changes = propagate(g)
        if not success:
            undo_changes(g, changes)
            return None
        if not check_black_connectable(g):
            undo_changes(g, changes)
            return None
        has_u = any(0 in row for row in g)
        if not has_u:
            if check_all(g):
                return g
            else:
                undo_changes(g, changes)
                return None
        i, j = find_branch_cell(g)
        if i == -1:
            undo_changes(g, changes)
            return None
        old = g[i][j]
        g[i][j] = 1
        res = backtrack(g)
        if res is not None:
            return res
        g[i][j] = old
        g[i][j] = 2
        res = backtrack(g)
        if res is not None:
            return res
        g[i][j] = old
        undo_changes(g, changes)
        return None

    res_grid = backtrack(grid)
    if res_grid is None:
        return "No Solution"
    else:
        out = [[None if cell == 1 else 'B' if cell == 2 else None for cell in row] for row in res_grid]
        return out

if __name__ == "__main__":
    print(solve(OBSERVATION))
