def solve(observation):
    tree = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']
    n = len(tree)
    m = len(tree[0])
    trees = []
    for i in range(n):
        for j in range(m):
            if tree[i][j] == 'T':
                trees.append((i, j))
    total_tents = sum(row_counts)
    if len(trees) != total_tents or len(trees) != sum(col_counts):
        return "No Solution"
    forbidden = [[False] * m for _ in range(n)]
    for i in range(n):
        if row_counts[i] == 0:
            for j in range(m):
                forbidden[i][j] = True
    for j in range(m):
        if col_counts[j] == 0:
            for i in range(n):
                forbidden[i][j] = True
    possible = [[] for _ in range(len(trees))]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for k, (ti, tj) in enumerate(trees):
        for di, dj in dirs:
            r = ti + di
            c = tj + dj
            if 0 <= r < n and 0 <= c < m and tree[r][c] is None and not forbidden[r][c]:
                count = 0
                for ddi, ddj in dirs:
                    rr = r + ddi
                    cc = c + ddj
                    if 0 <= rr < n and 0 <= cc < m and tree[rr][cc] == 'T':
                        count += 1
                if count == 1:
                    possible[k].append((r, c))
    for pos in possible:
        if not pos:
            return "No Solution"
    assigned = [None] * len(trees)
    def backtrack(unassigned, current_poss, placed, current_row, current_col):
        if not unassigned:
            if current_row == row_counts and current_col == col_counts:
                return True
            return False
        min_len = float('inf')
        min_k = -1
        for k in unassigned:
            l = len(current_poss[k])
            if l < min_len:
                min_len = l
                min_k = k
        if min_len == 0:
            return False
        k = min_k
        for pos_idx in range(len(current_poss[k])):
            r, c = current_poss[k][pos_idx]
            touch = False
            for pr, pc in placed:
                if max(abs(pr - r), abs(pc - c)) <= 1:
                    touch = True
                    break
            if touch:
                continue
            new_placed = placed + [(r, c)]
            new_current_row = current_row[:]
            new_current_row[r] += 1
            if new_current_row[r] > row_counts[r]:
                continue
            new_current_col = current_col[:]
            new_current_col[c] += 1
            if new_current_col[c] > col_counts[c]:
                continue
            new_unassigned = unassigned - {k}
            new_current_poss = [list(current_poss[i]) for i in range(len(possible))]
            can_continue = True
            for k2 in new_unassigned:
                to_remove = []
                for idx in range(len(new_current_poss[k2])):
                    r2, c2 = new_current_poss[k2][idx]
                    if max(abs(r2 - r), abs(c2 - c)) <= 1:
                        to_remove.append(idx)
                to_remove.sort(reverse=True)
                for idx in to_remove:
                    del new_current_poss[k2][idx]
                if len(new_current_poss[k2]) == 0:
                    can_continue = False
                    break
            if not can_continue:
                continue
            if backtrack(new_unassigned, new_current_poss, new_placed, new_current_row, new_current_col):
                assigned[k] = (r, c)
                return True
        return False
    unassigned = set(range(len(trees)))
    current_poss = [list(p) for p in possible]
    placed = []
    current_row = [0] * n
    current_col = [0] * m
    if backtrack(unassigned, current_poss, placed, current_row, current_col):
        grid = [[None] * m for _ in range(n)]
        for k in range(len(trees)):
            r, c = assigned[k]
            grid[r][c] = 't'
        return grid
    return "No Solution"

