OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

import collections

def solve(observation):
    data = observation['data']
    N = len(data)
    grid = [0] * (N * N)
    for r in range(N):
        for c in range(N):
            grid[r * N + c] = data[r][c]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(pos):
        r, c = divmod(pos, N)
        neigh = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neigh.append(nr * N + nc)
        return neigh

    assignment = [None] * (N * N)
    can_white = [True] * (N * N)
    can_black = [True] * (N * N)
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]

    def propagate(pos, value):
        trail = []
        forced = []
        queue = collections.deque()

        r, c = divmod(pos, N)
        num = grid[pos]

        if value is False:  # white
            row_used[r].add(num)
            col_used[c].add(num)
            # Propagate to same row
            for j in range(N):
                p2 = r * N + j
                if p2 != pos and assignment[p2] is None and grid[p2] == num:
                    if can_white[p2]:
                        trail.append((p2, True, True))
                        can_white[p2] = False
                        queue.append(p2)
            # Propagate to same col
            for i in range(N):
                p2 = i * N + c
                if p2 != pos and assignment[p2] is None and grid[p2] == num:
                    if can_white[p2]:
                        trail.append((p2, True, True))
                        can_white[p2] = False
                        queue.append(p2)
        else:  # black
            for np in get_neighbors(pos):
                if assignment[np] is None:
                    if can_black[np]:
                        trail.append((np, False, True))
                        can_black[np] = False
                        queue.append(np)

        while queue:
            p = queue.popleft()
            if assignment[p] is not None:
                continue
            cw = can_white[p]
            cb = can_black[p]
            if not cw and not cb:
                return False, trail, forced
            if cw and not cb:
                # force white
                assignment[p] = False
                ok, sub_trail, sub_forced = propagate(p, False)
                if not ok:
                    assignment[p] = None
                    return False, trail, forced
                trail.extend(sub_trail)
                forced.append(p)
                forced.extend(sub_forced)
            elif not cw and cb:
                # force black
                assignment[p] = True
                ok, sub_trail, sub_forced = propagate(p, True)
                if not ok:
                    assignment[p] = None
                    return False, trail, forced
                trail.extend(sub_trail)
                forced.append(p)
                forced.extend(sub_forced)

        return True, trail, forced

    def find_unassigned():
        for p in range(N * N):
            if assignment[p] is None:
                return p
        return -1

    def is_connected():
        whites = [p for p in range(N * N) if assignment[p] is False]
        if not whites:
            return True
        visited = [False] * (N * N)
        start = whites[0]
        stack = [start]
        visited[start] = True
        count = 1
        while stack:
            pos = stack.pop()
            for np in get_neighbors(pos):
                if assignment[np] is False and not visited[np]:
                    visited[np] = True
                    stack.append(np)
                    count += 1
        return count == len(whites)

    def backtrack():
        pos = find_unassigned()
        if pos == -1:
            if is_connected():
                mask = [[None] * N for _ in range(N)]
                for rr in range(N):
                    for cc in range(N):
                        if assignment[rr * N + cc] is True:
                            mask[rr][cc] = 'B'
                return mask
            return None

        r, c = divmod(pos, N)
        num = grid[pos]

        # Try white
        if can_white[pos]:
            assignment[pos] = False
            row_used[r].add(num)
            col_used[c].add(num)
            ok, trail, forced = propagate(pos, False)
            if ok:
                result = backtrack()
                if result is not None:
                    return result
            # undo
            row_used[r].remove(num)
            col_used[c].remove(num)
            for fp in forced:
                fr, fc = divmod(fp, N)
                fnum = grid[fp]
                if assignment[fp] is False:
                    row_used[fr].remove(fnum)
                    col_used[fc].remove(fnum)
                assignment[fp] = None
            for tp, is_w, old in trail:
                if is_w:
                    can_white[tp] = old
                else:
                    can_black[tp] = old
            assignment[pos] = None

        # Try black
        if can_black[pos]:
            assignment[pos] = True
            ok, trail, forced = propagate(pos, True)
            if ok:
                result = backtrack()
                if result is not None:
                    return result
            # undo
            for fp in forced:
                fr, fc = divmod(fp, N)
                fnum = grid[fp]
                if assignment[fp] is False:
                    row_used[fr].remove(fnum)
                    col_used[fc].remove(fnum)
                assignment[fp] = None
            for tp, is_w, old in trail:
                if is_w:
                    can_white[tp] = old
                else:
                    can_black[tp] = old
            assignment[pos] = None

        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
