                continue
            adj_trees = []
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and tree_grid[ni][nj] == 'T':
                    adj_trees.append((ni, nj))
            if len(adj_trees) == 1:
                possible[adj_trees[0]].add((i, j))

    if any(len(possible[t]) == 0 for t in trees):
        return "No Solution"

    placed = {}
    tent_row_count = [0] * n
    tent_col_count = [0] * m

    def backtrack():
        while True:
            changed = False

            # Place singletons
            for tree in [t for t in trees if t not in placed]:
                poss = possible[tree]
                if len(poss) == 0:
                    return None
                if len(poss) == 1:
                    pos = next(iter(poss))
                    # Check touching with placed
                    if any(max(abs(pos[0] - p[0]), abs(pos[1] - p[1])) <= 1 for p in placed.values()):
                        return None
                    placed[tree] = pos
                    tent_row_count[pos[0]] += 1
                    tent_col_count[pos[1]] += 1
                    # Remove touching
                    for otree in [t for t in trees if t not in placed]:
                        to_remove = [p for p in possible[otree] if max(abs(p[0] - pos[0]), abs(p[1] - pos[1])) <= 1]
                        for p in to_remove:
                            possible[otree].remove(p)
                    changed = True

            # Row count propagation
            for r in range(n):
                current = tent_row_count[r]
                remaining = row_counts[r] - current
                if remaining < 0:
                    return None
                may = []
                must = []
                for tree in [t for t in trees if t not in placed]:
                    poss_in = [p for p in possible[tree] if p[0] == r]
                    if poss_in:
                        may.append(tree)
                        if len(poss_in) == len(possible[tree]):
                            must.append(tree)
                if len(must) > remaining or len(may) < remaining:
                    return None
                if len(must) == remaining:
                    for tree in set(may) - set(must):
                        poss_in = [p for p in possible[tree] if p[0] == r]
                        if poss_in:
                            changed = True
                            for p in poss_in:
                                possible[tree].remove(p)
                if len(may) == remaining:
                    for tree in may:
                        poss_out = [p for p in possible[tree] if p[0] != r]
                        if poss_out:
                            changed = True
                            for p in poss_out:
                                possible[tree].remove(p)

            # Column count propagation
            for c in range(m):
                current = tent_col_count[c]
                remaining = col_counts[c] - current
                if remaining < 0:
                    return None
                may = []
                must = []
                for tree in [t for t in trees if t not in placed]:
                    poss_in = [p for p in possible[tree] if p[1] == c]
                    if poss_in:
                        may.append(tree)
                        if len(poss_in) == len(possible[tree]):
                            must.append(tree)
                if len(must) > remaining or len(may) < remaining:
                    return None
                if len(must) == remaining:
                    for tree in set(may) - set(must):
                        poss_in = [p for p in possible[tree] if p[1] == c]
                        if poss_in:
                            changed = True
                            for p in poss_in:
                                possible[tree].remove(p)
                if len(may) == remaining:
                    for tree in may:
                        poss_out = [p for p in possible[tree] if p[1] != c]
                        if poss_out:
                            changed = True
                            for p in poss_out:
                                possible[tree].remove(p)

            if not changed:
                break

        if len(placed) == len(trees):
            if all(tent_row_count[r] == row_counts[r] for r in range(n)) and all(tent_col_count[c] == col_counts[c] for c in range(m)):
                grid = [[None] * m for _ in range(n)]
                for pos in placed.values():
                    grid[pos[0]][pos[1]] = 't'
                return grid
            else:
                return None

        # Branch
        candidates = [(len(possible[t]), t) for t in trees if t not in placed and len(possible[t]) > 0]
        if not candidates:
            return None
        candidates.sort()
        _, chosen_tree = candidates[0]
        for pos in list(possible[chosen_tree]):
            # Save state
            placed_copy = placed.copy()
            row_count_copy = tent_row_count[:]
            col_count_copy = tent_col_count[:]
            removed = {}
            # Place
            if any(max(abs(pos[0] - p[0]), abs(pos[1] - p[1])) <= 1 for p in placed.values()):
                continue
            placed[chosen_tree] = pos
            tent_row_count[pos[0]] += 1
            tent_col_count[pos[1]] += 1
            if tent_row_count[pos[0]] > row_counts[pos[0]] or tent_col_count[pos[1]] > col_counts[pos[1]]:
                placed = placed_copy
                tent_row_count = row_count_copy
                tent_col_count = col_count_copy
                continue
            # Remove touching
            for otree in [t for t in trees if t not in placed]:
                removed[otree] = []
                for p in list(possible[otree]):
                    if max(abs(p[0] - pos[0]), abs(p[1] - pos[1])) <= 1:
                        possible[otree].remove(p)
                        removed[otree].append(p)
            # Recurse
            result = backtrack()
            if result is not None:
                return result
            # Undo
            placed = placed_copy
            tent_row_count = row_count_copy
            tent_col_count = col_count_copy
            for otree, rems in removed.items():
                for p in rems:
                    possible[otree].add(p)
        return None

    result = backtrack()
    if result is None:
        return "No Solution"
    return result

