from itertools import permutations

def visible_left(row):
    count = 0
    max_h = -1
    for h in row:
        if h > max_h:
            count += 1
            max_h = h
    return count

def visible_right(row):
    return visible_left(row[::-1])

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    possible_rows = [[] for _ in range(N)]
    all_perms = list(permutations(range(1, N + 1)))
    for i in range(N):
        left_clue = L[i]
        right_clue = R[i]
        for p in all_perms:
            perm_list = list(p)
            if visible_left(perm_list) == left_clue and visible_right(perm_list) == right_clue:
                possible_rows[i].append(perm_list)

    grid = [[0] * N for _ in range(N)]
    used = [set() for _ in range(N)]

    def is_possible(k):
        for c in range(N):
            rem_set = set(range(1, N + 1)) - used[c]
            r = len(rem_set)

            # Top
            partial_seq = [grid[t][c] for t in range(k)]
            vis_so_far = visible_left(partial_seq)
            max_so_far = max(partial_seq) if k > 0 else -1
            count_greater = sum(1 for x in rem_set if x > max_so_far)
            min_add = 1 if rem_set and max(rem_set) > max_so_far else 0
            min_vis = vis_so_far + min_add
            max_vis = vis_so_far + count_greater
            if not (min_vis <= U[c] <= max_vis):
                return False

            # Bottom
            M = max(rem_set) if rem_set else -1
            known_partial = partial_seq[::-1]
            add_k = 0
            current_max_prefix = -1
            for j in range(k):
                max_prefix = current_max_prefix
                height = known_partial[j]
                if height > max(M, max_prefix):
                    add_k += 1
                current_max_prefix = max(current_max_prefix, height)
            min_vis_d = (1 if r > 0 else 0) + add_k
            max_vis_d = r + add_k
            if not (min_vis_d <= D[c] <= max_vis_d):
                return False

        return True

    def backtrack(cur_row):
        if cur_row == N:
            # Exact check for completeness
            for c in range(N):
                col_seq = [grid[r][c] for r in range(N)]
                if visible_left(col_seq) != U[c] or visible_left(col_seq[::-1]) != D[c]:
                    return False
            return True

        for p in possible_rows[cur_row]:
            if all(p[j] not in used[j] for j in range(N)):
                grid[cur_row] = p[:]
                for j in range(N):
                    used[j].add(p[j])

                if is_possible(cur_row + 1):
                    if backtrack(cur_row + 1):
                        return True

                for j in range(N):
                    used[j].remove(p[j])

        return False

    if backtrack(0):
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
