from collections import deque

def get_adj(r, c, N):
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    return [(r + dr, c + dc) for dr, dc in dirs if 0 <= r + dr < N and 0 <= c + dc < N]

def is_adjacent(a, b):
    ar, ac = a
    br, bc = b
    return abs(ar - br) + abs(ac - bc) == 1

def is_straight(r, c, neighbors, N):
    if len(neighbors[r][c]) != 2:
        return False
    n1 = neighbors[r][c][0]
    n2 = neighbors[r][c][1]
    v1 = (n1[0] - r, n1[1] - c)
    v2 = (n2[0] - r, n2[1] - c)
    return v2 == (-v1[0], -v1[1])

def verify(w_conditions, neighbors, N):
    for p1, p2 in w_conditions:
        completed1 = len(neighbors[p1[0]][p1[1]]) == 2
        completed2 = len(neighbors[p2[0]][p2[1]]) == 2
        if completed1 and completed2:
            str1 = is_straight(p1[0], p1[1], neighbors, N)
            str2 = is_straight(p2[0], p2[1], neighbors, N)
            if str1 and str2:
                return False
    return True

def complete_vertex(r, c, data, neighbors, must_straight_count, w_conditions):
    typ = data[r][c]
    n1 = neighbors[r][c][0]
    n2 = neighbors[r][c][1]
    v1 = (n1[0] - r, n1[1] - c)
    v2 = (n2[0] - r, n2[1] - c)
    is_str = v2 == (-v1[0], -v1[1])
    added_c = []
    added_cond = False
    if typ is not None:
        if typ == 'W':
            if not is_str:
                return False, added_c, added_cond
            w_conditions.append(((n1[0], n1[1]), (n2[0], n2[1])))
            added_cond = True
        elif typ == 'B':
            if is_str:
                return False, added_c, added_cond
            for nn in [(n1[0], n1[1]), (n2[0], n2[1])]:
                if nn not in must_straight_count:
                    must_straight_count[nn] = 0
                must_straight_count[nn] += 1
                added_c.append(nn)
    if (r, c) in must_straight_count and must_straight_count[(r, c)] > 0 and not is_str:
        return False, added_c, added_cond
    return True, added_c, added_cond

def backtrack(path, used, must_straight_count, w_conditions, data, neighbors, N, clue_set):
    left = path[0]
    right = path[-1]
    # try close
    if len(used & clue_set) == len(clue_set) and is_adjacent(left, right) and right not in neighbors[left[0]][left[1]]:
        # add connection
        neighbors[left[0]][left[1]].append(right)
        neighbors[right[0]][right[1]].append(left)
        # complete left
        succ_l, added_cl, cond_l = complete_vertex(left[0], left[1], data, neighbors, must_straight_count, w_conditions)
        if succ_l:
            # complete right
            succ_r, added_cr, cond_r = complete_vertex(right[0], right[1], data, neighbors, must_straight_count, w_conditions)
            if succ_r and verify(w_conditions, neighbors, N):
                return list(path) + [path[0]]
            # back right
            for pp in added_cr:
                must_straight_count[pp] -= 1
                if must_straight_count[pp] == 0:
                    del must_straight_count[pp]
            if cond_r:
                w_conditions.pop()
        # back left
        for pp in added_cl:
            must_straight_count[pp] -= 1
            if must_straight_count[pp] == 0:
                del must_straight_count[pp]
        if cond_l:
            w_conditions.pop()
        # remove connection
        neighbors[left[0]][left[1]].pop()
        neighbors[right[0]][right[1]].pop()
    # extend
    possible_left = [p for p in get_adj(left[0], left[1], N) if p not in used]
    possible_right = [p for p in get_adj(right[0], right[1], N) if p not in used]
    exts = []
    if len(possible_left) <= len(possible_right):
        exts = [(possible_left, 0), (possible_right, 1)]
    else:
        exts = [(possible_right, 1), (possible_left, 0)]
    for poss, side in exts:
        for new_p in poss:
            old_end = left if side == 0 else right
            if side == 0:
                path.appendleft(new_p)
            else:
                path.append(new_p)
            used.add(new_p)
            neighbors[new_p[0]][new_p[1]].append(old_end)
            neighbors[old_end[0]][old_end[1]].append(new_p)
            succ, added_c, added_cond = complete_vertex(old_end[0], old_end[1], data, neighbors, must_straight_count, w_conditions)
            if succ and verify(w_conditions, neighbors, N):
                res = backtrack(path, used, must_straight_count, w_conditions, data, neighbors, N, clue_set)
                if res is not None:
                    return res
            # back
            if added_cond:
                w_conditions.pop()
            for pp in added_c:
                must_straight_count[pp] -= 1
                if must_straight_count[pp] == 0:
                    del must_straight_count[pp]
            neighbors[new_p[0]][new_p[1]].pop()
            neighbors[old_end[0]][old_end[1]].pop()
            used.remove(new_p)
            if side == 0:
                path.popleft()
            else:
                path.pop()
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    clues = [(i, j) for i in range(N) for j in range(N) if data[i][j] is not None]
    clue_set = set(clues)
    # find start
    min_num = float('inf')
    start = None
    for pr in clues:
        r, c = pr
        adj = get_adj(r, c, N)
        count = 0
        for ii in range(len(adj)):
            for jj in range(ii + 1, len(adj)):
                s = adj[ii]
                t = adj[jj]
                v1 = (s[0] - r, s[1] - c)
                v2 = (t[0] - r, t[1] - c)
                opp = v2 == (-v1[0], -v1[1])
                if data[r][c] == 'W' and opp:
                    count += 1
                elif data[r][c] == 'B' and not opp:
                    count += 1
        if 0 < count < min_num:
            min_num = count
            start = pr
    if start is None:
        return "No Solution"
    r, c = start
    adj = get_adj(r, c, N)
    possible_pairs = []
    for ii in range(len(adj)):
        for jj in range(ii + 1, len(adj)):
            s = adj[ii]
            t = adj[jj]
            if s > t:
                s, t = t, s
            v1 = (s[0] - r, s[1] - c)
            v2 = (t[0] - r, t[1] - c)
            opp = v2 == (-v1[0], -v1[1])
            if (data[r][c] == 'W' and opp) or (data[r][c] == 'B' and not opp):
                possible_pairs.append((s, t))
    for sp, tp in possible_pairs:
        neighbors = [[[] for _ in range(N)] for _ in range(N)]
        path = deque([sp, start, tp])
        used = set([sp, start, tp])
        must_straight_count = {}
        w_conditions = []
        # add connections
        neighbors[sp[0]][sp[1]].append(start)
        neighbors[start[0]][start[1]].append(sp)
        neighbors[start[0]][start[1]].append(tp)
        neighbors[tp[0]][tp[1]].append(start)
        # complete start
        succ, added_c, added_cond = complete_vertex(start[0], start[1], data, neighbors, must_straight_count, w_conditions)
        if not succ:
            continue
        if not verify(w_conditions, neighbors, N):
            # back
            for pp in added_c:
                must_straight_count[pp] -= 1
                if must_straight_count[pp] == 0:
                    del must_straight_count[pp]
            if added_cond:
                w_conditions.pop()
            continue
        res = backtrack(path, used, must_straight_count, w_conditions, data, neighbors, N, clue_set)
        if res is not None:
            return res
    return "No Solution"

