import copy
from collections import defaultdict, deque

def solve(observation):
    N = len(observation['region'])
    regions = defaultdict(list)
    clues = {}
    for i in range(N):
        for j in range(N):
            rid = observation['region'][i][j]
            regions[rid].append((i, j))
            if observation['data'][i][j] is not None:
                if rid in clues:
                    return "No Solution"  # invalid
                clues[rid] = observation['data'][i][j]

    grid = [[None for _ in range(N)] for _ in range(N)]

    # Initial forcing for 0
    for rid in list(clues):
        if clues[rid] == 0:
            for ci, cj in regions[rid]:
                grid[ci][cj] = 'W'

    ans = backtrack(grid, N, observation['region'], regions, clues)
    if ans is None:
        return "No Solution"
    return ans

def backtrack(grid, N, region_map, regions, clues):
    if not propagate(grid, N, region_map, regions, clues):
        return None

    # Check if all decided
    undecided = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                undecided = (i, j)
                break
        if undecided is not None:
            break

    if undecided is None:
        if check_global(grid, N, region_map):
            return [[ 'B' if grid[r][c] == 'B' else None for c in range(N)] for r in range(N)]
        return None

    i, j = undecided

    # Try 'W'
    grid_w = copy.deepcopy(grid)
    grid_w[i][j] = 'W'
    res = backtrack(grid_w, N, region_map, regions, clues)
    if res is not None:
        return res

    # Try 'B'
    grid_b = copy.deepcopy(grid)
    grid_b[i][j] = 'B'
    res = backtrack(grid_b, N, region_map, regions, clues)
    if res is not None:
        return res

    return None

def propagate(grid, N, region_map, regions, clues):
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    def is_valid(i, j):
        return 0 <= i < N and 0 <= j < N

    queue = deque()
    processed = set()

    # Add all set cells to queue
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                queue.append((i, j))

    while queue:
        i, j = queue.popleft()
        if (i, j) in processed:
            continue
        processed.add((i, j))

        val = grid[i][j]
        if val == 'B':
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if is_valid(ni, nj):
                    nval = grid[ni][nj]
                    if nval == 'B':
                        return False
                    if nval is None:
                        grid[ni][nj] = 'W'
                        queue.append((ni, nj))

        # Check region
        rid = region_map[i][j]
        b_count = 0
        u_cells = []
        for ci, cj in regions[rid]:
            cval = grid[ci][cj]
            if cval == 'B':
                b_count += 1
            elif cval is None:
                u_cells.append((ci, cj))

        u_count = len(u_cells)
        if rid in clues:
            k = clues[rid]
            if b_count > k or b_count + u_count < k:
                return False
            if b_count == k and u_count > 0:
                for ci, cj in u_cells:
                    grid[ci][cj] = 'W'
                    queue.append((ci, cj))
            elif b_count + u_count == k and u_count > 0:
                for ci, cj in u_cells:
                    grid[ci][cj] = 'B'
                    queue.append((ci, cj))

    return True

def check_global(grid, N, region_map):
    # Check white connected
    whites = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 'W']
    if not whites:
        connected = True
    else:
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        visited = set()
        q = deque([whites[0]])
        visited.add(whites[0])
        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and grid[nx][ny] == 'W' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    q.append((nx, ny))
        connected = len(visited) == len(whites)

    if not connected:
        return False

    # Check segments in rows
    for i in range(N):
        j = 0
        while j < N:
            if grid[i][j] == 'W':
                seg_regs = set()
                while j < N and grid[i][j] == 'W':
                    seg_regs.add(region_map[i][j])
                    j += 1
                if len(seg_regs) > 2:
                    return False
            else:
                j += 1

    # Check segments in columns
    for j in range(N):
        i = 0
        while i < N:
            if grid[i][j] == 'W':
                seg_regs = set()
                while i < N and grid[i][j] == 'W':
                    seg_regs.add(region_map[i][j])
                    i += 1
                if len(seg_regs) > 2:
                    return False
            else:
                i += 1

    return True

if __name__ == "__main__":
    print(solve(OBSERVATION))
