        lst = []
        for m in range(1 << n):
            s = sum(col_weights[j] for j in range(n) if m & (1 << j))
            if s == t:
                lst.append(m)
        possible_masks.append(lst)
    # Order rows by increasing number of possible masks for heuristic
    order = sorted(range(n), key=lambda i: len(possible_masks[i]))
    def dfs(pos, current_sums, chosen):
        if pos == n:
            return chosen[:]
        row = order[pos]
        for mask in possible_masks[row]:
            new_sums = current_sums[:]
            for j in range(n):
                if mask & (1 << j):
                    new_sums[j] += row_weights[row]
            if any(new_sums[j] > col_targets[j] for j in range(n)):
                continue
            # Get remaining weights
            remaining_rows = order[pos+1:]
            remaining_weights = [row_weights[r] for r in remaining_rows]
            # Check achievability for each column
            can = True
            for j in range(n):
                rem = col_targets[j] - new_sums[j]
                if not can_achieve(rem, remaining_weights):
                    can = False
                    break
            if not can:
                continue
            chosen[row] = mask
            res = dfs(pos + 1, new_sums, chosen)
            if res is not None:
                return res
        return None
    def can_achieve(target, weights):
        if target < 0:
            return False
        dp = [False] * (target + 1)
        dp[0] = True
        for w in weights:
            if w > target:
                continue
            for s in range(target, w - 1, -1):
                if dp[s - w]:
                    dp[s] = True
        return dp[target]
    chosen = dfs(0, [0] * n, [0] * n)
    if chosen is None:
        return "No Solution"
    # Build the grid
    grid = [[None] * n for _ in range(n)]
    for i in range(n):
        mask = chosen[i]
        for j in range(n):
            if mask & (1 << j):
                grid[i][j] = 'B'
    return grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
