def get_max_steps(r, c, dr, dc, N):
    steps = 0
    cr, cc = r + dr, c + dc
    while 0 <= cr <= N and 0 <= cc <= N:
        steps += 1
        cr += dr
        cc += dc
    return steps

def get_possible_pairs(r, c, color, num, N):
    possible = []
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    if color == 'B':
        vert = [d for d in dirs if d[0] != 0]
        horiz = [d for d in dirs if d[1] != 0]
        for vd in vert:
            nr = r + vd[0]
            nc = c + vd[1]
            if 0 <= nr <= N and 0 <= nc <= N:
                max_v = get_max_steps(r, c, vd[0], vd[1], N)
                for hd in horiz:
                    nrh = r + hd[0]
                    nch = c + hd[1]
                    if 0 <= nrh <= N and 0 <= nch <= N:
                        max_h = get_max_steps(r, c, hd[0], hd[1], N)
                        if 2 <= num <= max_v + max_h:
                            pair = frozenset([(nr, nc), (nrh, nch)])
                            possible.append(pair)
    else:  # 'W'
        # horizontal
        if c > 0 and c < N:
            max_left = get_max_steps(r, c, 0, -1, N)
            max_right = get_max_steps(r, c, 0, 1, N)
            if 2 <= num <= max_left + max_right:
                pair = frozenset([(r, c - 1), (r, c + 1)])
                possible.append(pair)
        # vertical
        if r > 0 and r < N:
            max_up = get_max_steps(r, c, -1, 0, N)
            max_down = get_max_steps(r, c, 1, 0, N)
            if 2 <= num <= max_up + max_down:
                pair = frozenset([(r - 1, c), (r + 1, c)])
                possible.append(pair)
    return possible

def is_adjacent(p1, p2):
    r1, c1 = p1
    r2, c2 = p2
    return abs(r1 - r2) + abs(c1 - c2) == 1

def get_adj(p, N):
    r, c = p
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    adj = []
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr <= N and 0 <= nc <= N:
            adj.append((nr, nc))
    return adj

def compute_arm(path, i, left=True):
    if left:
        sign = -1
        end = 0
    else:
        sign = 1
        end = len(path) - 1
    length = 0
    current = path[i]
    j = i + sign
    dir = None
    while sign * j <= sign * end:
        next_pos = path[j]
        vec = (next_pos[0] - current[0], next_pos[1] - current[1])
        if length == 0:
            dir = vec
            length = 1
        else:
            if vec != dir:
                return length, True, dir
        current = next_pos
        j += sign
    return length, False, dir

def get_max_additional(end_pos, dir, visited, N):
    count = 0
    cr, cc = end_pos[0], end_pos[1]
    dr, dc = dir
    while True:
        cr += dr
        cc += dc
        if not (0 <= cr <= N and 0 <= cc <= N):
            break
        if (cr, cc) in visited:
            break
        count += 1
    return count

def check_pruning(path, visited, possible_pairs, clue_to_num, N):
    for i in range(1, len(path) - 1):
        pos = path[i]
        if pos in possible_pairs:
            neighbors = frozenset([path[i - 1], path[i + 1]])
            if neighbors not in possible_pairs[pos]:
                return False
        if pos in clue_to_num:
            num = clue_to_num[pos]
            l_length, l_complete, l_dir = compute_arm(path, i, left=True)
            r_length, r_complete, r_dir = compute_arm(path, i, left=False)
            min_l = l_length if l_complete else l_length
            max_l = l_length if l_complete else l_length + get_max_additional(path[0], l_dir, visited, N)
            min_r = r_length if r_complete else r_length
            max_r = r_length if r_complete else r_length + get_max_additional(path[-1], r_dir, visited, N)
            min_sum = min_l + min_r
            max_sum = max_l + max_r
            if not (min_sum <= num <= max_sum):
                return False
    return True

def compute_cycle_arm(path, m, i, left=True):
    if left:
        sign = -1
    else:
        sign = 1
    length = 0
    j = i
    dir = None
    while True:
        next_j = (j + sign) % m
        next_pos = path[next_j]
        current = path[j]
        vec = (next_pos[0] - current[0], next_pos[1] - current[1])
        if length == 0:
            dir = vec
            length = 1
        else:
            if vec != dir:
                return length
        j = next_j
        if j == i:
            break
    return length

def dfs(path, visited, visited_clues, possible_pairs, clue_to_num, N):
    if len(path) > (N + 1) ** 2:
        return None
    if len(visited_clues) == len(clue_to_num):
        end1 = path[0]
        end2 = path[-1]
        if is_adjacent(end1, end2):
            # check local for ends
            if end1 in possible_pairs:
                neighbors = frozenset([path[1], end2])
                if neighbors not in possible_pairs[end1]:
                    return None
            if end2 in possible_pairs:
                neighbors = frozenset([path[-2], end1])
                if neighbors not in possible_pairs[end2]:
                    return None
            # check lengths
            m = len(path)
            good = True
            for pos, num in clue_to_num.items():
                i = path.index(pos)
                l_length = compute_cycle_arm(path, m, i, left=True)
                r_length = compute_cycle_arm(path, m, i, left=False)
                if l_length + r_length != num:
                    good = False
                    break
            if good:
                return path + [path[0]]
    # extend front
    for nr, nc in get_adj(path[0], N):
        if (nr, nc) not in visited:
            new_path = [(nr, nc)] + path
            new_visited = visited | {(nr, nc)}
            new_clues = visited_clues | {(nr, nc)} if (nr, nc) in clue_to_num else visited_clues
            if check_pruning(new_path, new_visited, possible_pairs, clue_to_num, N):
                res = dfs(new_path, new_visited, new_clues, possible_pairs, clue_to_num, N)
                if res is not None:
                    return res
    # extend back
    for nr, nc in get_adj(path[-1], N):
        if (nr, nc) not in visited:
            new_path = path + [(nr, nc)]
            new_visited = visited | {(nr, nc)}
            new_clues = visited_clues | {(nr, nc)} if (nr, nc) in clue_to_num else visited_clues
            if check_pruning(new_path, new_visited, possible_pairs, clue_to_num, N):
                res = dfs(new_path, new_visited, new_clues, possible_pairs, clue_to_num, N)
                if res is not None:
                    return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    clue_to_num = {}
    possible_pairs = {}
    for r in range(N + 1):
        for c in range(N + 1):
            if data[r][c] is not None:
                color = data[r][c][0]
                num = int(data[r][c][1:])
                clue_to_num[(r, c)] = num
                p = get_possible_pairs(r, c, color, num, N)
                possible_pairs[(r, c)] = p
                if not p:
                    return "No Solution"
    if not clue_to_num:
        return [(0, 0), (0, 0)]  # empty, but not
    lengths = [len(possible_pairs[pos]) for pos in possible_pairs]
    min_len = min(lengths)
    start = next(pos for pos in possible_pairs if len(possible_pairs[pos]) == min_len)
    path = [start]
    visited = set([start])
    visited_clues = set([start])
    res = dfs(path, visited, visited_clues, possible_pairs, clue_to_num, N)
    if res is None:
        return "No Solution"
    return res

if __name__ == "__main__":
    print(solve(OBSERVATION))
