def solve(observation):
    data = observation['data']
    N = len(data)
    clues = set((r, c) for r in range(N) for c in range(N) if data[r][c] is not None)
    delta = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def get_adj(pos, N):
        r, c = pos
        res = []
        for dr, dc in delta:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                res.append((nr, nc))
        return res

    def is_adjacent(p1, p2):
        return p2 in get_adj(p1, N)

    def get_dir(v, n):
        dr = n[0] - v[0]
        dc = n[1] - v[1]
        return {(-1, 0): 0, (0, 1): 1, (1, 0): 2, (0, -1): 3}[(dr, dc)]

    def check_conditions(cycle, data, N):
        m = len(cycle) - 1
        neigh = {}
        for i in range(m):
            a = cycle[i]
            b = cycle[i + 1]
            if a not in neigh:
                neigh[a] = []
            neigh[a].append(b)
            if b not in neigh:
                neigh[b] = []
            neigh[b].append(a)
        def is_straight(u):
            if u not in neigh:
                return False
            a, b = neigh[u]
            d1 = get_dir(u, a)
            d2 = get_dir(u, b)
            return (d1 + 2) % 4 == d2
        def is_turn(u):
            return not is_straight(u)
        for r in range(N):
            for c in range(N):
                typ = data[r][c]
                if typ is None:
                    continue
                v = (r, c)
                if v not in neigh:
                    return False
                nbs = neigh[v]
                if len(nbs) != 2:
                    return False
                n1, n2 = nbs
                d1 = get_dir(v, n1)
                d2 = get_dir(v, n2)
                if typ == 'W':
                    if (d1 + 2) % 4 != d2:
                        return False
                    if not (is_turn(n1) or is_turn(n2)):
                        return False
                elif typ == 'B':
                    if (d1 + 2) % 4 == d2:
                        return False
                    if not is_straight(n1):
                        return False
                    if not is_straight(n2):
                        return False
        return True

    from collections import deque
    def bfs(start, visited, N):
        q = deque([start])
        seen = set([start])
        while q:
            cur = q.popleft()
            for nx in get_adj(cur, N):
                if nx not in visited and nx not in seen:
                    seen.add(nx)
                    q.append(nx)
        return seen

    def dfs(path, visited):
        if len(path) > 2 and is_adjacent(path[-1], path[0]) and len(visited & clues) == len(clues):
            cycle = path + [path[0]]
            if check_conditions(cycle, data, N):
                return cycle
        current = path[-1]
        remaining_clues = clues - visited
        if remaining_clues:
            reachable = bfs(current, visited, N)
            if not remaining_clues.issubset(reachable):
                return None
        for nx in get_adj(current, N):
            if nx in visited:
                continue
            path.append(nx)
            visited.add(nx)
            res = dfs(path, visited)
            if res is not None:
                return res
            path.pop()
            visited.remove(nx)
        return None

    # choose start
    degs = {(r, c): len(get_adj((r, c), N)) for r in range(N) for c in range(N) if (r, c) in clues}
    min_deg = min(degs.values())
    candidates = [p for p, d in degs.items() if d == min_deg]
    start = min(candidates, key=lambda p: (p[0], p[1]))
    path = [start]
    visited = set([start])
    result = dfs(path, visited)
    if result is None:
        return "No Solution"
    else:
        return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
