                            if d1 != d2 and abs(d1 - d2) % 4 == 1:
                                possible.append((d1, d2))
            else:
                for ii in range(len(avail)):
                    for jj in range(ii + 1, len(avail)):
                        possible.append((avail[ii], avail[jj]))
            possible_pairs[(r, c)] = set(frozenset(t) for t in possible)
    clue_list = [c[0] for c in clues]
    clue_index = {p: i for i, p in enumerate(clue_list)}
    num_clues = len(clue_list)
    full_mask = (1 << num_clues) - 1

    def is_adjacent(a, b):
