    def compute_arm_from_i(path, i, dir_sign):
        len_p = len(path)
        if dir_sign == 1:
            if i == len_p - 1:
                return 0, False
            current_dir = (path[i + 1][0] - path[i][0], path[i + 1][1] - path[i][1])
            l = 1
            j = i + 1
            while j + 1 < len_p:
                next_dir = (path[j + 1][0] - path[j][0], path[j + 1][1] - path[j][1])
                if next_dir != current_dir:
                    return l, True
                l += 1
                j += 1
            return l, False
        else:
            if i == 0:
                return 0, False
            current_dir = (path[i - 1][0] - path[i][0], path[i - 1][1] - path[i][1])
            l = 1
            j = i - 1
            while j - 1 >= 0:
                next_dir = (path[j - 1][0] - path[j][0], path[j - 1][1] - path[j][1])
                if next_dir != current_dir:
