            l_right, fixed_right = compute_arm_from_i(path, i, 1)
            lower_left = l_left
            lower_right = l_right
            if fixed_left and fixed_right:
                if l_left + l_right != kk:
                    return False
            if lower_left + lower_right > kk:
                return False
            if fixed_left and l_left + lower_right > kk:
                return False
            if fixed_right and l_right + lower_left > kk:
