    def backtrack(path, visited, mask):
        if len(path) >= 3 and mask == full_mask and is_adjacent(path[0], path[-1]):
            # check closure conditions
            vec_from_last = (path[0][0] - path[-1][0], path[0][1] - path[-1][1])
            if vec_from_last not in dirs:
                return None
            incoming_vec_last = (path[-1][0] - path[-2][0], path[-1][1] - path[-2][1])
            incoming_dir_last = dirs.index((-incoming_vec_last[0], -incoming_vec_last[1]))
            outgoing_dir_last = dirs.index(vec_from_last)
            if frozenset([incoming_dir_last, outgoing_dir_last]) not in possible_pairs[path[-1]]:
                return None
            incoming_vec_first = (path[0][0] - path[-1][0], path[0][1] - path[-1][1])
            incoming_dir_first = dirs.index((-incoming_vec_first[0], -incoming_vec_first[1]))
            outgoing_vec_first = (path[1][0] - path[0][0], path[1][1] - path[0][1])
            outgoing_dir_first = dirs.index(outgoing_vec_first)
            if frozenset([incoming_dir_first, outgoing_dir_first]) not in possible_pairs[path[0]]:
