                    next_dir = (cycle[nj][0] - cycle[j][0], cycle[nj][1] - cycle[j][1])
                    if next_dir != cur_dir:
                        break
                    ll += 1
                    j = nj
                # backward
                cur_dir = (cycle[i - 1][0] - cycle[i][0], cycle[i - 1][1] - cycle[i][1])
                rr = 1
                j = i - 1
                while True:
                    nj = (j - 1) % clen
                    next_dir = (cycle[nj][0] - cycle[j][0], cycle[nj][1] - cycle[j][1])
                    if next_dir != cur_dir:
                        break
                    rr += 1
                    j = nj
                if ll + rr != kk:
                    good = False
                    break
            if good:
                return path + [path[0]]
        for eidx in [0, -1]:
            current = path[eidx]
            if eidx == 0:
                incoming_vec = (path[0][0] - path[1][0], path[0][1] - path[1][1])
            else:
                incoming_vec = (path[-1][0] - path[-2][0], path[-1][1] - path[-2][1])
            for dd, d in enumerate(dirs):
                nr, nc = current[0] + d[0], current[1] + d[1]
                npos = (nr, nc)
                if 0 <= nr <= N and 0 <= nc <= N and npos not in visited:
                    incoming_dir = dirs.index((-incoming_vec[0], -incoming_vec[1]))
