    # choose start with min possible
    min_len = float('inf')
    start = None
    for (r, c), _, _ in clues:
        l = len(possible_pairs[(r, c)])
        if l < min_len:
            min_len = l
            start = (r, c)
    # now start
    for pair in possible_pairs[start]:
        d1, d2 = sorted(pair)
        n1 = (start[0] + dirs[d1][0], start[1] + dirs[d1][1])
        n2 = (start[0] + dirs[d2][0], start[1] + dirs[d2][1])
        if n1 == n2:
            continue
        path = [n1, start, n2]
        visited = set(path)
        mask = 0
        if start in clue_index:
            mask |= (1 << clue_index[start])
        if not check_pruning(path, mask):
            continue
        result = backtrack(path, visited, mask)
        if result is not None:
            return result
    return "No Solution"

