                        min_size = size
                        chosen_i, chosen_j = i, j
        if min_size == 0:
            return False
        attempted = list(poss[chosen_i][chosen_j])
        for v in attempted:
            save_grid = copy.deepcopy(grid)
            save_poss = copy.deepcopy(poss)
            if assign(chosen_i, chosen_j, v):
                if propagate():
                    if backtrack():
                        return True
            grid[:] = save_grid[:]
            poss[:] = save_poss[:]
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

