    regions = sorted(regions, key=lambda reg: len(possible_configs[reg]))
    chosen = [None] * num_reg
    def backtrack(idx, curr_row, curr_col):
        if idx == num_reg:
            if curr_row == row_clues and curr_col == col_clues:
                grid = [[None] * m for _ in range(n)]
                for i in range(num_reg):
