import ast

def solve(observation):
    data = observation['data']
    N = len(data)
    shapes = {}
    shapes['I'] = [
        [(0,0),(0,1),(0,2),(0,3)],
        [(0,0),(1,0),(2,0),(3,0)]
    ]
    shapes['T'] = [
        [(0,0),(0,1),(0,2),(1,1)],
        [(0,1),(1,0),(1,1),(1,2)],
        [(0,0),(1,0),(2,0),(1,1)],
        [(0,1),(1,1),(2,1),(1,0)]
    ]
    shapes['S'] = [
        [(0,1),(0,2),(1,0),(1,1)],
        [(0,0),(1,0),(1,1),(2,1)],
        [(0,0),(0,1),(1,1),(1,2)],
        [(0,1),(1,0),(1,1),(2,0)]
    ]
    shapes['L'] = [
        [(0,0),(1,0),(2,0),(2,1)],
        [(0,0),(0,1),(0,2),(1,0)],
        [(0,0),(0,1),(1,1),(2,1)],
        [(0,2),(1,0),(1,1),(1,2)],
        [(0,1),(1,1),(2,1),(2,0)],
        [(0,2),(0,1),(0,0),(1,2)],
        [(0,1),(0,0),(1,0),(2,0)],
        [(0,0),(1,0),(1,1),(1,2)]
    ]

    cells_per_region = defaultdict(list)
    for r in range(N):
        for c in range(N):
            cells_per_region[data[r][c]].append((r, c))

    regions = sorted(cells_per_region.keys())
    R = len(regions)
    if R == 0:
        return "No Solution"
    region_index = {old_id: idx for idx, old_id in enumerate(regions)}
    cells = [cells_per_region[old_id] for old_id in regions]

    # Build adjacency graph for regions
    adj = [set() for _ in range(R)]
    for r in range(N):
        for c in range(N):
            id1 = region_index[data[r][c]]
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if nr < N and nc < N:
                    id2 = region_index[data[nr][nc]]
                    if id1 != id2:
                        adj[id1].add(id2)
                        adj[id2].add(id1)

    # Find possible placements for each region
    possible_placements = [defaultdict(list) for _ in range(R)]
    for ri in range(R):
        region_set = set(cells[ri])
        seen = set()
        for typ in 'LITS':
            for offset_list in shapes[typ]:
                for ar in range(N):
                    for ac in range(N):
                        placement = set()
                        valid = True
                        for dr, dc in offset_list:
                            nr, nc = ar + dr, ac + dc
                            if not (0 <= nr < N and 0 <= nc < N and (nr, nc) in region_set):
                                valid = False
                                break
                            placement.add((nr, nc))
                        if valid and len(placement) == 4:
                            fs = frozenset(placement)
                            if fs not in seen:
                                seen.add(fs)
                                possible_placements[ri][typ].append(fs)

    # Backtracking setup
    shaded_grid = [[False] * N for _ in range(N)]
    assigned_types = [None] * R
    assigned_placements = [None] * R

    def has_new_2x2(plac, shaded_grid):
        for cell in plac:
            r, c = cell
            for drr in [0, -1]:
                for dcc in [0, -1]:
                    rr = r + drr
                    cc = c + dcc
                    if 0 <= rr < N - 1 and 0 <= cc < N - 1:
                        if all(shaded_grid[rr + i][cc + j] for i in [0, 1] for j in [0, 1]):
                            return True
        return False

    def backtrack(placed):
        if len(placed) == R:
            return True
        candidates = []
        for ri in range(R):
            if ri not in placed:
                if len(placed) == 0 or any(a in placed for a in adj[ri]):
                    forbidden = set(assigned_types[a] for a in adj[ri] if a in placed)
                    num = sum(len(possible_placements[ri][t]) for t in 'LITS' if t not in forbidden and t in possible_placements[ri])
                    if num > 0:
                        candidates.append((num, ri))
        candidates.sort()
        for _, ri in candidates:
            forbidden = set(assigned_types[a] for a in adj[ri] if a in placed)
            for typ in 'LITS':
                if typ in forbidden or typ not in possible_placements[ri]:
                    continue
                for fs in possible_placements[ri][typ]:
                    plac = list(fs)
                    # Check connects
                    connects = len(placed) == 0
                    if not connects:
                        for cell in plac:
                            r, c = cell
                            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < N and 0 <= nc < N and shaded_grid[nr][nc]:
                                    connects = True
                                    break
                            if connects:
                                break
                    if not connects:
                        continue
                    # Set shaded
                    for cell in plac:
                        r, c = cell
                        shaded_grid[r][c] = True
                    # Check 2x2
                    if has_new_2x2(plac, shaded_grid):
                        for cell in plac:
                            r, c = cell
                            shaded_grid[r][c] = False
                        continue
                    # Recurse
                    assigned_types[ri] = typ
                    assigned_placements[ri] = fs
                    placed.add(ri)
                    if backtrack(placed):
                        return True
                    placed.remove(ri)
                    assigned_types[ri] = None
                    assigned_placements[ri] = None
                    for cell in plac:
                        r, c = cell
                        shaded_grid[r][c] = False
        return False

    # Start backtracking
    start_candidates = []
    for ri in range(R):
        num = sum(len(possible_placements[ri][t]) for t in possible_placements[ri])
        start_candidates.append((num, ri))
    start_candidates.sort()
    for _, start_ri in start_candidates:
        for typ in possible_placements[start_ri]:
            for fs in possible_placements[start_ri][typ]:
                plac = list(fs)
                # Set
                for cell in plac:
                    r, c = cell
                    shaded_grid[r][c] = True
                # Check 2x2
                if has_new_2x2(plac, shaded_grid):
                    for cell in plac:
                        r, c = cell
                        shaded_grid[r][c] = False
                    continue
                placed = set([start_ri])
                assigned_types[start_ri] = typ
                assigned_placements[start_ri] = fs
                if backtrack(placed):
                    # Construct answer
                    answer = [[None] * N for _ in range(N)]
                    for ri in range(R):
                        t = assigned_types[ri]
                        for cell in assigned_placements[ri]:
                            r, c = cell
                            answer[r][c] = t
                    return answer
                # Reset
                placed.clear()
                assigned_types[start_ri] = None
                assigned_placements[start_ri] = None
                for cell in plac:
                    r, c = cell
                    shaded_grid[r][c] = False
    return "No Solution"

