        while q:
            cur = q.popleft()
            for dx, dy in dirs:
                nx, ny = cur[0] + dx, cur[1] + dy
                if 0 <= nx <= N and 0 <= ny <= N and (nx, ny) not in visited and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    q.append((nx, ny))
                    if (nx, ny) in remaining_clues:
                        reached_clues.add((nx, ny))
        return reached_clues == remaining_clues

    def check_path(path):
        n = len(path)
        # Check types
        for i in range(n):
            prev = path[(i - 1) % n]
            curr = path[i]
            nextt = path[(i + 1) % n]
            dir_in = (curr[0] - prev[0], curr[1] - prev[1])
            dir_out = (nextt[0] - curr[0], nextt[1] - curr[1])
            dot_prod = dir_in[0] * dir_out[0] + dir_in[1] * dir_out[1]
            dot = -dot_prod
            if curr in clue_set:
                for p, col, _ in clues:
                    if p == curr:
                        if col == 'W' and dot != -1:
                            return False
                        elif col == 'B' and dot != 0:
                            return False
                        break
            else:
                if dot not in (-1, 0):
                    return False
        # Find turn positions
        turn_positions = []
        for i in range(n):
            prev = path[(i - 1) % n]
            curr = path[i]
            nextt = path[(i + 1) % n]
            dir_in = (curr[0] - prev[0], curr[1] - prev[1])
            dir_out = (nextt[0] - curr[0], nextt[1] - curr[1])
            dot_prod = dir_in[0] * dir_out[0] + dir_in[1] * dir_out[1]
            dot = -dot_prod
            if dot == 0:
                turn_positions.append(i)
        if not turn_positions:
            segment_lengths = [n]
        else:
            tp = turn_positions
            tp.append(tp[0] + n)
            segment_lengths = []
            for j in range(len(tp) - 1):
                segment_lengths.append(tp[j + 1] - tp[j])
        # Check whites and blacks
        for p, col, kk in clues:
            idx = path.index(p)
            if col == 'W':
                prev_turn = max([t for t in turn_positions if t < idx] or [idx - n])
                next_turn = min([t for t in turn_positions if t > idx] or [idx + n])
                seg_len = next_turn - prev_turn
                if seg_len != kk:
                    return False
            else:
                for jj in range(len(turn_positions)):
                    if turn_positions[jj] == idx:
                        len1 = segment_lengths[(jj - 1) % len(segment_lengths)]
                        len2 = segment_lengths[jj]
                        if len1 + len2 != kk:
                            return False
                        break
        return True

    def dfs(current, previous, path, visited):
        if clue_set - visited and not can_reach_all(current, visited):
            return None
        possible_next = []
        for dx, dy in dirs:
            nx, ny = current[0] + dx, current[1] + dy
            if 0 <= nx <= N and 0 <= ny <= N and (nx, ny) != previous:
                if (nx, ny) in visited:
                    if (nx, ny) == path[0] and len(path) >= 3 and clue_set.issubset(visited):
                        possible_next.append((nx, ny))
                else:
                    possible_next.append((nx, ny))
        for nextp in possible_next:
            dir_in = (current[0] - previous[0], current[1] - previous[1])
            dir_out = (nextp[0] - current[0], nextp[1] - current[1])
            dot_prod = dir_in[0] * dir_out[0] + dir_in[1] * dir_out[1]
            dot = -dot_prod
            is_valid = True
            if current in clue_set:
                col = next(cl[1] for cl in clues if cl[0] == current)
                if col == 'W' and dot != -1:
                    is_valid = False
                elif col == 'B' and dot != 0:
                    is_valid = False
            else:
                if dot not in (-1, 0):
                    is_valid = False
            if not is_valid:
                continue
            if nextp == path[0]:
                dir1 = (path[1][0] - start[0], path[1][1] - start[1])
                dir2 = (current[0] - start[0], current[1] - start[1])
                start_dot_prod = dir1[0] * dir2[0] + dir1[1] * dir2[1]
                start_valid = True
                if start in clue_set:
                    col = next(cl[1] for cl in clues if cl[0] == start)
                    if col == 'W' and start_dot_prod != -1:
                        start_valid = False
                    elif col == 'B' and start_dot_prod != 0:
                        start_valid = False
                else:
                    if start_dot_prod not in (-1, 0):
                        start_valid = False
                if not start_valid:
                    continue
                if check_path(path):
                    return path + [path[0]]
                continue
            new_path = path + [nextp]
            new_visited = visited | {nextp}
            res = dfs(nextp, current, new_path, new_visited)
            if res is not None:
                return res
        return None

    for dx, dy in dirs:
        nx, ny = start[0] + dx, start[1] + dy
        if 0 <= nx <= N and 0 <= ny <= N:
            initial_path = [start, (nx, ny)]
            initial_visited = set(initial_path)
            if not clue_set - initial_visited or can_reach_all((nx, ny), initial_visited):
                res = dfs((nx, ny), start, initial_path, initial_visited)
                if res is not None:
                    return str(res)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
