        for r, c in regions_cells[rid]:
            d = observation['data'][r][c]
            if d is not None:
                if clue is not None:
                    raise ValueError("Multiple clues in region")
                clue = d
        region_clue[rid] = clue

    def adjacent(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        return (r1 == r2 and abs(c1 - c2) == 1) or (c1 == c2 and abs(r1 - r2) == 1)

    # Generate possible configs for a region
    def generate_configs(rid):
        cells = regions_cells[rid]
        M = len(cells)
        clue = region_clue[rid]
        is_numbered = clue is not None
        configs = []
        def rec(idx, current):
            if idx == M:
                if is_numbered:
                    if len(current) == clue:
                        configs.append(set(current))
                else:
                    configs.append(set(current))
                return
            # skip
            rec(idx + 1, current)
            # take
            pos = cells[idx]
            can = True
            for cr in current:
                if adjacent(pos, cr):
                    can = False
                    break
            if can:
                rec(idx + 1, current + [pos])
        rec(0, [])
        return configs

    all_configs = {}
    for rid in region_list:
        all_configs[rid] = generate_configs(rid)

    # Sort regions by number of configs ascending
    region_list = sorted(region_list, key=lambda rid: len(all_configs[rid]))

    def check_segments(grid):
        # Check rows
        for r in range(N):
            i = 0
            while i < N:
                if grid[r][i] == 'B':
                    i += 1
                    continue
                reg_set = set()
                j = i
                while j < N and grid[r][j] is None:
                    reg_set.add(observation['region'][r][j])
                    j += 1
                if len(reg_set) > 2:
                    return False
                i = j
        # Check columns
        for c in range(N):
            i = 0
            while i < N:
                if grid[i][c] == 'B':
                    i += 1
                    continue
                reg_set = set()
                j = i
                while j < N and grid[j][c] is None:
                    reg_set.add(observation['region'][j][c])
                    j += 1
                if len(reg_set) > 2:
                    return False
                i = j
        return True

    def check_connectivity(grid):
        whites = [(r, c) for r in range(N) for c in range(N) if grid[r][c] is None]
        if not whites:
            return True
        visited = set()
        q = deque([whites[0]])
        visited.add(whites[0])
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] is None and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(whites)

    def search(reg_idx, current_blacks):
        if reg_idx == len(region_list):
            grid = [[None] * N for _ in range(N)]
            for r, c in current_blacks:
                grid[r][c] = 'B'
            if check_segments(grid) and check_connectivity(grid):
                return grid
            return None
        rid = region_list[reg_idx]
        for config in all_configs[rid]:
            can = True
            for pos in config:
                r, c = pos
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N and (nr, nc) in current_blacks:
                        can = False
                        break
                if not can:
                    break
            if can:
                new_blacks = current_blacks | config
                res = search(reg_idx + 1, new_blacks)
                if res is not None:
                    return res
        return None

    res = search(0, set())
    if res is not None:
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
