from collections import defaultdict, deque

def solve(observation):
    region_grid = observation['region']
    data = observation['data']
    N = len(region_grid)

    # Group cells by region
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            region_cells[rid].append((r, c))

    # Determine target for each region
    region_target = {}
    for rid, cells in region_cells.items():
        targets = set()
        for r, c in cells:
            if data[r][c] is not None:
                targets.add(data[r][c])
        if len(targets) > 1:
            return "No Solution"
        region_target[rid] = list(targets)[0] if targets else -1

    # State: -1 unknown, 0 white, 1 black
    state = [[-1] * N for _ in range(N)]

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid_pos(r, c):
        return 0 <= r < N and 0 <= c < N

    def deduce():
        changed = True
        while changed:
            changed = False

            # Region constraints
            for rid, cells in region_cells.items():
                target = region_target[rid]
                if target == -1:
                    continue
                black_count = 0
                white_count = 0
                unknown = []
                for r, c in cells:
                    s = state[r][c]
                    if s == 1:
                        black_count += 1
                    elif s == 0:
                        white_count += 1
                    else:
                        unknown.append((r, c))
                u = len(unknown)
                min_b = black_count
                max_b = black_count + u
                if max_b < target or min_b > target:
                    return False
                if max_b == target:
                    for pr, pc in unknown:
                        if state[pr][pc] == -1:
                            state[pr][pc] = 1
                            changed = True
                if white_count == len(cells) - target:
                    for pr, pc in unknown:
                        if state[pr][pc] == -1:
                            state[pr][pc] = 0
                            changed = True

            # Black not touching
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 1:
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if is_valid_pos(nr, nc):
                                if state[nr][nc] == 1:
                                    return False
                                if state[nr][nc] == -1:
                                    state[nr][nc] = 0
                                    changed = True

            # Segment rule propagation
            for is_row in [True, False]:
                for i in range(N):
                    line = [(i, j) if is_row else (j, i) for j in range(N)]
                    for s in range(N):
                        regions = set()
                        for e in range(s, N):
                            r, c = line[e]
                            regions.add(region_grid[r][c])
                            if len(regions) >= 3:
                                unknown_pos = []
                                all_white_or_unknown = True
                                for k in range(s, e + 1):
                                    r, c = line[k]
                                    s_val = state[r][c]
                                    if s_val == 1:
                                        all_white_or_unknown = False
                                        break
                                    if s_val == -1:
                                        unknown_pos.append((r, c))
                                if all_white_or_unknown:
                                    u = len(unknown_pos)
                                    if u == 0:
                                        return False
                                    if u == 1:
                                        pr, pc = unknown_pos[0]
                                        state[pr][pc] = 1
                                        changed = True

            # Connectivity propagation
            visited = [[False] * N for _ in range(N)]
            components = []
            for r in range(N):
                for c in range(N):
                    if not visited[r][c] and state[r][c] != 1:
                        component = []
                        forced_white = 0
                        q = deque([(r, c)])
                        visited[r][c] = True
                        while q:
                            cr, cc = q.popleft()
                            component.append((cr, cc))
                            if state[cr][cc] == 0:
                                forced_white += 1
                            for dr, dc in dirs:
                                nr, nc = cr + dr, cc + dc
                                if is_valid_pos(nr, nc) and not visited[nr][nc] and state[nr][nc] != 1:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                        components.append((component, forced_white))

            main_components = [c for c in components if c[1] > 0]
            if len(main_components) > 1:
                return False
            if len(main_components) == 1:
                main_comp_set = set(main_components[0][0])
                for comp, fw in components:
                    if fw == 0:
                        for pr, pc in comp:
                            if state[pr][pc] == -1:
                                state[pr][pc] = 1
                                changed = True
        return True

    def backtrack():
        if not deduce():
            return None

        # Check if all decided
        branch_r, branch_c = -1, -1
        min_u = float('inf')
        chosen_rid = -1
        for rid, cells in region_cells.items():
            u = sum(1 for pr, pc in cells if state[pr][pc] == -1)
            if 0 < u < min_u:
                min_u = u
                chosen_rid = rid
        if chosen_rid == -1:
            # All decided, check final conditions
            for rid, cells in region_cells.items():
                target = region_target[rid]
                if target != -1:
                    count = sum(1 for pr, pc in cells if state[pr][pc] == 1)
                    if count != target:
                        return None
            # White connected
            white_cells = [(r, c) for r in range(N) for c in range(N) if state[r][c] == 0]
            if white_cells:
                visited = [[False] * N for _ in range(N)]
                q = deque([white_cells[0]])
                visited[white_cells[0][0]][white_cells[0][1]] = True
                reached = 1
                while q:
                    cr, cc = q.popleft()
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if is_valid_pos(nr, nc) and not visited[nr][nc] and state[nr][nc] == 0:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                            reached += 1
                if reached != len(white_cells):
                    return None
            # Segment rule
            for is_row in [True, False]:
                for i in range(N):
                    j = 0
                    while j < N:
                        val = state[i][j] if is_row else state[j][i]
                        if val == 1:
                            j += 1
                            continue
                        s = j
                        regions = set()
                        while j < N and (state[i][j] if is_row else state[j][i]) == 0:
                            r = i if is_row else j
                            c = j if is_row else i
                            regions.add(region_grid[r][c])
                            j += 1
                        if len(regions) > 2:
                            return None
            # Good
            answer = [[None] * N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 1:
                        answer[r][c] = 'B'
            return answer

        # Branch on first unknown in chosen region
        for r, c in region_cells[chosen_rid]:
            if state[r][c] == -1:
                branch_r, branch_c = r, c
                break

        # Try white
        state[branch_r][branch_c] = 0
        res = backtrack()
        if res is not None:
            return res
        state[branch_r][branch_c] = -1

        # Try black
        state[branch_r][branch_c] = 1
        res = backtrack()
        if res is not None:
            return res
        state[branch_r][branch_c] = -1

        return None

    # Initial setup for target 0 regions
    for rid, target in region_target.items():
        if target == 0:
            for r, c in region_cells[rid]:
                state[r][c] = 0

    result = backtrack()
    if result is None:
        return "No Solution"
    return result

