def solve(observation):
    data = observation['data']
    N = len(data)
    from collections import defaultdict
    regions = defaultdict(list)
    for r in range(N):
        for c in range(N):
            regions[data[r][c]].append((r, c))
    region_list = sorted(regions, key=lambda idd: len(regions[idd]))
    m = len(region_list)
    shaded = [[False] * N for _ in range(N)]
    forbidden = [[False] * N for _ in range(N)]
    counts = {idd: 0 for idd in regions}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        ns = []
        for dr, dc in directions:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < N and 0 <= nc < N:
                ns.append((nr, nc))
        return ns

    def try_place(dominoes, index):
        all_cells = set()
        for pair in dominoes:
            p1, p2 = pair
            if p1 == p2 or abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) != 1:
                return None
            all_cells.add(p1)
            all_cells.add(p2)
        if len(all_cells) != len(dominoes) * 2:
            return None
        for i in range(len(dominoes)):
            set1 = set(dominoes[i])
            for j in range(i + 1, len(dominoes)):
                set2 = set(dominoes[j])
                for a in set1:
                    for b in set2:
                        if abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1:
                            return None
        for cell in all_cells:
            r, c = cell
            if shaded[r][c] or forbidden[r][c]:
                return None
            for nr, nc in get_neighbors(r, c):
                if shaded[nr][nc]:
                    return None
        # place
        added_shaded = []
        added_forbidden = []
        old_counts = counts.copy()
        for cell in all_cells:
            r, c = cell
            shaded[r][c] = True
            added_shaded.append((r, c))
            rid = data[r][c]
            counts[rid] += 1
            if counts[rid] > 2:
                break
        else:
            bad = False
            for rid in counts:
                if counts[rid] > 2:
                    bad = True
                    break
            if not bad:
                # mark forbidden
                mark_set = set()
                for cell in all_cells:
                    r, c = cell
                    for nr, nc in get_neighbors(r, c):
                        if not shaded[nr][nc] and not forbidden[nr][nc]:
                            forbidden[nr][nc] = True
                            added_forbidden.append((nr, nc))
                            mark_set.add((nr, nc))
                # recurse
                res = recurse(index + 1)
                if res is not None:
                    return res
        # backtrack
        for r, c in added_shaded:
            shaded[r][c] = False
        counts = old_counts
        for r, c in added_forbidden:
            forbidden[r][c] = False
        return None

    def recurse(idx):
        if idx == m:
            grid = [[ 'S' if shaded[r][c] else None for c in range(N)] for r in range(N)]
            return grid
        rid = region_list[idx]
        current = counts[rid]
        d = 2 - current
        if d < 0:
            return None
        if d == 0:
            return recurse(idx + 1)
        cells = [cell for cell in regions[rid] if not shaded[cell[0]][cell[1]] and not forbidden[cell[0]][cell[1]]]
        if d == 2:
            # internal domino
            for ii in range(len(cells)):
                p1 = cells[ii]
                r1, c1 = p1
                for jj in range(ii + 1, len(cells)):
                    p2 = cells[jj]
                    r2, c2 = p2
                    if abs(r1 - r2) + abs(c1 - c2) == 1:
                        dom = [(p1, p2)]
                        res = try_place(dom, idx)
                        if res is not None:
                            return res
        # crossing
        if d == 1:
            for ii in range(len(cells)):
                p1 = cells[ii]
                r1, c1 = p1
                outs = []
                for nr, nc in get_neighbors(r1, c1):
                    if data[nr][nc] != rid and not shaded[nr][nc] and not forbidden[nr][nc]:
                        outs.append((nr, nc))
                for outp in outs:
                    dom = [(p1, outp)]
                    res = try_place(dom, idx)
                    if res is not None:
                        return res
        elif d == 2:
            for ii in range(len(cells)):
                p1 = cells[ii]
                r1, c1 = p1
                outs1 = []
                for nr, nc in get_neighbors(r1, c1):
                    if data[nr][nc] != rid and not shaded[nr][nc] and not forbidden[nr][nc]:
                        outs1.append((nr, nc))
                for jj in range(ii + 1, len(cells)):
                    p2 = cells[jj]
                    r2, c2 = p2
                    outs2 = []
                    for nr, nc in get_neighbors(r2, c2):
                        if data[nr][nc] != rid and not shaded[nr][nc] and not forbidden[nr][nc]:
                            outs2.append((nr, nc))
                    for out1 in outs1:
                        for out2 in outs2:
                            if out1 == out2:
                                continue
                            dom = [(p1, out1), (p2, out2)]
                            res = try_place(dom, idx)
                            if res is not None:
                                return res
        return None

    res = recurse(0)
    if res is not None:
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
