```python
OBSERVATION = {'row_black_runs': [[2], [3], [1], [2, 2], [1, 2]], 'col_black_runs': [[4], [2, 2], [1], [2], [2]]}

def generate_patterns(clue, length, current):
    patterns = []
    def helper(idx, pos, pattern):
        if idx == len(clue):
            rest = ['.'] * (length - pos)
            for k in range(pos, length):
                if current[k] is not None and current[k] != '.':
                    return
            patterns.append(pattern + rest)
            return
        run = clue[idx]
        min_skip = 1 if idx > 0 else 0
        remaining = sum(clue[idx+1:]) + (len(clue) - idx - 1 if idx + 1 < len(clue) else 0)
        max_skip = length - pos - run - remaining + 1
        for skip in range(min_skip, max_skip + 1):
            if pos + skip + run > length:
                continue
            new_pattern = pattern[:]
            can = True
            for k in range(skip):
                symbol = '.'
                p = pos + k
                if current[p] is not None and current[p] != symbol:
                    can = False
                    break
                new_pattern.append(symbol)
            if not can:
                continue
            run_start = pos + skip
            for k in range(run):
                symbol = 'B'
                p = run_start + k
                if current[p] is not None and current[p] != symbol:
                    can = False
                    break
                new_pattern.append(symbol)
            if not can:
                continue
            helper(idx + 1, run_start + run, new_pattern)
    helper(0, 0, [])
    return patterns

def propagate(grid, row_clues, col_clues):
    n = len(grid)
    m = len(grid[0])
    while True:
        changed = False
        for i in range(n):
            possible = generate_patterns(row_clues[i], m, grid[i])
            if not possible:
                return False
            for j in range(m):
                if grid[i][j] is None:
                    symbols = set(p[j] for p in possible)
                    if len(symbols) == 1:
                        grid[i][j] = next(iter(symbols))
                        changed = True
        for j in range(m):
            current = [grid[i][j] for i in range(n)]
            possible = generate_patterns(col_clues[j], n, current)
            if not possible:
                return False
            for i in range(n):
                if grid[i][j] is None:
                    symbols = set(p[i] for p in possible)
                    if len(symbols) == 1:
                        grid[i][j] = next(iter(symbols))
                        changed = True
        if not changed:
            return True

def verify(grid, row_clues, col_clues):
    n = len(grid)
    m = len(grid[0])
    for i in range(n):
        runs = []
        count = 0
        for cell in grid[i]:
            if cell == 'B':
                count += 1
            else:
                if count > 0:
                    runs.append(count)
                count = 0
        if count > 0:
            runs.append(count)
        if runs != row_clues[i]:
            return False
    for j in range(m):
        runs = []
        count = 0
        for i in range(n):
            cell = grid[i][j]
            if cell == 'B':
                count += 1
            else:
                if count > 0:
                    runs.append(count)
                count = 0
        if count > 0:
            runs.append(count)
        if runs != col_clues[j]:
            return False
    return True

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    n = len(row_clues)
    m = len(col_clues)
    total_b_row = sum(sum(cl) for cl in row_clues)
    total_b_col = sum(sum(cl) for cl in col_clues)
    if total_b_row != total_b_col:
        return "No Solution"
    grid = [[None for _ in range(m)] for _ in range(n)]
    def backtrack(grid):
        if all(all(cell is not None for cell in row) for row in grid):
            if verify(grid, row_clues, col_clues):
                return [[ 'B' if cell == 'B' else None for cell in row] for row in grid]
            return None
        p_grid = [row[:] for row in grid]
        if not propagate(p_grid, row_clues, col_clues):
            return None
        if all(all(cell is not None for cell in row) for row in p_grid):
            if verify(p_grid, row_clues, col_clues):
                return [[ 'B' if cell == 'B' else None for cell in row] for row in p_grid]
            return None
        i, j = -1, -1
        for ii in range(n):
            for jj in range(m):
                if p_grid[ii][jj] is None:
                    i, j = ii, jj
                    break
            if i != -1:
                break
        b_grid = [row[:] for row in p_grid]
        b_grid[i][j] = 'B'
        result = backtrack(b_grid)
        if result is not None:
            return result
        d_grid = [row[:] for row in p_grid]
        d_grid[i][j] = '.'
        result = backtrack(d_grid)
        if result is not None:
            return result
        return None
    result = backtrack(grid)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
